insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'bank', 0, $official_bank_source${"code":"FIN216","courseId":"8e4bf369-a375-52bc-b5c2-fa55b4d5676c","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":820,"shell":{"contentKey":"fundamentals-deposit-insurance","titles":["Fundamentals of Deposit Insurance"],"level":"200-level","semesters":["second-semester"]},"rows":{"audited":0,"keep":0,"retire":0,"add":820}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 1, $official_bank_source${"itemId":"264fbe06-a84d-5213-9c6c-23dd93f0fc21","questionId":"1ae2efcf-6dea-51aa-9993-ee42720b67ff","sourceKey":"bank:FIN216:F216-0005","payload":{"prompt":"The NDIC was established by Decree No. 22 of ____","options":["2023","1988","1989","2006"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC was created by Decree No. 22 of 15 June 1988, following the earlier recommendation for a depositors' protection fund. It is easy to pick 1989 (option C), but that is the year the corporation actually began operations. 2006 and 2023 are the years of later Acts that repealed and replaced the original law, not the year the NDIC was set up."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 2, $official_bank_source${"itemId":"c7348e2c-7d05-58bd-957c-03311044eba4","questionId":"5e8c1e84-f702-53c9-a0c4-86955d106108","sourceKey":"bank:FIN216:F216-0005-b","payload":{"prompt":"The NDIC Act 2006 was repealed and replaced by the Nigeria Deposit Insurance Corporation Act of ____","options":["2023","2016","1988","2006"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC Act No. 33 of 2023 repealed the 2006 Act and is now the main law governing the NDIC. Option D is the Act that was replaced, not the replacement, and 1988 is the year of the original decree that created the NDIC. 2016 is not the year of any NDIC Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 3, $official_bank_source${"itemId":"c9177d25-e750-5364-badb-b51a659324a8","questionId":"6be78be8-be29-534d-9466-2738df01c8ef","sourceKey":"bank:FIN216:F216-0006","payload":{"prompt":"In 1983, a committee set up by the ____ recommended a depositors' protection fund, which led to the creation of the NDIC.","options":["Federal Government","Central Bank","Stock Exchange","Federal Ministry of Finance"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"In 1983 the Board of the Central Bank of Nigeria set up a committee to review the banking system, and it recommended a Depositors' Protection Fund, the idea that became the NDIC. Option A and option D are tempting because the Federal Government and the Ministry of Finance were involved in later legislation and ownership, but the committee itself came from the CBN. The Stock Exchange in option C had no role in it."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 4, $official_bank_source${"itemId":"00a18047-983f-5b6e-96df-bfe2da329499","questionId":"eac630cb-e9ab-5729-94df-841efbb28346","sourceKey":"bank:FIN216:F216-0007","payload":{"prompt":"The NDIC began operations in ____","options":["1988","1990","1986","1989"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Although the NDIC was legally created in 1988, it actually opened for business in March 1989. Option A, 1988, is the year of the decree that established it, which is why many students mix the two up. 1986 is the year the Structural Adjustment Programme started, and 1990 has no special link to the NDIC's start."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 5, $official_bank_source${"itemId":"8950f347-c416-5c0b-808f-4fda796effca","questionId":"fff484bf-2425-5047-bd6d-09a04b0e7a64","sourceKey":"bank:FIN216:F216-0038","payload":{"prompt":"The US Banking Act of 1933 (often called the Glass-Steagall Act) brought about the establishment of the ____","options":["Financial Claims Scheme","Deposit insurance scheme of Brazil","Federal Deposit Insurance Corporation (FDIC)","Deposit Insurance Corporation of India"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The Banking Act of 1933, signed in June 1933 after the wave of US bank failures during the Great Depression, created the Federal Deposit Insurance Corporation, which began insuring deposits on 1 January 1934. Option A is Australia's scheme, set up in 2008 during the global financial crisis. Option D began operating in 1962 and Brazil's fund (option B) was set up in 1995, both under their own countries' laws."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 6, $official_bank_source${"itemId":"902df003-6d17-5bbb-b59b-5b25b5c34879","questionId":"845625f7-5a48-523e-b8a2-2a6bc0ec3a51","sourceKey":"bank:FIN216:F216-0039","payload":{"prompt":"The current law governing the NDIC is the Nigeria Deposit Insurance Corporation Act, No. ____ of 2023.","options":["30","22","18","33"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC Act No. 33 of 2023 repealed the NDIC Act No. 16 of 2006 and is now the law governing the Corporation. Option B, 22, is the number of the original 1988 Decree that first established the NDIC, which is why it is a tempting choice. Options A and C are not the numbers of any NDIC law."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 7, $official_bank_source${"itemId":"61af578a-a8d2-58de-9332-d7a81a2bed0b","questionId":"907dbc30-45fd-5554-907a-0d7f580de88b","sourceKey":"bank:FIN216:F216-0039-b","payload":{"prompt":"The NDIC Act No. 33 of 2023 repealed and replaced which earlier law?","options":["CBN Act 2007","Failed Banks (Recovery of Debts) and Financial Malpractices in Banks Decree 1994","Banks and Other Financial Institutions Act 2020","NDIC Act No. 16 of 2006"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC's legal history runs from Decree No. 22 of 1988, to the NDIC Act No. 16 of 2006, to the NDIC Act No. 33 of 2023, which repealed the 2006 Act. Option C (BOFIA 2020) is the law under which banks are licensed, and option A governs the Central Bank; both remain in force. Option B was a 1990s law for recovering debts owed to failed banks, not the NDIC's establishing law."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 8, $official_bank_source${"itemId":"3e8037ec-e81d-5d60-86f9-6f96b0b9cbb4","questionId":"1bc591f3-12b4-52a3-82ba-8692e540bc2d","sourceKey":"bank:FIN216:F216-0040","payload":{"prompt":"The financial panics that led to many bank collapses between 1893 and 1907 occurred in:","options":["Britain","Nigeria","United States of America","Germany"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The United States suffered repeated banking panics in this period, notably the Panic of 1893 and the Panic of 1907, with runs that closed many banks. These episodes, followed by the collapses of the early 1930s, built the case for nationwide deposit insurance, which came with the FDIC in 1933. Options A, B and D did not experience this series of panics."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 9, $official_bank_source${"itemId":"0dc41b37-7e47-5e5e-9c10-bd5398c2e194","questionId":"e1ff1a01-2da8-5cde-ab47-b921537c5083","sourceKey":"bank:FIN216:F216-0088","payload":{"prompt":"The Nigeria Deposit Insurance Corporation (NDIC) commenced operations in the year:","options":["1987","1988","1989","1990"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC actually started operating in 1989, a few months after the law creating it was made. Option B (1988) is the tempting trap: that is the year NDIC was established by Decree No. 22, not the year it began operations. 1987 and 1990 do not match either milestone."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 10, $official_bank_source${"itemId":"8e3fca54-509d-5d0d-8d6e-9d7783f91bd5","questionId":"23c4b8d3-eafd-5196-9163-32f20f6deb7a","sourceKey":"bank:FIN216:F216-0088-b","payload":{"prompt":"The NDIC was established in 1988 by:","options":["The CBN Act of 1958","The NDIC Act No. 33 of 2023","The Banks and Other Financial Institutions Act (BOFIA) 2020","Decree No. 22 of 1988"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC was created by Decree No. 22 of 15 June 1988, during military rule, and started operations in 1989. Option B is a much later law that repealed and replaced the NDIC Act 2006, so it could not have created the NDIC in 1988. Option A established the Central Bank of Nigeria, and option C is the current law for licensing and regulating banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 11, $official_bank_source${"itemId":"78f82399-6c3a-5ef1-9977-912bff46e3f5","questionId":"47af4697-7130-5def-8a44-451dfa5471f4","sourceKey":"bank:FIN216:OVW-001","payload":{"prompt":"In 1983, a committee set up by the Board of the Central Bank of Nigeria to examine the operations of the Nigerian banking system recommended the establishment of a ____.","options":["Bank Recapitalisation Fund","Depositors Protection Fund","Asset Management Corporation","Financial Stability Fund"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The 1983 CBN committee recommended a Depositors Protection Fund, and that recommendation eventually led to the creation of the NDIC. Option D and option C name later rescue arrangements: a Financial Stability Fund for bank resolution costs and AMCON (2010) for buying bad loans. Option A is not what the committee proposed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 12, $official_bank_source${"itemId":"b1a7e902-1bd5-5efe-ab89-45ba4e1a284a","questionId":"cab7c834-83b4-5ba8-a8fe-d762d0e30422","sourceKey":"bank:FIN216:OVW-002","payload":{"prompt":"The committee whose report first recommended a deposit protection arrangement for Nigeria was set up by the Board of the Central Bank of Nigeria in which year?","options":["1986","1988","1983","1979"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The committee was set up in 1983 and recommended a Depositors Protection Fund. Option A is 1986, when the Structural Adjustment Programme began, and option B is 1988, when the NDIC itself was established by decree. Option D predates the committee."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 13, $official_bank_source${"itemId":"6fd56aef-6617-584e-a688-6274ff9d108c","questionId":"f87cdfb9-9992-5e12-a931-a49c48341c46","sourceKey":"bank:FIN216:OVW-003","payload":{"prompt":"The CBN committee that recommended a Depositors Protection Fund was set up in 1983, and the NDIC opened its doors for business in 1989. How many years passed between the two events?","options":["5 years","4 years","6 years","7 years"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"From 1983 to 1989 is 1989 - 1983 = 6 years. Option A (5 years) measures from 1983 to 1988, the year the decree was promulgated, not the year operations began. Options B and D are simple arithmetic slips."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 14, $official_bank_source${"itemId":"fb9035e4-6bd0-58eb-b1ad-a261daf7f376","questionId":"a65d265c-170b-55ba-aaa2-4c5e81b4a1e3","sourceKey":"bank:FIN216:OVW-005","payload":{"prompt":"The decree establishing the Nigeria Deposit Insurance Corporation was dated ____.","options":["1 January 1989","15 June 1986","26 May 1988","15 June 1988"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Decree No. 22 creating the NDIC is dated 15 June 1988; the Corporation then started operations in 1989. Option A confuses the decree with the start of operations, and option B has the right day but the year SAP began. Option C borrows the day and month of the 2023 Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 15, $official_bank_source${"itemId":"68b4721b-585e-5532-a2f2-f92987ec5986","questionId":"c2054a90-6232-5f59-b3e7-6c4fc66bc35e","sourceKey":"bank:FIN216:OVW-006","payload":{"prompt":"The 1988 decree that created the NDIC was repealed and re-enacted as ____.","options":["the CBN Act of 2007","the BOFI Act of 1991","the NDIC Act No. 16 of 2006","the NDIC Act No. 33 of 2023"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The 1988 Decree was repealed and re-enacted as the NDIC Act No. 16 of 2006. Option D is the 2023 Act, which in turn repealed the 2006 Act rather than the decree directly. Options A and B are banking and central bank laws, not the NDIC's own statute."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 16, $official_bank_source${"itemId":"333015b8-1313-5600-af64-33f35ecf5951","questionId":"4738a6d2-682f-5828-89af-53e3a6345267","sourceKey":"bank:FIN216:OVW-008","payload":{"prompt":"Which option lists the NDIC's governing laws in correct chronological order?","options":["Decree No. 22 of 1988, Act No. 16 of 2006, Act No. 33 of 2023","Act No. 16 of 2006, Decree No. 22 of 1988, Act No. 33 of 2023","Act No. 22 of 1983, Act No. 16 of 2006, Act No. 33 of 2023","Decree No. 22 of 1988, Act No. 33 of 2006, Act No. 16 of 2023"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC began under Decree No. 22 of 1988, which was replaced by the NDIC Act No. 16 of 2006, which was in turn repealed by the NDIC Act No. 33 of 2023. Option D swaps the numbers of the 2006 and 2023 Acts, and option B puts the 2006 Act first. Option C wrongly dates the first law to 1983, the year of the CBN committee."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 17, $official_bank_source${"itemId":"c3cea10b-bb2b-5b64-b0eb-0540a2f5f832","questionId":"cafe67c0-43ec-5fdc-bb56-7f469c6b3fce","sourceKey":"bank:FIN216:OVW-009","payload":{"prompt":"Which of the following was introduced by the NDIC Act 2023 and was absent from the NDIC Act 2006?","options":["A power for the NDIC to act as liquidator","An explicit statement of the NDIC's public policy objectives","A limit on the amount paid per depositor","A requirement that banks insure their deposits"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Section 2 of the NDIC Act 2023 states the public policy objectives of the deposit insurance system, which the 2006 Act did not do. Options A, C and D describe compulsory membership, the liquidator role and a coverage limit, all of which already existed under the earlier law."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 18, $official_bank_source${"itemId":"a08c5361-71f9-53c9-9deb-385052f2e8b1","questionId":"dcdf2ae8-c6f0-5aa6-9794-9c243f16562b","sourceKey":"bank:FIN216:OVW-010","payload":{"prompt":"Under the NDIC Act 2023, when can the NDIC begin paying insured deposits of a deposit-taking institution?","options":["Only after a court has wound up the institution","On revocation of its licence or on its actual suspension of payments","Only after the institution's assets have been sold","Only when shareholders approve the payment"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The 2023 Act allows insured deposits to be paid when the licence is revoked or when the institution actually suspends payments (with CBN concurrence). Option A and option C would make depositors wait for long court or asset-sale processes, which is exactly what fast payout tries to avoid. Option D is wrong because shareholders have no say in deposit insurance payouts."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 19, $official_bank_source${"itemId":"a3306583-12a7-5479-a514-a5914084a552","questionId":"e81ce565-4f9e-5ab8-b271-639fc659aeee","sourceKey":"bank:FIN216:OVW-011","payload":{"prompt":"The setting up of the NDIC in 1988 is best described as part of ____.","options":["the economic liberalisation efforts of the then military government","the IADI's programme for African deposit insurers","the recapitalisation of banks after the 2009 crisis","the banking consolidation exercise of the civilian government"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC was created as part of the economic liberalisation efforts of the military government of the time, to restore public confidence in banks. Option D refers to the 2004-2005 consolidation, option B to a body that was only formed in 2002, and option C to events two decades later."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 20, $official_bank_source${"itemId":"410c7ce8-c8a7-532c-9231-3b8d40e1cb94","questionId":"da942c62-352e-51fd-aa75-1af5a8b638c3","sourceKey":"bank:FIN216:OVW-012","payload":{"prompt":"Which economic programme, introduced in Nigeria in 1986, liberalised bank licensing and led to a rapid rise in the number of banks before the NDIC was created?","options":["Indigenisation Programme","Structural Adjustment Programme (SAP)","Financial System Strategy 2020","Banking Consolidation Programme"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The Structural Adjustment Programme of 1986 liberalised bank licensing, so the number of banks grew rapidly, which strengthened the case for explicit deposit insurance. Option A was a 1970s policy on Nigerian ownership, option D came in 2004-2005 and reduced the number of banks, and option C is a later strategy plan."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 21, $official_bank_source${"itemId":"96090a7c-8f43-5dcb-9bd9-12ef714ad11e","questionId":"9870108c-254c-5f71-94af-9149aee17f5a","sourceKey":"bank:FIN216:OVW-013","payload":{"prompt":"Following the liberalisation of bank licensing under SAP, the number of banks in Nigeria rose to about ____ by the early 1990s.","options":["25","89","120","55"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Bank numbers grew rapidly under SAP to about 120 by the early 1990s. Option A is the number of banks left after the 2005 consolidation, and option B is the number of banks before that consolidation. Option D is far below the early-1990s peak."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 22, $official_bank_source${"itemId":"a337874c-3506-522c-abbc-f1b5d75babca","questionId":"f071242c-e7a6-54c6-844b-61f31723cd17","sourceKey":"bank:FIN216:OVW-014","payload":{"prompt":"The proliferation of banks during the SAP era is linked to all of the following problems EXCEPT ____.","options":["sharp practices and window dressing","fraudulent activities in the foreign exchange market","inadequate manpower in banks","excess capital and very strong corporate governance"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Rapid growth in bank numbers heightened competition and led to sharp practices, window dressing, inadequate manpower and fraud in the foreign exchange market. Options A, B and C are all named consequences. Excess capital and strong governance are signs of a healthy system, not problems caused by proliferation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 23, $official_bank_source${"itemId":"ca6a36e6-09fc-5e9f-9b17-6f45f1c1bf34","questionId":"65eedfd1-d6d6-5236-a38d-0b5472be70e9","sourceKey":"bank:FIN216:OVW-015","payload":{"prompt":"The main impetus for establishing a deposit insurance scheme in Nigeria was the need to ____.","options":["raise revenue for the Federal Government from bank premiums","replace the CBN as the regulator of all deposit-taking banks","guarantee shareholders' investment in banks against all losses","protect small and medium depositors and assist banks so as to engender public confidence"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Deposit insurance was set up to protect depositors, especially small and medium ones, and to give technical and financial assistance to banks so that the public trusts the banking system. Option C is wrong because shareholders are not protected, and option A is wrong because premiums go into an insurance fund, not government revenue. Option B is wrong because the NDIC works alongside the CBN rather than replacing it."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 24, $official_bank_source${"itemId":"a2fc36b8-eaef-5633-85d8-8e225801eaad","questionId":"179ecddc-a993-5bdf-8f1d-c75840283f74","sourceKey":"bank:FIN216:OVW-017","payload":{"prompt":"When the NDIC began operations in 1989, banks paid a flat annual premium of 15/16 of 1 percent of total deposit liabilities. What premium would a bank with total deposit liabilities of N8 billion have paid?","options":["N120 million","N7.5 million","N750 million","N75 million"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"15/16 of 1 percent is 0.9375 percent, and 0.9375% x N8 billion = N75 million. Option C applies 9.375 percent and option B applies 0.09375 percent, both decimal-point slips. Option A wrongly uses 1.5 percent."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 25, $official_bank_source${"itemId":"bd66a53b-06ef-5f10-8db0-81636ed53682","questionId":"ed086c31-e28d-5d3b-8c85-4845b925f0a6","sourceKey":"bank:FIN216:OVW-018","payload":{"prompt":"In 2008 the NDIC moved from a flat-rate premium to a system in which each bank pays a base rate plus an add-on based on its riskiness. This system is known as ____.","options":["Pass-Through Deposit Insurance (PTDI)","Differential Premium Assessment System (DPAS)","Flat Premium Assessment System (FPAS)","Risk-Based Supervision Framework (RBSF)"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Under the Differential Premium Assessment System, the premium rate equals a base rate plus a risk-related add-on, so riskier banks pay more. Option C describes the old flat-rate approach it replaced, and option D is a supervision method, not a premium system. Option A is about insuring mobile money subscribers' pooled deposits."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 26, $official_bank_source${"itemId":"461d69ab-a1e8-5457-bbcd-9403bccee851","questionId":"3d921d32-5ac8-5290-9b79-ae22ed5aebb6","sourceKey":"bank:FIN216:OVW-022","payload":{"prompt":"Nigeria's deposit insurance arrangement is classified as an explicit guarantee mainly because ____.","options":["the coverage level and limits are stipulated by statute","there is no fund set aside for paying depositors","depositors merely assume the government will rescue banks","the decision to pay is negotiated only after a bank fails"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"An explicit guarantee rests on government declaration, with the level and limits of cover spelled out in legislation, as in the NDIC Act. Options B, C and D describe an implicit guarantee, which rests on public assumption with no rules, no fund and decisions made only when a failure occurs."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 27, $official_bank_source${"itemId":"98ebeece-42da-5e93-a2e3-07d597008ad3","questionId":"21c6fbdd-99df-538a-8619-014ca4c4eaaa","sourceKey":"bank:FIN216:OVW-024","payload":{"prompt":"Which of the following is one of the stated policy objectives of Nigeria's deposit insurance scheme?","options":["To facilitate the transition from blanket coverage to limited coverage","To finance government budget deficits with premiums","To replace bank supervision with deposit insurance","To provide blanket cover for all deposits without limit"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"One objective of the NDIC scheme is to help the system move away from blanket guarantees towards limited, rule-based cover. Option D is the opposite of that objective, option C is wrong because supervision remains a separate safety-net function, and option B misuses premiums, which go into the insurance fund."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 28, $official_bank_source${"itemId":"cc5b6d1a-08eb-5bcf-9be8-9346c23eca74","questionId":"95c6dfab-d512-5e5c-81d0-92cfdcac2aee","sourceKey":"bank:FIN216:OVW-026","payload":{"prompt":"Nigeria, through the NDIC, is one of the founding members of which international body launched in Basel in 2002?","options":["European Forum of Deposit Insurers (EFDI)","Financial Stability Board (FSB)","International Association of Deposit Insurers (IADI)","Basel Committee on Banking Supervision (BCBS)"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC is a founding member of the International Association of Deposit Insurers, launched in Basel in May 2002. Option B is the body that monitors the global financial system, option D sets bank supervision standards, and option A is a regional European forum, none of which was founded in 2002 with the NDIC as a founder."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 29, $official_bank_source${"itemId":"0317a992-2d59-5fe9-a4c4-6b0898362fe1","questionId":"3dc5e8a5-cbb3-56e6-a75e-084fdfa74ee2","sourceKey":"bank:FIN216:OVW-027","payload":{"prompt":"The establishment of the Federal Deposit Insurance Corporation (FDIC) in the United States was a response mainly to ____.","options":["the savings and loan crisis of the 1980s","the 1933 banking crisis and the Great Depression","the 2008 global financial crisis","the oil price shock of the 1970s"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The FDIC was created in 1933 after waves of bank failures during the Great Depression. Option C is the crisis behind Australia's Financial Claims Scheme, and options A and D happened decades after the FDIC was already in place."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 30, $official_bank_source${"itemId":"61414579-40fd-54f9-815c-9258f1740f4c","questionId":"5f404237-ae69-5d6a-9346-8cbaa05b138c","sourceKey":"bank:FIN216:OVW-028","payload":{"prompt":"The US Federal Deposit Insurance Corporation was created by the Banking Act of 1933. On what date did its deposit insurance cover actually begin?","options":["1 January 1934","1 January 1933","1 July 1935","16 June 1933"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The Banking Act creating the FDIC was signed on 16 June 1933, but insurance of deposits began on 1 January 1934. Option D is the date the law was signed, not the start of cover. Options B and C do not match either event."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 31, $official_bank_source${"itemId":"382ab812-d67c-5b94-8a7e-19555aae6b16","questionId":"97ec6e92-befa-55a2-b6b7-5b2a4655640b","sourceKey":"bank:FIN216:OVW-029","payload":{"prompt":"FDIC cover began in January 1934 at US$2,500 per depositor, and the standard cover as at 2026 is US$250,000 per depositor. How many times larger is the 2026 limit?","options":["25 times","1,000 times","100 times","10 times"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"US$250,000 / US$2,500 = 100, so the limit is 100 times its 1934 level. Option D and option B are slips of one decimal place either way, and option A confuses the 25 in 250,000 with the answer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 32, $official_bank_source${"itemId":"062e8887-838f-5384-af86-e8f36b49ec09","questionId":"5f088458-8a60-5e04-b7f2-67c6500220d2","sourceKey":"bank:FIN216:OVW-030","payload":{"prompt":"Before the FDIC was created, which American state had already introduced an insurance scheme for bank obligations in 1829?","options":["California","Texas","New York","Florida"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"New York introduced an insurance scheme for bank obligations in 1829, more than a century before the national FDIC. Options A, B and D are other states that did not start the 1829 scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 33, $official_bank_source${"itemId":"cb93806d-caf4-50ec-89ff-0cae4944e35f","questionId":"ce7c9390-9dbf-5a59-99d9-a896620026f2","sourceKey":"bank:FIN216:OVW-031","payload":{"prompt":"Which US law expanded the role of the FDIC after the 2008 crisis, extending its resolution role to bank holding companies and non-bank systemically important financial institutions?","options":["Dodd-Frank Act","Sarbanes-Oxley Act","Gramm-Leach-Bliley Act","Federal Reserve Act"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The Dodd-Frank Act widened the FDIC's role, so its remit covers depository institutions, bank holding companies and non-bank SIFIs. Option B deals with corporate accounting and audit, option C (1999) allowed banks and insurers to combine, and option D created the US central bank in 1913."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 34, $official_bank_source${"itemId":"3d589068-0161-5f1d-8a83-308cac09ca34","questionId":"c3eee87d-74c2-54de-be2d-934f53dc7189","sourceKey":"bank:FIN216:OVW-032","payload":{"prompt":"In the United States, the FDIC collaborates mainly with which two federal agencies in its supervisory work?","options":["The World Bank and the International Monetary Fund","The Securities and Exchange Commission and the Treasury","The Internal Revenue Service and the Federal Reserve","The Federal Reserve and the Office of the Comptroller of the Currency"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The FDIC works alongside the Federal Reserve and the Office of the Comptroller of the Currency, which also supervise US banks. Option B names a capital-market regulator and the finance ministry, option C pairs the tax authority with the Fed, and option A names international bodies rather than US agencies."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 35, $official_bank_source${"itemId":"4e507e42-0299-588f-8973-513136bf3902","questionId":"c4fdfe60-0472-5e3e-b6ee-7b311c19c332","sourceKey":"bank:FIN216:OVW-033","payload":{"prompt":"In which year did the European Union issue a directive requiring member states to establish deposit guarantee schemes?","options":["1994","2014","1984","2004"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Directive 94/19/EC of 1994 required every EU member state to have a deposit guarantee scheme, so all EU states have had explicit schemes since then. Option B is the year of the later directive that revised the rules, not the first one. Options C and D do not match either directive."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 36, $official_bank_source${"itemId":"bd3831b7-eb17-5250-a211-c6435ec21501","questionId":"ddcde1ad-e442-5870-8ec2-28ff2a8092e8","sourceKey":"bank:FIN216:OVW-034","payload":{"prompt":"Under EU rules, a retail depositor has EUR 130,000 in one bank in an EU member state when it fails. How much of this is covered by the national deposit guarantee scheme?","options":["EUR 130,000","EUR 100,000","EUR 85,000","EUR 30,000"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"EU law protects deposits up to EUR 100,000 per depositor per bank, so EUR 100,000 is covered and EUR 30,000 is not. Option A ignores the limit and option D is the uncovered part, not the covered part. Option C confuses the euro limit with the old UK limit in pounds."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 37, $official_bank_source${"itemId":"88893c6c-c332-5478-8475-5b9a89d5c1c2","questionId":"2d4bfec5-3f14-5677-b51b-8c6e6680a4b4","sourceKey":"bank:FIN216:OVW-035","payload":{"prompt":"Under the first EU deposit guarantee directive of 1994, depositors were usually paid within 3 months. Under Directive 2014/49/EU, the maximum payout period was phased down to how long from 2024?","options":["30 days","90 days","7 working days","20 working days"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Directive 2014/49/EU phased the payout period down to 7 working days from 2024, matching the international benchmark for fast reimbursement. Option D was an interim target set during the 2008 crisis, and option B is roughly the old 3-month period. Option A is not the EU standard."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 38, $official_bank_source${"itemId":"e3c07663-5f02-593a-8744-401219e48691","questionId":"3186eb82-bc56-5088-819b-87f067ee0efc","sourceKey":"bank:FIN216:OVW-036","payload":{"prompt":"In 2012 the European Council agreed a roadmap for completing Economic and Monetary Union through a Banking Union with three pillars. Which option correctly matches the pillars?","options":["SSM for deposit insurance, SRM for supervision, EDIS for resolution","SSM for supervision, SRM for resolution, EDIS for deposit insurance","SSM for resolution, SRM for supervision, EDIS for deposit insurance","SSM for supervision, SRM for deposit insurance, EDIS for resolution"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The first pillar is the Single Supervisory Mechanism (supervision), the second is the Single Resolution Mechanism (resolution) and the third is the European Deposit Insurance Scheme (deposit insurance). Options A, C and D each swap at least two of these functions; the names themselves tell you which job each pillar does."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 39, $official_bank_source${"itemId":"e57e5247-ba0c-5751-9673-2f47b4a25299","questionId":"c4c66675-7816-56bc-b520-06a29bf988e6","sourceKey":"bank:FIN216:OVW-037","payload":{"prompt":"Of the three pillars of the European Banking Union, which one had not yet been put in place when the first two were completed?","options":["The European Central Bank (ECB)","The Single Resolution Mechanism (SRM)","The European Deposit Insurance Scheme (EDIS)","The Single Supervisory Mechanism (SSM)"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The SSM and SRM were put in place, while the third pillar, a common European Deposit Insurance Scheme, remained a proposal. Options B and D are the two pillars already in operation. Option A is an institution that leads supervision, not a pillar awaiting adoption."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 40, $official_bank_source${"itemId":"1caf220c-bc6b-5763-b7ea-e1b9806f0e72","questionId":"9de0a5e3-d11c-54fd-b866-225f0152e07a","sourceKey":"bank:FIN216:OVW-038","payload":{"prompt":"Under the proposed European Deposit Insurance Scheme (EDIS), what would happen to the existing national deposit guarantee schemes?","options":["They would be abolished immediately","They would be merged into the ECB","They would stop covering retail deposits","They would remain in place and form part of EDIS"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Under EDIS, national deposit guarantee schemes would remain and be part of the scheme, playing an important role in the early stages while a European Deposit Insurance Fund insures them. Options A, B and C wrongly suggest that national schemes would disappear or stop protecting depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 41, $official_bank_source${"itemId":"7774d548-6a93-58ba-b38b-d6efbe542593","questionId":"cabd791a-4c59-558c-9473-7a2748aaba90","sourceKey":"bank:FIN216:OVW-039","payload":{"prompt":"In the proposed European Deposit Insurance Scheme, what happens to depositor coverage during the 'co-insurance period'?","options":["Coverage is shared between the European fund and the national scheme","Coverage is provided only by the ECB","Coverage is provided only by national schemes","Coverage is suspended until the fund is full"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"In the co-insurance period, the cost of covering deposits is shared between the European Deposit Insurance Fund and the national deposit guarantee schemes. Option C is closer to the earlier re-insurance stage, when national schemes do most of the paying out. Options B and D do not describe EDIS."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 42, $official_bank_source${"itemId":"40472b41-21a2-52ed-9532-f77bfa774f65","questionId":"d80d1e1f-659f-5b5d-854e-a2ebff20592c","sourceKey":"bank:FIN216:OVW-040","payload":{"prompt":"Within the European Banking Union, which institution is the main prudential supervisory authority for banks in the euro area?","options":["European Commission","Single Resolution Board (SRB)","European Central Bank (ECB)","European Council"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Supervision in the Banking Union is built around the European Central Bank as the main prudential supervisor of euro-area banks. Option B is the main authority for bank resolution, while options A and D are political bodies involved in approving resolution decisions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 43, $official_bank_source${"itemId":"6afbb082-6335-52b5-9afd-406debf79b84","questionId":"28108aba-cfff-55f7-b941-b62cdb24a5be","sourceKey":"bank:FIN216:OVW-041","payload":{"prompt":"Within the European Banking Union, which body is the main authority that decides on bank resolution?","options":["Single Resolution Board (SRB)","European Banking Authority (EBA)","European Investment Bank (EIB)","European Central Bank (ECB)"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The Single Resolution Board is the main authority for resolution decisions in the Banking Union. Option D determines whether a bank is failing and supervises banks, but does not take the main resolution decision. Options B and C are EU bodies with other jobs, such as development lending and rule-setting."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 44, $official_bank_source${"itemId":"85dcd5b6-d829-5018-95b7-c84c74cb291b","questionId":"e8070eee-be18-5411-be76-1905332317a0","sourceKey":"bank:FIN216:OVW-043","payload":{"prompt":"In the Banking Union's resolution procedure, decision-making typically involves all of the following EXCEPT ____.","options":["national authorities, which implement decisions","the ECB, which determines bank failure","the Single Resolution Board","the International Monetary Fund"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Resolution decisions in the Banking Union involve the ECB (determining failure), the Single Resolution Board, the Commission and the Council, with national authorities implementing them. Options A, B and C are all part of that chain. The IMF is an international lender and adviser, not an EU resolution decision-maker."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 45, $official_bank_source${"itemId":"f2883d4a-1a69-5e81-9101-b04d579bffbf","questionId":"4597f2a8-37cf-5bdc-b317-6a28e952cb1d","sourceKey":"bank:FIN216:OVW-044","payload":{"prompt":"Among EU stylised facts on deposit guarantee schemes (DGSs), which statement about administration is correct?","options":["DGSs must always be administered by banking associations","DGSs can be administered privately, publicly or by a combination of both","DGSs must always be administered by the central bank","DGSs must always be administered by the European Commission"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"EU deposit guarantee schemes may be run privately (for example by banking associations), publicly, or jointly. Options A, C and D each wrongly insist on a single type of administrator, which does not match the variety across member states."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 46, $official_bank_source${"itemId":"5e8067c5-9e13-504a-b053-96405931ee14","questionId":"dea5e210-6b93-51c4-af2f-c157eeab3e56","sourceKey":"bank:FIN216:OVW-045","payload":{"prompt":"According to EU stylised facts on deposit guarantee schemes, how can such schemes be financed?","options":["Ex ante or ex post, from public, private or both sources","Only ex post, from government budgets","Only from loans by the European Central Bank","Only ex ante, from depositors' fees"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"EU schemes may be funded ex ante (building a fund in advance) or ex post (collecting after a failure), using public money, private money or both. Options B, C and D each restrict funding to a single method or a single type of funder, which is not the case."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 47, $official_bank_source${"itemId":"e45766dc-77ed-513d-ac15-96223a8c41af","questionId":"fd8b3cc0-25b8-5a90-ae4e-60cda6c616f3","sourceKey":"bank:FIN216:OVW-046","payload":{"prompt":"Which of the following is an EU stylised fact about deposit guarantee schemes?","options":["Some countries, including Germany, have multiple schemes providing deposit protection","No EU scheme plays any role beyond paying out depositors","Implicit schemes are the norm in EU member states","Membership of every EU scheme is voluntary for banks"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Some countries, notably Germany, run more than one scheme to protect deposits. Option D is wrong because membership can be voluntary or compulsory, and option B is wrong because many schemes also help with resolution and restructuring. Option C is wrong because all EU states have had explicit schemes since 1994."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 48, $official_bank_source${"itemId":"c8cb0da1-248b-5a10-94ca-7f5bb2609813","questionId":"4c27dcc8-8824-5c99-a42a-b012b32a53da","sourceKey":"bank:FIN216:OVW-047","payload":{"prompt":"In the European Union, what is the most common way of organising a deposit guarantee scheme?","options":["As a department of the national treasury","As a legally separate scheme","As a branch of the European Central Bank","As a unit inside each commercial bank"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Legally separate schemes are the most common form of organisation in the EU, although a scheme can also sit within a ministry, the central bank or another supervisor. Option A is a possible but less common arrangement. Options C and D are not how EU schemes are organised."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 49, $official_bank_source${"itemId":"21cd478d-c290-5a3c-b472-bc827b7037be","questionId":"542ab8d6-9d2d-5712-a1a4-868b09109567","sourceKey":"bank:FIN216:OVW-048","payload":{"prompt":"The Deposit Insurance Corporation of India (DICI) was established in which year?","options":["1978","1971","1985","1962"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"India's Deposit Insurance Corporation began operating on 1 January 1962. Option B is the year the Credit Guarantee Corporation of India was set up, and option A is the year the two merged. Option C is the year of Taiwan's deposit insurance law."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 50, $official_bank_source${"itemId":"1b6b5b0b-cf71-5538-ac15-81e54b5112dc","questionId":"46df713c-09b6-5892-9b6d-42e9b55e45b3","sourceKey":"bank:FIN216:OVW-049","payload":{"prompt":"In 1978, the Deposit Insurance Corporation of India merged with the Credit Guarantee Corporation of India to form ____.","options":["Indian Financial Claims Scheme (IFCS)","Credit and Deposit Compensation Scheme (CDCS)","Reserve Bank Deposit Protection Board (RBDPB)","Deposit Insurance and Credit Guarantee Corporation (DICGC)"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The merger in 1978 created the Deposit Insurance and Credit Guarantee Corporation, which is wholly owned by the Reserve Bank of India. Options A, B and C are invented names that mix in terms from other countries' schemes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 51, $official_bank_source${"itemId":"a1a21d70-7cc4-59cf-8aa4-d94ec4476a00","questionId":"c5c8b789-1331-5058-afe8-c1697d927613","sourceKey":"bank:FIN216:OVW-050","payload":{"prompt":"Australia's deposit insurance arrangement, the Financial Claims Scheme (FCS), was set up in 2008 in response to ____.","options":["the global financial crisis","the Asian financial crisis of 1997","the collapse of the Australian mining boom","the Great Depression"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Australia created the Financial Claims Scheme in 2008 during the global financial crisis to protect depositors in authorised deposit-taking institutions. Option D was the crisis behind the US FDIC, and option B came about a decade earlier. Option C is not linked to the scheme's creation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 52, $official_bank_source${"itemId":"44222e04-503c-59e3-bc4a-b292732f5396","questionId":"e8e4fbe0-3b3f-5a91-9421-ce1832380e15","sourceKey":"bank:FIN216:OVW-051","payload":{"prompt":"Under Australia's Financial Claims Scheme, the institutions whose deposits are protected are called ____.","options":["primary mortgage institutions (PMIs)","authorised deposit-taking institutions (ADIs)","systemically important banks (SIBs)","deposit money banks (DMBs)"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Australia protects deposits held in authorised deposit-taking institutions, or ADIs. Option D and option A are Nigerian names for types of insured institutions, while option C refers to banks singled out for extra supervision, not the scheme's members."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 53, $official_bank_source${"itemId":"94ddae98-e3c8-5235-be8e-6148cf040bf2","questionId":"032e547e-1b23-5927-97f7-3a74e9d83925","sourceKey":"bank:FIN216:OVW-052","payload":{"prompt":"As at 2026, Australia's Financial Claims Scheme covers deposits up to what amount per account holder per authorised deposit-taking institution?","options":["A$250,000","A$100,000","A$85,000","A$1,000,000"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Australia's Financial Claims Scheme covers up to A$250,000 per account holder per ADI and is administered by APRA once activated by the government. Options B, C and D do not match the scheme's limit; A$85,000 echoes an old UK limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 54, $official_bank_source${"itemId":"1e8d6d0f-7b3b-5424-b780-27468cad86a8","questionId":"2d8dd299-d940-5813-b323-a17c98ecab71","sourceKey":"bank:FIN216:OVW-053","payload":{"prompt":"Brazil's deposit insurance scheme, set up in 1995, is financed through ____.","options":["loans from the International Monetary Fund","voluntary donations from large depositors","mandatory contributions from participating financial institutions","annual grants from the Brazilian federal budget"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Brazil's law does not support using government funds to rescue failing banks, so its scheme is funded by mandatory contributions from member institutions. Option D is the government money the law avoids, option A does not fund the scheme, and option B would not provide reliable funding."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 55, $official_bank_source${"itemId":"ce561f11-ad1f-55f1-8c4b-b2109ad7ea19","questionId":"cc16b137-45f3-5712-9a82-4bb379c6a6d9","sourceKey":"bank:FIN216:OVW-054","payload":{"prompt":"What is the name of the United Kingdom's deposit insurance scheme, set up in 2001?","options":["Financial Services Compensation Scheme (FSCS)","Prudential Regulation Authority (PRA)","Financial Claims Scheme (FCS)","Deposit Protection Fund Board (DPFB)"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The UK's scheme is the Financial Services Compensation Scheme, set up in 2001. Option C is Australia's scheme, option D is not the name of the UK's compensation scheme, and option B is the UK bank regulator rather than the compensation scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 56, $official_bank_source${"itemId":"d5f2b055-a3f8-53e6-93b0-d4396095a442","questionId":"a8f2c9b4-72ef-52a7-8a60-92f94eb17f54","sourceKey":"bank:FIN216:OVW-055","payload":{"prompt":"In January 2026, a UK resident had GBP150,000 in a single bank that failed. Under the FSCS deposit limit that took effect on 1 December 2025, how much of her deposit is protected?","options":["GBP85,000","GBP120,000","GBP150,000","GBP100,000"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"From 1 December 2025 the FSCS protects deposits up to GBP120,000 per depositor per bank, so GBP120,000 is covered and GBP30,000 is not. Option A was the limit before December 2025, option C ignores the limit, and option D confuses the UK limit with the EU's euro limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 57, $official_bank_source${"itemId":"14a86d27-59fc-553b-8f40-8cd16f184de3","questionId":"de53b1bc-fcbb-52b8-afaa-0e72da6a72a3","sourceKey":"bank:FIN216:OVW-056","payload":{"prompt":"As at 2026, the Kenya Deposit Insurance Corporation (KDIC) covers deposits up to what amount per depositor per member institution?","options":["KSh 100,000","KSh 250,000","KSh 500,000","KSh 5,000,000"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"As at 2026, KDIC covers up to KSh 500,000 per depositor per member institution. Options A, B and D do not match Kenya's limit; KSh 5,000,000 echoes the naira figure for Nigerian deposit money banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 58, $official_bank_source${"itemId":"992d0bd6-af4e-56cb-8856-8deb791700e7","questionId":"dd407baf-3de8-5d42-9d2a-3475138c06b9","sourceKey":"bank:FIN216:OVW-057","payload":{"prompt":"China moved from implicit protection to an explicit deposit insurance scheme when it launched one on 1 May 2015. What was its coverage level?","options":["5,000,000 yuan per depositor","500,000 yuan per depositor","100,000 yuan per depositor","50,000 yuan per depositor"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"China launched its scheme on 1 May 2015 with cover of 500,000 yuan, which protected over 99 percent of depositors in full. Options A and D are out by a factor of ten either way, and option C confuses the yuan figure with the EU's euro limit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 59, $official_bank_source${"itemId":"48e1f217-fa46-5df7-b662-cd4f7fc62b01","questionId":"bb83b10c-8d99-5419-a5da-63c912ad78a2","sourceKey":"bank:FIN216:OVW-058","payload":{"prompt":"When China launched explicit deposit insurance in May 2015 with cover of 500,000 yuan, about what share of depositors were fully covered?","options":["About 75 percent","About 50 percent","Over 99 percent","About 85 percent"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The 500,000 yuan limit fully covered over 99 percent of Chinese depositors (about 99.6 percent), which matches the international aim of protecting the large majority of depositors. Options A, B and D greatly understate the share covered."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 60, $official_bank_source${"itemId":"7b17f6f6-407a-53d1-8b69-71192beae408","questionId":"01f184e8-bcd2-5594-8f65-1a8b277e8a64","sourceKey":"bank:FIN216:OVW-060","payload":{"prompt":"Which of the following deposit insurers covers not only commercial banks but also insurance companies and securities companies?","options":["Nigeria Deposit Insurance Corporation (NDIC)","Deposit Protection Corporation of Zimbabwe","Kenya Deposit Insurance Corporation (KDIC Kenya)","Korea Deposit Insurance Corporation (KDIC)"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Korea's KDIC, set up in 1996, covers commercial banks, insurance companies, savings banks, securities companies and merchant banks. Option A covers deposit-taking institutions such as banks, microfinance banks and mortgage banks, not insurers or securities firms. Options B and C also focus on deposit-taking institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 61, $official_bank_source${"itemId":"0ca7dd6a-7a45-588c-981e-45d983e36416","questionId":"f133c068-613d-5830-ab73-19f1265a19e7","sourceKey":"bank:FIN216:OVW-062","payload":{"prompt":"Each of the following is correctly paired with its country's deposit insurer EXCEPT ____.","options":["United States - FDIC","India - DICGC","Nigeria - NDIC","Australia - FSCS"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The FSCS is the United Kingdom's scheme; Australia's is the Financial Claims Scheme. Options A, B and C are correct pairs: the NDIC in Nigeria, the FDIC in the US and the DICGC in India."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 62, $official_bank_source${"itemId":"dab1ad47-c873-5a67-8e6c-4037751f11ca","questionId":"10e69562-7103-5457-9033-b402cb90769d","sourceKey":"bank:FIN216:OVW-063","payload":{"prompt":"According to the World Bank's deposit insurance database, how many of 189 countries had explicit deposit insurance by year-end 2013?","options":["59","80","112","189"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"By the end of 2013, 112 of 189 countries had explicit deposit insurance. Option A is the percentage (about 59 percent), not the number of countries. Option B is a different figure altogether (it matches the number of IADI Members reported in 2016), and option D would mean every country had a scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 63, $official_bank_source${"itemId":"9f18b78a-8645-5cdf-8525-68c1fa1a87ae","questionId":"8e75f17f-7e3e-5abd-b344-c0a04af7640a","sourceKey":"bank:FIN216:OVW-064","payload":{"prompt":"According to the World Bank's 2016 Bank Regulation and Supervision Survey, what proportion of high-income countries have some form of explicit deposit insurance?","options":["Under 20 percent","Over 80 percent","About 40 percent","About 50 percent"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The 2016 survey found that over 80 percent of high-income countries have explicit deposit insurance, which shows that explicit schemes are standard in rich economies. Options A, C and D all understate how common explicit schemes are in that group."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 64, $official_bank_source${"itemId":"6938a4f2-84cb-5ba7-9a21-9f55ef768940","questionId":"4ed9bbaa-f024-55ff-82ac-c65813064ec7","sourceKey":"bank:FIN216:OVW-065","payload":{"prompt":"A deposit insurance scheme (DIS) is best defined as ____.","options":["a financial guarantee to protect depositors in the event of bank failure","a fund that guarantees bank profits during recessions","a loan facility from the central bank to illiquid banks","an insurance policy that protects bank shareholders' capital"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"A DIS is a financial guarantee that protects depositors when a bank fails and so gives the banking system a measure of safety. Option C describes the central bank's lender-of-last-resort role. Options B and D wrongly say the scheme protects owners or profits, when its focus is depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 65, $official_bank_source${"itemId":"2b29cbf3-f82f-53d2-9a44-7e0d95f494e5","questionId":"70a3b311-d362-5fb2-9242-ae2691659cea","sourceKey":"bank:FIN216:OVW-066","payload":{"prompt":"Deposit insurance is designed particularly to protect small savers because they ____.","options":["are required by law to keep all their savings in one bank","usually hold the largest share of a bank's total deposits","may not have adequate information on their banks' financial condition","are usually directors and shareholders of the banks"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Small savers often cannot judge the financial health of their banks because they lack adequate information, so they are least able to protect themselves. Option B is wrong because big depositors usually hold most of the value. Option A is not a legal rule, and option D describes insiders, whose deposits are often excluded from cover."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 66, $official_bank_source${"itemId":"dd15465f-9407-50df-ac08-d9f22024d4a5","questionId":"8048488e-d47b-5c1b-ac95-5e3c4a7aa7f2","sourceKey":"bank:FIN216:OVW-069","payload":{"prompt":"What are the two broad options for implementing deposit protection in a country?","options":["Ex ante and ex post funding","Public and private ownership","Pay-box and risk minimiser","Explicit and implicit deposit insurance"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Countries either have explicit deposit insurance, set out in law or contract, or rely on implicit protection, where there is no formal system. Option C lists mandate types within explicit schemes, option A lists funding methods, and option B lists ownership forms."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 67, $official_bank_source${"itemId":"b0ba99e1-c3fc-528f-80ca-bbb4423efe16","questionId":"7c2de5ab-356c-5323-951b-a2dad5a2c390","sourceKey":"bank:FIN216:OVW-070","payload":{"prompt":"Under an implicit deposit insurance arrangement, ____.","options":["there is no formal funding and no unambiguous government commitment to compensate depositors","banks pay risk-based premiums into a dedicated fund","a separate agency is set up by statute to reimburse depositors","depositors are covered up to a fixed limit set by law"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Implicit protection has no formal system: no formal funding and no clear government commitment to compensate depositors when a bank fails. Options B, C and D all describe features of an explicit scheme, which is set up by law with defined limits, funding and an agency."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 68, $official_bank_source${"itemId":"5118dda6-9438-5e97-a9a1-b08cad16f2e0","questionId":"bd6ecc14-0963-5bb1-8aae-6dd751e6e8b2","sourceKey":"bank:FIN216:OVW-071","payload":{"prompt":"An explicit deposit insurance scheme is established by ____.","options":["a decision taken only after a bank has failed","legislation or private contract that spells out its mandate, powers and governance","an informal promise made by bank managers to customers","public belief that government will rescue failing banks"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"An explicit DIS is created by law or private contract that sets out its mandate, powers, governance, funding, coverage and reimbursement rules. Options A and D describe implicit protection, which rests on public belief and decisions made after failure. Option C has no legal force."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 69, $official_bank_source${"itemId":"aa6af403-e377-5afa-8cae-444dd603400e","questionId":"28d3743a-d0bf-5649-bf35-77ba63496c94","sourceKey":"bank:FIN216:OVW-077","payload":{"prompt":"Which of the following is NOT one of the novel deposit insurance practices implemented by the NDIC?","options":["Risk-based bank supervision","Risk-based premium pricing","Unlimited blanket coverage of all deposits","The bridge-banking model"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The NDIC has introduced risk-based supervision, continuous review of coverage, risk-based premiums, closed bank resolution and the bridge-bank model, which covers options A, B and D. Nigeria uses limited, explicit coverage rather than unlimited blanket cover."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 70, $official_bank_source${"itemId":"a96cadb1-bcbe-5164-bfd4-895e20d8b418","questionId":"5f055f9b-61c5-514e-88c8-15062295e853","sourceKey":"bank:FIN216:OVW-082","payload":{"prompt":"Chinedu keeps savings in a microfinance bank in Lagos whose deposits are insured with the NDIC. Which element of a deposit insurance scheme does Chinedu represent?","options":["Insured depositor","Deposit insurance institution","Insured financial institution","Supervisory institution"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Chinedu is an insured depositor because he holds deposits in an institution covered by the NDIC. Option C is the microfinance bank itself, option B is the NDIC, and option D is a body such as the CBN."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 71, $official_bank_source${"itemId":"e4feaf58-5307-5002-aef5-4b0cceb393e5","questionId":"b59cf29d-80b7-5e8b-9d7f-38c54eaf17b4","sourceKey":"bank:FIN216:OVW-083","payload":{"prompt":"The NDIC in Nigeria, the FDIC in the United States and the FSCS in Britain are all examples of which element of a deposit insurance scheme?","options":["Central bank","Deposit insurance institution","Insured financial institution","Supervisory institution"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"These are deposit insurance institutions: the bodies that give depositors cover when a bank fails. Option D refers to supervisors of the scheme, option C refers to the banks whose deposits are insured, and option A is the reinsurance-type backstop."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 72, $official_bank_source${"itemId":"bc656d69-a9f8-5887-9f1e-7dfe32e6e629","questionId":"8659116e-a0a9-5ddc-a028-ac7555669edc","sourceKey":"bank:FIN216:OVW-084","payload":{"prompt":"Among the basic elements of a deposit insurance scheme, the central bank is described as acting as a form of ____ because it guarantees the deposits of the deposit insurance institution.","options":["co-insurance","blanket insurance","self-insurance","reinsurance"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The central bank backs the deposit insurer, so it acts like a reinsurer standing behind the insurer. Option A means sharing a loss with the insured party, option C means bearing your own risk, and option B refers to unlimited cover of deposits, none of which fits this role."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 73, $official_bank_source${"itemId":"3c8c3129-9923-5a18-844d-3e4fa196a778","questionId":"bd056313-4a7d-5025-9e32-62d9eca07437","sourceKey":"bank:FIN216:OVW-085","payload":{"prompt":"As a basic element of a deposit insurance scheme, what role can government play?","options":["Acting only as a depositor in insured banks","Acting as an agency of the scheme or as an implicit or explicit guarantor","Acting only as a borrower from the insurance fund","Acting as the sole shareholder of every insured bank"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Government can be an agency of the deposit insurance scheme or stand behind it as an implicit or explicit guarantor. Options A, C and D describe narrow or incorrect roles that are not how government fits into a deposit insurance scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 74, $official_bank_source${"itemId":"6828fdc6-ba07-57ef-8699-f22208338e67","questionId":"759882b9-0fbe-5502-bb90-b91eae0e033f","sourceKey":"bank:FIN216:OVW-086","payload":{"prompt":"In a deposit insurance scheme, the body that oversees the scheme, which may be a central bank, is called the ____.","options":["insured institution","supervisory institution","liquidating institution","eligible institution"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The supervisory institution oversees the deposit insurance scheme, and in many countries this is the central bank. Option A refers to the banks whose deposits are covered. Options C and D are not among the basic elements of a scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 75, $official_bank_source${"itemId":"6b217175-9449-5c95-8590-063ce77d1eaf","questionId":"d274326a-360b-52f6-b9a1-793fe7446c3a","sourceKey":"bank:FIN216:OVW-087","payload":{"prompt":"A guarantee promise to protect depositors can take which three forms?","options":["Explicit, implicit and ambiguous","Public, private and mixed","Pay-box, loss minimiser and risk minimiser","Explicit, blanket and partial"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"A guarantee promise for protecting deposits can be explicit, implicit or ambiguous. Option D mixes in coverage types, option B lists ownership structures, and option C lists mandate types of explicit schemes."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 76, $official_bank_source${"itemId":"198596dd-0086-5f66-a014-972e0c5f3f5d","questionId":"f5d151a3-44ca-5c2b-a144-dc3c8ac4eace","sourceKey":"bank:FIN216:OVW-088","payload":{"prompt":"A guarantee promise that is based on public assumption, with no rules on coverage, no funds set aside and decisions negotiated only when a bank fails, is called ____.","options":["an explicit guarantee","a pass-through guarantee","an implicit guarantee","an ambiguous guarantee"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"An implicit guarantee rests only on the public's assumption that depositors will be protected, so there are no rules or funds and decisions are made at the time of failure. Option A is set out in law with clear limits, and option D is neither explicit nor implicit. Option B is a way of extending explicit cover to the customers behind a pooled account."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 77, $official_bank_source${"itemId":"f9e821dc-d731-5196-9ba3-9a1bee7b5795","questionId":"0fe33dda-0361-5c3c-a35b-ee3190dddde8","sourceKey":"bank:FIN216:OVW-089","payload":{"prompt":"A guarantee promise that is based on governmental declarations, with the level and limits of cover usually stipulated by legislation, is called ____.","options":["an explicit guarantee","an implicit guarantee","a blanket guarantee","an ambiguous guarantee"],"correctOption":0,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"An explicit guarantee is formally declared by government and its level and limits are set in legislation, as with Nigeria's NDIC Act. Option B rests only on public assumption, and option D is neither explicit nor implicit. Option C covers deposits without the normal limits, usually only in a crisis."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 78, $official_bank_source${"itemId":"833de5ee-6762-51f2-900d-2cdf7e1f32e7","questionId":"7ae1ec0d-82aa-5762-86cf-ce15d2579d0c","sourceKey":"bank:FIN216:OVW-090","payload":{"prompt":"Which type of guarantee promise is neither explicit nor implicit, and is considered suitable mainly where the banking system is owned almost entirely by strong foreign financial institutions?","options":["Explicit guarantee","Ambiguous guarantee","Implicit guarantee","Blanket guarantee"],"correctOption":1,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"An ambiguous guarantee is neither explicit nor implicit, and experts see it as workable mainly when strong foreign banks own nearly the whole banking system. Option A has statutory limits, and option C rests on public assumption of rescue. Option D is a crisis-time promise to protect all deposits."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 79, $official_bank_source${"itemId":"1489779b-1c4c-5da3-926d-ded375644996","questionId":"ef6e52c6-452c-5d6f-bd9b-314cc8120bdf","sourceKey":"bank:FIN216:OVW-091","payload":{"prompt":"In the country of Zedland there is no deposit insurance law and no deposit insurance fund, but depositors widely believe the government will step in if a large bank fails. What type of guarantee promise does Zedland have?","options":["Pass-through guarantee","Ambiguous guarantee","Implicit guarantee","Explicit guarantee"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Zedland has an implicit guarantee because protection rests only on the public's belief in a rescue, with no law, fund or rules. Option D would need a statute setting coverage and limits. Option B is a guarantee that is neither explicit nor implicit, and here the public clearly assumes a rescue. Option A is a feature of explicit schemes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 80, $official_bank_source${"itemId":"40c6b6ec-1703-5a37-9734-6228d4335dc8","questionId":"7d8b9f92-dba3-517c-b584-f15a66e87c38","sourceKey":"bank:FIN216:OVW-092","payload":{"prompt":"A country passes a law creating a deposit insurer, requiring all banks to pay premiums into a fund and stating that each depositor is covered up to a fixed amount. Which type of guarantee promise has it adopted?","options":["Blanket guarantee","Implicit guarantee","Ambiguous guarantee","Explicit guarantee"],"correctOption":3,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"A law that sets up an insurer, a fund and a stated coverage limit is an explicit guarantee. Option B has no rules or funds, and option C is neither explicit nor implicit. Option A would protect deposits without any limit, but this law sets a fixed maximum."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 81, $official_bank_source${"itemId":"38ed16c6-9bd0-5f67-aca3-d33fc32fcad0","questionId":"509e998a-36e2-5bbc-bd0b-5ca7d9f5ab85","sourceKey":"bank:FIN216:OVW-093","payload":{"prompt":"Which feature best distinguishes an explicit deposit guarantee from an implicit one?","options":["Explicit cover protects shareholders; implicit cover protects depositors","Explicit cover applies only to foreign banks; implicit cover applies only to local banks","Explicit cover has limits and funding set in advance by law; implicit cover is decided only after failure","Explicit cover is always run privately; implicit cover is always run by government"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"The key difference is certainty: explicit cover has its limits, funding and rules fixed in law before any failure, while implicit cover depends on decisions made after a bank fails. Option A is wrong because neither form is meant to protect shareholders. Options B and D invent ownership and bank-nationality rules that do not define either type."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 82, $official_bank_source${"itemId":"c264efb8-4bd4-5501-a00f-9205307ea2a3","questionId":"c143eaf1-babe-5d1b-b5e7-52125f1368ab","sourceKey":"bank:FIN216:OVW-094","payload":{"prompt":"Which type of deposit insurance arrangement is described as the preferred arrangement in global practice?","options":["No deposit protection","Ambiguous deposit protection","Explicit deposit insurance","Implicit deposit insurance"],"correctOption":2,"section":"Overview of Deposit Insurance in Nigeria and Globally","explanation":"Explicit deposit insurance is the preferred arrangement because clear rules, funding and limits give depositors certainty and reduce panic. Options B and D leave depositors unsure of what they will get, which can trigger runs. Option A gives depositors no protection at all."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 83, $official_bank_source${"itemId":"45f19d1a-4a60-5fe5-823d-9a483fda1111","questionId":"07472cab-e341-5517-9810-a31b6a46a73d","sourceKey":"bank:FIN216:F216-0002","payload":{"prompt":"Which of the following countries operates both a statutory (public) deposit protection scheme and private, bank-association-run protection funds?","options":["Slovakia","Switzerland","Germany","Nigeria"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Germany is the classic example of a country with multiple deposit protection schemes: a statutory scheme exists alongside private protection funds run by banking associations. Option D is wrong because Nigeria has a single, publicly owned insurer, the NDIC. Switzerland's scheme is a self-regulatory arrangement run by the banks themselves, and Slovakia relies on a single national fund, so neither combines public and private schemes the way Germany does."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 84, $official_bank_source${"itemId":"87aba49f-85fb-5809-9396-67c42acfdc85","questionId":"749ab93d-c0e0-5034-a0f5-188a9353f1eb","sourceKey":"bank:FIN216:F216-0011","payload":{"prompt":"Which of the following is NOT a recognised mandate type of a deposit insurer?","options":["Risk minimiser","Pay box","Loss minimiser","Cost maximiser"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Deposit insurers are grouped by mandate as pay box, pay box plus, loss minimiser and risk minimiser, so a \"cost maximiser\" does not exist; no deposit insurer aims to make failures more expensive. A pay box only collects premiums and reimburses depositors, a loss minimiser actively picks least-cost resolution strategies, and a risk minimiser like the NDIC adds supervision and early intervention powers. Those three are all real mandate types."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 85, $official_bank_source${"itemId":"bdaff65c-0d1a-5f57-b74e-2e05b35564e2","questionId":"eb4358b6-e1fc-5ebe-8d90-ab5a8430cbbc","sourceKey":"bank:FIN216:F216-0019","payload":{"prompt":"Which of the following is NOT an ownership structure of deposit insurance schemes?","options":["Public-private (joint)","Private","Sole","Public"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Deposit insurance schemes are owned or administered publicly by government, privately by banks or banking associations, or jointly by both. \"Sole\" is not one of these categories. The NDIC, for example, is publicly owned by the CBN and the Federal Ministry of Finance, while some countries use private or joint arrangements, so options A, B and D are all real structures."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 86, $official_bank_source${"itemId":"d4ccebd1-664c-522e-ab00-2d4503645e71","questionId":"e1f090c0-d7a5-5558-b2bd-e92310e8f869","sourceKey":"bank:FIN216:F216-0027","payload":{"prompt":"Which of the following is a requirement of a well-designed deposit insurance scheme?","options":["Incentive compatibility","Deregulation of power","Exemption of weak banks from membership","Unlimited coverage of all deposits"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Incentive compatibility means the scheme is designed so that banks and depositors are not encouraged to take more risk just because deposits are insured, which is how moral hazard is kept in check. Option D is wrong because good practice is limited coverage, leaving large depositors with a reason to monitor their banks. Letting weak banks opt out would undermine the fund, and deregulation of power is not a design requirement at all."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 87, $official_bank_source${"itemId":"ba623798-2c62-522d-a417-cdf5710125e2","questionId":"ddecbc32-48e9-59a9-9d29-146b9c8a828f","sourceKey":"bank:FIN216:F216-0028","payload":{"prompt":"A deposit insurer that, in addition to paying depositors and resolving failed banks, has powers to supervise insured institutions and intervene early to protect insured deposits is called a ____","options":["Pay box plus","Pay box","Risk minimiser","Loss minimiser"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"A risk minimiser has the widest mandate: risk assessment, supervision, early intervention and a full set of resolution powers, and the NDIC is an example. Option D is the closest distractor, since a loss minimiser chooses least-cost resolution methods but usually has no supervisory powers. A pay box only reimburses depositors, and a pay box plus adds just some resolution functions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 88, $official_bank_source${"itemId":"ea07ee97-1dab-5330-a46e-192ba2049dc1","questionId":"f24160ca-6aa4-56c2-a937-acfcf8e67f4a","sourceKey":"bank:FIN216:F216-0031","payload":{"prompt":"Which of the following types of deposit guarantee is operated by the Nigeria Deposit Insurance Corporation?","options":["Implicit","Explicit","Ambiguous","Contingent"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"An explicit scheme is one where the guarantee is written into law, with clear rules on coverage, funding, membership and payout, and that is exactly how the NDIC operates. Option A, an implicit guarantee, rests only on the public's belief that government will not let banks fail, with no formal commitment or fund behind it. Options C and D are not recognised types of deposit insurance."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 89, $official_bank_source${"itemId":"987a9fb6-a156-5033-b4d2-caf680109a6b","questionId":"19f7c58a-183e-5a93-b8b1-1505fa8ed36b","sourceKey":"bank:FIN216:F216-0051","payload":{"prompt":"In deposit insurance, what does the abbreviation DIS commonly stand for?","options":["Deposit Insurance Scheme","Deposit Insurers' Supervision","Deposit Insurance Scope","Deposit Investment Scheme"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"DIS stands for Deposit Insurance Scheme, the arrangement that protects depositors up to a set limit if their bank fails; it is also often expanded as Deposit Insurance System, which means the same thing. Option C confuses the abbreviation with the scope of cover, option D wrongly turns it into an investment product, and option B describes supervision of insurers rather than protection of depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 90, $official_bank_source${"itemId":"f6538849-d41c-5e45-b69c-763fd79ca04d","questionId":"6d948883-05f5-5307-b18e-260dceea7488","sourceKey":"bank:FIN216:CON-001","payload":{"prompt":"A financial guarantee that protects depositors in the event of bank failure and also offers a measure of safety for the banking system is called a","options":["lender of last resort facility","deposit insurance scheme","prudential regulation framework","bank recapitalisation programme"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"A deposit insurance scheme guarantees depositors that they will be repaid, up to a limit, if their bank fails, and in doing so it adds a layer of safety to the whole banking system. Option A is the central bank lending to banks with temporary liquidity problems, not a guarantee to depositors. Options C and D are about rules for banks and injecting capital into banks, not about protecting depositors' funds."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 91, $official_bank_source${"itemId":"0326fd94-1a4a-5f56-b06c-229fc402df9a","questionId":"358c1e18-0740-5fb5-b1e8-db6b3c3fe6ad","sourceKey":"bank:FIN216:CON-002","payload":{"prompt":"Which of the following best describes a deposit insurance scheme?","options":["A facility through which the central bank lends to banks short of liquidity","A policy that insures a bank's loan book against borrower default","A guarantee that reimburses depositors, up to set limits, when an insured bank fails","A fund that compensates shareholders when a bank's share price falls"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Deposit insurance protects depositors: if an insured bank fails, depositors are paid back up to the coverage limit. Option A describes the lender of last resort role of a central bank. Option B is credit insurance for lenders, and option D is wrong because deposit insurance never protects shareholders' investment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 92, $official_bank_source${"itemId":"f66cd8cb-7f39-55e8-8653-25f98e38c962","questionId":"f3f0b430-71af-5523-8b25-05be23f9eb3c","sourceKey":"bank:FIN216:CON-003","payload":{"prompt":"A deposit insurance scheme is designed to save particularly which group of people?","options":["Large corporate depositors with access to detailed bank data","Foreign investors who hold shares in local banks","Small savers who may lack adequate information on their banks' financial condition","Banks that lend to one another in the interbank market"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Small savers usually cannot study a bank's accounts or judge its soundness, so deposit insurance is built mainly to protect them. Option A describes sophisticated depositors who can monitor banks themselves and are the group usually left partly exposed. Options B and D are investors and banks, not the small depositors the scheme targets."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 93, $official_bank_source${"itemId":"4283c012-eff0-50e0-bf65-e44e84b64963","questionId":"50a0aceb-3960-524f-b53f-095f30368bbd","sourceKey":"bank:FIN216:CON-004","payload":{"prompt":"Which of the following is NOT a benefit of a deposit insurance scheme?","options":["It protects depositors against full or partial loss of their savings","It reduces bank runs and contributes to financial stability","It creates a formal mechanism for addressing bank failure","It guarantees that no insured bank will ever fail"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Deposit insurance does not stop banks from failing; it makes sure that when a bank does fail, insured depositors are protected and the failure is handled in an orderly way. Options A, B and C are all genuine benefits of a deposit insurance scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 94, $official_bank_source${"itemId":"685317e0-0308-5e3d-bb63-ebf188b00825","questionId":"d84a16b8-e1ea-5140-a8ff-24789e43ccb2","sourceKey":"bank:FIN216:CON-005","payload":{"prompt":"Which of the following is a benefit of a deposit insurance scheme?","options":["It removes the need for banks to be supervised","It guarantees every deposit in full, whatever its size","It ensures shareholders of failed banks are repaid in full","It can limit the government's fiscal and political exposure when banks fail"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"With a formal, pre-funded scheme, the cost of protecting depositors is not left to the government's budget and political pressure each time a bank fails. Option A is wrong because supervision is still needed and even helps contain the risks deposit insurance creates. Option B is wrong because cover is limited, and option C is wrong because shareholders are never protected by deposit insurance."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 95, $official_bank_source${"itemId":"f58fd7a6-279d-545b-a8f8-b1b4bacad801","questionId":"d4e52c93-d40b-5a72-bfd7-be9f58ec3760","sourceKey":"bank:FIN216:CON-006","payload":{"prompt":"Before Country K set up deposit insurance, its government used tax money to rescue every failing bank. It then created an explicit scheme funded by premiums from banks. Which deposit insurance objective does this change mainly serve?","options":["Promoting competition among deposit-taking institutions","Contributing to an orderly payment system mechanism","Redistributing the cost of bank failure away from taxpayers","Facilitating the move from limited to blanket coverage"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"When banks pay premiums into a fund, the cost of failures is shared by the banking industry instead of falling on taxpayers, which is the objective of redistributing the cost of failure. Options A and B are genuine objectives but are not what this change is about. Option D reverses a real objective: the aim is to move from blanket coverage to limited coverage, not the other way round."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 96, $official_bank_source${"itemId":"f50343cf-c2be-58ea-9c8a-712eae66d2ef","questionId":"6b8faee0-1491-52a2-9e5b-efe653ff1ce9","sourceKey":"bank:FIN216:CON-007","payload":{"prompt":"Which of the following is NOT a policy objective of the deposit insurance scheme in Nigeria?","options":["To promote competition amongst deposit-taking financial institutions","To guarantee the profits of insured banks","To facilitate transitioning from blanket coverage to limited coverage","To contribute to an orderly payment system mechanism"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Deposit insurance protects depositors and the stability of the system; it does not protect a bank's profits, which are the owners' business risk. Options A, C and D are all listed policy objectives of Nigeria's scheme, alongside protecting small depositors, supporting financial stability, providing a failure-resolution mechanism and redistributing the cost of failure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 97, $official_bank_source${"itemId":"9ea875cc-391e-51e4-8a27-3baef174119e","questionId":"9f680ec9-57d2-50c2-b46d-43ae4b9a1ac5","sourceKey":"bank:FIN216:CON-008","payload":{"prompt":"Under the NDIC Act 2023, the public policy objectives of deposit insurance in Nigeria include all of the following EXCEPT","options":["fixing the interest rates banks pay on savings deposits","protecting depositors, especially small and less-informed ones, through an orderly means of compensation","contributing to the stability of the financial system","providing a framework for the resolution and orderly exit of failing and failed institutions"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Section 2 of the NDIC Act 2023 sets out three public policy objectives: protecting depositors (especially small, less-informed ones), contributing to financial system stability, and providing a framework for resolving and closing failing and failed institutions in an orderly way. Options B, C and D are those objectives. Setting interest rates is a monetary policy matter for the central bank, not a deposit insurance objective."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 98, $official_bank_source${"itemId":"4c50b1b9-03cc-5014-89cf-514508b908d8","questionId":"db16255a-fbce-51eb-87f0-b8e8585a31e4","sourceKey":"bank:FIN216:CON-009","payload":{"prompt":"Under the NDIC Act 2006, which statement about the public policy objectives of Nigeria's deposit insurance scheme was correct?","options":["They were stated in Section 2 of the 2006 Act","They were not stated in the Act; they were later spelt out in the NDIC Act 2023","They were fixed each year by a CBN circular","They were set by IADI rules that bound Nigeria directly"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"The 2006 Act gave the NDIC its powers but did not state the public policy objectives of the scheme, which was a gap compared with international practice; the NDIC Act 2023 filled it in Section 2. Option A confuses the two Acts. Options C and D are wrong because objectives of a statutory scheme belong in the law itself, and IADI guidance is not binding law in Nigeria."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 99, $official_bank_source${"itemId":"45e4e040-1c78-5b5a-83ae-2460fcd19938","questionId":"2058b309-a2cb-5688-b550-cde0be651af2","sourceKey":"bank:FIN216:CON-011","payload":{"prompt":"A small new bank in Ibadan is able to attract savings because customers know their deposits are protected up to the same limit as deposits in the biggest banks. Which deposit insurance objective does this illustrate?","options":["Promoting competition among deposit-taking institutions","Redistributing the cost of bank failure","Limiting the government's fiscal exposure","Providing a formal mechanism for failure resolution"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Because every insured bank's depositors enjoy the same protection, small banks can compete for deposits with big ones, which promotes competition. Options B, C and D are real objectives or benefits of deposit insurance, but none of them explains why savers are willing to use a small bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 100, $official_bank_source${"itemId":"26fc1fa0-da57-5074-a000-fed8d502afdf","questionId":"a10f1eb9-403f-5402-9928-47ad5becd4c9","sourceKey":"bank:FIN216:CON-012","payload":{"prompt":"A deposit insurance system established by legislation or private contract that spells out its mandate, powers, governance, funding, coverage limits and reimbursement rules is","options":["an implicit deposit insurance system","an explicit deposit insurance system","a blanket guarantee","an ambiguous guarantee"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"An explicit scheme is written down in law or contract, so its mandate, funding, coverage and rules are known in advance. Option A has no formal rules or funding. Option C is a declaration protecting deposits beyond normal limited cover, and option D is protection that is neither clearly explicit nor implicit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 101, $official_bank_source${"itemId":"c0aaff2c-0046-512a-91e3-d554965a8026","questionId":"5363c9e0-922f-511a-ba1a-bf11a30c642b","sourceKey":"bank:FIN216:CON-013","payload":{"prompt":"Where there is no formal deposit protection system, no formal means of funding and no clear government commitment to compensate depositors, but people believe the government will step in when banks fail, deposit protection is","options":["explicit","risk-minimising","implicit","ex ante funded"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Implicit protection rests only on the expectation that the government will not let depositors lose their money, without any law, fund or set limits. Option A is the opposite, a scheme written in law. Options B and D describe features of formal explicit schemes, namely a mandate type and a funding method."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 102, $official_bank_source${"itemId":"d11c43f7-114f-5d3e-9a4a-34aba1907cea","questionId":"6597ceac-466b-561c-8df1-864083a49efd","sourceKey":"bank:FIN216:CON-014","payload":{"prompt":"Which of the following is a feature of implicit deposit protection?","options":["Coverage limits are set out in a statute","Premiums are collected from banks before any failure","Membership is made compulsory by law","Whether and how depositors are compensated is decided only when a bank fails"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Under implicit protection there are no rules on coverage and no fund set aside, so decisions about compensating depositors are negotiated at the time of failure. Options A, B and C are all features of an explicit scheme, which fixes coverage, funding and membership in advance."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 103, $official_bank_source${"itemId":"0713825a-2ff8-5b28-b498-220dfe00b7e6","questionId":"28ce62db-dde8-53d4-ab32-e79bf84bbd14","sourceKey":"bank:FIN216:CON-015","payload":{"prompt":"Which of the following would NOT normally be spelt out in the law that sets up an explicit deposit insurance scheme?","options":["Coverage and compensation limits","Funding arrangements of the scheme","Rules guiding participation by insured institutions","The dividend each insured bank must pay its shareholders"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"The law for an explicit scheme sets out its mandate, powers, governance, membership rules, funding, coverage limits, failure resolution and reimbursement of depositors. Options A, B and C are all such provisions. A bank's dividend policy is decided by its board and shareholders within banking rules, not by the deposit insurance law."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 104, $official_bank_source${"itemId":"d3d13241-a4e1-54e9-93f6-77461caf8dfc","questionId":"fb792dc1-5b73-50d2-a797-505be1fa2fa0","sourceKey":"bank:FIN216:CON-016","payload":{"prompt":"Nigeria's deposit insurance system is classified as explicit mainly because","options":["the government has informally promised to rescue large banks","the CBN decides case by case whether to repay depositors","banks signed a voluntary private pact to help each other","its mandate, coverage, funding and membership are set out in the NDIC Act"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Nigeria's scheme is created and governed by statute, the NDIC Act, which fixes who is insured, how much is covered and how the scheme is funded, so it is explicit. Options A and B describe implicit or discretionary protection. Option C is wrong because membership in Nigeria is compulsory by law, not a voluntary pact."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 105, $official_bank_source${"itemId":"48960702-9495-5615-a4c5-b716f64bb4ae","questionId":"3e2def2b-2ced-5dd2-896b-e9e16cff211a","sourceKey":"bank:FIN216:CON-017","payload":{"prompt":"Which statement correctly contrasts explicit and implicit deposit protection?","options":["Implicit schemes have pre-set coverage limits; explicit schemes rely on government discretion","Explicit schemes cover all deposits without limit; implicit schemes cover only small deposits","Both have formal funding and differ only in who owns the insurer","Explicit schemes have pre-set coverage and funding rules; implicit protection rests on the expectation of government support"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"The difference is formality: an explicit scheme sets coverage, funding and rules in law before any failure, while implicit protection relies only on the belief that government will step in. Option A reverses the two. Option B is wrong because explicit schemes normally have limited cover, and option C is wrong because implicit protection has no formal funding at all."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 106, $official_bank_source${"itemId":"2ace7e98-72a4-50b9-bb2d-c587c8896ff7","questionId":"099ba066-9d71-5af7-9370-e8e9ca133609","sourceKey":"bank:FIN216:CON-018","payload":{"prompt":"China introduced deposit insurance on 1 May 2015 with cover of 500,000 yuan per depositor. This is best described as","options":["a move from explicit to implicit deposit protection","a move from implicit to explicit deposit protection","a switch from a risk minimiser to a paybox mandate","the introduction of a blanket guarantee on all deposits"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Before 2015 Chinese depositors relied on an implied state guarantee; the 2015 scheme put a formal, limited cover into law, which is a move to explicit protection. Option A reverses the direction. Option D is wrong because a fixed 500,000 yuan limit is limited cover, not a blanket guarantee, and option C confuses this with a change of mandate."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 107, $official_bank_source${"itemId":"84e4b07b-e330-50cc-9f96-21d8759f5bc7","questionId":"81de0ff0-31cb-5b37-8d50-3f0209f037e6","sourceKey":"bank:FIN216:CON-019","payload":{"prompt":"A declaration by the authorities that, in addition to the protection provided by limited deposit insurance coverage, certain deposits and possibly other financial instruments will be protected is called","options":["co-insurance","pass-through coverage","a deposit payoff","a blanket guarantee"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"A blanket guarantee goes beyond the normal limited cover, usually announced in a crisis to stop panic. Option A makes depositors bear part of the loss, which is the opposite. Option B extends cover to the beneficial owners of pooled accounts, and option C is the act of paying out insured deposits after a bank closes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 108, $official_bank_source${"itemId":"9bea447f-bbf0-5ef9-b36a-60d2578ff55b","questionId":"7259dec9-5600-5abf-83a0-05e92fa7bedc","sourceKey":"bank:FIN216:CON-021","payload":{"prompt":"Which of the following is NOT one of the four deposit insurance mandates identified by IADI?","options":["Paybox plus","Loss minimiser","Risk minimiser","Profit maximiser"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"IADI groups deposit insurer mandates into paybox, paybox plus, loss minimiser and risk minimiser, from the narrowest to the broadest set of powers. Options A, B and C are three of those four. A deposit insurer is a public-interest body, so 'profit maximiser' is not a mandate type."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 109, $official_bank_source${"itemId":"205c1945-9566-5adb-9649-21346530c091","questionId":"8551d394-1483-5935-bb37-2bfab8e74cbc","sourceKey":"bank:FIN216:CON-022","payload":{"prompt":"A deposit insurer that is responsible only for reimbursing insured deposits when a bank fails operates which mandate?","options":["Paybox","Paybox plus","Loss minimiser","Risk minimiser"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"The paybox is the narrowest mandate: the insurer simply pays insured depositors. Option B adds certain resolution functions, option C actively chooses least-cost resolution strategies, and option D adds supervision and early intervention powers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 110, $official_bank_source${"itemId":"ba35ec8e-9739-58f2-ba72-a0616991d33b","questionId":"e1b29fdf-ec19-5c9a-aefb-cc9b9ed573c1","sourceKey":"bank:FIN216:CON-023","payload":{"prompt":"The role of a paybox deposit insurer is limited to","options":["supervising banks and enforcing prompt corrective action","choosing the least-cost resolution option for failing banks","collecting premiums, managing the insurance fund and reimbursing insured depositors","setting prudential regulations for all deposit-taking banks"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"A paybox collects premiums, looks after the fund and pays depositors when a bank fails, and nothing more. Options A and D describe powers of a risk minimiser. Option B describes a loss minimiser."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 111, $official_bank_source${"itemId":"6c6d3eb1-bd37-5a8e-bade-38a671682a7f","questionId":"86c54497-076a-50db-9c77-ee20eb9f5705","sourceKey":"bank:FIN216:CON-024","payload":{"prompt":"To reimburse depositors in a timely and efficient way when banks fail, a paybox system needs","options":["appropriate authority, access to deposit information and adequate funding","the power to license and revoke bank licences","the power to set the monetary policy rate","ownership of the banks whose deposits it insures"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Even a paybox cannot pay quickly unless the law gives it authority, it can get accurate depositor records, and it has money ready. Option B belongs to the bank licensing authority, usually the central bank. Options C and D are not needed to reimburse depositors at all."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 112, $official_bank_source${"itemId":"957f710e-432d-5c4e-a910-af02b9ca7b2a","questionId":"6cd316c8-bb55-5e31-8a49-72ce728c72e5","sourceKey":"bank:FIN216:CON-025","payload":{"prompt":"A deposit insurer that reimburses depositors and also has certain limited resolution functions, such as giving financial support to a failing bank, but does not actively choose among least-cost strategies or supervise banks, has which mandate?","options":["Paybox","Loss minimiser","Risk minimiser","Paybox plus"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Paybox plus is a paybox with some extra resolution responsibilities, such as financial support. Option A only pays depositors. Option B actively selects from a range of least-cost resolution strategies, and option C also has supervision and early intervention powers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 113, $official_bank_source${"itemId":"33626f56-98b2-5c5e-a60a-acb3c2e09307","questionId":"32c639b0-b991-5ae5-9da5-c46fd3b99162","sourceKey":"bank:FIN216:CON-026","payload":{"prompt":"A deposit insurer that actively engages in selecting from a range of least-cost resolution strategies has which mandate?","options":["Paybox","Paybox plus","Loss minimiser","Risk minimiser"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"The loss minimiser's defining feature is choosing the resolution method that costs the fund least. Option A only pays depositors and option B has only certain limited resolution functions. Option D goes further still, adding risk assessment, early intervention and, in some cases, prudential oversight."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 114, $official_bank_source${"itemId":"06042ded-3adf-56a7-adbb-add4662ba74a","questionId":"65d7714d-b849-5ab7-b3a6-82642b64ab51","sourceKey":"bank:FIN216:CON-027","payload":{"prompt":"Which of the following correctly describes a loss minimiser deposit insurer?","options":["It has full prudential oversight and sets regulations for banks","It determines resolution and receivership strategies and optimises recoveries, but in most cases has no supervisory powers","It only collects premiums and reimburses insured depositors","It licenses new banks and acts as lender of last resort"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"A loss minimiser has wide resolution tools, decides how failed banks are handled, manages claims and maximises recoveries, but usually does not supervise banks. Option A describes a risk minimiser and option C a paybox. Option D describes central bank functions, not a deposit insurer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 115, $official_bank_source${"itemId":"ded4dd90-3c2e-5b84-ae2f-8502e151cf9a","questionId":"9a0ee89c-5497-5cdf-bd34-c0f55719a0c8","sourceKey":"bank:FIN216:CON-029","payload":{"prompt":"Which deposit insurance mandate has the widest set of powers and is therefore best placed to contribute to financial stability?","options":["Paybox","Paybox plus","Risk minimiser","Loss minimiser"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"A risk minimiser can supervise, intervene early, enforce corrective action and resolve failing banks, so it can act before losses arise. Options A and B mainly pay depositors after failure. Option D has wide resolution tools but in most cases no supervisory powers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 116, $official_bank_source${"itemId":"e7833ad0-809f-5b76-afe1-5abec5708471","questionId":"131d1e87-b805-57ae-895f-5ee1b848016e","sourceKey":"bank:FIN216:CON-030","payload":{"prompt":"The Nigeria Deposit Insurance Corporation (NDIC) operates which type of deposit insurance mandate?","options":["Paybox","Paybox plus","Risk minimiser","Loss minimiser"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"The NDIC guarantees deposits, supervises insured institutions with the CBN, resolves failing banks and liquidates failed ones, which makes it a risk minimiser. Option A would only pay depositors. Options B and D lack the supervisory powers the NDIC has."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 117, $official_bank_source${"itemId":"28c770c6-664e-56fe-b894-2960069fecd2","questionId":"86b492b3-88ee-57d9-afe4-305159b6c0e1","sourceKey":"bank:FIN216:CON-031","payload":{"prompt":"The NDIC Act makes the NDIC a risk minimiser rather than a paybox mainly by","options":["giving it powers to supervise insured institutions","limiting it to collecting premiums from banks","making it privately owned by the insured banks","removing its power to liquidate failed banks"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Supervisory power is what moves a deposit insurer from merely paying depositors to actively reducing risk in the banks it insures. Option B describes a paybox. Option C is wrong because the NDIC is publicly owned, and option D is wrong because the NDIC is the liquidator of failed insured institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 118, $official_bank_source${"itemId":"ddf425d2-8620-5e98-baf0-07739134d206","questionId":"67f76a72-8d37-5339-b886-13a67f13e92c","sourceKey":"bank:FIN216:CON-032","payload":{"prompt":"The deposit insurer of Country A collects premiums and pays insured depositors whenever the central bank closes a bank. It plays no part in supervising banks or deciding how failed banks are resolved. Its mandate is","options":["paybox plus","loss minimiser","risk minimiser","paybox"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"An insurer that only collects premiums and pays depositors is a paybox. Option A would also have some resolution functions. Option B would choose the least-cost resolution method, and option C would supervise banks as well."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 119, $official_bank_source${"itemId":"68a12acd-5a8d-55e7-a22d-b96e31b53cbf","questionId":"904370e0-145b-5fac-9dd2-c33dc09d20a9","sourceKey":"bank:FIN216:CON-033","payload":{"prompt":"The deposit insurer of Country B does not supervise banks, but when a bank fails it compares purchase and assumption, a bridge bank and a deposit payoff, and chooses whichever costs its fund the least. Its mandate is","options":["paybox","paybox plus","risk minimiser","loss minimiser"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Actively choosing the least-cost resolution option, without supervisory powers, is the mark of a loss minimiser. Option A would simply pay depositors. Option B has only certain limited resolution functions, and option C would also supervise banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 120, $official_bank_source${"itemId":"88d6e157-281b-5e10-a4c5-3074a97ac82c","questionId":"99af42a5-8e32-53e8-ae2d-220c4d672543","sourceKey":"bank:FIN216:CON-034","payload":{"prompt":"The deposit insurer of Country C examines banks on-site, analyses their returns off-site, issues directives to correct unsafe practices and resolves failing banks. Its mandate is","options":["loss minimiser","risk minimiser","paybox plus","paybox"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Supervision, enforcement and prompt corrective action on top of resolution powers make this a risk minimiser, like the NDIC. Option A usually has no supervisory powers. Options C and D are focused on paying depositors with, at most, limited resolution roles."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 121, $official_bank_source${"itemId":"a38cb44a-93ed-5db7-8219-3d2d7ca45a3c","questionId":"23fd11ac-54ed-5c20-a38f-a1119db9a25e","sourceKey":"bank:FIN216:CON-035","payload":{"prompt":"The deposit insurer of Country D pays insured depositors and can also provide financial support to a failing bank and act as liquidator, but it does not supervise banks or select among least-cost strategies. Its mandate is","options":["paybox","loss minimiser","paybox plus","risk minimiser"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Paybox plus means paying depositors plus certain resolution functions such as financial support and liquidation. Option A would only pay depositors. Option B would actively choose least-cost resolution strategies, and option D would also supervise banks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 122, $official_bank_source${"itemId":"e19e9bdc-8df8-5e8f-8013-faa254fab292","questionId":"3420fe1c-d9fd-547e-8b93-64dbf5050ac3","sourceKey":"bank:FIN216:CON-036","payload":{"prompt":"Which statement correctly distinguishes a paybox from a risk minimiser?","options":["A paybox supervises banks; a risk minimiser only reimburses insured depositors","A paybox only reimburses insured depositors; a risk minimiser also has supervisory, early intervention and resolution powers","Both supervise banks, but only a risk minimiser collects premiums","A risk minimiser cannot pay depositors; it can only supervise banks"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"The two sit at opposite ends of the range: the paybox only pays depositors, while the risk minimiser also supervises, intervenes early and resolves failing banks. Option A reverses them. Option C is wrong because a paybox does not supervise and also collects premiums, and option D is wrong because a risk minimiser still guarantees and pays insured deposits."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 123, $official_bank_source${"itemId":"ddf797b0-a3dc-5a81-85ae-5fcfa87c3766","questionId":"928ea3cd-6049-59fb-a4af-3c34942924cf","sourceKey":"bank:FIN216:CON-037","payload":{"prompt":"What mainly distinguishes a risk minimiser from a loss minimiser?","options":["The loss minimiser supervises banks, which a risk minimiser cannot do","The risk minimiser cannot take part in resolving failed banks","The risk minimiser has supervisory and prudential oversight powers, which a loss minimiser in most cases lacks","The loss minimiser only reimburses depositors and has no resolution role"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Both have strong resolution roles, but the risk minimiser adds supervision, enforcement and prompt corrective action to reduce risk before failure. Option A reverses the two. Option B is wrong because a risk minimiser has a full suite of resolution powers, and option D describes a paybox."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 124, $official_bank_source${"itemId":"801bfa88-9ae5-531f-82d5-36fb861fbab5","questionId":"7e596824-4d89-58ba-80c9-c1461c9e3c1a","sourceKey":"bank:FIN216:CON-038","payload":{"prompt":"Lessons from the global financial crisis led many deposit insurance systems to migrate","options":["from risk minimiser mandates back to the pure paybox model","from explicit schemes to implicit protection","from compulsory membership to voluntary membership","from the paybox model towards mandates involving more supervision and resolution"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"As financial stability became a central goal, many insurers were given wider roles in supervision and resolution instead of only paying depositors. Option A reverses this trend. Options B and C go against the post-crisis push for explicit schemes with compulsory membership."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 125, $official_bank_source${"itemId":"dd975582-2003-55ee-a34e-c51da89e3c73","questionId":"2a37668d-a062-5735-bd30-d20c0f1445d4","sourceKey":"bank:FIN216:CON-039","payload":{"prompt":"After the global financial crisis, the main goal of deposit insurance shifted from primarily protecting small depositors towards","options":["maintaining financial stability","maximising the insurer's investment income","protecting the shareholders of failing banks","financing government budget deficits"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"The crisis showed that depositor panic can threaten the whole system, so deposit insurers came to see financial stability as a major objective alongside depositor protection. Option B is not a policy goal. Option C is wrong because deposit insurance does not protect shareholders, and option D is a fiscal matter."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 126, $official_bank_source${"itemId":"b161b7c0-51a5-5dce-b36c-5ed677784925","questionId":"f279443e-29b4-5727-b5d1-943b3f7ebf6f","sourceKey":"bank:FIN216:CON-040","payload":{"prompt":"A deposit insurance scheme run by a banking association and financed by its member banks, with no government ownership, is","options":["publicly administered","jointly (public-private) administered","privately administered","an implicit scheme"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"When the banking industry itself owns and runs the scheme, it is privately administered. Option A would be owned or run by government or the central bank, and option B would combine public and private bodies. Option D is wrong because a scheme run under formal arrangements by an association is explicit, not implicit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 127, $official_bank_source${"itemId":"4c44f752-884e-56d8-9648-df50ec90427f","questionId":"581dd235-c16a-5ab1-a3fb-58c3bb4372da","sourceKey":"bank:FIN216:CON-041","payload":{"prompt":"The NDIC's paid-up capital was contributed 60 percent by the Central Bank of Nigeria and 40 percent by the Federal Ministry of Finance. Its ownership is therefore best described as","options":["public","private","mixed public-private","mutual (owned by insured banks)"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Both owners, the CBN and the Federal Ministry of Finance, are government bodies, so the NDIC is publicly owned. Option C is tempting because there are two owners, but a mixed structure needs a private-sector owner such as the banks. Options B and D are wrong because insured banks pay premiums but do not own the NDIC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 128, $official_bank_source${"itemId":"f5197cbc-4f47-5df3-b5d1-b50714859e92","questionId":"ef805684-467e-5ff5-b939-aa094fd99561","sourceKey":"bank:FIN216:CON-043","payload":{"prompt":"India's Deposit Insurance and Credit Guarantee Corporation (DICGC) is wholly owned by the Reserve Bank of India. It is therefore an example of","options":["a privately owned deposit insurer","a mixed public-private deposit insurer","a publicly owned deposit insurer","implicit deposit protection"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"A deposit insurer owned entirely by the central bank is publicly owned. Options A and B would need private-sector ownership. Option D is wrong because the DICGC is a formal statutory insurer, which makes India's protection explicit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 129, $official_bank_source${"itemId":"61b1b203-0523-58cf-bc84-fb660bb43cbe","questionId":"314651f1-b6a1-5791-9057-ee5156829af5","sourceKey":"bank:FIN216:CON-044","payload":{"prompt":"Which of the following deposit insurers is privately run?","options":["India's DICGC","Brazil's Fundo Garantidor de Creditos (FGC)","Nigeria's NDIC","Taiwan's Central Deposit Insurance Corporation"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Brazil's FGC is a private non-profit body funded by contributions from its member institutions. Option A is owned by the Reserve Bank of India, option C by the CBN and the Federal Ministry of Finance, and option D by Taiwan's government through its finance ministry and central bank, so all three are public."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 130, $official_bank_source${"itemId":"d66d3059-de42-500d-a772-5f682854f483","questionId":"b11b3e2a-ffe4-5259-a249-6143950b9a11","sourceKey":"bank:FIN216:CON-045","payload":{"prompt":"Switzerland's esisuisse is a self-regulatory organisation formed by banks and securities firms to protect depositors. Its administration is best described as","options":["private (run by the industry)","public (run by the government)","run by the central bank","implicit protection"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"A scheme set up and run by the banks and securities firms themselves is privately administered. Options B and C would need the state or central bank to run it. Option D is wrong because esisuisse is a formal arrangement with set rules, so the protection is explicit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 131, $official_bank_source${"itemId":"f1b90329-0575-512c-87ef-9f2dc6e2cc96","questionId":"8c4bebaa-52dc-56b3-b1ac-8021ca7ac25a","sourceKey":"bank:FIN216:CON-046","payload":{"prompt":"Taiwan's Central Deposit Insurance Corporation is government-owned, with capital provided jointly by the Ministry of Finance and the central bank. Its ownership is","options":["public","private","mixed public-private","owned by insured banks"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Both owners are state bodies, so the corporation is publicly owned, just like the NDIC. Option C is a trap: having two owners does not make ownership mixed unless one of them is private. Options B and D are wrong because banks and private investors do not own it."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 132, $official_bank_source${"itemId":"97d83042-e661-5d73-8dae-86e19fb86c69","questionId":"fa86de17-fc94-5d51-ae3a-ddc45bbe852d","sourceKey":"bank:FIN216:CON-047","payload":{"prompt":"A deposit insurance scheme set up and run jointly by public authorities and the private banking industry is said to have","options":["public administration","mixed (public-private) administration","private administration","implicit administration"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"When government bodies and the banking industry share in running the scheme, administration is mixed. Option A is run by government alone and option C by the industry alone. Option D is not an administration type; implicit protection has no formal scheme to administer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 133, $official_bank_source${"itemId":"4828acf0-377f-5e3a-bff4-c229073c4983","questionId":"5f4b724b-a27c-5771-b448-b8ae2d4dda9d","sourceKey":"bank:FIN216:CON-048","payload":{"prompt":"Which statement about how deposit guarantee schemes can be organised is correct?","options":["A scheme must always be a separate privately owned company","A scheme must always be a department of the ministry of finance","A scheme can only operate as a unit inside a commercial bank","A scheme may be a separate legal entity or part of a ministry, the central bank or another supervisory authority"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Countries organise deposit insurance in different ways: some create a separate body, while others place the scheme within the central bank, the ministry or the supervisor. Options A and B wrongly insist on one fixed form. Option C is wrong because an insurer cannot sit inside one of the banks it insures."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 134, $official_bank_source${"itemId":"c2f091b5-b94e-5f76-8029-79e29cae8e1d","questionId":"934e855d-ed9f-5fca-a849-9d5e9076af39","sourceKey":"bank:FIN216:CON-049","payload":{"prompt":"World Bank data for 2013 showed that about two-thirds of the world's deposit insurance schemes were administered","options":["privately","jointly by public and private bodies","by the International Association of Deposit Insurers","publicly"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"About 66 percent of schemes in the 2013 data were run by public bodies, making public administration the most common form. Options A and B are real forms but much less common. Option C is wrong because IADI sets standards and does not administer national schemes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 135, $official_bank_source${"itemId":"0e38153d-b411-51ea-82f2-1e2821de9242","questionId":"276b9f7a-f706-5754-913f-25518e3cb9f6","sourceKey":"bank:FIN216:CON-050","payload":{"prompt":"When the law requires every licensed deposit-taking institution in a country to join the deposit insurance scheme, membership is","options":["compulsory","voluntary","optional for small banks","implicit"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Compulsory membership means no licensed deposit-taker can stay outside the scheme. Option B lets each bank decide, and option C is a form of voluntary membership. Option D describes a type of deposit protection, not a membership rule."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 136, $official_bank_source${"itemId":"23d33bc1-0df9-52bf-8df4-c0c2b6655005","questionId":"5f739725-64a5-5605-8c3d-9986021ac3a0","sourceKey":"bank:FIN216:CON-051","payload":{"prompt":"Under a voluntary deposit insurance scheme, riskier banks are keen to join while safer banks stay out because they see little value in paying premiums. This problem is called","options":["adverse selection","moral hazard","contagion","subrogation"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Adverse selection happens when those most likely to claim are the ones who choose to buy insurance, leaving the fund loaded with weak banks. Option B is the extra risk-taking that insurance encourages after a bank is covered. Option C is the spread of runs or failures from one bank to others, and option D is the insurer stepping into depositors' claims after paying them."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 137, $official_bank_source${"itemId":"f6e552c6-c359-586e-9fa7-44660d3157f4","questionId":"7ec3778f-dfd6-55ce-bdc0-e2a2d5aeb4b6","sourceKey":"bank:FIN216:CON-052","payload":{"prompt":"The 2014 IADI Core Principles state that membership in a deposit insurance system should be compulsory for all banks. A main reason is to prevent","options":["adverse selection, where mainly weak banks join the scheme","subrogation of insured depositors' claims","pass-through coverage of pooled accounts","deposit payoffs to insured depositors"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"If membership were optional, strong banks could stay out and the fund would be left covering mostly risky banks; making it compulsory spreads the risk across all banks. Options B, C and D are normal parts of how deposit insurance works, not problems that compulsory membership is meant to prevent."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 138, $official_bank_source${"itemId":"3dbfcad9-1790-5722-9ff4-3fffd7b29b88","questionId":"6382b3ee-36d9-5da3-b477-f1540c582389","sourceKey":"bank:FIN216:CON-053","payload":{"prompt":"In Country M, joining the deposit insurance scheme is voluntary. After five years only weak banks have joined, while strong banks have stayed out. This outcome illustrates","options":["moral hazard","market discipline","adverse selection","co-insurance"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"When the riskiest banks select themselves into a voluntary scheme, the insurer faces adverse selection and a fund exposed to high losses. Option A is about insured banks taking more risk after joining, not about who joins. Option D is depositors bearing part of a loss, and option B is depositors and markets punishing risky banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 139, $official_bank_source${"itemId":"0e990fe0-ebc6-5b73-98a3-4bf89669553e","questionId":"6d3bd3ce-530f-56ea-b1ba-1c6798bce788","sourceKey":"bank:FIN216:CON-056","payload":{"prompt":"A deposit insurance funding method in which premiums are collected regularly from member banks to build up a fund before any failure occurs is called","options":["ex post funding","co-insurance","ex ante funding","a blanket guarantee"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Ex ante means 'beforehand': the fund is built from regular premiums so money is ready when a bank fails. Option A collects money from surviving banks only after a failure. Option B is about depositors sharing losses, and option D is a broad crisis guarantee."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 140, $official_bank_source${"itemId":"84a62b57-f29d-585f-8ae1-a97c778c4db3","questionId":"86469d29-7309-56ca-be5a-2a12a7dad33a","sourceKey":"bank:FIN216:CON-060","payload":{"prompt":"Under the 2014 IADI Core Principles, funding for a deposit insurance system should be provided","options":["only on an ex post basis","only from the government's annual budget","from contributions by depositors","on an ex ante basis"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Core Principle 9 (2014) says funding should be ex ante, so money is available to pay depositors promptly. Option A is the approach the principle moves away from. Options B and C are wrong because the main funding should come from premiums paid by member banks, not taxpayers or depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 141, $official_bank_source${"itemId":"cab2e35c-dcfc-5237-85d2-583681b578c8","questionId":"dfb0d8d0-c7cc-553f-8ba0-9f791571ed1b","sourceKey":"bank:FIN216:CON-063","payload":{"prompt":"Suppose a deposit insurer charges a bank a base premium of 0.35 percent plus a risk add-on of 0.15 percent per annum on assessable deposits of N400 billion. What premium does the bank pay for the year?","options":["N1.4 billion","N0.6 billion","N2.0 billion","N20.0 billion"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"The total rate is 0.35 + 0.15 = 0.50 percent, and 0.50 percent of N400 billion is N2.0 billion. Option A uses only the base rate (0.35 percent), and option B uses only the add-on (0.15 percent). Option D treats 0.50 percent as 5 percent."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 142, $official_bank_source${"itemId":"aa0aad0e-8ad2-534b-97d5-eccaae51d7bf","questionId":"98902d3d-75e1-5ad6-8306-c5063b938cbd","sourceKey":"bank:FIN216:CON-064","payload":{"prompt":"A deposit insurance scheme funded ex ante charges a flat premium of 0.5 percent per annum of assessable deposits. What premium does a bank with assessable deposits of N120 billion pay for the year?","options":["N60 million","N600 million","N6 billion","N1.2 billion"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"0.5 percent of N120 billion is 0.005 x 120,000,000,000 = N600 million. Option A uses 0.05 percent and option C uses 5 percent. Option D uses 1 percent instead of 0.5 percent."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 143, $official_bank_source${"itemId":"0621bd24-d5bd-5f02-99f1-c95e5c115d92","questionId":"874e8a00-1a1e-5966-9f25-134049ebf937","sourceKey":"bank:FIN216:CON-065","payload":{"prompt":"The tendency of parties to accept more risk because the costs that arise from that risk are borne by others is called","options":["moral hazard","adverse selection","contagion","market discipline"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Moral hazard is the danger that protection changes behaviour: insured banks and depositors take more risk because someone else will carry the loss. Option B is about which banks choose to join a voluntary scheme. Option C is the spread of distress from one bank to others, and option D is the pressure that uninsured creditors put on risky banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 144, $official_bank_source${"itemId":"78aca9a3-6d7f-55df-a473-34811eb233bc","questionId":"4a996277-f0c6-5c72-9f67-356424099a8e","sourceKey":"bank:FIN216:CON-066","payload":{"prompt":"After deposit insurance was introduced, the managers of Bank Z began granting very risky, high-interest loans, reasoning that insured depositors would not withdraw their funds and the insurer would bear much of any loss. This is an example of","options":["adverse selection","a bank run","moral hazard","co-insurance"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Taking extra risk because the insurer and others will bear the cost is moral hazard. Option A concerns which banks choose to join a voluntary scheme. Option D is a design feature in which depositors share losses, and option B is a sudden mass withdrawal of deposits."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 145, $official_bank_source${"itemId":"ddd76720-b6f5-5a40-92cf-71ca000195dd","questionId":"0746ed2a-9e12-55fe-a2c2-3da02888c75a","sourceKey":"bank:FIN216:CON-067","payload":{"prompt":"Mr Adeyemi's savings are fully covered by deposit insurance, so he picks the bank offering the highest interest rate without checking whether it is sound. When many depositors behave like this, what is weakened?","options":["The insurer's ex ante fund","Compulsory membership of the scheme","Market discipline on risky banks","The lender of last resort role of the central bank"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Fully protected depositors stop watching their banks, so risky banks no longer lose deposits or pay more for them; this is how moral hazard weakens market discipline. Options A, B and D are not directly affected by how carefully depositors choose their banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 146, $official_bank_source${"itemId":"6697a136-1a24-5be6-95fc-681a31f86916","questionId":"24c1630e-5c7e-5f8d-910d-168ba9163899","sourceKey":"bank:FIN216:CON-068","payload":{"prompt":"Which of the following is NOT a way of limiting moral hazard in a deposit insurance system?","options":["Limited coverage levels","Unlimited cover for all deposits regardless of size","Risk-based (differential) premiums","Timely intervention and resolution of weak banks"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Unlimited cover removes any reason for depositors to watch their banks, so it increases moral hazard rather than limiting it. Options A, C and D are design features that contain moral hazard, along with strong supervision and holding parties at fault responsible."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 147, $official_bank_source${"itemId":"01d1f0f5-a4c1-578d-94a7-c6528d394a1c","questionId":"cfcbbb1f-cf7b-53b7-8fa5-89b29bd85d4a","sourceKey":"bank:FIN216:CON-069","payload":{"prompt":"Which deposit insurance design feature limits moral hazard by making banks that take more risk pay more for their cover?","options":["Flat-rate premiums","Blanket guarantees","Ex post funding","Risk-based (differential) premiums"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"When premiums rise with a bank's risk, the bank feels a direct cost for risky behaviour, which counters moral hazard. Option A charges every bank the same rate, so risk-taking is not penalised. Option B increases moral hazard, and option C is about timing of collection, not pricing risk."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 148, $official_bank_source${"itemId":"ce261449-3fa8-5fa0-831f-0e288ce9861c","questionId":"55089837-eb6c-5e68-8afe-c31f682a98ca","sourceKey":"bank:FIN216:CON-070","payload":{"prompt":"Under the 2014 IADI Core Principles, deposit insurance coverage should be limited and credible, covering the large majority of depositors while leaving a substantial share of the value of deposits exposed to","options":["market discipline","government guarantees","co-insurance by the central bank","blanket protection"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Covering most depositors protects small savers, while leaving large balances uninsured keeps big depositors watching their banks, which is market discipline. Options B and D would extend protection and so weaken discipline. Option C is not a real arrangement for covering deposits."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 149, $official_bank_source${"itemId":"1f3f3f4d-06c0-50b0-b5dd-03c68207e62a","questionId":"ba85c189-1187-5b0d-a890-da690ec947e4","sourceKey":"bank:FIN216:CON-071","payload":{"prompt":"A deposit insurance arrangement in which insured depositors bear part of the loss, for example receiving only 90 percent of their insured balance, is called","options":["a blanket guarantee","co-insurance","pass-through coverage","subrogation"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Under co-insurance the depositor shares the loss with the insurer, which is meant to keep depositors watchful of their banks. Option A is the opposite, extending protection beyond normal limits. Option C extends cover to the owners of funds in pooled accounts, and option D is the insurer taking over depositors' claims after paying them."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 150, $official_bank_source${"itemId":"92c60d24-96c1-58ce-9008-3afef18ca886","questionId":"c337a32a-adcb-5ec4-a8ee-32683d54630a","sourceKey":"bank:FIN216:CON-072","payload":{"prompt":"Under a hypothetical scheme, insured deposits are reimbursed at 90 percent (10 percent co-insurance) up to a cover limit of N1,000,000. Mrs Okon holds N800,000 in a bank that fails. How much does she receive from the deposit insurer?","options":["N720,000","N800,000","N900,000","N80,000"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Her N800,000 is within the N1,000,000 limit, so she receives 90 percent of it: 0.9 x 800,000 = N720,000. Option B ignores the co-insurance. Option C applies 90 percent to the cover limit instead of to her balance, and option D is the amount she loses, not the amount paid."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 151, $official_bank_source${"itemId":"8beda192-7d74-51af-ab60-a17820246bf8","questionId":"41444653-3f36-55ef-a23e-5ea0156c5b85","sourceKey":"bank:FIN216:CON-073","payload":{"prompt":"During the 2008 crisis many countries reduced or removed co-insurance in their deposit insurance schemes. Why?","options":["Making depositors bear part of their loss could trigger runs and undermine confidence","Co-insurance made banks too safe to need supervision","Co-insurance forced the government to guarantee all deposits","Co-insurance prevented banks from paying any premiums"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Co-insurance is meant to curb moral hazard, but in a panic depositors who know they will lose part of their money have a reason to run; removing it helped keep confidence. Options B, C and D describe effects that co-insurance does not have."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 152, $official_bank_source${"itemId":"c050cf84-f09e-5b5d-8ca9-885ea1b1a5a2","questionId":"a36ff9ae-c6d6-5630-90ae-801aade32869","sourceKey":"bank:FIN216:CON-074","payload":{"prompt":"Supervisory powers held by a risk-minimiser deposit insurer help to contain moral hazard mainly because","options":["supervision guarantees that every insured bank makes a profit","the insurer can detect excessive risk-taking early and require corrective action","supervision allows the insurer to cover deposits without limit","supervision removes the need to collect premiums"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Banks may take extra risk once they are insured, so an insurer that examines banks and can order prompt corrective action can stop that behaviour before it causes losses. Options A, C and D are false: supervision does not guarantee profits, set coverage, or replace funding."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 153, $official_bank_source${"itemId":"2d79655c-c99b-5627-af0f-6106b60c67ef","questionId":"b09a2156-2b9c-55c3-b4ec-b0f39d56f71e","sourceKey":"bank:FIN216:CON-076","payload":{"prompt":"Deposit insurance reduces the likelihood of bank runs mainly because","options":["it bans depositors from withdrawing during a crisis","it guarantees that banks never make losses","it allows banks to refuse withdrawals above a limit","insured depositors know they will be repaid even if their bank fails, so they have no reason to rush"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Runs are driven by fear of losing money; once depositors trust that their insured deposits are safe, the urge to be first in the queue disappears. Options A and C describe withdrawal freezes, which deposit insurance does not impose. Option B is wrong because banks can still make losses and fail."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 154, $official_bank_source${"itemId":"5055e8ca-d191-525d-9d62-730757f277e9","questionId":"66874b1a-4ce4-5b2e-b2f1-b77b1488c3ba","sourceKey":"bank:FIN216:CON-080","payload":{"prompt":"Chief Eze held N9 million in a deposit money bank that failed in 2025. Under the coverage limits in force since May 2024, how much of his balance is uninsured and must wait for liquidation dividends?","options":["N5,000,000","N9,000,000","N8,500,000","N4,000,000"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"The NDIC pays up to N5 million for a deposit money bank depositor, so N9 million minus N5 million leaves N4,000,000 uninsured, to be recovered from liquidation dividends as the bank's assets are sold. Option A is the insured part. Option B treats the whole balance as uninsured, and option C uses the old N500,000 limit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 155, $official_bank_source${"itemId":"c803bcfc-1c18-51af-9a20-905eac7fb725","questionId":"4df47a37-aaf0-5560-b867-dc124051adba","sourceKey":"bank:FIN216:CON-081","payload":{"prompt":"IADI notes that deposit insurance works within a wider operating environment. Which of the following is NOT part of that operating environment?","options":["Macroeconomic conditions","The insurer's annual profit target","Prudential regulation and supervision","The legal and judicial framework"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"The operating environment covers outside conditions that affect how well a scheme works: macroeconomic conditions, the financial system's structure, prudential regulation and supervision, the legal and judicial framework, and accounting and disclosure. Options A, C and D are all part of it. A deposit insurer is not run to meet a profit target."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 156, $official_bank_source${"itemId":"9f80f56e-3e7b-5877-b493-c34ee8dadb75","questionId":"f417c23f-43fd-509e-abf0-2057030cf9b3","sourceKey":"bank:FIN216:CON-082","payload":{"prompt":"Which of the following would most WEAKEN the effectiveness of a deposit insurance system?","options":["Making membership voluntary so that mainly weak banks join","Setting limited but credible coverage for most depositors","Building an ex ante fund from bank premiums","Making the insurer operationally independent"],"correctOption":0,"section":"The Concept of Deposit Insurance","explanation":"Voluntary membership invites adverse selection, leaving the fund exposed to the riskiest banks. Options B, C and D are features that IADI recommends for an effective system: credible limited coverage, ex ante funding and operational independence."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 157, $official_bank_source${"itemId":"299312a0-a1ce-5e42-bde0-bed123402723","questionId":"a2ea8162-d3e7-57b7-a435-8a71f3dd9ebd","sourceKey":"bank:FIN216:CON-083","payload":{"prompt":"Under the 2014 IADI Core Principles, a deposit insurer should be operationally independent. This means it","options":["does not need to account to anyone for its actions","can use its powers to fulfil its mandate without interference from external parties","must be owned by private investors rather than government","may set its own coverage limit with no legal framework"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Operational independence means the insurer can carry out its mandate without outside interference, while still being accountable and well governed. Option A is wrong because Core Principle 3 also demands accountability and transparency. Option C is wrong because public insurers such as the NDIC can be independent, and option D ignores the legal framework."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 158, $official_bank_source${"itemId":"1e07595b-4ff5-5c09-b2b1-66dd3a9083a7","questionId":"c35ffc86-ba83-54e9-ae07-3bb513af0a3f","sourceKey":"bank:FIN216:CON-084","payload":{"prompt":"The legal framework of an explicit deposit insurance system such as Nigeria's provides for all of the following EXCEPT","options":["ownership and funding of the scheme","membership and coverage","failure resolution options and enforcement powers","the interest rates banks charge their borrowers"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"The enabling law of a deposit insurance system covers its objectives, mandate, ownership, funding, membership, coverage, administrative structure, supervisory responsibilities, failure resolution options and enforcement powers. Options A, B and C are all among these. Lending rates are set by banks within monetary policy, not by deposit insurance law."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 159, $official_bank_source${"itemId":"09fc848a-666b-53af-a1a0-c198e9d5030b","questionId":"4fb4cf99-a1c6-5a13-88d1-e98883e534e3","sourceKey":"bank:FIN216:CON-086","payload":{"prompt":"Which of the following is NOT one of the basic elements of a deposit insurance scheme?","options":["Insured financial institutions","The stock exchange","Eligible deposits","The deposit insurance institution"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"A deposit insurance scheme is built from insured institutions, insured depositors, eligible deposits, the deposit insurance institution, the supervisory institution, the central bank and the government. Options A, C and D are among these elements. The stock exchange deals with shares and securities, not insured deposits."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 160, $official_bank_source${"itemId":"4577c6b4-c1d9-5c57-b905-932dc6ef2bae","questionId":"06f62743-e61f-57a1-b135-aa85029dd8f8","sourceKey":"bank:FIN216:CON-088","payload":{"prompt":"One reason for establishing an explicit deposit insurance scheme with supervisory powers in Nigeria in 1988 was that","options":["the CBN had stopped supervising banks altogether","Nigeria had no banks owned by state governments","liberalised bank licensing under SAP greatly increased the number of banks, so a body was needed to complement CBN supervision","IADI had made deposit insurance compulsory for its members"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"The 1986 Structural Adjustment Programme liberalised bank licensing, and the number of banks rose sharply; an insurer with supervisory powers was expected to support the CBN. Option A is false because the CBN kept supervising. Option D is wrong because IADI was only founded in 2002, and option B is false since state governments owned several banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 161, $official_bank_source${"itemId":"daf6f62d-49dd-566a-a102-2601a8738cdf","questionId":"13d257d4-772c-5689-86e5-83797d9f2bd8","sourceKey":"bank:FIN216:CON-090","payload":{"prompt":"Which of the following was NOT a reason for establishing deposit insurance in Nigeria?","options":["Increased competition among banks could encourage excessive risk-taking with depositors' funds","To protect bank shareholders against loss of their investment","Government wanted to shift from propping up banks to protecting depositors","Liberalised licensing was expected to increase the number of banks to be supervised"],"correctOption":1,"section":"The Concept of Deposit Insurance","explanation":"Deposit insurance protects depositors, not shareholders, who carry the risk of their investment. Options A, C and D are genuine reasons: competition that could lead to excessive risk-taking, the change in government bank support policy, and the effect of economic reforms on supervision."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 162, $official_bank_source${"itemId":"f5ff3dbf-811a-52c5-bb35-5430a6090059","questionId":"49d24f27-1daa-591e-adc3-ecca370e83fc","sourceKey":"bank:FIN216:CON-091","payload":{"prompt":"Why can increased competition among banks create a need for deposit insurance?","options":["Competition always causes banks to raise their capital","Competition reduces the number of banks to be supervised","Competition guarantees that no bank will fail","Competition can push banks into excessive risk-taking with depositors' funds, so small depositors need protection"],"correctOption":3,"section":"The Concept of Deposit Insurance","explanation":"Competition is good for customers, but banks chasing market share may take excessive risks with depositors' money, which is why small depositors need protection. Option A is not a guaranteed result of competition. Options B and C are wrong because liberalisation increased the number of banks and competition does not prevent failures."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 163, $official_bank_source${"itemId":"ea3577ab-38ef-55ce-a642-bbddde29d191","questionId":"22313a5c-16c6-5afa-89a2-16f81fc3a106","sourceKey":"bank:FIN216:CON-092","payload":{"prompt":"Which of the following is TRUE of deposit insurance arrangements around the world?","options":["Every country must have exactly one publicly owned scheme","All schemes must be funded ex post","Some countries have more than one scheme providing deposit protection","Membership must always be voluntary"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Practice varies: some countries, Germany for example, have multiple schemes, and schemes can be public, private or mixed, funded ex ante or ex post, with compulsory or voluntary membership. Options A, B and D all wrongly insist on one fixed design."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 164, $official_bank_source${"itemId":"81b83e45-2954-500f-a209-e99177c256d1","questionId":"6b42f7eb-4b23-5bcc-b341-42e6dbac919c","sourceKey":"bank:FIN216:CON-093","payload":{"prompt":"In a deposit insurance system, the institutions whose depositors are protected, such as deposit money banks, microfinance banks and primary mortgage banks in Nigeria, are called","options":["supervisory institutions","deposit insurance institutions","insured institutions","eligible deposits"],"correctOption":2,"section":"The Concept of Deposit Insurance","explanation":"Insured institutions are the banks and other deposit-takers whose deposits are covered by the scheme. Option A is the body that supervises, such as the central bank. Option B is the insurer itself, such as the NDIC, and option D refers to the deposits covered, not the institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 165, $official_bank_source${"itemId":"cd86e7c1-6ab9-58bc-b347-c1438cbe420f","questionId":"dbbfed43-3632-50d0-ba3d-d7cf84624d6a","sourceKey":"bank:FIN216:F216-0003","payload":{"prompt":"When the NDIC began operations in 1989, depositors of an insured bank were covered up to a maximum of ____","options":["N1,500,000","N50,000","N5,000,000","N200,000"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Under the 1988 decree that set up the NDIC, the maximum cover was N50,000 per depositor of an insured bank, and this was the limit when operations started in 1989. Option D, N200,000, only came in under the NDIC Act 2006, while N5,000,000 in option C is the much later limit for deposit money banks set in May 2024. N1,500,000 in option A was never a coverage limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 166, $official_bank_source${"itemId":"ffb7b7f6-461e-5fc6-b7e2-cbdb33bf64c2","questionId":"46c29155-5096-5edd-b451-62d1e021999d","sourceKey":"bank:FIN216:F216-0004","payload":{"prompt":"Which of the following is NOT a statutory mandate of the NDIC?","options":["Distress resolution","Bank liquidation","Deposit insurance","Lender of last resort"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Acting as lender of last resort is a central bank function, carried out in Nigeria by the CBN, not the NDIC. The NDIC's four statutory mandates are deposit guarantee (insurance), bank supervision jointly with the CBN, resolution of failing or distressed banks, and liquidation of failed banks. That is why options A, B and C are all genuine NDIC mandates."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 167, $official_bank_source${"itemId":"f580340b-6d07-59ea-8626-dfa23e5932ae","questionId":"8ca1b475-29b7-55f9-b62a-0aa272f2a975","sourceKey":"bank:FIN216:F216-0009","payload":{"prompt":"In the 2010-2011 review of coverage limits, the NDIC raised the maximum cover for depositors of deposit money banks from N200,000 to ____","options":["N1,000,000","N100,000","N250,000","N500,000"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"In that review, the cover for deposit money banks rose from N200,000 to N500,000, while microfinance and primary mortgage banks went from N100,000 to N200,000. Option B is too low and was only the limit for other deposit-taking institutions under the 2006 Act. N500,000 itself was later replaced by N5,000,000 for deposit money banks in May 2024."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 168, $official_bank_source${"itemId":"94871cd2-d083-5292-bba4-85c00b8ffec7","questionId":"34378474-6626-5f5a-bd83-91f077702586","sourceKey":"bank:FIN216:F216-0021","payload":{"prompt":"In the 2010-2011 review of coverage limits, the NDIC raised the maximum cover for depositors of primary mortgage banks to ____","options":["N200,000","N100,000","N300,000","N500,000"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"In that review, primary mortgage banks and microfinance banks moved from N100,000 to N200,000, while deposit money banks went to N500,000. Option B was the older limit under the 2006 Act, and N500,000 was the deposit money bank figure (mortgage banks only reached N500,000 later, in 2016). N300,000 was never a coverage limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 169, $official_bank_source${"itemId":"3e9b05aa-18f6-5dd4-b92d-eaa181b74d22","questionId":"371c0324-235d-5003-985b-c6b5bbe83624","sourceKey":"bank:FIN216:F216-0023","payload":{"prompt":"Following the review announced in May 2024, the NDIC's maximum deposit insurance cover for depositors of microfinance banks is ____","options":["N5,000,000","N2,000,000","N300,000","N500,000"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"In May 2024 the NDIC raised the cover for microfinance banks from N200,000 to N2,000,000, the same level as primary mortgage banks and payment service banks. Option A, N5,000,000, is the new limit for deposit money banks, not microfinance banks. N500,000 in option D was the earlier deposit money bank limit, and N300,000 was never a coverage limit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 170, $official_bank_source${"itemId":"9ebe45a0-f38d-50a2-a9af-e74c6c1b658b","questionId":"161d37de-0574-57dc-89e0-630121379fee","sourceKey":"bank:FIN216:F216-0023-b","payload":{"prompt":"Following the review announced in May 2024, the NDIC's maximum deposit insurance cover for each depositor of a deposit money bank is ____","options":["N2,000,000","N500,000","N1,000,000","N5,000,000"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"In May 2024 the NDIC raised the cover for deposit money banks tenfold, from N500,000 to N5,000,000 per depositor. Option B is the old limit, which many students still remember. N2,000,000 is the new limit for microfinance banks, primary mortgage banks and payment service banks, not commercial banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 171, $official_bank_source${"itemId":"400ef41b-181d-54d9-82ff-aaa8598958db","questionId":"5fa85170-ba88-5c93-80ab-90a77f11d0b0","sourceKey":"bank:FIN216:F216-0042","payload":{"prompt":"The primary responsibility of the NDIC is to implement a ______ in Nigeria.","options":["Deposit Reinsurance System","Deposit Insurance Power","Deposit Reinsurance Power","Deposit Insurance System"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The NDIC was set up to run Nigeria's deposit insurance system: guaranteeing deposits in insured institutions up to a limit and paying depositors if an institution fails. Options A and C wrongly mention reinsurance, which is insurance bought by insurers, and option B is not a recognised term."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 172, $official_bank_source${"itemId":"37758d32-cfde-5b16-8965-92a87c9ce400","questionId":"e9ee27ed-7a6d-5efd-a9a6-54456bb2bc08","sourceKey":"bank:FIN216:F216-0048","payload":{"prompt":"Under the NDIC's public awareness programme, information is conveyed about all of the following EXCEPT:","options":["The scope of the deposit insurance scheme","The date of payment","The deposit insurance coverage limit","Member banks and how they can be identified"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"A general public awareness programme explains how the scheme works before any bank fails: what it covers (option A), which institutions are members and how to recognise them (option D), and how much each depositor is covered for (option C). A date of payment only exists once a particular bank has failed, so it is announced during that specific closure rather than as part of the ongoing awareness programme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 173, $official_bank_source${"itemId":"5d99e81d-51d1-5d31-be13-91a78b5500d1","questionId":"e95e3480-ba50-55b4-a544-6ae3bad2fccd","sourceKey":"bank:FIN216:F216-0055","payload":{"prompt":"Suggestions for an effective public awareness campaign include the following EXCEPT:","options":["Allocation of adequate budget","Setting clear communication objectives","Non-implementation of the public awareness programme","Identifying specific target groups"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"An awareness campaign only works if it is actually carried out, so failing to implement the programme defeats its whole purpose. Options A, B and D are all good practice: enough money to run the campaign, clear objectives for what the public should learn, and messages aimed at specific groups such as depositors and insured institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 174, $official_bank_source${"itemId":"f3c1e899-0ba5-5d9f-890b-5d15f9ef280c","questionId":"96338009-bb97-5878-b267-10dab82892b0","sourceKey":"bank:FIN216:F216-0075","payload":{"prompt":"Under the NDIC dispensation, the public awareness programme involves activities to convey information about:","options":["the scope of deposit insurance coverage (which deposits are covered)","the member banks and how they can be identified","the coverage limit per depositor","all of the above"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"For depositors to rely on deposit insurance, they need to know which deposits are covered, which banks are members and how to recognise them, and how much each depositor can recover if a bank fails. The NDIC's awareness activities cover each of these points, so A, B and C are all correct and D is the answer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 175, $official_bank_source${"itemId":"704b81cf-d298-52d8-be04-3f24a6ee34b6","questionId":"e7f9469a-c2b6-505e-adf3-f4672ec3e8d6","sourceKey":"bank:FIN216:F216-0093","payload":{"prompt":"The broad mandate(s) of the NDIC in ensuring an effective financial safety net is/are to:","options":["Deal with solvency problems of banks","Protect depositors","Provide a mechanism for failure resolution","All of the above"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Within the safety net, the CBN mainly handles liquidity problems, while the NDIC deals with banks facing solvency problems, protects depositors through deposit insurance and provides a mechanism for resolving failed or failing banks. Each of A, B and C is part of that role, so D is the best answer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 176, $official_bank_source${"itemId":"4b9226ee-addc-527b-8388-5a082a1caf8d","questionId":"b45ce2f0-a487-53af-9156-61b187eef945","sourceKey":"bank:FIN216:FUN-001","payload":{"prompt":"Under the NDIC Act 2023, which of the following sets correctly lists the four statutory mandates of the Nigeria Deposit Insurance Corporation?","options":["Deposit guarantee, foreign exchange management, bank supervision and liquidation","Bank licensing, lender of last resort, failure resolution and debt recovery","Deposit guarantee, monetary policy, bank licensing and bank liquidation","Deposit guarantee, bank supervision, failure resolution and bank liquidation"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The NDIC's four statutory mandates are deposit guarantee, bank supervision (jointly with the CBN), failure resolution and bank liquidation. Options C, B and A each slip in a CBN job such as monetary policy, bank licensing, lender of last resort or foreign exchange management, which the NDIC does not perform."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 177, $official_bank_source${"itemId":"5166bb67-c914-5c3a-81f8-446366e147a8","questionId":"533e2aca-9d76-5445-ba9e-c3232cea3f93","sourceKey":"bank:FIN216:FUN-002","payload":{"prompt":"Under the NDIC Act 2023, which of the following is NOT one of the statutory mandates of the NDIC?","options":["Guaranteeing the deposit liabilities of insured institutions","Supervising insured institutions jointly with the CBN","Granting and revoking banking licences","Liquidating failed insured institutions"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Licensing banks and revoking their licences is the work of the Central Bank of Nigeria; the NDIC can only recommend revocation and then acts as liquidator. Options A, B and D are genuine NDIC mandates: deposit guarantee, joint supervision and liquidation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 178, $official_bank_source${"itemId":"2926a8ef-a9b8-5edc-b25c-013aa81dbefb","questionId":"e76576cb-a919-5fca-9f57-5f0d7a05f61a","sourceKey":"bank:FIN216:FUN-003","payload":{"prompt":"In Nigeria's financial safety net, which of the following functions belongs to the Central Bank of Nigeria rather than to the NDIC?","options":["Paying insured depositors of a failed bank","Acting as liquidator of a bank whose licence has been revoked","Guaranteeing insured deposits up to a stated limit","Acting as lender of last resort to banks with liquidity problems"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The CBN is the lender of last resort, lending to banks that are short of cash, and it also licenses banks. Options C, B and A are NDIC jobs: guaranteeing deposits, liquidating failed banks and reimbursing insured depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 179, $official_bank_source${"itemId":"9dc52e88-1d2a-50ce-b304-6525e6c19743","questionId":"dd0bab76-66b3-5ec4-9834-548744e6bfb2","sourceKey":"bank:FIN216:FUN-004","payload":{"prompt":"Under the NDIC Act 2023, the NDIC carries out the supervision and resolution of insured institutions with the concurrence of which body?","options":["The Securities and Exchange Commission","The Central Bank of Nigeria","The Federal Ministry of Finance","The National Assembly"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Section 3 of the NDIC Act 2023 says the NDIC supervises and resolves insured institutions with the concurrence of the Central Bank of Nigeria, which licenses and regulates banks. Option C, the Ministry of Finance, co-owns the NDIC but does not give this concurrence, and options A and D play no role in bank resolution."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 180, $official_bank_source${"itemId":"d92ea574-a565-598a-9385-54cade0f849c","questionId":"838604c4-9040-5dc0-b99b-0b25545e9aa8","sourceKey":"bank:FIN216:FUN-006","payload":{"prompt":"Country X sets up a deposit insurer whose only job is to reimburse insured depositors after a bank fails; it has no power to examine banks. Compared with Nigeria's NDIC, this insurer is best described as a:","options":["Pay box, whereas the NDIC is a risk minimiser","Loss minimiser, whereas the NDIC is a pay box","Pay box plus, whereas the NDIC is a loss minimiser","Risk minimiser, whereas the NDIC is a pay box"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"An insurer that only pays out insured deposits is a pay box, while the NDIC, which also supervises, resolves and liquidates banks, is a risk minimiser. Options D and B wrongly call the NDIC a pay box, and option C mislabels both schemes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 181, $official_bank_source${"itemId":"e96f78fe-5c68-5d8a-a502-8a5019f6f332","questionId":"48a04ec9-6faa-5174-88c1-19bb47ce9db6","sourceKey":"bank:FIN216:FUN-007","payload":{"prompt":"Under section 2 of the NDIC Act 2006, which of the following was one of the functions of the NDIC?","options":["Printing and issuing the national currency","Giving assistance to insured institutions in imminent or actual financial difficulty","Setting the Monetary Policy Rate for deposit money banks","Regulating insurance companies that sell motor and life cover"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Section 2 of the NDIC Act 2006 empowered the NDIC to insure deposits, guarantee payments to depositors and assist insured institutions in financial difficulty to protect public confidence. Options A and C are CBN functions, and option D is the job of NAICOM."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 182, $official_bank_source${"itemId":"7d91b46c-dc69-532e-bcf8-be923fd3e611","questionId":"a77835a5-3c1d-5919-8a7d-862fc219359a","sourceKey":"bank:FIN216:FUN-008","payload":{"prompt":"Under the NDIC Act 2006, besides insuring deposits, the NDIC was to assist the monetary authorities in:","options":["Collecting company income tax from insured banks","Approving the annual budget of the Federal Government","Fixing the official exchange rate of the naira","Formulating and implementing banking policy to promote sound banking practice"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Section 2(1)(d) of the 2006 Act asked the NDIC to help the monetary authorities formulate and implement banking policy so as to ensure sound banking practice and fair competition among insured institutions. Options C, A and B belong to the CBN, the tax authority and the National Assembly respectively."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 183, $official_bank_source${"itemId":"d0a34193-1efb-567d-bd4f-fc4392610ea8","questionId":"085bbe93-e35a-5f77-9b67-afafef72a902","sourceKey":"bank:FIN216:FUN-010","payload":{"prompt":"On 3 June 2024 the licence of Heritage Bank was revoked. Which statement correctly shows the roles of the two agencies involved?","options":["The NDIC revoked the licence and the CBN paid insured depositors","The NDIC revoked the licence and became the bank's new owner","The CBN revoked the licence and AMCON paid insured depositors","The CBN revoked the licence and the NDIC became liquidator and paid insured depositors"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Licence revocation is a CBN power, and once a licence is revoked the NDIC steps in as liquidator and reimburses insured depositors, as it did for Heritage Bank in 2024. Options A and B wrongly give the revocation power to the NDIC, and option C wrongly gives the payout to AMCON."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 184, $official_bank_source${"itemId":"e8ad634a-8c52-5c2d-908f-245373573715","questionId":"58271ece-3bf9-5f4b-b581-0558fa2a34f1","sourceKey":"bank:FIN216:FUN-011","payload":{"prompt":"Under section 4(a) of the NDIC Act 2023, insured deposits can be paid when an insured institution's licence is revoked or when:","options":["The institution reports a loss in one financial year","The institution delays paying its annual premium","The institution's share price falls on the stock exchange","The institution actually suspends payments to depositors, with CBN concurrence"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2023 Act allows payout either on licence revocation or on actual suspension of payments, with the CBN's concurrence, so depositors need not wait for the licence to go. Options A, C and B are signs of weakness or non-compliance, but none of them triggers payment of insured deposits."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 185, $official_bank_source${"itemId":"ef95dca3-46dd-5d78-9fb5-15d1765d4297","questionId":"904d4430-d418-54d6-9148-b2f062cb9d4c","sourceKey":"bank:FIN216:FUN-012","payload":{"prompt":"Which change did the NDIC Act 2023 make compared with the NDIC Act 2006?","options":["It made membership of the scheme voluntary for banks","It abolished the guarantee limit so all deposits are fully covered","It states the public policy objectives of deposit insurance in the law","It turned the NDIC into a pay box with no supervisory role"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2006 Act did not spell out public policy objectives, while section 2 of the 2023 Act does. Option D is wrong because the NDIC remains a risk minimiser that supervises banks, option A is wrong because membership stays compulsory, and option B is wrong because coverage is still limited."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 186, $official_bank_source${"itemId":"44d0fa38-2b9c-59da-b92e-f9f2ce68d284","questionId":"89797ef6-ccc3-5074-964a-0223478058af","sourceKey":"bank:FIN216:FUN-013","payload":{"prompt":"Which of the following is NOT one of the public policy objectives of deposit insurance stated in section 2 of the NDIC Act 2023?","options":["Guaranteeing a minimum dividend to shareholders of insured banks","Contributing to the stability of the financial system","Providing a framework for the resolution and orderly exit of failing and failed institutions","Protecting depositors, especially small and less-informed ones, through orderly compensation"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Deposit insurance protects depositors, not shareholders; shareholders bear losses when a bank fails and are paid last in liquidation. Options D, B and C are the genuine objectives in section 2: depositor protection, financial stability and orderly resolution and exit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 187, $official_bank_source${"itemId":"63404797-5568-5856-ba51-f08fd7e6c384","questionId":"67d38151-b6ac-58f8-a0b2-4c4b75874eef","sourceKey":"bank:FIN216:FUN-014","payload":{"prompt":"Which public policy objective of the NDIC is described as giving small, uninformed and less financially sophisticated depositors an orderly means of compensation when their bank fails?","options":["Promotion of competition among banks","Depositor protection","Orderly resolution and exit of failing institutions","Financial system stability"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Providing an orderly means of compensation for small, less sophisticated depositors is the depositor protection objective. Option D is about making bank runs less likely, and option C is about the framework for closing failing banks. Option A is not one of the stated objectives."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 188, $official_bank_source${"itemId":"09985a14-9569-5ff8-b389-e0c5fe1c2d1c","questionId":"18942881-5216-5df9-9cd2-a21b8422600d","sourceKey":"bank:FIN216:FUN-015","payload":{"prompt":"When deposit insurance makes bank runs less likely, it is mainly serving which public policy objective?","options":["Providing cheap loans to small businesses","Contributing to financial system stability","Protecting shareholders of failing banks","Raising premium income for the deposit insurer"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"When depositors trust that their insured money is safe, they are less likely to rush to withdraw it, so runs and contagion are reduced and the system stays stable. Option C is wrong because shareholders are not protected, and options D and A are not objectives of a deposit insurance scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 189, $official_bank_source${"itemId":"73d6072a-57a8-5f99-bef6-dc826a0aaa0a","questionId":"70793a0d-8738-51a7-a064-4cbad3b27c3e","sourceKey":"bank:FIN216:FUN-018","payload":{"prompt":"The NDIC's enabling Act and related laws provide for the scheme's objectives, mandate, ownership and funding. Which of the following is NOT one of the areas they provide for?","options":["Membership of the scheme","Coverage of insured deposits","Setting the interest rates banks charge on loans","Failure resolution options"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The deposit insurance legal framework covers matters such as objectives, mandate, ownership, funding, membership, coverage, supervision, failure resolution and enforcement powers. Lending rates are not fixed by the NDIC law. Options A, B and D are genuine parts of the framework."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 190, $official_bank_source${"itemId":"76058006-acf6-5387-bc30-7b6f297c9a0a","questionId":"8dc9ae3a-07e3-52ca-bb1b-f9a79287d547","sourceKey":"bank:FIN216:FUN-019","payload":{"prompt":"Nigeria's deposit insurance system is described as explicit because:","options":["It protects every deposit in full without any stated limit","Depositors simply assume the government will rescue any bank that fails","Its mandate, membership, funding and coverage limits are spelt out in legislation","It is run by the banks through a voluntary private arrangement"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"An explicit system is set up by law or contract that spells out mandate, powers, membership, funding and coverage, as the NDIC Act does. Option B describes an implicit system, option A describes a blanket guarantee, and option D does not describe the NDIC, which is a public body with compulsory membership."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 191, $official_bank_source${"itemId":"741464ac-0831-5537-8801-60de5dd96182","questionId":"058b9b7a-db97-5bc8-91d4-28b7a2193ddc","sourceKey":"bank:FIN216:FUN-020","payload":{"prompt":"Under the NDIC Act 2006 and BOFIA, which of the following is NOT an enforcement power of the NDIC over insured institutions?","options":["Terminating the insured status of an insured institution","Taking over the management and control of an insured institution","Prosecuting directors and officers of insured institutions for financial malpractice","Revoking the operating licence of an insured institution on its own authority"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The NDIC can only recommend licence revocation or suspension to the CBN; the CBN itself revokes licences. Options A, B and C are genuine NDIC enforcement powers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 192, $official_bank_source${"itemId":"512ccd1d-48e0-5d35-abb9-7b7839ad71dd","questionId":"a41efeee-d9bc-5d88-be8e-0baef56f0773","sourceKey":"bank:FIN216:FUN-022","payload":{"prompt":"After examining Bank Z, the NDIC issues it specific directives to stop unsafe and unsound banking practices before its condition gets worse. This action is best described as:","options":["Liquidation","Deposit payout","Prompt corrective action","Purchase and assumption"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Issuing directives after an examination to correct unsafe practices early is prompt corrective action, one of the NDIC's enforcement powers. Options B, D and A are actions taken after a bank has failed or is being closed, not early corrective steps."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 193, $official_bank_source${"itemId":"8c2af499-68e1-5218-b6ed-984577be2845","questionId":"39ced54a-4172-5a1a-a704-f10373925525","sourceKey":"bank:FIN216:FUN-023","payload":{"prompt":"Under section 25 of the NDIC Act 2006, if the NDIC Board finds a grievous violation by an insured institution, it can:","options":["Terminate the institution's insured status","Raise the coverage limit for that institution only","Revoke the institution's banking licence directly","Seize the personal assets of all its depositors"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Section 25(1) of the 2006 Act let the Board terminate the insured status of an institution guilty of a grievous violation. Option C is wrong because revocation is a CBN power, and options D and B make no sense as penalties."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 194, $official_bank_source${"itemId":"cd4eb676-4c3c-5732-b17e-792b7eb80697","questionId":"5321f553-61b0-5097-959e-d5d77a0c61a8","sourceKey":"bank:FIN216:FUN-024","payload":{"prompt":"In 2015 the NDIC terminated the insured status of Bank K under the NDIC Act 2006. What happened to the deposits Bank K already held on the termination date?","options":["They became fully insured with no limit","They lost cover immediately on the termination date","They stayed insured for six more years","They stayed insured for one more year, less any later withdrawals"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Under section 25(4) of the 2006 Act, deposits held at termination stayed covered for another year, reduced by later withdrawals, and new deposits were not insured. Option B ignores this grace period, option C confuses it with the six-year limit for claiming insured deposits, and option A is never the case."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 195, $official_bank_source${"itemId":"c7532946-69d4-5750-9b00-fd68f975a684","questionId":"c1406701-7857-51ba-bb66-b0ea768c12c7","sourceKey":"bank:FIN216:FUN-025","payload":{"prompt":"Under section 21(1) of the NDIC Act 2023, membership of the deposit insurance scheme for licensed banks and other licensed deposit-taking institutions is:","options":["Compulsory only for banks listed on the stock exchange","Voluntary for microfinance banks but compulsory for others","Voluntary, at the discretion of each bank's board","Compulsory for all of them"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2023 Act requires all licensed banks and other licensed deposit-taking institutions to insure their deposit liabilities with the NDIC. Options C, A and B wrongly make membership optional or limited to some institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 196, $official_bank_source${"itemId":"fd9f994f-6436-55d9-9ed7-35acbbb28226","questionId":"b16e9f01-4359-5008-aa76-15fc971ec0d1","sourceKey":"bank:FIN216:FUN-026","payload":{"prompt":"A newly licensed microfinance bank in Lagos tells customers in 2025 that it has 'chosen not to join' the NDIC scheme to save on premiums. Under the NDIC Act 2023 this is:","options":["Allowed, because microfinance deposits are covered by the CBN instead","Allowed, if the bank tells customers in writing","Not allowed, because every licensed deposit-taking institution must insure its deposits with the NDIC","Allowed, because only deposit money banks must join the scheme"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Membership is compulsory for all licensed deposit-taking institutions, and microfinance banks are insured institutions. Options D and A wrongly exclude MFBs, and option B wrongly suggests a bank can opt out by notice."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 197, $official_bank_source${"itemId":"e68e8e10-61ea-5959-85d6-052b9c6f48da","questionId":"bde46d7d-0d61-5a80-be4b-180be367e96f","sourceKey":"bank:FIN216:FUN-027","payload":{"prompt":"Which of the following institutions has its deposit liabilities insured by the NDIC (as at 2024)?","options":["Insurance companies","Payment service banks","Pension fund administrators","Stockbroking firms"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"As at 2024 the NDIC insures deposit money banks (including non-interest banks), microfinance banks, primary mortgage banks and payment service banks. Options A, C and D do not take deposits and are supervised by NAICOM, PenCom and the SEC respectively."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 198, $official_bank_source${"itemId":"d314fa6d-72f4-5c5d-8f86-e4dbf1bfced8","questionId":"51b9c09f-393d-5b75-9987-8707a5de7317","sourceKey":"bank:FIN216:FUN-028","payload":{"prompt":"Which of the following is NOT an institution whose deposits are insured by the NDIC (as at 2024)?","options":["A pension fund administrator","A primary mortgage bank","A microfinance bank","A non-interest bank"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"A pension fund administrator manages retirement savings under PenCom and does not take bank deposits, so it is outside the NDIC scheme. Options B, C and D are all licensed deposit-taking institutions insured by the NDIC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 199, $official_bank_source${"itemId":"10a72b0f-b31d-59a0-bbb4-ecee1ebb4590","questionId":"00e13109-daac-5a3a-acb9-083d64ba8006","sourceKey":"bank:FIN216:FUN-029","payload":{"prompt":"As at 2024, the NDIC insured all of the following EXCEPT:","options":["Microfinance banks","Deposit money banks","Bureaux de change","Payment service banks"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Bureaux de change buy and sell foreign currency and do not hold insured deposits. Options B, D and A are deposit-taking banks that must insure their deposits with the NDIC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 200, $official_bank_source${"itemId":"a804d3e6-4f74-5f96-baa5-92baeee98469","questionId":"f2c9160f-6e9a-5b46-8994-0fb4b3341c38","sourceKey":"bank:FIN216:FUN-030","payload":{"prompt":"How are non-interest (Islamic) banks treated under Nigeria's deposit insurance scheme?","options":["They are insured, but only their shareholders' funds are covered","They are excluded because they do not pay interest on deposits","They are insured by AMCON instead of the NDIC","They are insured institutions, and before May 2024 their depositors had the same cover as deposit money bank depositors"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Non-interest banks are insured by the NDIC, and before the May 2024 review their cover matched the deposit money bank limit of N500,000. Option B is wrong because paying no interest does not remove a deposit from cover, option C names the wrong body, and option A is wrong because deposit insurance protects depositors, not shareholders."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 201, $official_bank_source${"itemId":"ad3919d8-187b-536d-ae4c-9a701625b556","questionId":"b0c46dc3-01d3-5ae9-8321-3b912fba525f","sourceKey":"bank:FIN216:FUN-032","payload":{"prompt":"Under the NDIC Act 2023, deposits of microfinance banks and primary mortgage banks are protected through which fund?","options":["The Special Insured Institutions Fund","The Payment Service Banks Insurance Fund","The Non-Interest Deposit Insurance Fund","The Deposit Insurance Fund"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"MFBs and PMBs are 'special insured institutions', and their premiums go into the Special Insured Institutions Fund. Option D is for deposit money banks and mobile money operators, option B is for payment service banks, and option C is for non-interest banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 202, $official_bank_source${"itemId":"454c22cc-dd07-588f-a03f-a49bba7a88b7","questionId":"b099ce3b-666e-5b68-ab9d-66799d460877","sourceKey":"bank:FIN216:FUN-033","payload":{"prompt":"Under the NDIC Act 2023, which fund covers deposit money banks and mobile money operators?","options":["The Deposit Insurance Fund","The Non-Interest Special Insured Institutions Fund","The Special Insured Institutions Fund","The Payment Service Banks Insurance Fund"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The Deposit Insurance Fund covers deposit money banks and mobile money operators. Option C is for MFBs and PMBs, option B is for non-interest MFBs and PMBs, and option D is for payment service banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 203, $official_bank_source${"itemId":"60b7ac78-0929-55ce-8f99-26f68022f611","questionId":"bf7943e9-37ee-593b-be09-1b8a18ded5bb","sourceKey":"bank:FIN216:FUN-034","payload":{"prompt":"In Nigeria's deposit insurance arrangement, who pays the deposit insurance premium?","options":["The Central Bank of Nigeria","The Federal Ministry of Finance","The individual depositor","The insured bank"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Deposit insurance involves three parties: the insurer, the bank that pays the premium, and the depositor who is protected without paying any premium. Option C is the protected party, not the payer, and options B and A provided the NDIC's capital but do not pay premiums."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 204, $official_bank_source${"itemId":"c46e59c7-40ff-54f2-85a4-9480cfcefd06","questionId":"56bffc5e-5d2a-5d55-844c-fba27af733f3","sourceKey":"bank:FIN216:FUN-035","payload":{"prompt":"Deposits that meet the requirements for cover under a deposit insurance scheme, usually defined by type of depositor or type of deposit, are called:","options":["Insider deposits","Eligible deposits","Uninsured deposits","Brokered deposits"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Eligible deposits are those that fall within the scope of cover set by the scheme. Option A refers to deposits of staff and directors, which were excluded under the 2006 Act, option C refers to amounts outside cover, and option D refers to deposits placed through middlemen, which is not what the definition describes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 205, $official_bank_source${"itemId":"7bd52674-26eb-5b97-b453-9a988a98406b","questionId":"b0cc9cc2-014b-5ae7-8268-60189b8f2279","sourceKey":"bank:FIN216:FUN-036","payload":{"prompt":"Under section 3 of the NDIC Act 2023, the NDIC guarantees the deposit liabilities of institutions licensed under which law?","options":["The Investments and Securities Act","The Companies and Allied Matters Act 2020","The Banks and Other Financial Institutions Act 2020","The Insurance Act"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Section 3 of the 2023 Act ties the guarantee to deposit-taking institutions licensed under BOFIA 2020, the banking licensing law. Option B governs ordinary companies, and options A and D govern capital market and insurance firms, which are not insured by the NDIC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 206, $official_bank_source${"itemId":"f7fd59fa-884e-58ff-a598-196337f4dcb3","questionId":"d7d28d12-a822-5fc1-bbd9-3cbf6d2ac658","sourceKey":"bank:FIN216:FUN-037","payload":{"prompt":"The NDIC set up a Special Insured Institutions Department. This department was created to supervise:","options":["Insurance companies and pension funds","Deposit money banks only","Microfinance banks and primary mortgage banks","Bureaux de change"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The NDIC created a Special Insured Institutions Department to supervise MFBs and PMBs, which are smaller than deposit money banks. Option B is wrong because the department was set up specifically for the smaller MFBs and PMBs, and options A and D are not NDIC-insured institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 207, $official_bank_source${"itemId":"a0e010a6-e5fa-5660-b5fd-47e75192a0a9","questionId":"14bd27ee-dea8-53b4-bb18-7df260a6287c","sourceKey":"bank:FIN216:FUN-038","payload":{"prompt":"Under NDIC guidelines, the trust account a mobile money operator keeps with a bank is insured as if each subscriber held the deposit directly, up to the limit per subscriber. This arrangement is called:","options":["Reinsurance","Pass-through deposit insurance","Co-insurance","Blanket guarantee"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Pass-through deposit insurance looks through the pooled account and covers each mobile money subscriber separately. Option D is unlimited protection declared by the authorities, option C is when the depositor bears part of the loss, and option A is insurance for the insurer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 208, $official_bank_source${"itemId":"c68b8311-6592-52e4-ae67-b0264a126ff5","questionId":"408fd5b5-74a4-5651-91bf-770f4482d425","sourceKey":"bank:FIN216:FUN-039","payload":{"prompt":"The NDIC released guidelines extending pass-through deposit insurance to subscribers of mobile money operators in:","options":["2009","2023","2016","2006"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The NDIC issued its pass-through deposit insurance guidelines for mobile money in January 2016. Option D is the year of the NDIC Act 2006, option A is too early because the mobile money guidelines came later, and option B is the year of the new NDIC Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 209, $official_bank_source${"itemId":"987b4f2b-054c-52aa-a9d4-4af155b012d4","questionId":"c844129b-3580-50d1-a8f6-1c3cfc36c90e","sourceKey":"bank:FIN216:FUN-040","payload":{"prompt":"In 2025 a deposit money bank holding the pooled trust account of a mobile money operator fails. Chidi's mobile wallet balance is N6.4 million. Under the pass-through cover set by the NDIC in May 2024, the maximum the NDIC pays Chidi is:","options":["N500,000","N6,400,000","N5,000,000","N2,000,000"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Since May 2024 the pass-through cover for mobile money subscribers is N5 million per subscriber per MMO, so Chidi gets N5 million and the remaining N1.4 million is uninsured. Option B assumes full cover, option D uses the MFB/PMB/PSB limit, and option A is the old pre-2024 subscriber limit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 210, $official_bank_source${"itemId":"f6aa65b4-64d4-53ed-951d-056c8d58274f","questionId":"5a6743e4-526e-5806-a1bf-9a73e4774fed","sourceKey":"bank:FIN216:FUN-041","payload":{"prompt":"In 2020 a bank holding an MMO's pooled trust account failed. Under the pass-through cover in force then, a subscriber with N750,000 in her wallet could receive at most:","options":["N200,000","N750,000","N5,000,000","N500,000"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"From the 2016 guidelines until May 2024, each mobile money subscriber was covered up to N500,000, so N250,000 of her N750,000 was uninsured. Option B assumes full cover, option A is the old MFB limit, and option C is the limit introduced only in May 2024."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 211, $official_bank_source${"itemId":"b27bfb5f-d3a5-5459-b794-e03541a10385","questionId":"3acdddb9-c8cf-5cb5-acc2-85da824d7260","sourceKey":"bank:FIN216:FUN-042","payload":{"prompt":"Why is pass-through deposit insurance for mobile money subscribers important for financial inclusion in Nigeria?","options":["It lets mobile money operators avoid supervision by the CBN","It removes the need for any coverage limit on mobile wallets","It guarantees mobile money operators a profit on every transfer","It extends deposit protection to low-income mobile wallet users who may not hold bank accounts"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Many newly included Nigerians save through mobile wallets, and pass-through cover gives each subscriber protection if the bank holding the pooled funds fails. Option A is wrong because MMOs remain regulated, option C has nothing to do with insurance, and option B is wrong because cover is capped per subscriber."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 212, $official_bank_source${"itemId":"8cbc6a07-909c-527c-8fa9-f1383fad73bd","questionId":"cfbc5aba-3344-56ab-a761-031b0ba7116e","sourceKey":"bank:FIN216:FUN-043","payload":{"prompt":"Under section 16 of the NDIC Act 2006, which of the following deposits was excluded from insurance cover?","options":["Deposits of staff, including directors, of the insured institution","Current account balances of small businesses","Fixed deposits of retired civil servants","Savings deposits of individual customers"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2006 Act excluded insider deposits, meaning deposits of the bank's own staff and directors. Options D, B and C are ordinary customer deposits that were insured up to the limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 213, $official_bank_source${"itemId":"0d09a723-cc01-510a-989d-b2e5739f7b2d","questionId":"b7f630ac-083b-519a-885b-9bf0485c870d","sourceKey":"bank:FIN216:FUN-044","payload":{"prompt":"Under the NDIC Act 2006, deposits held by the staff and directors of an insured bank in that same bank were called:","options":["Insider deposits","Eligible deposits","Public sector deposits","Brokered deposits"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Insider deposits are deposits of the bank's own staff and directors, and the 2006 Act excluded them from cover. Option B means deposits inside the scheme's cover, and options D and C are not the term the Act used for this group."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 214, $official_bank_source${"itemId":"1866096f-9076-580e-8cda-2fd85c80cfe0","questionId":"25aa8793-4171-5def-b3bc-db244aac4eea","sourceKey":"bank:FIN216:FUN-045","payload":{"prompt":"In 2012 Bank R failed. Which of these depositors had NO insured deposit under the NDIC Act 2006?","options":["Mr Eze, an executive director of Bank R, with N400,000 in Bank R","Mr Musa, a teacher, with N400,000 in Bank R","Mrs Okafor, a trader, with N150,000 in Bank R","Miss Adeyemi, a student, with N30,000 in Bank R"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"As a director, Mr Eze's deposit was an insider deposit, which the 2006 Act excluded from cover. Options C, B and D are ordinary customers whose deposits were insured up to the limit then in force."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 215, $official_bank_source${"itemId":"fbfeff33-aa9b-5716-97e3-9be52e8e26ab","questionId":"17b6413a-84bb-5918-a592-67e8c4b7af83","sourceKey":"bank:FIN216:FUN-046","payload":{"prompt":"Under section 16 of the NDIC Act 2006, which of the following was NOT a category of deposit excluded from cover?","options":["Savings deposits of ordinary individual customers","Deposits that serve as counterclaims for a customer who has both a deposit and a loan account","Other deposits specified from time to time by the NDIC Board","Deposits of staff and directors of the insured institution"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Ordinary customers' savings are exactly what deposit insurance is meant to protect. Options D, B and C are the three genuine exclusions in section 16 of the 2006 Act: insider deposits, deposits matched by loans (counterclaims) and deposits the Board specifies."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 216, $official_bank_source${"itemId":"638d6f82-b29b-579a-b8fe-fe3594134b75","questionId":"4272dd7f-518e-565d-b077-481dd800e98b","sourceKey":"bank:FIN216:FUN-047","payload":{"prompt":"Under section 22(2) of the NDIC Act 2006, if a depositor of a failed bank also owed that bank money, the NDIC could:","options":["Withhold part of the insured deposit until the debt was settled","Refuse to pay any of the deposit, forever","Pay double the insured amount to cover the debt","Pay the insured deposit in full and cancel the debt"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2006 Act allowed the NDIC to withhold the portion of an insured deposit needed to cover a debt the depositor owed the failed bank until that debt was determined and paid. Option D wrongly cancels the debt, option B goes beyond the rule, and option C is not allowed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 217, $official_bank_source${"itemId":"43be810a-5d97-50a8-9ee8-2a0f1e2908ef","questionId":"a24bd8b7-cbe4-5000-b934-e760994c251d","sourceKey":"bank:FIN216:FUN-048","payload":{"prompt":"Under section 22(1) of the NDIC Act 2006, the NDIC could withhold payment of a depositor's claim pending a determination where:","options":["The depositor held a savings account rather than a current account","The depositor was found to have connived with officials of the failed bank","The depositor lived outside Lagos","The depositor's balance was below the coverage limit"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Where a depositor had connived with the failed bank's officials, the NDIC could hold back the claim until the matter was decided. Options D, C and A are irrelevant to eligibility; a small balance, location or account type does not stop payment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 218, $official_bank_source${"itemId":"c9fa5359-0607-5bc1-ab02-ca5ea92f7393","questionId":"90726cdc-d02e-596b-b154-73fb9e725f15","sourceKey":"bank:FIN216:FUN-049","payload":{"prompt":"Why does the NDIC set a maximum guarantee limit rather than insure every deposit in full?","options":["Because the law forbids paying any depositor more than N50,000","To protect most small depositors while leaving large depositors with reason to monitor their banks","Because insured banks pay no premiums on large deposits","To make sure large corporate depositors are fully protected"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Limited cover protects the large majority of small depositors while leaving part of large balances at risk, which keeps market discipline and reduces moral hazard. Option A cites a limit that ended long ago, option D is the opposite of the purpose, and option C is wrong because premiums are charged on total deposits."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 219, $official_bank_source${"itemId":"e85065a8-599d-5f8f-b3c5-97203b3fb4d8","questionId":"74c5c4d7-5300-5bf9-b5a7-63546810e555","sourceKey":"bank:FIN216:FUN-050","payload":{"prompt":"In 1995 a bank insured under the 1988 NDIC Decree failed. Mr Obi had N80,000 in the bank. What was the maximum insured amount the NDIC would pay him?","options":["N50,000","N100,000","N200,000","N80,000"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"When the NDIC began in 1989 under the 1988 Decree, cover was a maximum of N50,000 per depositor, so N30,000 of Mr Obi's balance was uninsured. Option D assumes full cover, and options B and C are limits introduced under the 2006 Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 220, $official_bank_source${"itemId":"6661c9ef-0399-5be5-833b-9ef5fb424b49","questionId":"f7e438ff-4c25-57d1-b8e9-920be1b6cd70","sourceKey":"bank:FIN216:FUN-051","payload":{"prompt":"Under section 20 of the NDIC Act 2006 (as originally enacted), the maximum insured amount per depositor was:","options":["N50,000 for all insured institutions","N100,000 for licensed banks and N200,000 for other deposit-taking institutions","N200,000 for licensed banks and N100,000 for other deposit-taking institutions","N500,000 for licensed banks and N200,000 for other deposit-taking institutions"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2006 Act raised cover to N200,000 for licensed banks and set N100,000 for other deposit-taking institutions such as MFBs and PMBs. Option B reverses the two figures, option D gives the later raised limits, and option A is the 1988 Decree limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 221, $official_bank_source${"itemId":"d82131af-94e7-5e2e-b186-c39a6f2de941","questionId":"c1a3d6c9-4cbf-568b-94c4-63209d145095","sourceKey":"bank:FIN216:FUN-052","payload":{"prompt":"In 2008 a microfinance bank failed. Under the NDIC Act 2006 as then in force, a depositor with N180,000 in the bank could receive at most:","options":["N180,000","N100,000","N200,000","N50,000"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Under the 2006 Act, depositors of other deposit-taking institutions such as microfinance banks were covered up to N100,000. Option A assumes full cover, option C is the licensed bank limit of the time, and option D is the old 1988 Decree limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 222, $official_bank_source${"itemId":"6a96afe4-f97e-5460-873b-79db70e9ed01","questionId":"3fe0ff89-06b4-5679-a10f-13288cfe0e03","sourceKey":"bank:FIN216:FUN-053","payload":{"prompt":"When the NDIC raised the coverage limit from N200,000 to N500,000 under the NDIC Act 2006, which institutions did this increase apply to?","options":["Microfinance banks","Mobile money operators","Deposit money banks","Payment service banks"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The rise from N200,000 to N500,000 applied to deposit money banks, while MFBs and PMBs moved from N100,000 to N200,000 at the same time. Option A got the smaller increase, and options D and B were not yet part of the scheme at that time."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 223, $official_bank_source${"itemId":"2e2b17b9-3b63-55a7-b7ed-cf6b16ffd671","questionId":"95f59544-f88a-5966-b1c7-23c331e99e10","sourceKey":"bank:FIN216:FUN-054","payload":{"prompt":"In the same review that raised deposit money bank cover from N200,000 to N500,000, cover for microfinance and primary mortgage banks was raised from:","options":["N100,000 to N200,000","N200,000 to N500,000","N200,000 to N2,000,000","N50,000 to N100,000"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"MFB and PMB cover moved from N100,000 to N200,000 when DMB cover moved to N500,000. Option B is the DMB change, option C is the May 2024 MFB change, and option D does not match any NDIC review."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 224, $official_bank_source${"itemId":"4e621b6e-e912-5e1c-b1de-be27a1522e02","questionId":"5e380a7a-8421-5c30-ade4-505b39b1a750","sourceKey":"bank:FIN216:FUN-055","payload":{"prompt":"In late 2016 the NDIC raised the maximum cover for depositors of primary mortgage banks from N200,000 to:","options":["N500,000","N2,000,000","N300,000","N5,000,000"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"In late 2016 PMB cover was raised to N500,000, bringing it level with deposit money banks at that time. Options B and D are limits set only in May 2024, and option C was never an NDIC limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 225, $official_bank_source${"itemId":"73ffcaea-883e-5b12-8a21-a9b30d1f3810","questionId":"c434ae00-ff42-5388-bc3d-3d6e4d2956d4","sourceKey":"bank:FIN216:FUN-056","payload":{"prompt":"The NDIC raised the maximum cover for deposit money bank depositors from N500,000 to N5,000,000 in:","options":["December 2025","May 2023","January 2016","May 2024"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The NDIC announced on 2 May 2024 that DMB cover would rise from N500,000 to N5 million with immediate effect. Option B is when the NDIC Act 2023 was signed, option C is when the pass-through guidelines for mobile money were issued, and option A is when two primary mortgage banks lost their licences."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 226, $official_bank_source${"itemId":"144a0882-99bf-55fa-9a21-10de9e68de64","questionId":"50578222-cef7-5e11-89b4-f22a4ebbb74e","sourceKey":"bank:FIN216:FUN-058","payload":{"prompt":"Following the NDIC's May 2024 review, the maximum cover per depositor of a payment service bank is:","options":["N500,000","N5,000,000","N2,000,000","N200,000"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"In May 2024 PSB cover went from N500,000 to N2 million, the same as MFBs and PMBs. Option A is the PSB limit before May 2024, option B is the new DMB limit, and option D is the old MFB limit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 227, $official_bank_source${"itemId":"b040e370-81a8-5fcf-8647-9358fe029cd3","questionId":"20b15790-b7d1-543b-a268-75a826755582","sourceKey":"bank:FIN216:FUN-059","payload":{"prompt":"In the NDIC's May 2024 review, which two types of institution both had their cover raised from N500,000 to N2,000,000?","options":["Primary mortgage banks and payment service banks","Microfinance banks and primary mortgage banks","Deposit money banks and payment service banks","Deposit money banks and microfinance banks"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"PMBs and PSBs were both at N500,000 before May 2024 and both moved to N2 million. Option D is wrong because DMBs went to N5 million and MFBs started from N200,000, option B is wrong because MFBs started from N200,000, and option C is wrong because DMBs went to N5 million."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 228, $official_bank_source${"itemId":"e3f570f6-c691-596d-92c3-70d710e22474","questionId":"682e2539-fbd6-5a8d-96a1-784cd2103764","sourceKey":"bank:FIN216:FUN-060","payload":{"prompt":"In the May 2024 review, cover for microfinance bank depositors was raised from N200,000 to N2,000,000. By what factor did the MFB limit increase?","options":["Four times","Two and a half times","Ten times","Twenty times"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"N2,000,000 divided by N200,000 equals 10, so the MFB limit rose tenfold, the same factor as the DMB rise from N500,000 to N5 million. Option A is the factor for PMBs and PSBs (N500,000 to N2 million), and options B and D are miscalculations."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 229, $official_bank_source${"itemId":"bc2521dd-756f-5c1e-baa2-3065bef18e7f","questionId":"9651ba9d-2869-57f7-a71c-62caff610707","sourceKey":"bank:FIN216:FUN-061","payload":{"prompt":"Which pairing of institution and maximum cover per depositor is correct after the NDIC's May 2024 review?","options":["Primary mortgage bank - N5,000,000","Deposit money bank - N2,000,000","Microfinance bank - N2,000,000","Payment service bank - N500,000"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Since May 2024 MFB depositors are covered up to N2 million. Option A wrongly gives PMBs the DMB figure, option B wrongly gives DMBs the N2 million figure, and option D is the old PSB limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 230, $official_bank_source${"itemId":"c88edf78-7354-55bf-a273-bb901ca0aa39","questionId":"539a71ae-f25b-5c48-ad85-092f8a5c9063","sourceKey":"bank:FIN216:FUN-062","payload":{"prompt":"Which of the following statements about NDIC cover after the May 2024 review is NOT correct?","options":["A mobile money subscriber is covered up to N5,000,000 per MMO under pass-through cover","A deposit money bank depositor is covered up to N5,000,000","A primary mortgage bank depositor is covered up to N5,000,000","A microfinance bank depositor is covered up to N2,000,000"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"PMB depositors are covered up to N2 million, not N5 million. Options B, D and A correctly state the 2024 limits for DMBs, MFBs and mobile money subscribers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 231, $official_bank_source${"itemId":"65c4f49a-8656-57b9-adae-601b75ddd86a","questionId":"8591fa98-84a0-5e51-ae79-4ee71a86ecf9","sourceKey":"bank:FIN216:FUN-063","payload":{"prompt":"After the May 2024 increase, the NDIC said about 98.98 percent of deposit money bank depositors were fully covered, but only about 25.37 percent of the value of DMB deposits was covered. This shows that limited cover:","options":["Covers every naira of deposits held in deposit money banks","Protects almost all large depositors while leaving small savers exposed","Covers fewer depositors than it did before the increase","Protects almost all small depositors while leaving most of the value of large deposits exposed to market discipline"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Most depositors hold small balances, so nearly all of them are fully covered, while large balances above N5 million stay partly uninsured and keep big depositors watchful. Option B reverses the effect, option A contradicts the 25.37 percent figure, and option C is wrong because coverage rose from 89.20 percent of depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 232, $official_bank_source${"itemId":"137700c5-4547-5cb7-8d35-e31ebc6a28dc","questionId":"2de18032-0af8-5f03-8102-259f9979e74d","sourceKey":"bank:FIN216:FUN-064","payload":{"prompt":"Mrs Bello has N7.5 million in a savings account in her own name at a deposit money bank whose licence is revoked in 2025. Under the cover set by the NDIC in May 2024, how much of her deposit is uninsured?","options":["N7,000,000","N2,500,000","N5,000,000","N0"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"DMB cover is N5 million, so N7.5 million minus N5 million leaves N2.5 million uninsured, which she can claim through liquidation dividends. Option C is the insured part, not the uninsured part, option A uses the old N500,000 limit, and option D assumes full cover."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 233, $official_bank_source${"itemId":"4ccd9849-0408-5d99-8476-994c55f83708","questionId":"2569b4bd-4ad6-5c41-9b1d-83ccf0831a13","sourceKey":"bank:FIN216:FUN-065","payload":{"prompt":"In December 2025 the CBN revoked the licence of a primary mortgage bank. Tunde had N1.6 million in his account there. How much insured deposit should the NDIC pay him?","options":["N1,600,000","N500,000","N2,000,000","N400,000"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"PMB cover is N2 million per depositor, and since his N1.6 million balance is below the limit, all of it is insured. Option C wrongly pays the full limit rather than the actual balance, option B is the old PMB limit, and option D is the gap between his balance and the limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 234, $official_bank_source${"itemId":"092db761-15e6-5e0a-a1f7-433c0e641179","questionId":"51b47f24-8b1c-55b2-af18-b05c7fcb5885","sourceKey":"bank:FIN216:FUN-066","payload":{"prompt":"In 2025 a microfinance bank in Ibadan fails. Mama Kemi has N3.5 million in her account there. What is the maximum insured amount the NDIC pays her?","options":["N5,000,000","N200,000","N3,500,000","N2,000,000"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"MFB depositors are covered up to N2 million since May 2024, so N1.5 million of her balance is uninsured. Option C assumes full cover, option A wrongly applies the DMB limit, and option B is the pre-2024 MFB limit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 235, $official_bank_source${"itemId":"d57940f6-6b67-5d0d-989e-5523776ec11e","questionId":"b2c70734-7c86-54d8-9150-de6c1afa1218","sourceKey":"bank:FIN216:FUN-067","payload":{"prompt":"In 2025 a microfinance bank fails with three depositors: A has N500,000, B has N2.5 million and C has N4 million. Under the May 2024 limits, what is the NDIC's total insured payout to the three?","options":["N6,000,000","N4,500,000","N1,500,000","N7,000,000"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Each depositor is paid the lower of the balance and the N2 million MFB limit: N500,000 + N2,000,000 + N2,000,000 = N4,500,000. Option D adds the full balances, option A pays everyone the full N2 million limit, and option C uses the old N500,000 limit for all three."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 236, $official_bank_source${"itemId":"d1dddd79-4863-56cc-bf44-05284d05dd90","questionId":"eec21165-6ff9-5b6d-8e61-f847e0cf06cd","sourceKey":"bank:FIN216:FUN-068","payload":{"prompt":"In 2025 Mr Ade had N12 million at a failed deposit money bank. The NDIC paid his insured amount under the May 2024 limit, and later declared a liquidation dividend of 40 percent on uninsured balances. How much did Mr Ade recover in total?","options":["N9,800,000","N7,800,000","N4,800,000","N5,000,000"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"He gets N5 million insured, and the uninsured N7 million earns a 40 percent dividend of N2.8 million, so he recovers N7.8 million. Option D ignores the dividend, option C applies 40 percent to the whole N12 million, and option A adds the insured N5 million to 40 percent of the whole balance."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 237, $official_bank_source${"itemId":"0bb40ad8-866e-56d1-a579-e6483162a487","questionId":"12ba9b98-dec6-5a3a-86d3-192004cab141","sourceKey":"bank:FIN216:FUN-069","payload":{"prompt":"In 2015, while DMB cover was N500,000, Mr Ojo held a savings account of N300,000 and a current account of N400,000, both in his own name, at a bank whose licence was revoked. Under the NDIC Act 2006, his insured amount was:","options":["N500,000","N900,000","N1,000,000","N700,000"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Section 20(3) of the 2006 Act merged all accounts held in the same right and capacity in one failed bank, so his two accounts counted as N700,000, capped at N500,000. Option D assumes full cover, option B wrongly gives N500,000 for one account plus N400,000 for the other, and option C wrongly gives a full N500,000 to each account."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 238, $official_bank_source${"itemId":"f81287b9-dbff-5d07-9f66-a22841ba220b","questionId":"87d505f7-423f-570e-bbdf-eeb1d7066647","sourceKey":"bank:FIN216:FUN-070","payload":{"prompt":"Under section 20(3) of the NDIC Act 2006, if a depositor held several accounts in the same right and capacity in one failed insured bank, those accounts were:","options":["Insured only for the largest single account","Each insured separately up to the full limit","Merged and treated as one account for the coverage limit","Excluded from cover altogether"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2006 Act merged all accounts held in the same right and capacity in one failed bank, so a depositor could not multiply cover by opening several accounts in the same bank. Option B is the mistake the rule prevents, option D is too harsh, and option A ignores the smaller accounts."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 239, $official_bank_source${"itemId":"6d4ad230-7d7b-5c96-91d5-482d9077a82a","questionId":"8aa64aff-83e6-5186-a00d-d9b8e55138b3","sourceKey":"bank:FIN216:FUN-071","payload":{"prompt":"Before May 2024, when DMB cover was N500,000 per depositor of an insured institution, Mrs Ibe had N400,000 at Bank A and N400,000 at Bank B, two separate DMBs that both failed. Her total insured amount was:","options":["N1,000,000","N500,000","N800,000","N400,000"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Cover applied per depositor of each insured institution, so each N400,000 balance was fully insured in its own bank, giving N800,000. Option B wrongly applies one limit across two banks, option D pays only one bank, and option A pays the full limit in each bank even though each balance was below it."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 240, $official_bank_source${"itemId":"27de4dae-270f-5ce6-85af-be2041c8ddb8","questionId":"6ee410ce-c4ed-5a88-a4b1-c19b3b7a1018","sourceKey":"bank:FIN216:FUN-072","payload":{"prompt":"Under section 20(4) of the NDIC Act 2006, once a depositor received the insured sum, what happened to the part of the deposit above the limit?","options":["It was lost forever once the insured sum was paid","It was paid in full at once by the CBN","It was turned into shares in the failed bank","The depositor could still receive liquidation dividends on it as the bank's assets were sold"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Paying the insured sum did not stop the depositor sharing in liquidation dividends on the uninsured balance as the failed bank's assets were realised. Option A ignores this right, option B wrongly brings in the CBN, and option C has no basis in law."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 241, $official_bank_source${"itemId":"af2796d9-bf45-54bc-9b8a-42483bdfd514","questionId":"026db403-1875-5fda-b0f5-f84d2ab7324c","sourceKey":"bank:FIN216:FUN-078","payload":{"prompt":"Under section 21(1) of the NDIC Act 2006, which of the following was a way the NDIC could pay an insured depositor?","options":["Transferring the insured deposit to an account at another insured institution","Offsetting the deposit against the depositor's taxes","Issuing shares in the failed bank to the depositor","Giving the depositor land owned by the failed bank"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2006 Act allowed payment in cash, by negotiable instrument, or by making the insured deposit available as a transferred deposit in another insured institution. Options C, D and B are not payment methods allowed by the Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 242, $official_bank_source${"itemId":"1300a44a-3d7c-5953-bf4d-bf6740fe0f90","questionId":"904d07d9-e769-5f63-b045-f317f4758e07","sourceKey":"bank:FIN216:FUN-081","payload":{"prompt":"Under section 22(4) of the NDIC Act 2006, an insured depositor who did not claim the insured deposit lost the right to it after:","options":["Eighteen months","One year","90 days","Six years"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 2006 Act gave depositors six years after notice to claim, after which the rights passed to the NDIC. Option A was the 1988 Decree rule, option C was the 2006 deadline for the NDIC to pay, and option B was the extra year of cover after insured status was terminated."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 243, $official_bank_source${"itemId":"0501eaf0-18b6-55dd-8235-1a9ff9216abe","questionId":"180647e1-f8c0-583d-aee4-3d0e96e14b43","sourceKey":"bank:FIN216:FUN-082","payload":{"prompt":"Under the 1988 NDIC Decree, an insured depositor who did not claim within what period of the receiver's appointment (after notice) lost the right to the insured deposit?","options":["6 years","30 days","90 days","18 months"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 1988 Decree set an 18-month claim period, which the 2006 Act later extended to six years. Option A is the later 2006 rule, option C is the 2006 payment deadline, and option B is the 2023 Service Charter target for paying depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 244, $official_bank_source${"itemId":"36e34321-6fbf-5698-9b26-ce627ef9c3a6","questionId":"0526a29b-e392-5f0e-88ac-f95154fc1fc7","sourceKey":"bank:FIN216:FUN-084","payload":{"prompt":"Which of the following best describes how the NDIC supports financial inclusion in Nigeria?","options":["By issuing national identity numbers to unbanked adults","By regulating insurance firms that sell microinsurance","By granting interest-free loans directly to unbanked Nigerians","By guaranteeing deposits, especially of small savers, and providing consumer protection, distress resolution and public education"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The NDIC supports inclusion by protecting small savers' deposits, protecting consumers, resolving distressed banks and educating the public, all of which build trust in banks. Option C is not an NDIC function, option A is the work of NIMC, and option B is the work of NAICOM."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 245, $official_bank_source${"itemId":"f4affae7-d753-5993-9cf6-ca8852e1d24b","questionId":"2e58576f-9d2d-577f-8e04-5e969540c3b9","sourceKey":"bank:FIN216:FUN-085","payload":{"prompt":"Financial inclusion primarily implies access to which of the following?","options":["A government job, free housing and a pension","Informal savings clubs such as esusu and ajo","Shares in listed companies and foreign currency accounts","A bank account backed by deposit insurance, affordable credit and the payments system"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Financial inclusion mainly means access to a deposit-insured bank account, affordable credit and payment services, which is why deposit insurance matters for inclusion. Options A and C are not the core of inclusion, and option B describes informal finance, which is outside the formal insured system."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 246, $official_bank_source${"itemId":"1da23bc0-3a90-5aa8-ae0f-9718dc54500a","questionId":"76a4255b-1303-5ac5-be67-6f69e6fc4b11","sourceKey":"bank:FIN216:FUN-086","payload":{"prompt":"Under the Nigerian National Financial Inclusion Strategy (2012), the NDIC is classified in which stakeholder group?","options":["Providers","Beneficiaries","Supporting institutions","Enablers"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Enablers are regulators and public institutions such as the CBN, NIMC, PenCom and the NDIC that set rules and policies for financial inclusion. Option A covers banks, MFBs and telcos that offer products, and option C covers development partners such as the Bill and Melinda Gates Foundation, SMEDAN and NIPOST. Option B is not one of the strategy's stakeholder groups."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 247, $official_bank_source${"itemId":"46a9a3ad-ef72-54af-bd3d-8807a22afb62","questionId":"3d197508-26ed-5c56-8653-a077d70dd2a9","sourceKey":"bank:FIN216:FUN-087","payload":{"prompt":"Which institution has been the main driver of financial inclusion in Nigeria, with the NDIC playing a supporting role?","options":["The NDIC","The Central Bank of Nigeria","NAICOM","The Nigerian Postal Service"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The CBN leads and coordinates the National Financial Inclusion Strategy, while the NDIC supports it by guaranteeing deposits and protecting small savers. Option A supports but does not lead, and options C and D play narrower roles in insurance and limited postal financial services."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 248, $official_bank_source${"itemId":"701171b4-dacc-5c0d-872a-5885e273e73b","questionId":"f0abd4dd-6b84-5a42-b377-61dfe9c65f6d","sourceKey":"bank:FIN216:FUN-088","payload":{"prompt":"The Financial Literacy Steering Committee, inaugurated on 16 July 2013 to give policy direction on financial literacy, is chaired by the CBN Governor. Which NDIC official sits on it?","options":["The Managing Director/Chief Executive of the NDIC","No NDIC official sits on the committee","The NDIC Head of Liquidation as secretary","The NDIC Board Chairman as alternate chairman"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The MD/CEO of the NDIC is a member of the Financial Literacy Steering Committee, which shows the NDIC's role in financial education. Option D is wrong because the alternate chairman is the CBN Deputy Governor (Financial System Stability), option C is wrong because the CBN's Consumer Protection Department is secretary, and option B is simply untrue."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 249, $official_bank_source${"itemId":"58f73ff3-2e34-5488-b3e9-1c80e15f120b","questionId":"320d9d39-91e9-5a82-9e5a-338d2bbbff07","sourceKey":"bank:FIN216:FUN-089","payload":{"prompt":"Iya Basira saves N5,000 a week with an ajo (esusu) collector in her market and has no bank account. Which statement is correct?","options":["She is financially excluded, but her savings are covered by pass-through insurance","She is in the 'informal only' group, and her ajo savings are not protected by the NDIC","She is 'banked', and her savings are insured up to N2 million","She is 'formal other', and her savings are insured up to N5 million"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Using only informal services such as ajo or esusu puts her in the 'informal only' group, and only deposits in licensed insured institutions are covered by the NDIC. Options C and D wrongly treat ajo as formal banking, and option A misuses pass-through cover, which applies to mobile money subscribers' funds held in insured banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 250, $official_bank_source${"itemId":"2604a8b5-9340-5b31-bed1-db3e23aebc2d","questionId":"93e5931c-68a3-5854-ba3d-13fb2377bc8f","sourceKey":"bank:FIN216:FUN-090","payload":{"prompt":"When the National Financial Inclusion Strategy was launched in October 2012, its overall target was to reduce the share of financially excluded adult Nigerians from 46.3 percent in 2010 to:","options":["39.7 percent by 2020","10 percent by 2015","58.4 percent by 2020","20 percent by 2020"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The NFIS aimed to cut financial exclusion from 46.3 percent in 2010 to 20 percent by 2020. Option A is the 2012 exclusion rate quoted under the Maya Declaration, and option C is the inclusion rate actually achieved. Option B was never the target."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 251, $official_bank_source${"itemId":"aafeb44f-9aa2-5cdf-8f21-e6cda1e9705f","questionId":"448a35e3-ed35-55bc-8ec0-2e2e18d942fa","sourceKey":"bank:FIN216:FUN-091","payload":{"prompt":"Which of the following was NOT one of the key interventions under Nigeria's financial inclusion commitment (Maya Declaration)?","options":["Mobile payments and cash-less policy initiative","Abolishing deposit insurance for microfinance banks","Agent banking regulatory framework","Simplified KYC framework"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Removing deposit insurance from MFBs would hurt inclusion, since MFBs serve many low-income savers; it was never an intervention. Options D, C and A are genuine interventions that make it easier and cheaper for the unbanked to open and use accounts."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 252, $official_bank_source${"itemId":"76633f5d-aa91-50dc-b1ea-25d068afb50c","questionId":"915d7398-07c7-5e18-963e-edf803ba3fcf","sourceKey":"bank:FIN216:FUN-092","payload":{"prompt":"A rural trader in Kano is reluctant to move her savings from her home into a microfinance bank. How does deposit insurance help address her concern?","options":["It guarantees her a fixed high interest rate on savings","It assures her that, if the MFB fails, her deposit is protected up to the insured limit","It guarantees that the MFB will never fail","It guarantees she will receive a loan from the MFB"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Deposit insurance does not stop banks failing, but it promises insured depositors repayment up to the limit, which builds the trust needed to bring savings into formal banks. Option C overstates what insurance can do, and options D and A confuse deposit protection with lending and pricing decisions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 253, $official_bank_source${"itemId":"d8041715-a9c9-56af-b6fa-d58839900da4","questionId":"e93a058f-8d31-5b02-b68b-677a47594244","sourceKey":"bank:FIN216:FUN-093","payload":{"prompt":"In Nigeria's deposit insurance scheme, an 'insured institution' is best defined as:","options":["A licensed deposit-taking institution whose deposit liabilities are insured with the NDIC","A depositor whose account balance is below the coverage limit","Any company listed on the Nigerian Exchange","An insurance company licensed by NAICOM"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Insured institutions are the banks and other licensed deposit-takers, such as DMBs, MFBs, PMBs and PSBs, that insure their deposits with the NDIC and pay premiums. Option B describes an insured depositor, not an institution, and options D and C are not covered by the scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 254, $official_bank_source${"itemId":"2f4c5158-0bfc-5077-9de7-033f75c97d4b","questionId":"1b442c3b-bc02-50ce-9efe-88b26e506fec","sourceKey":"bank:FIN216:FUN-094","payload":{"prompt":"In 2025 Bank T stops paying depositors, but the CBN has not yet revoked its licence. Compared with the 2006 Act, what does the NDIC Act 2023 allow?","options":["The NDIC may pay only depositors who sue Bank T in court","The NDIC must wait until the licence is revoked before any payout","The NDIC may pay insured deposits on the actual suspension of payments, with CBN concurrence","The NDIC must wait 18 months before any payout"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Under section 4(a) of the 2023 Act, actual suspension of payments, with the CBN's concurrence, can trigger payout even before revocation; the 2006 Act's payout clock ran from licence revocation. Option B describes the older position, option D is the old 1988 claim period, and option A is not a legal condition for payout."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 255, $official_bank_source${"itemId":"0f20a0ed-3499-5633-87d0-aed8a8eeca5a","questionId":"738f3daf-31d2-5660-a2b4-84f45ebdd940","sourceKey":"bank:FIN216:FUN-095","payload":{"prompt":"A depositor with N4 million in a deposit money bank would have been insured for N50,000 when the NDIC began in 1989. Under the limit set in May 2024, how much of the same balance is insured?","options":["N4,000,000","N2,000,000","N5,000,000","N500,000"],"correctOption":0,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The May 2024 DMB limit is N5 million, so a N4 million balance is fully insured, compared with only N50,000 in 1989. Option C wrongly pays the full limit instead of the actual balance, option D is the pre-2024 DMB limit, and option B is the MFB, PMB and PSB limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 256, $official_bank_source${"itemId":"7803ad06-f669-5b4b-a95a-270f0f07d790","questionId":"b559402d-4565-5555-b9ea-252dc343b853","sourceKey":"bank:FIN216:FUN-096","payload":{"prompt":"In 2025 Mr Hassan's N10 million deposit at a failed deposit money bank is insured up to the May 2024 limit. What percentage of his deposit is insured?","options":["5 percent","50 percent","100 percent","20 percent"],"correctOption":1,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"With N5 million of N10 million insured, 5,000,000 divided by 10,000,000 equals 50 percent. Option C assumes full cover, option A uses the old N500,000 limit (500,000 divided by 10,000,000), and option D uses the N2 million MFB limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 257, $official_bank_source${"itemId":"f1b2bd29-9796-596c-a3c0-538184c2ca4d","questionId":"13ec2eed-991d-5dce-9f5f-000622c65979","sourceKey":"bank:FIN216:FUN-097","payload":{"prompt":"Before the NDIC Act 2023, one legal gap the NDIC wanted fixed was that it could not pay insured depositors when a bank was merely unable to meet its obligations. The 2023 Act addressed this mainly by:","options":["Making membership of the scheme voluntary","Transferring the deposit guarantee function to the CBN","Allowing payout on actual suspension of payments, with CBN concurrence, not only on licence revocation","Abolishing the coverage limit for all depositors"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Section 4(a) of the 2023 Act lets insured deposits be paid when an institution actually suspends payments, with the CBN's concurrence, which deals with the earlier gap. Option D is wrong because coverage is still limited, option B is wrong because the guarantee remains with the NDIC, and option A is wrong because membership is still compulsory."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 258, $official_bank_source${"itemId":"d895d182-bf16-5502-bb50-c63884b77270","questionId":"bcc12bd5-f8c0-5882-bc95-820c47f4adb6","sourceKey":"bank:FIN216:FUN-098","payload":{"prompt":"The NDIC examines the books of an insured bank through on-site examination and off-site surveillance. Which statutory mandate is it carrying out?","options":["Bank liquidation","Failure resolution","Deposit guarantee","Bank supervision"],"correctOption":3,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Examining banks' books on-site and analysing their returns off-site is the supervision mandate, which the NDIC shares with the CBN. Option C is about paying insured depositors, option A is about winding up closed banks, and option B is about dealing with banks that are failing or have failed."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 259, $official_bank_source${"itemId":"29076000-d961-5b0d-a6aa-24c596a7016c","questionId":"bdeb9ed9-52a0-5468-a0fb-362f5643a6c8","sourceKey":"bank:FIN216:FUN-099","payload":{"prompt":"After the CBN revokes a bank's licence, the NDIC sells the bank's assets, settles claims of uninsured depositors and creditors and closes the bank in an orderly way. Which mandate is this?","options":["Bank supervision","Deposit guarantee","Bank liquidation","Open bank assistance"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"Selling a closed bank's assets and settling claims in an orderly way is liquidation, normally the last option. Option A is ongoing monitoring of banks, option B is the payment of insured sums, and option D is support given to a bank that is still open."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 260, $official_bank_source${"itemId":"af9c60f3-ff5e-5310-aa3f-2392b06316e5","questionId":"4f32c5db-109f-5e0f-945b-0ef78692fc76","sourceKey":"bank:FIN216:FUN-100","payload":{"prompt":"When the NDIC Act 2006 replaced the 1988 Decree, the maximum cover for depositors of licensed banks moved from:","options":["N100,000 to N200,000","N200,000 to N500,000","N50,000 to N200,000","N50,000 to N100,000"],"correctOption":2,"section":"Functions, Membership and Guarantee Limit of the NDIC","explanation":"The 1988 Decree covered up to N50,000 per depositor, and the 2006 Act raised the cover for licensed banks to N200,000. Option D confuses the new N100,000 limit for other deposit-taking institutions, option A is the later MFB/PMB increase, and option B is the later DMB increase."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 261, $official_bank_source${"itemId":"1decb913-bd2c-5013-bab3-10e9a8e5320a","questionId":"fea9cb84-9c22-5b97-8e71-c6d2f429f220","sourceKey":"bank:FIN216:F216-0014","payload":{"prompt":"The \"E\" in CAMEL stands for ____","options":["Expenditure","Expenses","Earnings","Exigencies"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"CAMEL is the rating framework examiners use to judge a bank's health: Capital adequacy, Asset quality, Management, Earnings and Liquidity. Earnings measures how profitable the bank is and whether its income can absorb losses and build capital. Options A and B are tempting because they sound like income-statement items, but expenses are only one part of the earnings picture and are not what the letter stands for."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 262, $official_bank_source${"itemId":"9f656d0d-af02-5c13-9907-68c2cfc4d998","questionId":"60ec6d75-0963-5db3-9ea3-ecd63eca14ff","sourceKey":"bank:FIN216:F216-0017","payload":{"prompt":"Supervision based on the entire banking group, including its subsidiaries and related entities, is known as ____ supervision.","options":["Transaction-based","Consolidated","Risk-based","On-site"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Consolidated supervision looks at a banking group as a whole, so risks in subsidiaries, including foreign ones, are captured along with the parent bank. Option C, risk-based supervision, focuses on how risky a bank's activities are rather than on the group structure. On-site supervision in option D simply means examiners visiting the bank, and transaction-based checking looks at individual deals."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 263, $official_bank_source${"itemId":"9fec025c-cc2e-5212-9829-31c544e8ce17","questionId":"9b3945ef-a7ef-5f53-84e1-37e252ad5eda","sourceKey":"bank:FIN216:F216-0056","payload":{"prompt":"The Financial Stability Board (FSB) describes G-SIFIs as financial institutions whose distress or disorderly failure would cause significant disruption to ____","options":["The wider financial system only","Both the wider financial system and economic activity","Economic activity only","Neither the financial system nor economic activity"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"The FSB defines global systemically important financial institutions as those whose distress or disorderly failure, because of their size, complexity and interconnectedness, would significantly disrupt both the wider financial system and economic activity. Options A and C are each only half of that definition, and option D contradicts the very idea of being systemically important."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 264, $official_bank_source${"itemId":"e5b47446-ac3c-5e70-bee9-1f5e5d8cb9ab","questionId":"c37e8f03-df7c-5aac-a89c-53d64b1e5b1f","sourceKey":"bank:FIN216:F216-0057","payload":{"prompt":"A Systemically Important Financial Institution (SIFI) could be:","options":["only a government-owned financial institution","only a deposit money bank","a bank, an insurance company or any other financial institution","only an insurance company"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"A SIFI is defined by how much damage its failure would do to the wider financial system, not by the type of licence it holds, so it can be a bank, an insurer or any other large, interconnected financial institution. Option B and option D each pick out just one type of institution, which is too narrow. Option A is wrong because ownership does not decide systemic importance; size, interconnectedness, substitutability and complexity do."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 265, $official_bank_source${"itemId":"4af4efdd-a34d-5650-978e-be5a5667351d","questionId":"7a65e182-7509-5f68-8bf4-92c24595068a","sourceKey":"bank:FIN216:F216-0058","payload":{"prompt":"The Basel Committee has identified factors for assessing the systemic importance of a financial institution, such as:","options":["interconnectedness","substitutability","cross-jurisdictional activity","all of the above"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"The Basel Committee looks at several indicators when judging how systemically important a bank is: its size, interconnectedness, substitutability, complexity and cross-jurisdictional activity. Interconnectedness (A) captures links with other institutions, substitutability (B) asks how easily others could take over its services, and cross-jurisdictional activity (C) measures its reach across countries. Since all three are on the list, D is the best answer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 266, $official_bank_source${"itemId":"71cd01de-2ecf-590f-969e-b6ffa414da28","questionId":"a01d61a9-b8c6-5087-a719-15cc181c6996","sourceKey":"bank:FIN216:F216-0059","payload":{"prompt":"In Nigeria, because banks dominate the financial system, the CBN and NDIC focus enhanced supervision on:","options":["bureaux de change","Systemically Important Banks (SIBs)","primary mortgage banks","microfinance banks"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Banks hold most of the assets in Nigeria's financial system, so the CBN and NDIC framework concentrates on Systemically Important Banks, whose failure could destabilise the whole system. SIBs face more frequent and intensive on-site and off-site supervision. Options D, C and A are small institutions whose individual failure would not threaten the system in the same way."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 267, $official_bank_source${"itemId":"3fa055e8-6f55-5c4e-b20d-0ad16d5e8302","questionId":"458f19ee-fc92-52f8-a7ae-2a7e3adde31e","sourceKey":"bank:FIN216:F216-0060","payload":{"prompt":"Methodologies suggested by the Basel Committee for identifying systemically important banks include:","options":["indicator-based measurement approach","bucketing approach","supervisory judgement approach","all of the above"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"The Basel Committee's methodology combines an indicator-based measurement approach (scoring banks on indicators such as size and interconnectedness), a bucketing approach (grouping banks by score to set extra capital charges) and supervisory judgement to adjust the results. Each of A, B and C is part of that methodology, so D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 268, $official_bank_source${"itemId":"8650472d-cb86-54fe-95a7-9822f1676a6d","questionId":"9a677697-0c07-5522-8c31-9ef203d3487d","sourceKey":"bank:FIN216:F216-0061","payload":{"prompt":"In determining Systemically Important Banks (SIBs) in Nigeria, the CBN/NDIC framework used:","options":["the indicator-based measurement approach together with supervisory judgement","the bucketing approach only","the indicator-based approach only, with no supervisory judgement","the age of each bank and its number of branches only"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Nigeria's SIB framework scored banks with an indicator-based measurement approach (size, interconnectedness, substitutability and complexity) and then applied supervisory judgement to arrive at the final list. Option C leaves out the judgement step, which the regulators did use. Option B is one of the Basel methods, but Nigeria did not adopt it to identify SIBs, and option D is not a recognised method at all."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 269, $official_bank_source${"itemId":"47bd4d8b-5980-549f-8b09-28fbfd460341","questionId":"c6a03c7d-78fb-566e-9de2-db49408bc7d1","sourceKey":"bank:FIN216:SUP-001","payload":{"prompt":"A statutory function in which a specialised agency monitors banks for compliance with written rules on acceptable conduct, so that their activities promote a safe, sound and stable financial system, is called","options":["bank liquidation","failure resolution","deposit guarantee","bank supervision"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Bank supervision is the ongoing monitoring of banks against rules of acceptable behaviour, with the aim of keeping the financial system safe, sound and stable. Option A is the winding up of a bank that has already failed, and option C is the promise to pay insured depositors. Option B deals with banks that are already failing, not routine monitoring of all banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 270, $official_bank_source${"itemId":"c5e7dbe0-8b8b-5d83-9705-46e07a10f428","questionId":"b08532fd-d90a-5e2d-9dbf-e1b9669ac1d8","sourceKey":"bank:FIN216:SUP-002","payload":{"prompt":"Which of the following is NOT an aim of banking supervision?","options":["Guaranteeing shareholders a minimum return on their investment","Safeguarding the financial system against disruption and mass bank failure","Minimising money laundering in the financial system","Reducing the risk to which depositors and creditors are exposed"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Supervision protects the system and its depositors and creditors; it does not promise shareholders any return, since owners carry the risk of the business. Options B, C and D are all genuine aims of supervision, alongside improving efficiency and channelling resources to priority sectors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 271, $official_bank_source${"itemId":"45615ea6-e565-54df-99d1-2beab48fca5e","questionId":"e186c55a-45de-5c33-889e-d37e19cac6f7","sourceKey":"bank:FIN216:SUP-003","payload":{"prompt":"The NDIC examines the books and affairs of every licensed insured institution through two forms of supervision. These are","options":["off-site surveillance and on-site examination","solo and consolidated supervision","compliance-based and risk-based supervision","statutory and non-statutory returns"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"The two forms of supervision are off-site surveillance (analysing returns away from the bank) and on-site examination (inspecting the bank on its premises). Option B describes the scope of supervision and option C describes methodologies of supervision. Option D names the two categories of returns, which feed off-site surveillance."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 272, $official_bank_source${"itemId":"578846d0-2c7a-5b22-bd71-203ce111162a","questionId":"f3ae1a1c-e5a7-560a-8c36-abb5388489a8","sourceKey":"bank:FIN216:SUP-004","payload":{"prompt":"The receipt and analysis of returns sent periodically by insured banks, to check their compliance with prudential regulations, is known as","options":["special examination","consolidated supervision","on-site examination","off-site surveillance"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Off-site surveillance is done from the supervisor's office by analysing the periodic returns banks submit. Option C requires examiners to visit the bank's premises, and option A is a type of on-site visit called for a particular concern. Option B concerns supervising a whole banking group, not the method of analysing returns."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 273, $official_bank_source${"itemId":"c099bef3-ac62-57e8-a691-6bf6add9f848","questionId":"47bd39bf-3aed-54a3-8eca-e4fa392593fd","sourceKey":"bank:FIN216:SUP-005","payload":{"prompt":"Examining a bank's reports and documents within its premises and reconciling them with physical realities such as cash and other inventories is called","options":["off-site surveillance","solo-based supervision","on-site examination","risk profiling"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"On-site examination takes place inside the bank, where examiners check documents against physical assets like cash. Option A is carried out away from the bank using returns. Option B refers to the scope of supervision (one bank on its own), and option D is a step within risk-based supervision rather than a form of supervision."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 274, $official_bank_source${"itemId":"6509b502-2d02-50d8-b7b5-3772ec11b618","questionId":"45d0f814-935a-5cad-bed4-69369bcc238e","sourceKey":"bank:FIN216:SUP-006","payload":{"prompt":"NDIC examiners visit a branch of Ikeja Trust Bank in Lagos, count the cash in the vault and compare the total with the cash figure in the bank's last monthly return. This activity is part of","options":["on-site examination","deposit payoff","consolidated supervision","off-site surveillance"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Checking a bank's returns against the physical cash on its premises is the heart of on-site examination. Option D only analyses the returns without visiting the bank. Option C looks at a whole banking group, and option B is paying insured depositors after a bank fails."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 275, $official_bank_source${"itemId":"71b2d038-ca2d-5378-b8c7-28c374b46b78","questionId":"ea1ef064-f682-59a4-830b-0a764c5f9cff","sourceKey":"bank:FIN216:SUP-007","payload":{"prompt":"Which of the following is NOT one of the things an on-site examination seeks to determine?","options":["How much each insured depositor should be paid after the bank closes","Whether the returns sent by the bank match the physical realities in the bank","Whether the bank complies with banking regulations","Whether the findings of off-site analysis truly describe the bank's financial risk performance"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Calculating payments to insured depositors happens after a bank has failed and its licence is revoked; it is part of deposit payout, not examination. Options C, B and D are exactly the three things an on-site examination checks: regulatory compliance, the accuracy of returns, and whether off-site findings are correct."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 276, $official_bank_source${"itemId":"22e1f7f0-28d5-5651-aad2-1888ca734b95","questionId":"503ac338-80a7-524f-8370-1608bcfd38fc","sourceKey":"bank:FIN216:SUP-008","payload":{"prompt":"After an examination, exceptions are reported and recommendations made to the bank. How is the bank's implementation of those recommendations monitored?","options":["Through the bank's annual general meeting of shareholders","Through the appointment of a liquidator for the bank","Through the yearly assessment of deposit insurance premium","Through scheduled post-examination visits to the bank"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Supervisors follow up with scheduled post-examination visits to confirm that the lapses they found are being corrected. Option A is a shareholders' forum, not a supervisory tool, and option C is a funding exercise. Option B happens only when a bank has failed, not as follow-up to an examination."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 277, $official_bank_source${"itemId":"67508b76-808b-5b32-96b6-dcc976ee0e8f","questionId":"9b235d56-1193-5902-825d-fb7f58516352","sourceKey":"bank:FIN216:SUP-009","payload":{"prompt":"Requirements made by regulatory or supervisory authorities on banks, submitted on a set periodic basis to help ensure the banks conform to desired operating rules, are called","options":["holding actions","premiums","liquidation dividends","returns"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Returns are the periodic reports banks must send to supervisors, and they are the raw input of off-site surveillance. Option B is what banks pay for deposit insurance, and option C is what creditors of a failed bank receive as its assets are sold. Option A refers to restrictions placed on distressed banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 278, $official_bank_source${"itemId":"431883e4-8175-5775-8fd1-006eb248ad2c","questionId":"6cc24090-7c0e-5923-ad7f-4c70fc3dab5d","sourceKey":"bank:FIN216:SUP-010","payload":{"prompt":"Statutory returns are best described as returns that","options":["supervisors request from time to time through circulars or questionnaires","must be made by banks as provided for in the Acts governing banking business","banks submit voluntarily to attract more depositors","are prepared by the NDIC for publication in its annual report"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Statutory returns are required by law, that is, by the Acts that govern banking business. Option A describes non-statutory returns, which are called for in day-to-day supervision. Options C and D are not regulatory returns at all, since returns are mandatory submissions from banks to supervisors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 279, $official_bank_source${"itemId":"23fadddb-ce2f-5291-b2a7-e135135a1df6","questionId":"96b1bad8-98ba-5331-b563-7b19ad5602ce","sourceKey":"bank:FIN216:SUP-011","payload":{"prompt":"Non-statutory returns are usually called for by supervisors by means of","options":["resolutions of shareholders","Acts of the National Assembly","circulars or questionnaires","court orders"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Non-statutory returns are requested in the course of day-to-day supervision, so they are typically demanded through circulars or questionnaires. Option B is how statutory returns arise, since those are set by law. Options D and A are not ways supervisors request information from banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 280, $official_bank_source${"itemId":"f46c15d2-5a36-5f6e-b940-48135eb67504","questionId":"3ceb79f2-01b4-52bf-a578-a47f3671c462","sourceKey":"bank:FIN216:SUP-012","payload":{"prompt":"The NDIC sends a questionnaire to all deposit money banks asking for details of their loans to the aviation sector. No Act specifically requires this report. The information the banks send back is an example of","options":["a statutory return","a liquidation dividend claim","an on-site examination report","a non-statutory return"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"A return requested by the supervisor through a questionnaire, without a specific legal requirement, is a non-statutory return. Option A would be one required by the Acts governing banking. Option C is prepared by examiners after visiting a bank, and option B relates to failed banks in liquidation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 281, $official_bank_source${"itemId":"5143f01a-8817-5971-a081-188784d1ab46","questionId":"99b1adcb-38ee-5f70-bc43-2ebae2630546","sourceKey":"bank:FIN216:SUP-013","payload":{"prompt":"Which statement correctly distinguishes off-site surveillance from on-site examination?","options":["Off-site surveillance is done only after a bank fails, while on-site examination is done before failure","Off-site surveillance analyses banks' periodic returns away from the bank, while on-site examination verifies the bank's records on its premises","Off-site surveillance covers only microfinance banks, while on-site examination covers only deposit money banks","Off-site surveillance is done by the CBN alone, while on-site examination is done by the NDIC alone"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"The difference is about where and how the work is done: off-site work analyses returns at the supervisor's office, while on-site work checks records and assets inside the bank. Option A is wrong because both are used on going-concern banks. Options D and C are wrong because both CBN and NDIC use both forms, across all types of insured institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 282, $official_bank_source${"itemId":"a0236366-5561-5429-abef-32d631bf9848","questionId":"a2cd9c7e-7861-5235-91d3-d48d42cd50f5","sourceKey":"bank:FIN216:SUP-015","payload":{"prompt":"A method of examination that involves checking for and enforcing compliance with the legislation, regulations or policies that apply to a bank is known as","options":["compliance-based supervision","cross-border supervision","risk-based supervision","consolidated supervision"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Compliance-based supervision is rule-checking: examiners test whether the bank obeyed the applicable laws and regulations. Option C focuses instead on identifying and assessing each bank's most critical risks. Options D and B describe the scope of supervision (a group, or operations across countries), not a rule-checking method."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 283, $official_bank_source${"itemId":"b2b3b349-ab85-5b85-9a6a-ebc38bc885df","questionId":"338d6844-3216-50b5-af7c-a63bbd639598","sourceKey":"bank:FIN216:SUP-016","payload":{"prompt":"A major weakness of compliance-based supervision is that it is","options":["unconcerned with laws and regulations","too forward-looking and focused on future risks","reactive and static, and less useful in a constantly changing environment","applied only to groups of banks rather than single banks"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Compliance-based supervision checks past behaviour against rules, so it reacts after problems occur and does not adapt well to a dynamic financial world. Option B describes risk-based supervision, which is forward-looking. Option D confuses it with consolidated supervision, and option A is the opposite of what compliance checking does."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 284, $official_bank_source${"itemId":"5efc3fa3-0133-5d0e-a0ed-a20d4f4fd24c","questionId":"8a44f12a-cb54-5365-a042-a3a2ab935e05","sourceKey":"bank:FIN216:SUP-017","payload":{"prompt":"A structured process that identifies the most critical risks facing each bank and, through a focused review, assesses the bank's management of those risks and its financial vulnerability to adverse experience is called","options":["off-site surveillance","risk-based supervision","solo-based supervision","compliance-based supervision"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Risk-based supervision (RBS) starts from each bank's key risks and then judges how well the bank manages them. Option D only checks obedience to rules, and option C refers to supervising a single bank on its own. Option A is a form of supervision based on analysing returns, which can be used under either methodology."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 285, $official_bank_source${"itemId":"6e53c487-d4c5-5519-ba6d-f1a60d1d1deb","questionId":"e1df6b5e-7cda-50d1-8730-d2082fedd5c9","sourceKey":"bank:FIN216:SUP-018","payload":{"prompt":"Which of the following is NOT a feature of risk-based supervision?","options":["It assesses inherent risks separately from risk management processes","It applies the same examination intensity to every bank regardless of its risk profile","It allows supervisors to channel more resources to banks with higher risk profiles","It is a dynamic, forward-looking process that seeks early identification of emerging risks"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"RBS deliberately treats banks differently, putting more supervisory effort where the risks are greatest, so a one-size-fits-all intensity is not one of its features. Options D, A and C are genuine features: RBS is forward-looking, separates inherent risks from risk management, and prioritises higher-risk banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 286, $official_bank_source${"itemId":"25a26f58-3221-5d88-9017-c62d105394a5","questionId":"db0988c1-12e5-5e60-aeef-dfe135928cca","sourceKey":"bank:FIN216:SUP-019","payload":{"prompt":"Under risk-based supervision, which of the following is NOT a Risk Management Control Function (RMCF)?","options":["Senior management","Internal audit","Credit risk","Compliance"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Credit risk is an inherent risk that a bank faces; the RMCFs are the functions that manage such risks. Options B, D and A are all RMCFs, together with the board, risk management and financial analysis."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 287, $official_bank_source${"itemId":"7e06962f-4770-599d-8979-542609216eb7","questionId":"afe6c50a-7817-5af7-b754-fcc0d1f08906","sourceKey":"bank:FIN216:SUP-020","payload":{"prompt":"Under risk-based supervision, which of the following is classified as an inherent risk of a bank?","options":["The compliance function","The board of directors","Liquidity risk","Internal audit"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Inherent risks are the risks that come with the business of banking, such as credit, operational, liquidity and market risk. Options B, D and A are Risk Management Control Functions, which exist to manage those inherent risks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 288, $official_bank_source${"itemId":"eb79c9be-3a79-5186-aca3-ca281e93a9e3","questionId":"d0171ba0-5a13-51dd-8e3a-3fa53876d457","sourceKey":"bank:FIN216:SUP-021","payload":{"prompt":"After profiling all insured banks, a supervisor decides to send more examiners to Bank Q, which has a high risk profile, and fewer to Bank R, which has a low risk profile. This approach is typical of","options":["compliance-based supervision","solo-based supervision","deposit payout","risk-based supervision"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Allocating supervisory resources in line with each bank's risk profile is a defining feature of risk-based supervision. Option A focuses on checking rules and is not driven by risk profiles. Option B is about supervising single entities rather than allocating resources, and option C is paying depositors of a failed bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 289, $official_bank_source${"itemId":"098d8446-7ceb-554f-8e91-4e605872ad91","questionId":"c92064f8-e956-5dfb-b890-3ed272c1292f","sourceKey":"bank:FIN216:SUP-022","payload":{"prompt":"Which statement correctly compares risk-based supervision (RBS) with compliance-based supervision?","options":["RBS ignores how a bank manages its risks, while compliance-based supervision focuses on it","RBS is proactive and forward-looking, while compliance-based supervision is reactive","RBS is reactive, while compliance-based supervision is forward-looking","RBS checks only past compliance with rules, while compliance-based supervision profiles risks"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"RBS looks ahead to emerging risks and how well they are managed, whereas compliance-based supervision checks after the fact whether rules were followed. Option C reverses the two. Options A and D also swap the defining features of the two methods."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 290, $official_bank_source${"itemId":"b27b9644-80fa-521d-a32b-02b961bdc9a4","questionId":"ae8ad784-cefb-5bbe-8359-8161d18603da","sourceKey":"bank:FIN216:SUP-023","payload":{"prompt":"Which supervisory approach is described as gradually becoming the dominant approach to the supervision of financial institutions around the world?","options":["Compliance-based supervision","Transaction-based supervision","Risk-based supervision","Solo-based supervision"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Risk-based supervision is spreading worldwide because it focuses supervisory effort on the biggest risks. Options A and B are the same older rule-checking approach under two names. Option D describes the scope of supervision, not the dominant methodology."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 291, $official_bank_source${"itemId":"7590fe0b-f6b1-5097-974e-6a1d235f97ec","questionId":"6c151853-c185-5c15-8e9d-9ed9063b8eec","sourceKey":"bank:FIN216:SUP-024","payload":{"prompt":"Which of the following is NOT one of the scopes of bank supervision?","options":["Cross-border supervision","Consolidated supervision","Solo-based supervision","Risk-based supervision"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Risk-based supervision is a methodology of supervision, not a scope. The scope of supervision covers how widely the supervisor looks: a single bank (option C), the whole group (option B), or operations across national borders (option A)."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 292, $official_bank_source${"itemId":"887f49a9-2d3a-5495-8f31-851edd4f9742","questionId":"e1e3604b-b888-581f-90fb-29cbace0f12d","sourceKey":"bank:FIN216:SUP-025","payload":{"prompt":"Supervision that focuses on a single bank, its distinct individual operations, risk profile and management is called","options":["solo-based supervision","cross-border supervision","joint supervision","consolidated supervision"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Solo-based supervision looks at one entity on its own, under the capital rules of its own regulator. Option D assesses the whole business group, and option B covers operations in other countries. Option C describes who carries out supervision (for example CBN and NDIC together), not its scope."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 293, $official_bank_source${"itemId":"1aa40722-7c19-5125-b563-aa3c50677fea","questionId":"62543438-f563-5741-adeb-0b63f1bcdac3","sourceKey":"bank:FIN216:SUP-026","payload":{"prompt":"A qualitative and quantitative assessment of the strength of business groups that contain banks, in order to identify and evaluate all the risks to which the banks are exposed, is known as","options":["compliance-based supervision","off-site surveillance","consolidated supervision","solo-based supervision"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Consolidated supervision looks at the group as a whole, including a group-wide assessment of capital adequacy. Option D looks only at a single entity. Option A is a rule-checking methodology, and option B is a form of supervision based on returns."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 294, $official_bank_source${"itemId":"1dc25c23-26d2-5206-a957-e7158d158b83","questionId":"b39baa9b-5294-5b04-9db4-d7d1564324a0","sourceKey":"bank:FIN216:SUP-027","payload":{"prompt":"The adoption of which banking model in Nigeria in 2001 increased the need for consolidated supervision, because many banks began to operate through subsidiaries and affiliates?","options":["Non-interest banking","Structural Adjustment Programme","Universal banking","Banking consolidation"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Universal banking (2001) let banks carry on many activities through subsidiaries, so supervisors had to look at whole groups. Option D was the later recapitalisation exercise that cut the number of banks, and option A is a type of banking based on non-interest principles. Option B was the 1986 reform that liberalised bank licensing."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 295, $official_bank_source${"itemId":"15d3872b-727e-53a4-bc8d-aed1ae1e6adb","questionId":"ea3c6810-12fe-5d14-ab60-f753515ead62","sourceKey":"bank:FIN216:SUP-028","payload":{"prompt":"Consolidated supervision helps prevent the over-leveraging of capital within a group, where the same capital is counted more than once by different group entities. This problem is known as","options":["adverse selection","double gearing","moral hazard","maturity mismatch"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Double gearing happens when capital is used to support risks in more than one entity of a group, overstating the group's true capital; consolidated supervision checks for it. Option C is the incentive to take more risk when others bear the cost. Option D is funding long-term assets with short-term liabilities, and option A is about attracting riskier customers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 296, $official_bank_source${"itemId":"64cf2a33-6ddc-5855-9cd0-e3d7e8b0cc14","questionId":"53f02e12-1437-5343-a5cb-689d715c7e58","sourceKey":"bank:FIN216:SUP-029","payload":{"prompt":"Which of the following is NOT an objective of consolidated supervision?","options":["Evaluating the strength of the group's consolidated financial resources","Preventing the over-leveraging of capital (double gearing)","Supporting the principle that no business segment's risk escapes supervision","Supervising each group entity only by its own regulator's capital rules without looking at the group"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Looking at each entity only on its own is solo-based supervision, which is exactly the gap consolidated supervision is meant to close. Options C, B and A are the stated objectives of consolidated supervision."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 297, $official_bank_source${"itemId":"d315ffb6-3a67-5d47-b77c-81186a5a1de7","questionId":"85c32c4e-dac1-5123-852d-5ee0e168284b","sourceKey":"bank:FIN216:SUP-030","payload":{"prompt":"Consolidated supervision is regarded as an essential element of","options":["risk-based supervision","compliance-based supervision","deposit payoff","liquidation of failed banks"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Because group links can expose a bank to risks from its parent or affiliates, a full risk-based view requires looking at the whole group. Option B focuses on rule-checking rather than risk. Options C and D are post-failure activities, not supervision."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 298, $official_bank_source${"itemId":"b7e083bf-aef2-53cf-81e6-3951bc51bfc6","questionId":"f62f14d7-8b3f-5a33-93df-a5168f32193c","sourceKey":"bank:FIN216:SUP-031","payload":{"prompt":"Afro Holdings Plc owns a deposit money bank, an insurance company and a stockbroking firm. Supervisors assess the risks and the capital adequacy of the whole group, not just the bank. This is","options":["solo-based supervision","compliance-based supervision","consolidated supervision","a maiden examination"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Assessing a whole business group, including a group-wide view of capital, is consolidated supervision. Option A would look at the bank alone. Option B is a rule-checking method, and option D is the first examination of a newly licensed bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 299, $official_bank_source${"itemId":"20ed94c7-35d2-592c-b577-2c71e830f359","questionId":"381ce6ff-f405-55bc-9514-39e0c4f560d8","sourceKey":"bank:FIN216:SUP-032","payload":{"prompt":"A Nigerian bank has subsidiaries in Ghana, Sierra Leone and The Gambia. Supervising the risks that arise from its operations in these other countries falls under","options":["off-site surveillance only","compliance-based supervision","solo-based supervision","cross-border supervision"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Supervising a bank's operations outside its home country is the cross-border scope of supervision. Option C focuses on one entity in isolation. Option A is a form of supervision, not a scope, and option B is a rule-checking methodology."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 300, $official_bank_source${"itemId":"be1d59d4-b547-59f9-aa7f-f152ce995bf6","questionId":"3c5becb9-2ea2-512f-9bb6-ba66cc367460","sourceKey":"bank:FIN216:SUP-033","payload":{"prompt":"The global financial meltdown showed that some events could have been foreseen if supervisors had adopted a holistic approach rather than a solo perspective. This lesson strengthens the case for","options":["implicit deposit protection","flat-rate premiums","consolidated supervision","compliance-based supervision"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"A holistic approach looks at the whole group and its connections, which is what consolidated supervision does. Option D is narrow rule-checking. Options A and B concern deposit protection design and premium setting, not the scope of supervision."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 301, $official_bank_source${"itemId":"271fb46d-3485-5480-ad79-716224eb8999","questionId":"dc50696a-542e-5149-b31f-640805b8a321","sourceKey":"bank:FIN216:SUP-034","payload":{"prompt":"Because the law confers on the NDIC powers to supervise all insured institutions, the NDIC is classified as a","options":["pay box","loss minimiser","pay box plus","risk minimiser"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"A deposit insurer with supervisory powers, enforcement and prompt corrective action is a risk minimiser, and the NDIC is one. Option A only reimburses insured deposits. Option C adds some resolution functions, and option B actively chooses least-cost resolutions but in most cases has no supervisory powers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 302, $official_bank_source${"itemId":"45225475-e340-5b5f-a200-7df6683dda31","questionId":"1f657400-e7e4-5213-8945-f1082124124f","sourceKey":"bank:FIN216:SUP-036","payload":{"prompt":"Why does a deposit insurer such as the NDIC supervise banks instead of only paying depositors after a bank fails?","options":["To replace the CBN as the licensing authority for banks","To detect problems early and reduce the likelihood and cost of failures that its fund would have to bear","To earn examination fees that pay for its operating expenses","To guarantee all deposits in full regardless of size"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"A deposit insurer that supervises can spot unsafe practices early and act before failure, which protects depositors and the insurance fund. Option C is wrong because supervision is a statutory function, not a fee business. Option A is wrong because the CBN remains the licensing authority, and option D confuses supervision with a blanket guarantee."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 303, $official_bank_source${"itemId":"6570670d-2495-5125-8f6b-f464e758a12f","questionId":"a10fb782-74a9-57df-a2f4-142861f9cd10","sourceKey":"bank:FIN216:SUP-037","payload":{"prompt":"Which of the following is NOT part of the 'nature of banking business' that justifies bank regulation and supervision?","options":["Banks operate the payment system","Banks perform the financial intermediation function","Banks are funded mainly by their owners' equity rather than by deposits","Banks have a large fiduciary responsibility over cash assets in the economy"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Banks trade largely on other people's money, mainly deposits, not on their owners' equity, which is precisely why they are supervised. Options D, B and A are genuine features of banking that make supervision necessary."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 304, $official_bank_source${"itemId":"56ff502e-0a9f-5d0c-b9c2-b535b9ddae7a","questionId":"7b627c2d-afb2-544e-8301-3b8422f1cd53","sourceKey":"bank:FIN216:SUP-038","payload":{"prompt":"Banks are said to trade largely on 'OPM'. This means that","options":["banks invest only in options and other derivative products","banks are owned mostly by the government","most of the funds banks use belong to people other than the bank's owners, mainly depositors","banks borrow only from the central bank"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"OPM stands for other people's money: most of the funds a bank controls belong to depositors rather than its shareholders, which is a key reason for supervision. Options A, B and D do not describe this feature of banking."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 305, $official_bank_source${"itemId":"d842da91-9de0-535b-aebf-9fb0849596fb","questionId":"5cc197ae-d34e-50b8-a625-fb8575000c45","sourceKey":"bank:FIN216:SUP-039","payload":{"prompt":"The Structural Adjustment Programme of 1986 liberalised bank licensing and was expected to sharply increase the number of banks. How was an explicit deposit insurer with supervisory powers expected to help?","options":["By complementing the supervisory efforts of the CBN over the larger number of banks","By issuing banking licences in place of the CBN","By taking over the CBN's role as lender of last resort","By guaranteeing that no bank would ever fail"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"With many more banks to watch, an insurer with supervisory powers was meant to add to, not replace, the CBN's supervision. Options C and B are wrong because lender of last resort and licensing remain CBN functions. Option D is wrong because deposit insurance protects depositors when banks fail; it does not prevent all failures."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 306, $official_bank_source${"itemId":"95f419bf-873d-5bbd-9eb0-58688f3e65dc","questionId":"b4c42072-a5d5-5eb7-b56b-82a257b4c1d5","sourceKey":"bank:FIN216:SUP-040","payload":{"prompt":"Since the NDIC began operations in 1989, what has been one practical benefit of having both the CBN and the NDIC supervise banks?","options":["On-site examinations were abolished in favour of off-site surveillance","Routine and special examinations of banks could be carried out more frequently despite the increase in the number of banks","Banks no longer needed to send returns to the CBN","Banks stopped paying deposit insurance premiums"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Two supervisors sharing the work made it possible to examine banks more often, even as bank numbers grew. Option C is wrong because returns remain central to off-site work. Options A and D are wrong because on-site examination continued and banks still pay premiums."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 307, $official_bank_source${"itemId":"6b0693ea-732e-54b1-859e-68e6d5c97e22","questionId":"93321197-dd30-5192-b18d-e21667389bb2","sourceKey":"bank:FIN216:SUP-041","payload":{"prompt":"Many new banks enter the market and compete fiercely for deposits. Some start making very risky loans with depositors' money to grow quickly. Which rationale for supervision and deposit insurance does this illustrate?","options":["Increased competition among banks can encourage excessive risk-taking with depositors' funds","Lessons from the founding of the IADI","The need for financial inclusion","Change in government bank support policy"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Competition is generally good, but it can push banks to take excessive risks with depositors' funds, so depositors, especially small ones, need protection. Option D is about government shifting from propping up weak banks to protecting deposits. Options C and B are not the rationale shown in this scenario."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 308, $official_bank_source${"itemId":"3a32f342-2f88-5d0c-a9ff-73a0498137f2","questionId":"113d1fe0-1b66-5e0f-81de-857df4cad86e","sourceKey":"bank:FIN216:SUP-045","payload":{"prompt":"Within Nigeria's financial safety net, which function is carried out jointly by the CBN and the NDIC?","options":["Lender of last resort","Bank supervision","Issuing bank licences","Deposit insurance"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Supervision of banks is done jointly by the CBN and NDIC. Option A is a CBN function, and option D is the NDIC's own function. Option C also belongs to the CBN, which grants and revokes licences."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 309, $official_bank_source${"itemId":"aa477707-72be-567f-86f4-cd7560c2ecda","questionId":"14b2325d-3898-50e1-8149-04026df25d9c","sourceKey":"bank:FIN216:SUP-046","payload":{"prompt":"When supervision shows that an insured bank's licence should be revoked, which institution actually revokes the licence?","options":["The Financial Services Regulation Coordinating Committee","The Central Bank of Nigeria","The NDIC","The Federal High Court"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Licensing and licence revocation belong to the CBN; the NDIC can recommend revocation but then acts as liquidator after the CBN revokes. Option C is the tempting wrong answer because the NDIC makes the recommendation. Options D and A do not revoke banking licences."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 310, $official_bank_source${"itemId":"c8609171-51f5-5ef0-a0bb-eb39ecbaa302","questionId":"7df6153e-1e9b-5c80-b119-47711f06278a","sourceKey":"bank:FIN216:SUP-047","payload":{"prompt":"Under the NDIC Act 2023, when an examination shows that an insured institution needs action that lies outside the NDIC's own powers, the Act provides for the NDIC to","options":["revoke the institution's licence directly","make recommendations to the CBN","refer the matter to the IADI for a decision","sell the institution to AMCON on its own authority"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"The 2023 Act has a provision for the NDIC to make recommendations to the CBN after examination, consistent with the CBN being the licensing authority. Option A is wrong because licence revocation is a CBN power. Options D and C are not how supervisory findings are acted on; the IADI is an international association, not a Nigerian regulator."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 311, $official_bank_source${"itemId":"ad2dda82-8219-52c5-89f5-a8f33dccdb1b","questionId":"da517e90-4e15-5930-a68e-76dff2b1afae","sourceKey":"bank:FIN216:SUP-048","payload":{"prompt":"eFASS, an electronic platform used for the rendering and analysis of banks' returns, was developed by the NDIC in collaboration with","options":["the Securities and Exchange Commission","the International Monetary Fund","the Central Bank of Nigeria","the Asset Management Corporation of Nigeria"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"eFASS was developed jointly by the CBN and NDIC to support off-site surveillance of banks. Options B, A and D are other institutions that were not partners in developing this joint supervisory platform."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 312, $official_bank_source${"itemId":"9af7307e-a705-565f-95e1-d7fb329d2a2c","questionId":"eea175be-0f3d-5e1d-b686-45ca8e1a0f34","sourceKey":"bank:FIN216:SUP-049","payload":{"prompt":"Risk-based supervision of insured banks in Nigeria was adopted by the NDIC","options":["at the direction of the Securities and Exchange Commission","in collaboration with the CBN","in place of any form of on-site examination","only for microfinance banks"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"The NDIC adopted risk-based supervision together with the CBN, and the two use a jointly developed RBS framework. Option C is wrong because on-site examinations continue under RBS. Options D and A are wrong because RBS covers deposit money banks too and was not directed by the SEC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 313, $official_bank_source${"itemId":"1541944f-faa0-5607-b99b-5c3aeeae2684","questionId":"7abf6b77-2d56-5a9a-b59d-2be21485143d","sourceKey":"bank:FIN216:SUP-050","payload":{"prompt":"Under the NDIC Act 2006, a 'failing insured institution' was defined as one whose","options":["shareholders have voted to wind it up","licence has been withdrawn by the CBN","deposits have all been paid out by the NDIC","capital adequacy ratio is below the minimum prescribed by the CBN"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"A failing institution was one whose capital adequacy (capital to risk-weighted assets) had fallen below the CBN minimum, while it still held a licence. Option B is the definition of a failed insured institution. Options C and A describe later stages or voluntary winding up, not the statutory test."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 314, $official_bank_source${"itemId":"bbb0b557-a6b7-5c84-a88b-b283d444bc1a","questionId":"27c3a2b9-ae9b-5160-8db8-bb9f577065dc","sourceKey":"bank:FIN216:SUP-052","payload":{"prompt":"The first examination conducted on a newly licensed bank, to assess its safety, soundness and compliance with banking laws, is called a","options":["maiden examination","routine examination","target examination","special examination"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"A maiden examination is the first examination of a new bank. Option B is the regular, scheduled examination of an existing bank. Option D is called because of a particular concern, and option C focuses on one specific area of a bank's operations."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 315, $official_bank_source${"itemId":"bca28042-0153-5ce9-8e27-5fbd08720450","questionId":"e27d1257-3734-537b-bebc-0c0326d81ea3","sourceKey":"bank:FIN216:SUP-053","payload":{"prompt":"A regular, scheduled examination carried out on every insured bank as part of the normal supervisory cycle is a","options":["target examination","special examination","maiden examination","routine examination"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Routine examinations are the periodic examinations every bank receives in the normal cycle. Option B is unscheduled and triggered by specific concerns. Option C is only for newly licensed banks, and option A concentrates on a particular area rather than the whole bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 316, $official_bank_source${"itemId":"26d9c4c2-7667-5fa7-a8ee-e25f8c2dffc9","questionId":"fb5a084d-e827-5856-96e2-3cba9abef821","sourceKey":"bank:FIN216:SUP-054","payload":{"prompt":"In 2009, the CBN and NDIC jointly examined 24 banks, outside the normal cycle, because of concerns about their condition. This kind of unscheduled examination triggered by specific concerns is a","options":["special examination","routine examination","post-examination visit","maiden examination"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"An examination called outside the normal cycle because of particular concerns is a special examination, and the 2009 CBN/NDIC exercise is a well-known example. Option D is for newly licensed banks, and option B is the normal scheduled examination. Option C only follows up on earlier recommendations."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 317, $official_bank_source${"itemId":"02569e88-6d59-5d26-a0f1-e46cac497c2f","questionId":"632d7c3d-6f10-5490-949c-c6edb784170a","sourceKey":"bank:FIN216:SUP-055","payload":{"prompt":"Examiners visit Coastal Bank Plc to review only its foreign exchange operations, without examining the rest of the bank. This is best described as a","options":["maiden examination","consolidated examination","target examination","routine examination"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"A target examination concentrates on a specific area of a bank's business, such as foreign exchange or risk assets. Option A is the first examination of a new bank, and option B covers a whole group. Option D is the regular full-scope examination in the normal cycle."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 318, $official_bank_source${"itemId":"563b2ecb-e5e9-5378-b57e-90d892b91cfb","questionId":"f8082354-0909-50be-a3c5-0f4321d5c2df","sourceKey":"bank:FIN216:SUP-056","payload":{"prompt":"In 2018, the NDIC and CBN together conducted a Risk Assets Examination of deposit money banks to assess asset quality and loan loss provisions. This exercise is an example of","options":["a joint CBN/NDIC examination","a maiden examination","solo examination by the NDIC alone","off-site surveillance"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Because both supervisors carried out the exercise together, it is a joint CBN/NDIC examination. Option B applies only to newly licensed banks, and option D does not involve visiting banks. Option C is wrong because the CBN took part."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 319, $official_bank_source${"itemId":"49814e59-6fda-5f6e-9075-8d2b004d5182","questionId":"b67b4f03-e0a0-5f42-96c9-c587262624e0","sourceKey":"bank:FIN216:SUP-057","payload":{"prompt":"Which of the following is a type of bank examination rather than a failure resolution option?","options":["Target examination","Deposit payoff","Purchase and assumption","Bridge bank"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"A target examination is a supervisory tool used on going-concern banks to look at a specific area. Options C, D and B are ways of dealing with banks that are failing or have failed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 320, $official_bank_source${"itemId":"8a6788c6-2d42-57d5-8537-3226aff5a6d3","questionId":"98acd10d-1433-556b-8462-3c00b68f3452","sourceKey":"bank:FIN216:SUP-058","payload":{"prompt":"In the CAMEL rating framework, the component measured mainly by a bank's ratio of capital to risk-weighted assets is","options":["earnings","asset quality","capital adequacy","liquidity"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"The capital to risk-weighted assets ratio measures how much capital cushion a bank has, which is the C (capital adequacy) in CAMEL. Option B is about the quality of loans and other assets. Options A and D measure profitability and the ability to meet withdrawals."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 321, $official_bank_source${"itemId":"aa08bb5f-60ca-5938-b529-2328af247bf0","questionId":"42b32458-8997-5d1d-aac2-83552cd1f96d","sourceKey":"bank:FIN216:SUP-059","payload":{"prompt":"Unity Star Bank's ratio of non-performing loans to total loans rose from 4% to 22% within a year. Which CAMEL component is most directly weakened?","options":["Management","Liquidity","Capital adequacy","Asset quality"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Non-performing loans are bad assets, so a sharp rise in the NPL ratio mainly hurts asset quality, the A in CAMEL. Option C may suffer later as losses eat into capital, but the direct measure here is asset quality. Options A and B measure governance and the ability to meet withdrawals."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 322, $official_bank_source${"itemId":"2624e0a3-8cfa-593a-b997-ea4346f5b1e3","questionId":"99a0f8cf-6f41-5dcd-bf77-2167e8bd48f0","sourceKey":"bank:FIN216:SUP-060","payload":{"prompt":"Examiners find that the directors of a bank are constantly quarrelling, internal controls are weak and insiders are granted loans without proper approval. In the CAMEL framework, these findings mainly affect the rating for","options":["earnings","sensitivity to market risk","management","liquidity"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Board conflicts, weak controls and insider abuse are signs of poor management, the M in CAMEL. Options A and D measure profitability and liquidity position. Option B measures exposure to changes in interest rates, exchange rates and prices."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 323, $official_bank_source${"itemId":"5166ce91-7a8b-58a6-989f-2f32779ff5bb","questionId":"810061fc-4b76-5ff8-9140-99b19032c16d","sourceKey":"bank:FIN216:SUP-061","payload":{"prompt":"Prime Savings Bank repeatedly borrows overnight from other banks at very high rates just to meet customers' daily withdrawals. The CAMEL component that best captures this problem is","options":["liquidity","capital adequacy","asset quality","earnings"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Struggling to meet withdrawals and relying on expensive short-term borrowing shows a liquidity problem, the L in CAMEL. Option B concerns the capital cushion. Options C and D concern the quality of loans and profitability, though both may suffer if the liquidity problem persists."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 324, $official_bank_source${"itemId":"98331e9f-8893-5de6-ab53-3f26182c2e08","questionId":"37e9798e-feb2-5147-bf99-f85962e8865c","sourceKey":"bank:FIN216:SUP-062","payload":{"prompt":"When CAMEL is extended to CAMELS, the added 'S' stands for","options":["supervisory review","solvency of shareholders","size of the bank","sensitivity to market risk"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"The S in CAMELS stands for sensitivity to market risk, meaning how changes in interest rates, exchange rates and prices could affect the bank. Options B and C are not CAMELS components. Option A is one of the three pillars of Basel II, not part of CAMELS."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 325, $official_bank_source${"itemId":"5aeca35d-3f9b-5716-9aec-9e3c6338b811","questionId":"ce79687c-cc85-5292-b3ac-32bc07eaa613","sourceKey":"bank:FIN216:SUP-063","payload":{"prompt":"Which of the following is NOT a component of the CAMEL rating framework?","options":["Asset quality","Earnings","Market share","Liquidity"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"CAMEL stands for Capital adequacy, Asset quality, Management, Earnings and Liquidity; market share is not one of them. Options A, B and D are all genuine CAMEL components."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 326, $official_bank_source${"itemId":"d30facfa-8b38-5b9d-8084-2301bc198b90","questionId":"95f862f7-f8c0-5bf5-b186-e5a69ea4efdd","sourceKey":"bank:FIN216:SUP-064","payload":{"prompt":"On the standard CAMEL(S) composite rating scale of 1 to 5, a bank rated 1 is","options":["the weakest, with a high risk of failure","the soundest, with the least supervisory concern","average, needing moderate supervisory attention","one whose licence has already been revoked"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"The scale runs from 1 (strongest, least concern) to 5 (weakest, highest risk of failure). Option A describes a rating of 5, and option C describes the middle of the scale. Option D is wrong because CAMEL ratings apply to operating banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 327, $official_bank_source${"itemId":"73429977-e97b-5150-91c0-ab89d98b2a19","questionId":"9f822976-a4a9-5225-96bf-39ae39446525","sourceKey":"bank:FIN216:SUP-065","payload":{"prompt":"A set of indicators, mostly drawn from banks' periodic returns, that supervisors use to detect banks heading towards distress early enough to intervene before they fail is called","options":["a bridge bank mechanism","an early warning system","a deposit payout system","a differential premium assessment system"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"An early warning system flags deteriorating banks from their ratios and trends so supervisors can act in time. Option D is how risk-based premiums are set. Options A and C are used after a bank fails, not to detect distress early."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 328, $official_bank_source${"itemId":"2fe66ff2-548c-5275-8f1a-728b7e50a836","questionId":"35f3ef56-d003-53ae-ab0b-8314c008b689","sourceKey":"bank:FIN216:SUP-066","payload":{"prompt":"Under the 2014 IADI Core Principles, which principle requires the deposit insurer to be part of a framework for early detection and timely intervention, acting before a bank becomes non-viable?","options":["Core Principle 13","Core Principle 10","Core Principle 8","Core Principle 15"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Core Principle 13 of the 2014 set deals with early detection and timely intervention. Option C covers coverage limits, option B covers public awareness, and option D covers reimbursing depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 329, $official_bank_source${"itemId":"68ef80d6-121a-5fb3-8033-29e0a03142d3","questionId":"9f5766b7-3141-5c76-bbf8-ebe45bca3f45","sourceKey":"bank:FIN216:SUP-067","payload":{"prompt":"Which of the following is NOT an early warning signal of bank distress?","options":["A rising ratio of non-performing loans","Persistent heavy borrowing in the interbank market at high rates","Steady growth in retained earnings alongside improving liquidity","Late or inaccurate rendition of returns to supervisors"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Growing retained earnings and better liquidity are signs of strength, not distress. Options B, A and D are classic warning signals that a bank may be heading for trouble."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 330, $official_bank_source${"itemId":"86473c6b-d291-5e45-9ae2-2e72047d10c8","questionId":"b55f391d-87af-5554-b082-caf1f07943e9","sourceKey":"bank:FIN216:SUP-068","payload":{"prompt":"Mrs Okafor notices that her bank suddenly offers deposit rates far above what other banks pay and keeps phoning customers to bring in cash, while supervisors note it is borrowing heavily from other banks. To a supervisor, this pattern is best read as","options":["a sign the bank has just passed a maiden examination","evidence of strong asset quality","proof that the bank is a systemically important bank","an early warning signal of liquidity distress"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Paying unusually high rates and borrowing desperately for funds usually means a bank is short of liquidity, a common early warning signal. Option B is unrelated, since deposit-chasing says nothing good about loan quality. Options A and C are not shown by this pattern."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 331, $official_bank_source${"itemId":"b93cda5b-00fb-506a-9f9d-bea576b6346e","questionId":"fc542465-1c77-5add-aecb-ffb1f05f4f46","sourceKey":"bank:FIN216:SUP-069","payload":{"prompt":"Analysing the periodic returns of all insured banks to flag those whose key ratios are deteriorating is mainly carried out through","options":["off-site surveillance","purchase and assumption","liquidation","on-site cash counts"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Off-site surveillance analyses returns from all banks and is the natural home of ratio-based early warning. Option D is a physical on-site check of one bank. Options C and B deal with banks that have already failed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 332, $official_bank_source${"itemId":"e8573466-18f8-518a-8a25-97e7d3487872","questionId":"97061242-86e9-5921-805e-2acc289d6566","sourceKey":"bank:FIN216:SUP-070","payload":{"prompt":"The risk-weighted capital ratio (capital adequacy ratio) of a bank is calculated as","options":["liquid assets divided by total deposits","capital divided by risk-weighted assets","total deposits divided by total loans","risk-weighted assets divided by capital"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"The capital adequacy ratio is capital divided by risk-weighted assets (RWA). Option D inverts the formula. Option C is a loan-to-deposit type measure, and option A is a liquidity ratio."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 333, $official_bank_source${"itemId":"77fd4417-6fb7-58f0-9eed-3b48399b8be5","questionId":"d29e7d89-5290-5cfd-bb14-899b6f84f284","sourceKey":"bank:FIN216:SUP-071","payload":{"prompt":"Under the original Basel I Accord, which of the following was NOT one of the credit risk weights applied to assets?","options":["50%","20%","0%","75%"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Basel I used a simple set of risk weights: 0%, 10%, 20%, 50% and 100%; 75% was not among them. Options C, B and A are genuine Basel I risk weights."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 334, $official_bank_source${"itemId":"003fa867-5200-50b2-946d-32fc3ff89cf4","questionId":"530c8308-4453-5e0b-a58f-ceabead9e187","sourceKey":"bank:FIN216:SUP-072","payload":{"prompt":"Under Basel I risk weights, a bank holds cash of N20m (0%), claims on other banks of N30m (20%), residential mortgages of N40m (50%) and corporate loans of N60m (100%). What are its total risk-weighted assets?","options":["N106m","N150m","N86m","N80m"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Multiply each exposure by its weight and add: 0 + 6 + 20 + 60 = N86m. Option B simply adds the exposures without weighting. Option D leaves out the N6m from interbank claims, and option A wrongly weights cash at 100%."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 335, $official_bank_source${"itemId":"f07500af-1863-5efc-962c-a5680d98949d","questionId":"02a1944f-0115-5a80-9179-07e66e022d41","sourceKey":"bank:FIN216:SUP-073","payload":{"prompt":"A Nigerian bank required to keep a minimum capital adequacy ratio of 10% has risk-weighted assets of N500m. What is the minimum capital it must hold?","options":["N75m","N5m","N40m","N50m"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Minimum capital = RWA x required ratio = N500m x 10% = N50m. Option C uses the 8% Basel I international minimum instead of the 10% given. Option A uses 15%, and option B misplaces the decimal point."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 336, $official_bank_source${"itemId":"85e7a579-3e4a-54f1-885a-8cbcf3d24a07","questionId":"9cf94142-76ab-5753-a65a-ca49a6bbffd4","sourceKey":"bank:FIN216:SUP-074","payload":{"prompt":"A bank has qualifying capital of N12bn and risk-weighted assets of N80bn. What is its capital adequacy ratio?","options":["15%","12%","8%","6.67%"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Capital adequacy ratio = capital / RWA = 12 / 80 = 0.15, or 15%. Option D divides RWA by capital the wrong way round and misplaces the decimal. Option B assumes RWA of N100bn, and option C is simply the Basel I minimum, not this bank's ratio."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 337, $official_bank_source${"itemId":"dc6600ed-3305-5a18-a901-88ef0f811586","questionId":"6f338831-842a-554c-a95b-4360763b0fa2","sourceKey":"bank:FIN216:SUP-075","payload":{"prompt":"The original 1988 Basel I Accord set minimum capital requirements mainly to cover which risk?","options":["Credit risk","Operational risk","Reputational risk","Strategic risk"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Basel I's capital requirements were built around credit risk, with an inherent buffer for other risks. Option B was brought into explicit capital requirements under Basel II. Options C and D were not the basis of Basel I's capital charge."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 338, $official_bank_source${"itemId":"5734bfa5-aa23-5c61-a60c-c30229fa2c64","questionId":"183da272-84fa-55ea-a1dc-bbede94a8338","sourceKey":"bank:FIN216:SUP-076","payload":{"prompt":"Which of the following is NOT one of the three pillars of Basel II?","options":["Market discipline","Deposit insurance","Supervisory review","Minimum capital requirements"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Basel II rests on three pillars: minimum capital requirements, supervisory review and market discipline. Deposit insurance is part of the financial safety net, not a Basel II pillar. Options D, C and A are the genuine pillars."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 339, $official_bank_source${"itemId":"5ee5d4ab-5ec1-51a1-8737-4ccec0a5dc79","questionId":"db27813d-3379-5f70-ae9e-685af004b1eb","sourceKey":"bank:FIN216:SUP-077","payload":{"prompt":"Which of the following is NOT a weakness of Basel I?","options":["Its capital requirements did not always reflect economic risk","It created arbitrage opportunities, for example through securitisation","It gave little recognition to credit risk mitigants","It created an internationally recognised capital standard"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Creating an internationally recognised standard is an advantage of Basel I, not a weakness. Options A, B and C are recognised weaknesses that Basel II tried to fix."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 340, $official_bank_source${"itemId":"f66740eb-2ff6-5358-b244-c8106b5f9eaf","questionId":"3db23bc2-ad5f-5139-809b-11f7e0f2c801","sourceKey":"bank:FIN216:SUP-078","payload":{"prompt":"Basel II requires banks to measure the riskiness of their assets with respect to which three risks?","options":["Market, country and interest rate risks only","Liquidity, strategic and political risks","Credit, legal and reputational risks","Credit, market and operational risks"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"Basel II aligns capital more closely with risk by covering credit, market and operational risks. Options C, B and A mix in risks that are not the three named in the Basel II capital framework."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 341, $official_bank_source${"itemId":"4b8c6d8d-6fc8-5b98-b647-eec1f90d0854","questionId":"dc037a54-d0a6-551b-99c4-0be766b90bb3","sourceKey":"bank:FIN216:SUP-079","payload":{"prompt":"International Financial Reporting Standards (IFRS), now part of the banking supervision environment, are developed and published by the","options":["International Association of Deposit Insurers","Financial Stability Board","International Accounting Standards Board (IASB)","Basel Committee on Banking Supervision"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"IFRS are a single set of global accounting standards issued by the IASB. Option D sets bank capital standards such as Basel I-III, and option A sets deposit insurance principles. Option B monitors the global financial system but does not write accounting standards."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 342, $official_bank_source${"itemId":"59c3ebe1-6f26-5fc8-9a96-4f7585981986","questionId":"1d4381ba-1399-5153-8744-d8e15eadb9d4","sourceKey":"bank:FIN216:SUP-080","payload":{"prompt":"Banks whose failure would generate severe undesirable externalities, including disruption of the financial system and the real economy, are called","options":["bridge banks","non-interest banks","special insured institutions","systemically important financial institutions (SIFIs)"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"SIFIs are institutions whose size, complexity and interconnectedness mean their failure would seriously disrupt the wider system and economy. Option A is a temporary bank set up to take over a failed bank. Options C and B are categories of institution that are not defined by systemic impact."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 343, $official_bank_source${"itemId":"e0156e6e-da11-5787-b79d-bf92cd16c26d","questionId":"00b07df8-9e06-5692-9f9c-9b2cee5fe7eb","sourceKey":"bank:FIN216:SUP-081","payload":{"prompt":"In the CBN/NDIC framework for domestic systemically important banks issued in 2014, which two indicators carry the highest weight (30% each) in assessing systemic importance?","options":["Size and complexity","Substitutability and interconnectedness","Complexity and interconnectedness","Size and substitutability"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"The 2014 framework weights size (total assets) at 30%, substitutability at 30%, complexity at 25% and interconnectedness at 15%. Options C, A and B each include complexity or interconnectedness, which carry lower weights."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 344, $official_bank_source${"itemId":"0d36e435-172d-57b7-b264-db12580aee58","questionId":"1ac173d8-1c22-5971-a0c9-584f95fe3780","sourceKey":"bank:FIN216:SUP-082","payload":{"prompt":"Under the CBN/NDIC framework for systemically important banks (2014), the minimum capital adequacy ratio for a bank designated as a SIB is","options":["8%","10%","20%","15%"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"SIBs must keep a minimum CAR of 15%, higher than ordinary national banks, plus a 1% higher loss absorbency surcharge. Option A is the Basel I international minimum, and option B is the general Nigerian minimum for many non-SIB banks. Option C is not the framework's minimum."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 345, $official_bank_source${"itemId":"80327584-908c-55a0-b9e9-8f62e7ddb3d9","questionId":"7b50c50e-540d-5158-a1ad-680f10293444","sourceKey":"bank:FIN216:SUP-083","payload":{"prompt":"Under the 2014 CBN/NDIC framework for systemically important banks, the additional 1% Higher Loss Absorbency surcharge must be met with","options":["deposit insurance premiums","Common Equity Tier 1 capital","customer deposits","Tier 2 capital"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"The 1% HLA surcharge must be met with CET1, the highest-quality capital, so SIBs can absorb losses as going concerns. Option D is lower-quality capital that is already limited to 25% of qualifying capital. Options C and A are liabilities or payments, not capital."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 346, $official_bank_source${"itemId":"98286aa0-b30c-5464-82e4-b8e5d269e9a0","questionId":"f8594d4d-5630-551d-98bb-2e3b94f2d678","sourceKey":"bank:FIN216:SUP-084","payload":{"prompt":"Under the 2014 CBN/NDIC SIB framework, Tier 2 capital may not exceed 25% of a SIB's qualifying capital. If a SIB has qualifying capital of N400bn, what is the maximum amount of Tier 2 capital it can count?","options":["N100bn","N300bn","N25bn","N60bn"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Maximum Tier 2 = 25% x N400bn = N100bn, which means Tier 1 must be at least N300bn (75%). Option B is the minimum Tier 1 amount, not the Tier 2 cap. Option D applies 15% (the minimum CAR) by mistake, and option C treats 25% as N25bn."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 347, $official_bank_source${"itemId":"b60ead52-dea3-5297-80ff-8731fb9cd6ec","questionId":"d8b617e2-f956-51d8-825a-3e355203a638","sourceKey":"bank:FIN216:SUP-085","payload":{"prompt":"Under the 2014 CBN/NDIC framework, systemically important banks must submit a specific recovery plan to the CBN and NDIC","options":["only after their licence is revoked","by 1 January of every year","only when they record a loss","once every five years"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"SIBs must prepare and submit a recovery plan to both the CBN and NDIC by 1 January each year, so authorities are ready before trouble comes. Option A is wrong because recovery planning is for going-concern banks. Options D and C do not match the annual requirement."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 348, $official_bank_source${"itemId":"9cdd8707-ed08-5448-82a1-ca169b3354b2","questionId":"3d4de917-854a-54e9-bab1-ee6f39df59b8","sourceKey":"bank:FIN216:SUP-086","payload":{"prompt":"Under the 2014 CBN/NDIC framework, how often must systemically important banks carry out stress tests of their capital and liquidity?","options":["Monthly","Only during a crisis","Every two years","Quarterly"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"SIBs must run capital and liquidity stress tests every quarter, with results reviewed by the CBN. Option A is the frequency of the CBN's monitoring of SIB key performance indicators, not of stress tests. Options C and B are not what the framework requires."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 349, $official_bank_source${"itemId":"a440cae4-3dcd-5579-ab47-c279291db641","questionId":"75ed960e-fd8d-54d0-aa6c-6d33df10fcf7","sourceKey":"bank:FIN216:SUP-087","payload":{"prompt":"Under the NDIC Act 2006, which of the following was NOT one of the NDIC's enforcement powers over insured institutions?","options":["Terminating the insured status of an insured institution","Setting the monetary policy rate for the banking system","Issuing specific directives to address unsafe and unsound practices after an examination","Taking over the control and management of an insured institution"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Setting the monetary policy rate is a CBN monetary policy function, not an NDIC enforcement power. Options C, D and A were among the NDIC's enforcement powers, along with recommending licence revocation and prosecuting directors for malpractice."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 350, $official_bank_source${"itemId":"b135af58-1f63-568e-b3de-dfa137ca7d75","questionId":"e67039ca-dd01-5660-b43d-62dfe829300b","sourceKey":"bank:FIN216:SUP-088","payload":{"prompt":"After examining Eko Commerce Bank, the NDIC directs it to stop granting new loans to its directors and to raise fresh capital within six months. Directives like this, issued promptly after an examination to correct unsafe practices, are known as","options":["purchase and assumption","prompt corrective action","liquidation","deposit payoff"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"Prompt corrective action means supervisors quickly order a bank to fix unsafe or unsound practices while it is still operating. Options A, D and C are ways of dealing with a bank that has failed or is being closed, not corrective orders to an operating bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 351, $official_bank_source${"itemId":"59b549b2-118e-55ac-b7e2-419d74933bb6","questionId":"395db63a-3df8-5b63-a239-272a422471b0","sourceKey":"bank:FIN216:SUP-090","payload":{"prompt":"Holding actions belong to which group of bank failure resolution options?","options":["Deposit payoff and liquidation","Purchase and assumption","Open bank assistance","Bridge bank mechanism"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Holding actions are applied while the bank is still open and operating, so they fall under open bank assistance, together with financial assistance and takeover of management. Options A, B and D all involve a bank that has been closed or had its licence revoked."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 352, $official_bank_source${"itemId":"aba97925-53b8-53d6-8aec-153bf7a2e97a","questionId":"587fb39e-41fa-562b-b897-6e2c1376bf85","sourceKey":"bank:FIN216:SUP-091","payload":{"prompt":"The CBN and NDIC bar a distressed bank from opening new branches and granting fresh loans until it restructures and recapitalises, but allow it to keep operating. This is an example of","options":["a holding action","a liquidation","a deposit payoff","a bridge bank"],"correctOption":0,"section":"Banking Supervision at the NDIC","explanation":"Restricting a distressed but still-open bank's operations while it restructures is a holding action. Option D would require a failed bank's business to be moved into a new temporary bank. Options C and B happen only after the bank is closed."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 353, $official_bank_source${"itemId":"41f784dd-5dda-5a9e-9f7b-c67772105fbc","questionId":"18efdc6c-a0cc-5fb9-91f9-6b45d48a177b","sourceKey":"bank:FIN216:SUP-092","payload":{"prompt":"The NDIC has expressed serious concern about the integrity of data supplied by insured banks. Which problem most clearly shows this?","options":["Depositors filing claims too quickly after a bank closes","Significant disparity between data from on-site examination and data from off-site returns","Banks paying premiums before the due date","Too many banks applying for deposit insurance"],"correctOption":1,"section":"Banking Supervision at the NDIC","explanation":"When figures found on-site differ widely from what banks reported in their returns, off-site analysis becomes unreliable; this is the data integrity problem. Options D, A and C are not data integrity issues, and early premium payment is not a problem at all."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 354, $official_bank_source${"itemId":"4929623f-7c3d-5118-999d-4b489951d8d6","questionId":"7a6179dc-9220-54f3-bf8d-5e46bcf23c33","sourceKey":"bank:FIN216:SUP-093","payload":{"prompt":"How does deposit insurance differ from conventional insurance such as fire or motor insurance?","options":["Deposit insurance involves only two parties, the insurer and the depositor","Deposit insurance never pays out because banks cannot fail","Deposit insurance involves three parties and actively seeks to reduce the insured risk through supervision","In deposit insurance the depositor pays the premium directly"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Deposit insurance has three parties (the insurer, the depositor who pays no premium, and the bank that pays the premium), and the insurer works to reduce the risk through supervision. Option A describes conventional insurance. Option D is wrong because the bank, not the depositor, pays, and option B is wrong because banks do fail."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 355, $official_bank_source${"itemId":"80bb1386-6316-5423-818c-0c7db68cb742","questionId":"3d361204-2a9a-5240-a2fb-4069fdfb878d","sourceKey":"bank:FIN216:SUP-094","payload":{"prompt":"Both the depositor and the bank benefit from deposit insurance. How does the bank benefit?","options":["Its shareholders are guaranteed against loss","It receives the premiums paid by depositors","It is exempted from all prudential regulations","It is supervised and assisted in times of problems"],"correctOption":3,"section":"Banking Supervision at the NDIC","explanation":"While the depositor is protected, the bank gains from being supervised and assisted when it runs into problems. Option C is wrong because insured banks remain fully regulated. Option B is wrong because depositors pay no premium, and option A is wrong because deposit insurance protects depositors, not shareholders."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 356, $official_bank_source${"itemId":"78e2e1f1-ad25-548e-953d-974853e09920","questionId":"bf82a955-ef29-53ca-817a-53120541e1ee","sourceKey":"bank:FIN216:SUP-095","payload":{"prompt":"Why does the NDIC see emerging distress in microfinance banks and primary mortgage institutions as a supervisory concern even when deposit money banks are sound?","options":["Because their depositors are never insured","Because they are supervised by the SEC","Because these segments are interdependent with the mainstream insured banks","Because they pay no deposit insurance premiums at all"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"Distress in MFBs and PMBs can spill over to deposit money banks because the segments are linked. Option D is wrong because MFBs pay premiums (at a flat rate). Options B and A are wrong because these institutions are supervised by the CBN and NDIC and their depositors are insured up to set limits."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 357, $official_bank_source${"itemId":"3b03b4e8-68a4-583f-85a6-d39ab4c8facc","questionId":"e658c5fc-2197-565a-826f-0c3ce870d86f","sourceKey":"bank:FIN216:SUP-096","payload":{"prompt":"Under the NDIC Act 2023, from which of the following must the NDIC NOT meet its day-to-day operating expenses?","options":["Investment income","Money borrowed with Board approval","The deposit insurance funds held in trust for depositors","Its capital"],"correctOption":2,"section":"Banking Supervision at the NDIC","explanation":"The insurance funds are held in trust for depositors, so running costs come from a separate Operating Fund financed by capital, investment income, approved borrowing and other approved sources. Options A, D and B are all permitted ways of financing operating costs."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 358, $official_bank_source${"itemId":"db0bb8cc-89d3-586b-824a-3880b550afe2","questionId":"9b64fdc7-4a06-506c-bf6a-89e85b6494d6","sourceKey":"bank:FIN216:F216-0012","payload":{"prompt":"Which of the following banks did NOT have its licence revoked on 16 January 1998, when the CBN closed 26 banks with the NDIC as liquidator?","options":["Allied Bank","Amicable Bank","Allstates Trust Bank","Pan African Bank"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"Allstates Trust Bank survived the 1998 closures and only lost its licence in January 2006, when it was one of the banks that failed to meet the N25 billion consolidation requirement. Allied Bank, Amicable Bank and Pan African Bank in options A, B and D were among the 26 banks whose licences were revoked at once in January 1998, the largest single closure in Nigerian banking history."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 359, $official_bank_source${"itemId":"240afcae-01c8-5dfe-bd3f-891f60410982","questionId":"58b1b659-2382-571c-a2f1-f61569662a63","sourceKey":"bank:FIN216:F216-0015","payload":{"prompt":"Which of the following is a symptom of bank distress?","options":["Boardroom squabbles","Window dressing","Desperate borrowing","All of the above"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"All three are warning signs that a bank is in trouble. Boardroom squabbles point to weak governance, window dressing means making the accounts look healthier than they are, and desperate borrowing, often at high rates in the interbank market, shows the bank is struggling for liquidity. Because options A, B and C are each a symptom, D is the best answer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 360, $official_bank_source${"itemId":"f4b4def9-0f2c-5315-ba8e-baa411b95b2b","questionId":"d72bba39-c1fd-53f5-9e6a-2470b289c6e0","sourceKey":"bank:FIN216:F216-0022","payload":{"prompt":"Which of the following is NOT a cause of bank distress?","options":["Macroeconomic instability","Political interference","Fraud","Strong management"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"Strong management helps a bank avoid distress, so it is not a cause. Macroeconomic instability is an external cause that hurts borrowers and asset values, political interference can push banks into bad lending, and fraud drains a bank's resources directly. That makes options A, B and C genuine causes of distress."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 361, $official_bank_source${"itemId":"61b3127e-a41b-5a2c-ab37-64b145d8ac93","questionId":"c5cb0fd7-797e-54e4-a6de-e03f8ff2adc4","sourceKey":"bank:FIN216:F216-0024","payload":{"prompt":"At the end of the 2004-2005 banking consolidation exercise, the number of banks in Nigeria fell from 89 to ____","options":["18","25","14","34"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"In July 2004 the CBN required every bank to have at least N25 billion in capital by 31 December 2005, and through mergers and acquisitions the 89 banks were reduced to 25. Option C is close to the number of banks that failed to meet the deadline and lost their licences in January 2006, not the number that remained. The other figures do not match the outcome of the exercise."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 362, $official_bank_source${"itemId":"5687cc40-0bc9-54c0-b881-c480f6bc2dab","questionId":"d71e75cf-06ba-5146-9be3-6c1cad64a28b","sourceKey":"bank:FIN216:F216-0037","payload":{"prompt":"On 16 January 1998, the Central Bank of Nigeria revoked the licences of ____ banks.","options":["30","26","20","40"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"On 16 January 1998 the CBN revoked the licences of 26 distressed banks in one go, the largest single closure of the 1990s distress era, with the NDIC appointed as liquidator. The other figures are distractors and do not match that closure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 363, $official_bank_source${"itemId":"fb199736-6836-54b9-a403-16446e582617","questionId":"cb56f7a0-541d-5c1f-aa55-fdca5b728418","sourceKey":"bank:FIN216:DIS-001","payload":{"prompt":"Under the NDIC Act 2006, an insured institution whose capital-to-risk-weighted-assets ratio had fallen below the minimum prescribed by the CBN was defined as a:","options":["Failing insured institution","Systemically important bank","Bridge bank","Failed insured institution"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"The 2006 Act used capital adequacy below the CBN minimum as the test for a failing insured institution: it is in trouble but still holds its licence. Option D is wrong because a failed institution is one whose licence has already been withdrawn. A bridge bank (C) is a temporary bank that takes over a failed bank, and a systemically important bank (B) is identified by size and interconnectedness, not weak capital."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 364, $official_bank_source${"itemId":"92469c9d-436f-56ab-aaea-a20571037f17","questionId":"a0634889-561a-5047-bc1d-d5dbff67443f","sourceKey":"bank:FIN216:DIS-002","payload":{"prompt":"Under the NDIC Act 2006, a 'failed insured institution' was one whose:","options":["Capital adequacy ratio was below the CBN minimum","Banking licence had been withdrawn","Management had been changed by the CBN","Deposits had fallen for two consecutive years"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"A failed insured institution is one whose licence has been withdrawn, so it can no longer operate as a bank. Option A describes a failing institution, which is still licensed but undercapitalised. Options C and D may happen to troubled banks but were not the legal test of failure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 365, $official_bank_source${"itemId":"98b1f902-9a65-5cc4-abfc-8d01fbb77187","questionId":"8e98316b-8499-5266-80b6-1df6f88d3c63","sourceKey":"bank:FIN216:DIS-003","payload":{"prompt":"Under the NDIC Act 2006, what was the key difference between a failing and a failed insured institution?","options":["A failing institution was a microfinance bank; a failed institution was a deposit money bank","A failing institution had lost its licence; a failed institution was only undercapitalised","A failing institution was still licensed but undercapitalised; a failed institution had lost its licence","A failing institution was under CBN control; a failed institution was under NDIC control"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"Distress comes before failure: a failing bank has capital below the CBN minimum but still operates, while a failed bank has had its licence withdrawn. Option B simply reverses the two definitions. Options A and D are wrong because the terms depend on capital and licence status, not on the type of bank or which regulator is involved."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 366, $official_bank_source${"itemId":"c2db8cbf-2ab8-5c5b-a021-d1198dab21d7","questionId":"a215bbf8-b7f5-568b-a326-a35b0a073542","sourceKey":"bank:FIN216:DIS-004","payload":{"prompt":"Effective bank resolution is described as a series of systematic actions designed to end a bank's distressed condition with minimal disruption and:","options":["By guaranteeing all deposits without any limit","Without exposing taxpayers to losses","By keeping the failed bank's management in place","By passing all losses to insured depositors"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Good resolution ends a bank's distress smoothly while keeping the cost off taxpayers, so losses fall on shareholders and uninsured creditors instead. Option A describes a blanket guarantee, which is costly and encourages moral hazard. Options D and C are the opposite of what resolution tries to do, since insured depositors are protected and the managers who caused the problem are usually removed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 367, $official_bank_source${"itemId":"ff27da1a-9300-520b-a84f-b8387ddac479","questionId":"f4b235f8-b3f3-52e0-992f-89787e8ae06e","sourceKey":"bank:FIN216:DIS-005","payload":{"prompt":"Which of the following is NOT an objective of bank resolution in Nigeria?","options":["Ensuring continuity of basic banking functions","Protecting depositors","Minimising reliance on public sector support","Protecting the investment of the failed bank's shareholders"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"Resolution aims to protect depositors, keep essential banking services running, protect client funds, limit harm to financial stability and reduce reliance on public money. Shareholders are not protected; they are expected to bear losses first. Options A, C and B are all genuine objectives of resolution."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 368, $official_bank_source${"itemId":"8db3b071-d077-5121-80b8-ef38cdc93243","questionId":"85b58b08-b8f8-55c3-ac16-8ef2f050522f","sourceKey":"bank:FIN216:DIS-006","payload":{"prompt":"Which of the following is NOT a reason why the failure of a bank has a greater impact than the failure of an ordinary commercial business?","options":["Banks have a low capital-to-assets ratio (high leverage)","Banks keep most of their assets in cash, so they rarely need to sell assets","Banks fund themselves heavily with demand deposits","Banks are closely linked through interbank lending and the payments system"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Banks actually keep only a small share of assets in cash (fractional reserve banking), which is why they may have to sell earning assets to meet withdrawals. Options A, D and C are genuine reasons: high leverage leaves little room for losses, interconnection spreads failure to other banks, and demand deposits create the risk of runs."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 369, $official_bank_source${"itemId":"32e6de4b-0fc3-5f83-9b61-cea1d16b78a9","questionId":"e950ac94-9575-535c-b9e1-0ade0e1b63fb","sourceKey":"bank:FIN216:DIS-007","payload":{"prompt":"Because banks lend to and borrow from one another, hold deposits with one another and share the payments clearing system, the failure of one bank can spill over and threaten the whole banking system. This danger is known as:","options":["Credit risk","Systemic risk","Interest rate risk","Moral hazard"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Systemic risk is the risk that trouble at one institution spreads through its links with others and endangers the whole system. Credit risk (A) is the risk that a particular borrower will not repay. Moral hazard (D) is the incentive to take more risk when others bear the cost, and interest rate risk (C) comes from changes in interest rates."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 370, $official_bank_source${"itemId":"60b2ad59-9488-5dca-afde-645ee4fce159","questionId":"a9ffa880-2e53-5c59-9eb2-657d1e4608ff","sourceKey":"bank:FIN216:DIS-008","payload":{"prompt":"After rumours of trouble, depositors rush to withdraw from Gamma Bank. With little cash on hand, the bank must sell loans and other hard-to-value assets quickly at heavy discounts to pay them. The losses from such forced sales are called:","options":["Liquidation dividends","Premium rebates","Provisioning gains","Fire-sale losses"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"Fire-sale losses arise when a bank must sell opaque or illiquid assets in a hurry for much less than their true value, which can turn a liquidity problem into insolvency. Liquidation dividends (A) are payments made to uninsured depositors and creditors after a bank is closed. Premium rebates (B) are refunds of deposit insurance premiums, and provisioning gains (C) are not the result of forced sales."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 371, $official_bank_source${"itemId":"807d8ff0-0c84-5e9c-844c-d37495149880","questionId":"eea22ebb-02e7-56bd-802a-4a1bf3e9d8a6","sourceKey":"bank:FIN216:DIS-009","payload":{"prompt":"Why does a low capital-to-assets ratio make a bank more likely to fail when it suffers losses?","options":["It leaves only a thin cushion of owners' funds to absorb losses before depositors' money is affected","It forces the bank to hold too much idle cash","It means the bank has too few depositors to lend to","It reduces the bank's deposit insurance premium to zero"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Capital is the buffer that absorbs losses; when it is small relative to assets (high leverage), even modest loan losses can wipe it out and leave the bank insolvent. Option B confuses capital with cash holdings. Options C and D have nothing to do with leverage."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 372, $official_bank_source${"itemId":"147ceada-cba0-5831-835b-a3ab94065a2f","questionId":"9877e76c-42d7-585c-8e7c-9f888145c4a8","sourceKey":"bank:FIN216:DIS-010","payload":{"prompt":"Causes of bank failure that arise from within the bank itself, such as weak credit policies, insider loans and frauds, are classified as:","options":["Macroeconomic causes","Systemic causes","Exogenous causes","Endogenous causes"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"Endogenous causes come from inside the bank: its policies, its operations and the way it is managed. Exogenous causes (C) come from outside the bank, such as the economy or regulation. Options B and A describe problems in the wider system or economy, not internal weaknesses."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 373, $official_bank_source${"itemId":"f3d2aa2a-98fc-5b35-bfc8-fcf91581ef16","questionId":"71cd7ab1-925b-57f8-86b7-542f32a52935","sourceKey":"bank:FIN216:DIS-011","payload":{"prompt":"Which of the following is an endogenous (internal) cause of bank failure?","options":["Connected lending and insider loans","Rapid rise in asset prices (boom and burst)","Major regulatory change","Weak supervisory framework"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Connected lending and insider loans are decisions made inside the bank, where directors or related parties borrow on soft terms and often fail to repay. Options B, C and D are exogenous causes because they come from markets, the regulator or the supervisory system rather than from the bank itself."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 374, $official_bank_source${"itemId":"b3c4908d-67f7-5a85-8e96-653547a1ae3a","questionId":"7f7a6fc7-2022-5de2-ab95-101c2b3de5a7","sourceKey":"bank:FIN216:DIS-012","payload":{"prompt":"Which of the following is NOT an endogenous cause of bank failure?","options":["Credit concentration","Ineffective audit","An unfavourable macroeconomic environment","Frauds and forgeries"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"The macroeconomic environment is outside any single bank's control, so it is an exogenous cause. Frauds and forgeries (D) and ineffective audit (B) are failures in the bank's operations, while credit concentration (A) is a failure of the bank's lending policy."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 375, $official_bank_source${"itemId":"50ce35d9-b215-572d-a503-b9bb43d0adea","questionId":"dafb1933-d0b6-5581-8d51-02f0206e6f86","sourceKey":"bank:FIN216:DIS-013","payload":{"prompt":"The directors of Delta Bank approve large loans on soft terms, with little collateral, to companies they own. Most of the loans are never repaid. Which cause of distress does this best illustrate?","options":["Connected lending and insider loans","Loan/deposit mismatch","Credit concentration","Major regulatory change"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Lending to directors or their related companies on favourable terms is connected (insider) lending, a classic cause of bank distress in Nigeria. Credit concentration (C) means lending too much to one borrower group or sector, whether insiders or not. A loan/deposit mismatch (B) is about maturities, and regulatory change (D) is an external cause."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 376, $official_bank_source${"itemId":"c599842c-3928-52e1-822a-3d4c15c61a3e","questionId":"57a8c9f4-ea25-51a7-b032-cc8b353b557d","sourceKey":"bank:FIN216:DIS-014","payload":{"prompt":"Epsilon Bank lends about 70 percent of its loan book to a handful of oil-marketing companies. When the sector runs into trouble, most of the loans go bad at the same time. Which internal cause of failure does this illustrate?","options":["Credit concentration","Insider loans","Postponement of accrual of expenditures","Failure of information technology"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Credit concentration means putting too large a share of loans into one borrower, group or sector, so a single shock damages much of the portfolio at once. Insider loans (B) involve lending to directors or related parties, which is not stated here. Options D and C are operational and accounting weaknesses unrelated to how the loan book is spread."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 377, $official_bank_source${"itemId":"86935232-f1c0-58e6-848f-045914fcc4af","questionId":"90a7e875-e47d-5d70-b00c-00a3f6a78be7","sourceKey":"bank:FIN216:DIS-015","payload":{"prompt":"Zeta Bank funds 10-year mortgage loans mainly with customers' demand deposits that can be withdrawn at any time. When many depositors withdraw together, it cannot pay them. This weakness is called:","options":["Frauds and forgeries","Ineffective and inadequate recovery","Credit concentration","Loan/deposit mismatch"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"A loan/deposit (maturity) mismatch occurs when long-term loans are financed with short-term or demand funds, so the bank cannot meet withdrawals even if the loans are good. Credit concentration (C) is about lending too much to one sector, frauds (A) involve dishonest acts, and ineffective recovery (B) is failure to collect bad debts."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 378, $official_bank_source${"itemId":"32281c14-ce50-5233-ba19-23f2774fceea","questionId":"d03563ea-0fbe-5681-839c-2b9bd943264e","sourceKey":"bank:FIN216:DIS-016","payload":{"prompt":"For several years Eta Bank's internal auditors failed to detect that some staff were diverting customers' deposits, and the losses grew until the bank became distressed. Which internal causes of failure are shown?","options":["Credit concentration combined with loan/deposit mismatch","Frauds and forgeries combined with ineffective audit","Major regulatory change combined with weak supervision","Boom and burst in asset prices combined with external shocks"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Staff diverting deposits is fraud, and the auditors' failure to catch it points to ineffective audit; both are failures in the bank's operations. Option A concerns lending and funding structure, not theft. Options C and D are exogenous causes that come from outside the bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 379, $official_bank_source${"itemId":"f9c9c7ac-cc68-509f-b084-253b64cadf29","questionId":"a05f12ec-9167-50ab-be90-8af0b666abfd","sourceKey":"bank:FIN216:DIS-019","payload":{"prompt":"Theta Bank knows that N8 billion of its loans are unlikely to be repaid, but sets aside only N2 billion against them so that its profit looks higher. This practice is:","options":["Dipping into general reserves","Making less provision than required","Credit concentration","Postponement of accrual of expenditures"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Setting aside less than the expected loan losses is under-provisioning; it inflates profit and capital and hides the bank's true condition. Dipping into reserves (A) means using past retained profits, and postponing accruals (D) means delaying the recording of expenses such as salaries. Credit concentration (C) is about how loans are spread, not how losses are provided for."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 380, $official_bank_source${"itemId":"eec46238-4aae-5477-9bae-cc9ec45bcac6","questionId":"910099d6-8d3d-5e41-b106-eb70fd15fe12","sourceKey":"bank:FIN216:DIS-020","payload":{"prompt":"Kappa Bank continues to book interest as income on loans that have not been serviced for over a year. Apart from overstating profit, why does this practice worsen the bank's condition?","options":["It automatically cancels the bank's deposit insurance cover","It forces the CBN to revoke the licence immediately","It attracts additional tax on income the bank will never receive","It turns the bad loans into insured deposits"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"Recognising uncollectable interest as income makes profit look larger than it is, and the bank then pays tax on money it will never collect, draining real cash. Option A is wrong because insurance cover does not lapse because of an accounting practice. Options D and B are not consequences of this practice."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 381, $official_bank_source${"itemId":"90c4d22e-5476-51bc-a0da-6a71b572cc12","questionId":"1de1cb12-4261-54f7-9d7e-1b7e437fc558","sourceKey":"bank:FIN216:DIS-021","payload":{"prompt":"Iota Bank delays recording expenses it has already incurred, such as staff costs and rent, until the next financial year so that this year's results look better. Which cause of bank failure is this?","options":["Postponement of accrual of expenditures","Laissez-faire credit review procedures","Loan/deposit mismatch","Making less provision than required"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Expenses should be recorded in the period in which they are incurred; delaying them overstates current profit and hides weakness. Under-provisioning (D) relates specifically to provisions for bad loans. Laissez-faire credit review (B) and loan/deposit mismatch (C) are lending and funding problems, not expense recording."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 382, $official_bank_source${"itemId":"658ca582-4b04-540e-9005-3f50b5da9edc","questionId":"17243285-b11e-5fe3-a555-9945378e4b3e","sourceKey":"bank:FIN216:DIS-022","payload":{"prompt":"Under-provisioning for bad loans, booking uncollectable interest as income and postponing expenses all make a distressed bank's accounts look healthier than they really are. Such practices are commonly called:","options":["Consolidated supervision","Purchase and assumption","Risk-based supervision","Window dressing"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"Window dressing means presenting financial statements in a way that hides a bank's true weakness, and it is both a cause and a symptom of distress. Options C and A are supervisory approaches used by regulators, and purchase and assumption (B) is a method of resolving a failed bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 383, $official_bank_source${"itemId":"75832a80-842c-5a5d-8935-306c18a968c5","questionId":"f03c9292-c89d-587e-8cd2-22546019931d","sourceKey":"bank:FIN216:DIS-023","payload":{"prompt":"Which of the following is an endogenous cause of bank failure arising from a bank's operations?","options":["Major regulatory change","Failure of information technology","A relatively open and undiversified economy","Type and ease of entry into the market"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Breakdown of a bank's IT systems is an internal operational failure that can disrupt records, payments and controls. Options D, C and A are exogenous causes: they come from market structure, the wider economy and the regulator, not from the bank's own operations."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 384, $official_bank_source${"itemId":"42fe8b63-d8ff-5dfc-8d21-0885ed0b559a","questionId":"1aee0fb3-7639-5387-9a6c-725a13d5c32f","sourceKey":"bank:FIN216:DIS-024","payload":{"prompt":"Lambda Bank's bad loans keep piling up because it rarely follows up defaulters, enforces collateral or takes legal action to recover debts. Which internal cause of failure is this?","options":["Ineffective and inadequate recovery","Rapid rise in asset prices","Credit concentration","Weak supervisory framework"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Failing to pursue defaulting borrowers means losses that could have been reduced are left to grow, which is ineffective and inadequate recovery. Credit concentration (C) concerns how loans are spread across borrowers. Options D and B are exogenous causes rather than weaknesses in the bank's own recovery effort."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 385, $official_bank_source${"itemId":"390a06d5-c969-5367-a0e0-c77425c30ff8","questionId":"9fd3034f-0065-5c78-afb2-746e64d1305f","sourceKey":"bank:FIN216:DIS-025","payload":{"prompt":"Mu Bank's credit department rarely reviews existing loans after disbursement, so loans that start to go bad are noticed only when they are long overdue. Which internal cause of failure does this describe?","options":["Weak supervisory framework","Dipping into general reserves","Laissez-faire credit review procedures","Connected lending and insider loans"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"A laissez-faire (hands-off) credit review process fails to monitor loans after they are granted, so problems are caught too late. Insider lending (D) concerns who receives the loans. A weak supervisory framework (A) is a weakness of the regulator, not the bank, and dipping into reserves (B) is an accounting abuse."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 386, $official_bank_source${"itemId":"cb8f7524-a2f5-5471-ac29-3c54051a09db","questionId":"1a2f0c95-5271-5e4c-b3e5-fd36cd80802c","sourceKey":"bank:FIN216:DIS-026","payload":{"prompt":"Weak credit policies, connected lending and insider loans, and credit concentration are grouped together as failures arising from banks':","options":["Mismanagement","Policies","Regulatory environment","Operations"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"These causes all come from how a bank decides to lend, which is its credit and risk policy. Operational failures (D) include fraud, IT failure and ineffective audit, while mismanagement failures (A) are accounting abuses such as under-provisioning. The regulatory environment (C) relates to exogenous causes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 387, $official_bank_source${"itemId":"7ce819ee-b882-5c03-a2b5-4a800fa367fb","questionId":"9f0c818b-3780-5fb0-abbc-8b1cdea083ec","sourceKey":"bank:FIN216:DIS-027","payload":{"prompt":"Bank failure causes that originate outside the bank, such as an unstable macroeconomy or an asset price bubble, are called:","options":["Exogenous causes","Endogenous causes","Operational causes","Policy causes"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Exogenous causes come from the environment in which banks operate, such as the economy, markets, regulation and supervision. Endogenous causes (B) come from inside the bank, and operational (C) and policy (D) failures are both subgroups of endogenous causes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 388, $official_bank_source${"itemId":"a4be82e2-c709-5e54-a3cd-248e9aa6d2b4","questionId":"d972c01f-d979-55a5-b46c-568f3e5b6fe8","sourceKey":"bank:FIN216:DIS-028","payload":{"prompt":"Which of the following is an exogenous cause of bank failure?","options":["Ineffective audit","Type and ease of entry into the market","Weak human resource and capacity","Optimistic assessment of borrowers"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"How easily new banks can enter the industry is set by licensing policy and market structure, so it is outside any individual bank. Options C, A and D are internal weaknesses in staffing, controls and lending judgement, which makes them endogenous causes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 389, $official_bank_source${"itemId":"c3f47d79-d9a8-5a36-938e-5e3959dd01ad","questionId":"099a881f-03f9-592c-af49-a662753055d4","sourceKey":"bank:FIN216:DIS-029","payload":{"prompt":"After the 1986 Structural Adjustment Programme liberalised bank licensing, the number of banks in Nigeria rose sharply into the early 1990s, stretching supervisory capacity. Which exogenous cause of distress does this illustrate?","options":["Rapid rise in asset prices","Type and ease of entry into the market","Credit concentration","A relatively open and undiversified economy"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Easy entry let many new banks open quickly, often with weak capital and management, which raised competition and the risk of distress. A rise in asset prices (A) is a market bubble, and credit concentration (C) is an internal lending problem. An open undiversified economy (D) refers to vulnerability to external shocks, not the number of banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 390, $official_bank_source${"itemId":"a5df1d25-493e-5ea1-81f0-6affccce8813","questionId":"81f3011c-58c2-57ae-b2a7-a1a41bdb352f","sourceKey":"bank:FIN216:DIS-030","payload":{"prompt":"In July 2004 the CBN raised banks' minimum capital to N25 billion, to be met by 31 December 2005, and banks that could not comply lost their licences. For those banks, the new rule is an example of which exogenous cause of failure?","options":["Major regulatory change","A relatively open and undiversified economy","Type and ease of entry into the market","Rapid rise in asset prices"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"A sudden, large change in rules, such as a much higher capital requirement, can push weaker banks into failure if they cannot adjust. A rise in asset prices (D) and an open undiversified economy (B) are market and economic causes. Ease of entry (C) refers to lax licensing that lets too many banks in, which is the opposite of this tightening."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 391, $official_bank_source${"itemId":"bacdcfc3-1ce1-5877-be08-51b5e501c578","questionId":"44f12368-7bc6-5131-90a1-93fa5732ce2a","sourceKey":"bank:FIN216:DIS-031","payload":{"prompt":"Suppose property prices in a city rise rapidly for several years and banks lend heavily against land and houses. Prices then collapse, the collateral loses value and many loans go bad. Which exogenous cause of bank failure is this?","options":["Failure of information technology","Type and ease of entry into the market","Rapid rise in asset prices (boom and burst)","Loan/deposit mismatch"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"A boom and burst occurs when asset prices climb far above sustainable levels and then crash, destroying the value of collateral and borrowers' wealth. Ease of entry (B) concerns licensing of new banks. Options D and A are internal weaknesses of a bank, not market-wide price movements."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 392, $official_bank_source${"itemId":"dcc97237-56bc-5f90-8d9d-d51513d648a0","questionId":"36b8cd2e-f02b-5c1e-83b6-aee321848df0","sourceKey":"bank:FIN216:DIS-032","payload":{"prompt":"A country earns most of its export income from one commodity and imports much of what it consumes. When the world price of that commodity crashes, borrowers default and banks come under pressure. Which exogenous cause is shown?","options":["A relatively open and undiversified economy susceptible to external shocks","Type and ease of entry into the market","Weak supervisory framework","Connected lending and insider loans"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"An economy that depends on one export and on imports is exposed to shocks from abroad, which then hit borrowers and banks. A weak supervisory framework (C) is about the quality of oversight. Insider lending (D) is an internal cause, and ease of entry (B) concerns licensing."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 393, $official_bank_source${"itemId":"d02e318d-5c9a-5387-9541-249e75d0620f","questionId":"0a87db57-924c-5bf3-8b94-831ef1ada60a","sourceKey":"bank:FIN216:DIS-033","payload":{"prompt":"Regulators know that several banks routinely break single-borrower lending limits, but no sanctions are imposed for years. Which exogenous cause of bank failure does this reflect?","options":["Rapid and unsuitable economic growth","Major regulatory change","Non-compliance and weak enforcement of regulation","Rapid rise in asset prices"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"Rules only protect banks and depositors if they are obeyed and enforced; when breaches go unpunished, risky behaviour spreads. Major regulatory change (B) is about new rules, not failure to enforce existing ones. Options D and A are economic and market causes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 394, $official_bank_source${"itemId":"de5e25be-d565-5993-8a91-beada9307858","questionId":"81cae737-32ae-50a0-b62b-cf535d9e1caf","sourceKey":"bank:FIN216:DIS-034","payload":{"prompt":"High inflation, a sharp fall in the naira and rising interest rates leave many bank borrowers unable to repay their loans. Which broad exogenous cause of bank distress is this?","options":["Credit concentration","Type and ease of entry into the market","Macroeconomic environment","Frauds and forgeries"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"Inflation, exchange rates and interest rates make up the macroeconomic environment, and when it turns hostile, borrowers struggle and banks' assets weaken. Frauds (D) and credit concentration (A) are internal causes. Ease of entry (B) concerns licensing, not economic conditions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 395, $official_bank_source${"itemId":"f8713643-0ead-5a56-8cd9-18ad25ca7692","questionId":"f8cd2726-5722-5bc0-9384-24e9de01f783","sourceKey":"bank:FIN216:DIS-035","payload":{"prompt":"Which of the following was NOT one of the pre-crisis conditions said to have made banks vulnerable before the global financial crisis?","options":["A large amount of system-wide liquidity that encouraged excessive risk taking","Outsourcing of due diligence to rating agencies","Regulatory gaps that left parts of the financial system under-regulated","Excessively strict lending (underwriting) standards"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"Before the crisis, underwriting standards were poor, not too strict, so loans were granted too easily. Options C, B and A are genuine pre-crisis weaknesses: gaps in regulation, reliance on rating agencies instead of banks' own checks, and abundant liquidity that fuelled risk taking."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 396, $official_bank_source${"itemId":"267d0fb1-472e-52e5-abdd-5c97da0c2ae8","questionId":"defbb6fe-b38b-5da8-bc6e-8b2e538d4925","sourceKey":"bank:FIN216:DIS-036","payload":{"prompt":"Before the global financial crisis, weaknesses in banks' risk management were described as only a symptom of a deeper problem. That deeper problem was:","options":["Fundamental shortcomings in financial institutions' governance","Excessive capital held by banks","Too much supervision of banks","Deposit insurance coverage that was too low"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Poor risk management reflected poor governance: boards and senior management failed to set and enforce sound risk-taking. Option B is wrong because thin capital and high leverage were the problem, not excess capital. Options C and D were not identified as root causes; regulatory gaps meant too little oversight, not too much."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 397, $official_bank_source${"itemId":"ac874863-6777-52b6-904d-6c7e9d9005ba","questionId":"bfc438a3-395f-5258-9d7d-004f41d3a8fa","sourceKey":"bank:FIN216:DIS-037","payload":{"prompt":"Why can increased competition among banks contribute to bank distress, even though competition is generally good for customers?","options":["It forces banks to stop accepting deposits","It can encourage banks to take excessive risks with depositors' funds","It removes the need for any bank supervision","It always reduces banks' capital to zero"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Under strong competition banks may chase market share and profits by lending to riskier borrowers or underpricing risk, putting depositors' money in danger. That is why small depositors need protection. Options A, C and D are exaggerations that do not follow from competition."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 398, $official_bank_source${"itemId":"1c7711ee-1d30-5a1e-b2ec-c8326eb05d48","questionId":"9e2453fd-cfac-58eb-9d39-8ed171b9e415","sourceKey":"bank:FIN216:DIS-038","payload":{"prompt":"Before the NDIC was established, the government was unwilling to let any bank fail and propped up inefficient banks, especially those owned by state governments. Under the Structural Adjustment Programme, policy shifted towards:","options":["Banning state governments from owning banks","Nationalising every failing bank","Guaranteeing all deposits without limit","Protecting depositors, especially small ones, rather than directly supporting weak banks"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"The new approach accepted that weak banks could fail, and focused on protecting depositors, particularly small, less-informed ones, through an explicit deposit insurance scheme. Options B and C would have continued, or widened, unlimited support for banks. Option A was not the policy shift."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 399, $official_bank_source${"itemId":"0eee52ae-a5f4-5f80-92d4-79aaa988a505","questionId":"6f4ca3a3-f8d0-5642-8277-9899a7055c7d","sourceKey":"bank:FIN216:DIS-039","payload":{"prompt":"Which of the following is most likely an early warning sign that a bank is becoming distressed?","options":["Prompt and accurate submission of regulatory returns","A steady rise in non-performing loans alongside falling capital","A rising capital adequacy ratio","A steady fall in non-performing loans"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Growing bad loans eat into earnings and capital, and capital erosion is one of the clearest signals that a bank is sliding towards failure. Options C, D and A are signs of a healthier bank: stronger capital, better asset quality and reliable reporting."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 400, $official_bank_source${"itemId":"aa8ca568-003c-535b-84fa-249263473eeb","questionId":"9552f370-f180-5af4-9143-5ad1ffe04b72","sourceKey":"bank:FIN216:DIS-040","payload":{"prompt":"Nu Bank regularly borrows overnight from other banks at rates well above the market, delays customers' withdrawals and keeps missing its cash reserve requirement. These are symptoms of:","options":["Excess liquidity","Over-provisioning for bad loans","Liquidity distress","A strong capital position"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"A bank that must borrow desperately, cannot meet withdrawals on time and falls short of reserve requirements does not have enough liquid funds, which is liquidity distress. Excess liquidity (A) is the opposite situation. Options D and B describe strength or caution, not a cash shortage."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 401, $official_bank_source${"itemId":"b44d83ce-47f8-5cfb-9c9a-6b06c7a2df42","questionId":"6f405c24-4e4a-53ec-b806-00831542dd97","sourceKey":"bank:FIN216:DIS-041","payload":{"prompt":"Which of the following is NOT a symptom of bank distress?","options":["Window dressing of financial statements","Desperate borrowing on the interbank market","Persistent boardroom squabbles","Consistently timely and accurate regulatory returns"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"A bank that files timely, accurate returns is showing good governance and controls. Boardroom squabbles (C) point to governance breakdown, window dressing (A) hides losses, and desperate interbank borrowing (B) signals a liquidity shortage, so all three are symptoms of distress."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 402, $official_bank_source${"itemId":"0a574f23-1ae7-5a83-8b6a-00a243dc67dd","questionId":"50271496-d6b2-5459-bee2-856bb49c7c9c","sourceKey":"bank:FIN216:DIS-042","payload":{"prompt":"During an on-site examination, NDIC examiners find that Xi Bank's actual loan losses are far larger than those shown in the returns it sent for off-site analysis. Besides the losses themselves, this gap is a warning sign of:","options":["Effective risk management by the bank","Strong internal controls","Excess liquidity in the bank","Inadequate and unreliable information disclosure"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"A wide difference between on-site findings and off-site returns shows the bank's reported data cannot be trusted, which often hides deeper distress. Options B and A are the opposite of what the gap shows. Option C is unrelated to misreporting of loan losses."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 403, $official_bank_source${"itemId":"03779586-5758-5ccb-9366-fdd6b7c618ce","questionId":"ff47a220-12e6-5661-b508-b33bc4d35f6d","sourceKey":"bank:FIN216:DIS-044","payload":{"prompt":"In the mid-1990s, the CBN and NDIC imposed 'holding actions' on many distressed banks. Holding actions were:","options":["Payments of insured deposits to depositors","Sales of failed banks to new investors","Revocations of banking licences","Corrective or self-restructuring measures imposed on distressed banks"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"Holding actions restricted a distressed bank's activities and required it to restructure itself, as an early form of open bank intervention. Option A is deposit payout, which happens after closure. Option B is an acquisition and sale, and option C is the end point of failure rather than a corrective step."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 404, $official_bank_source${"itemId":"b7d18e4c-ad03-5b85-af98-f60f1749b344","questionId":"dc9c901f-c0ca-5ea1-9512-1125a93b7f00","sourceKey":"bank:FIN216:DIS-046","payload":{"prompt":"When depositors lose confidence in a distressed bank and rush to withdraw their funds at the same time, the event is called:","options":["A purchase and assumption","A liquidation dividend","A holding action","A bank run"],"correctOption":3,"section":"Distress in Nigerian Banks","explanation":"A bank run is a sudden wave of withdrawals driven by fear that the bank will fail, and it can bring down even a solvent bank because banks keep only a fraction of deposits in cash. A liquidation dividend (B) is paid after closure. Options A and C are resolution and corrective measures used by the authorities."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 405, $official_bank_source${"itemId":"c4dc10f6-94c9-5ec3-a5bc-b90c4d83dd0a","questionId":"5cb49656-1330-599a-9702-c27ca3ed81ef","sourceKey":"bank:FIN216:DIS-047","payload":{"prompt":"Which of the following is NOT a likely consequence of widespread bank distress?","options":["Increased public confidence in the banking system","Disruption of credit to businesses and households","Runs on other banks","Losses to uninsured depositors"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"Distress damages confidence rather than increasing it. Uninsured depositors (D) may lose part of their money, fear can spread and trigger runs on other banks (C), and credit to the real economy (B) dries up as banks shrink or close."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 406, $official_bank_source${"itemId":"1264ec42-b6d7-5618-9148-4734aa0becfd","questionId":"933f9adc-a1fb-5908-af4f-29661ca7519c","sourceKey":"bank:FIN216:DIS-049","payload":{"prompt":"Mr Okafor had N9 million in a deposit money bank whose licence was revoked in 2025. If the liquidator later pays a liquidation dividend of 40 percent on uninsured deposits, how much does he recover in total under the coverage limits in force since May 2024?","options":["N5,000,000","N3,600,000","N6,600,000","N8,600,000"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"He first receives the insured N5 million; the uninsured part is N9m - N5m = N4m, and 40 percent of that is N1.6m, giving N6.6m in total. Option B takes 40 percent of the whole N9m and ignores the insured payment. Option D wrongly adds 40 percent of the whole deposit to the N5m, and option A ignores the liquidation dividend."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 407, $official_bank_source${"itemId":"76828ca2-1270-5a9b-9ddd-d484806db528","questionId":"5c0336b0-4a55-57ee-87bc-b7cb578483e1","sourceKey":"bank:FIN216:DIS-050","payload":{"prompt":"Chioma had N3.2 million in a microfinance bank whose licence was revoked in 2025. Under the coverage limits introduced in May 2024, her insured amount is:","options":["N5,000,000","N2,000,000","N3,200,000","N200,000"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Since May 2024 microfinance bank depositors are covered up to N2 million, so she receives N2 million as insured deposit and claims the remaining N1.2 million from liquidation dividends. Option A applies the N5 million limit meant for deposit money banks, and option D is the older N200,000 limit. Option C ignores the limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 408, $official_bank_source${"itemId":"27c27dbd-d1da-585b-822c-752ac2390208","questionId":"967d7f70-bf40-5aea-9c06-f295f4d02cf6","sourceKey":"bank:FIN216:DIS-051","payload":{"prompt":"In December 2025 the CBN revoked the licences of Aso Savings and Loans Plc and Union Homes Savings and Loans Plc, two primary mortgage banks. A depositor with N1.5 million in one of them should receive:","options":["Only N500,000, the old mortgage bank limit","The full N1,500,000, because it is within the N2 million limit","Nothing, because mortgage bank deposits are not insured","Only N200,000"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"Primary mortgage banks are insured institutions, and since May 2024 their depositors are covered up to N2 million, so a N1.5 million balance is fully protected. Option A uses the pre-2024 limit, and option D is an even older figure. Option C is wrong because PMBs must insure their deposits with the NDIC."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 409, $official_bank_source${"itemId":"d9c8efec-f9ec-5641-890b-fb7b20813a4e","questionId":"dbae141f-0b8a-5c11-bbad-b558ac71b27d","sourceKey":"bank:FIN216:DIS-053","payload":{"prompt":"Under the resolution cost (AMCON sinking fund) arrangement, the CBN contributes N50 billion a year for 10 years and each bank pays an annual levy on its total assets. When the levy was 0.5 percent, what were the CBN's total 10-year contribution and the annual levy of a bank with total assets of N3 trillion?","options":["N500 billion and N15 billion","N50 billion and N15 billion","N5 trillion and N150 billion","N500 billion and N1.5 billion"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"The CBN pays N50bn x 10 = N500bn, and the bank pays 0.5 percent x N3 trillion = N15bn a year. Option B counts only one year of the CBN's contribution. Option D misplaces the decimal (0.05 percent), and option C inflates both figures tenfold."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 410, $official_bank_source${"itemId":"e01fbfc9-6faa-53dd-a281-e58aa57a022f","questionId":"fdc3446d-8615-52f2-b4c3-bc2330db36dc","sourceKey":"bank:FIN216:DIS-055","payload":{"prompt":"In 1994 the Federal Government promulgated the Failed Banks (Recovery of Debts) and Financial Malpractices in Banks Decree. Its main purpose was to:","options":["Establish the NDIC","Merge distressed banks with healthy banks","Speed up recovery of debts owed to failed banks and punish financial malpractice in banks","Raise the deposit insurance coverage limit"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"The decree targeted two problems behind the distress of the 1990s: unpaid loans, often to insiders, and malpractice by bank officials, through special recovery and prosecution powers. Option D concerns coverage, which this decree did not set. Option A is wrong because the NDIC was created in 1988, and option B describes a resolution method, not this law."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 411, $official_bank_source${"itemId":"eb284510-f1ff-5aa6-8aac-4c5442489097","questionId":"9709ee83-07fa-5590-a653-edf67fd74197","sourceKey":"bank:FIN216:DIS-056","payload":{"prompt":"On 16 January 1998 the CBN revoked the licences of 26 banks at once. What role did the NDIC play for these banks?","options":["Lender of last resort","Operator of bridge banks","Liquidator","Acquirer under purchase and assumption"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"Once the licences were revoked, the NDIC was appointed liquidator to pay insured depositors, realise the banks' assets and pay liquidation dividends. Purchase and assumption (D) was first used only in 2006, and bridge banks (B) came in 2011. The lender of last resort (A) is the CBN, not the NDIC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 412, $official_bank_source${"itemId":"34b7c748-a7f1-57b1-a565-4a53a46e6626","questionId":"189d0031-fe6c-5b11-9add-ae1ca482b6d4","sourceKey":"bank:FIN216:DIS-057","payload":{"prompt":"In July 2004 the CBN required every bank in Nigeria to have a minimum capital base of ____ by 31 December 2005.","options":["N50 billion","N5 billion","N25 billion","N2 billion"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"The 2004-2005 consolidation set a minimum capital of N25 billion, which forced mergers and acquisitions and cut the number of banks sharply. Options D, B and A are not the figure set for that exercise."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 413, $official_bank_source${"itemId":"e413940c-fe11-51f3-a24a-ed8b79586117","questionId":"0ad09d03-d12a-525a-8a16-a6776af7fcb6","sourceKey":"bank:FIN216:DIS-060","payload":{"prompt":"In 2009 a CBN/NDIC special examination of 24 banks found 10 in grave condition. Which of the following was NOT among the problems it identified?","options":["Poor risk management","Large volumes of non-performing loans","Excess capital and too little lending","Poor corporate governance"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"The examination found the troubled banks weighed down by bad loans, with eroded capital, weak risk management and poor governance; excess capital was the opposite of their condition. Options B, D and A were all genuine findings."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 414, $official_bank_source${"itemId":"26a11a16-597b-51fb-8e46-6f8f7cd73ac1","questionId":"2f17c5d8-ec28-522c-a06a-6b2c3141bd30","sourceKey":"bank:FIN216:DIS-061","payload":{"prompt":"Following the 2009 special examination of Nigerian banks, roughly how much was injected into the banks found to be in grave condition?","options":["About N2.3 billion","About N620 billion","About N50 billion","About N25 billion"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"About N620 billion was injected in 2009, starting with N400 billion into five banks on 14 August 2009 when their chief executives were removed. Option A is the 1989 accommodation to 10 banks, option C is the CBN's annual contribution to the resolution cost fund, and option D is the 2005 minimum capital figure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 415, $official_bank_source${"itemId":"aedfda1f-4732-5ba3-8eb4-2b1060af1e3c","questionId":"a214c623-9690-54c2-9bbe-d54607ed8bbd","sourceKey":"bank:FIN216:DIS-062","payload":{"prompt":"On 14 August 2009 the CBN removed the chief executives of five banks and injected N400 billion into them, keeping the banks open. This intervention is best described as:","options":["Open bank assistance (a bailout)","Purchase and assumption","Liquidation","Deposit payoff"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"The banks kept their licences while the authority replaced management and supplied funds, which is open bank assistance, often called a bailout. Purchase and assumption (B) requires a failed bank's business to pass to another institution. Deposit payoff (D) and liquidation (C) happen only after a bank is closed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 416, $official_bank_source${"itemId":"f4cc5b2c-a6d7-5c9e-96f4-9ee5e4f61e88","questionId":"880f61f8-412e-5612-87db-e6c999cfebe1","sourceKey":"bank:FIN216:DIS-069","payload":{"prompt":"In 2010 the CBN revoked the licences of 224 microfinance banks, but 121 of them had their licences restored after capital verification. How many microfinance banks were finally closed?","options":["103","121","224","345"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"The banks finally closed equal those revoked minus those restored: 224 - 121 = 103. Option B is the number restored, option C the number first revoked, and option D wrongly adds the two figures."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 417, $official_bank_source${"itemId":"3fe59acd-1ad4-54ea-88c0-753317a82af6","questionId":"37078a2a-7cd6-5808-8b3c-c29341877e3b","sourceKey":"bank:FIN216:DIS-072","payload":{"prompt":"During the global financial crisis some countries gave blanket guarantees on deposits. Their main aim was to:","options":["Encourage depositors to move funds abroad","Maintain depositor confidence and prevent systemic runs","Reduce deposit insurance coverage","Introduce co-insurance for depositors"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"A blanket guarantee protects deposits beyond the normal limit so that frightened depositors do not rush to withdraw from all banks at once. Option C is the opposite of a blanket guarantee. Options A and D would weaken rather than restore confidence."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 418, $official_bank_source${"itemId":"1ea287f4-49e4-5b05-b3e2-df895ed19572","questionId":"ff786bc4-5ff2-5e5a-ae8c-052154cb8b91","sourceKey":"bank:FIN216:DIS-073","payload":{"prompt":"Which of the following was NOT among the deposit insurance policy measures taken in the fall of 2008?","options":["Introducing or increasing co-insurance for depositors","Taking steps to ensure timely access to insured deposits","Raising maximum coverage levels","Extending coverage to a wider range of deposits"],"correctOption":0,"section":"Distress in Nigerian Banks","explanation":"In late 2008 authorities reduced the role of co-insurance, because making depositors bear part of the loss encouraged runs. Options C, B and D were genuine measures taken to strengthen confidence."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 419, $official_bank_source${"itemId":"9b733949-2f5c-544f-a6f8-cf7535a76de8","questionId":"bb22b04e-7d2a-582b-814d-95c56b3f43eb","sourceKey":"bank:FIN216:DIS-074","payload":{"prompt":"After the crisis, countries with implicit protection reconsidered explicit schemes. Which country launched explicit deposit insurance on 1 May 2015 with cover of 500,000 yuan?","options":["India","Japan","China","Kenya"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"China moved from implicit to explicit deposit insurance on 1 May 2015, with cover of 500,000 yuan that protects over 99 percent of depositors. India (A) has had deposit insurance since 1962, Kenya (D) since the 1980s, and Japan (B) does not use the yuan."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 420, $official_bank_source${"itemId":"5d11b573-3dd1-549e-835f-8e3a51714079","questionId":"91a1a187-fe15-5783-96e7-658ab7ff2c18","sourceKey":"bank:FIN216:DIS-076","payload":{"prompt":"Which of the following was NOT one of the key new measures in deposit insurance introduced after the global financial crisis?","options":["Higher and more harmonised coverage levels","Reducing coordination between deposit insurers and other safety-net participants","Greater convergence of deposit insurance practices across jurisdictions","Identification and resolution of systemically important financial institutions"],"correctOption":1,"section":"Distress in Nigerian Banks","explanation":"The crisis led to more, not less, information sharing and coordination among deposit insurers, central banks, supervisors and finance ministries. Options D, A and C were all genuine post-crisis reforms."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 421, $official_bank_source${"itemId":"9d2610a9-47bf-5475-8176-716f9f398bf6","questionId":"9e5ab15c-72b1-51ac-abb4-d16c517b691d","sourceKey":"bank:FIN216:DIS-078","payload":{"prompt":"Which of the following was a lesson of the global financial crisis concerning deposit insurance premiums and supervision?","options":["Premiums should be abolished and replaced by government grants","Supervision should be reduced to cut costs for banks","Premium assessment was adjusted towards risk-based pricing, backed by enhanced risk-based supervision","All banks should pay the same flat premium regardless of risk"],"correctOption":2,"section":"Distress in Nigerian Banks","explanation":"Risk-based premiums, such as Nigeria's Differential Premium Assessment System, make riskier banks pay more, and enhanced risk-based supervision discourages unnecessary risk taking. Option D is the flat-rate approach that risk-based pricing replaces. Options A and B would weaken the system and are not lessons of the crisis."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 422, $official_bank_source${"itemId":"530150d0-67f6-5913-b9d2-28e49c8dd72c","questionId":"7d34e946-d35f-5303-95d8-cf4cd6e13c3d","sourceKey":"bank:FIN216:F216-0010","payload":{"prompt":"A series of systematic actions designed to end a bank's distressed condition with minimal disruption and without exposing taxpayers to losses is known as ____","options":["Bank distress","Bank liquidation","Bank resolution","Bank consolidation"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Bank resolution covers all the actions used to deal with a failing bank in an orderly way, such as purchase and assumption, bridge banks or mergers, with liquidation as the last resort. Option B is narrower: liquidation means closing the bank and selling off its assets, which is only one possible outcome of resolution. Option A describes the troubled condition itself, not the remedy, and consolidation in option D is about mergers to meet capital rules."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 423, $official_bank_source${"itemId":"9e7f375e-4eca-570d-a042-8553e0a4bed4","questionId":"01aa7ca9-5999-5039-b7b3-7ab137ba0f30","sourceKey":"bank:FIN216:F216-0018","payload":{"prompt":"After the CBN revokes the licence of an insured bank in Nigeria, which body is by law appointed as its liquidator?","options":["AMCON","The Federal Ministry of Finance","The NDIC","The CBN"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Once a bank's licence is revoked, the NDIC becomes its statutory liquidator: it pays insured depositors, sells off the bank's assets and pays liquidation dividends to uninsured depositors and creditors. Option D is tempting because the CBN revokes the licence, but it hands the winding-up to the NDIC. AMCON buys bad loans and has funded bridge banks, and the Ministry of Finance is a part-owner of the NDIC, not a liquidator."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 424, $official_bank_source${"itemId":"0273304b-aa25-55fc-a416-d50942532821","questionId":"afa59b80-8728-5900-a17d-3b394da6b9c2","sourceKey":"bank:FIN216:F216-0032","payload":{"prompt":"Which of the following is NOT a bank failure resolution option used by the NDIC?","options":["Deposit payout","Realignment","Purchase and assumption","Bridge bank"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Realignment is not a recognised failure resolution tool, so it is the odd one out. The NDIC's resolution options include purchase and assumption (option C), where a healthy bank takes over the failed bank's deposits and good assets, paying off insured depositors (option A), and setting up a bridge bank (option D) to keep a failed bank's business running until a buyer is found, as was done with Mainstreet, Keystone and Enterprise banks in 2011."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 425, $official_bank_source${"itemId":"34cd241c-dff2-5e2a-9908-854cc4b2a79e","questionId":"1eeeded6-0cbf-57e4-86bd-25aa6fd93313","sourceKey":"bank:FIN216:F216-0034","payload":{"prompt":"The resolution method in which a healthy bank takes over the deposits and some or all of the assets of a failed bank is known as ____","options":["Bail out","Purchase and assumption","Outright liquidation","Deposit payout"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"In a purchase and assumption, a healthy bank buys some or all of the failed bank's assets and assumes its deposit liabilities, so depositors simply become customers of the acquiring bank. Option A, a bail out, means injecting public money to keep the troubled bank itself alive, not handing it to another bank. Options C and D close the bank down: liquidation sells off its assets, and a payout reimburses insured depositors directly without any bank taking over the business."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 426, $official_bank_source${"itemId":"a636f30e-0668-5712-9cbb-b11ff72ca8c5","questionId":"d790cb44-7c2e-5447-987b-fb65dae03c05","sourceKey":"bank:FIN216:F216-0106","payload":{"prompt":"Effective failure resolution, as practised by the NDIC, is best described as:","options":["A series of systematic actions designed to end a bank's distressed condition with minimal disruption","A single action by shareholders to raise new capital","The immediate liquidation of every distressed bank","A government guarantee of all bank liabilities"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Resolution is a planned set of steps aimed at ending a bank's distress while limiting disruption to the financial system and avoiding losses to taxpayers. Option C is wrong because liquidation is only one tool and usually the last resort. Option B describes just one possible step, and option D is a blanket guarantee, which shifts losses to taxpayers rather than resolving the bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 427, $official_bank_source${"itemId":"7bf42e18-07dd-50c6-ad06-d7d98623f9e0","questionId":"f433494d-8737-50cb-97c6-103fd73d3f66","sourceKey":"bank:FIN216:F216-0107","payload":{"prompt":"Which of the following is NOT an objective of an effective failure-resolution process?","options":["Meet the deposit insurer's obligations","Ensure depositors are reimbursed promptly and accurately","Maximize recoveries on the failed bank's assets","Protect shareholders of the failed bank from any loss"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"In a bank failure, shareholders are the owners who took the risk, so they are expected to bear losses first; shielding them would reward bad management and create moral hazard. Options A, B and C are all genuine aims of good resolution: the insurer honours its guarantee, depositors get paid quickly and correctly, and asset recoveries are maximized to cut the cost of the failure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 428, $official_bank_source${"itemId":"9a75e4ea-c12f-5857-b313-c17cfa39d308","questionId":"f9d668a5-8ce1-5d9d-8fd2-61c90c14758f","sourceKey":"bank:FIN216:F216-0108","payload":{"prompt":"Broadly, bank failure resolution methods are grouped into which two categories?","options":["Explicit and implicit resolution","Open-bank resolution and closed-bank resolution","Pay-box and risk-minimiser resolution","Ex ante and ex post resolution"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Resolution methods are grouped by whether the bank keeps operating: open-bank methods (such as financial assistance or takeover of management) keep it running, while closed-bank methods (such as purchase and assumption, bridge banks or deposit payout and liquidation) follow licence revocation. Option A describes types of deposit insurance, not resolution. Option C names deposit insurer mandates, and option D refers to ways of funding a deposit insurance scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 429, $official_bank_source${"itemId":"f759f43d-56cc-56c3-a63c-c348631bf927","questionId":"bb671a5f-889b-54df-895a-0015f2505142","sourceKey":"bank:FIN216:F216-0110","payload":{"prompt":"Which of the following is NOT a failure resolution option available to the NDIC?","options":["Open bank assistance","Lender of last resort facility","Deposit payout","Purchase and assumption"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Lending to banks as a lender of last resort is a CBN power, used to ease temporary liquidity shortages, so it is not one of the NDIC's own resolution tools. Options A, C and D are all NDIC resolution options: it can assist a bank while it stays open, pay insured depositors when a bank is closed, or arrange for a healthy bank to buy assets and assume deposits of a failed one."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 430, $official_bank_source${"itemId":"bb436cba-83af-5ca5-9ba1-8d977d794d0d","questionId":"1e13c018-e85c-5365-a976-4cba0804eb18","sourceKey":"bank:FIN216:LIQ-002","payload":{"prompt":"Which of the following is NOT an objective of an effective bank failure resolution regime in Nigeria?","options":["Maximising the returns of the failed bank's shareholders","Minimising reliance on public sector support","Ensuring continuity of basic banking functions","Protecting client funds and assets"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Resolution aims to protect depositors and the financial system, not to secure profits for the owners whose bank has failed; shareholders are expected to bear losses first. Options B, C and D are all genuine resolution objectives, together with protecting depositors and limiting harm to financial stability."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 431, $official_bank_source${"itemId":"8aebcbcd-3e43-53ad-9e12-338e89e09c37","questionId":"65694008-6681-521a-90a5-e1608b30c019","sourceKey":"bank:FIN216:LIQ-003","payload":{"prompt":"Which of the following is one of the stated objectives of bank failure resolution in Nigeria?","options":["Minimising adverse effects on banking and financial system stability","Keeping the failed bank's management in office","Ensuring that no bank is ever closed","Guaranteeing every creditor of the failed bank in full"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Resolution seeks to limit the damage a failure does to the wider banking and financial system. Option D goes beyond deposit insurance, which protects insured depositors only up to a limit, while option B is wrong because those who mismanaged the bank are usually removed. Option C is wrong since closure and liquidation remain valid resolution options."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 432, $official_bank_source${"itemId":"e1bc66d6-7c64-5d1a-a5d3-29c2ceaf65b5","questionId":"b683ff13-e259-57b2-87b7-f2c2a3c8557b","sourceKey":"bank:FIN216:LIQ-004","payload":{"prompt":"A well-designed resolution regime tries to deal with a failing bank without exposing which group to losses?","options":["Uninsured creditors of the failed bank","Taxpayers","Managers of the failed bank","Shareholders of the failed bank"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Good resolution keeps public money out of the picture, so taxpayers should not end up paying for a bank's failure. Options A and D are exactly the parties expected to absorb losses in order of seniority, and option C describes people who may even be held responsible for the failure."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 433, $official_bank_source${"itemId":"1200e166-5413-5b5e-b56c-b9aef469dbfc","questionId":"461b687c-6b5e-59cf-96c8-3737f0b929d9","sourceKey":"bank:FIN216:LIQ-005","payload":{"prompt":"Bank failures have a greater impact than failures of ordinary businesses. Which of the following is NOT a reason for this?","options":["Banks hold a low cash-to-assets ratio under fractional reserve banking","Banks are closely linked through interbank lending and payments","Banks generally have a high capital-to-assets ratio","Banks have a high share of demand deposits and short-term debt"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Banks actually have a LOW capital-to-assets ratio (high leverage), which leaves little room to absorb losses, so a high ratio would make them safer, not riskier. Option A explains why banks may have to sell earning assets to pay depositors, option D explains their exposure to runs, and option B explains how one failure spreads to others."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 434, $official_bank_source${"itemId":"662f2f83-5dfb-5833-92cf-878c716fea61","questionId":"7f9cfb60-7593-5458-a3b8-91f54be8df61","sourceKey":"bank:FIN216:LIQ-007","payload":{"prompt":"Under the FSB Key Attributes of Effective Resolution Regimes, resolution authorities should be able to allocate the losses of a non-viable institution to:","options":["The deposit insurer and central bank in equal shares","Insured depositors before any other party","Shareholders and unsecured or uninsured creditors in order of seniority","Taxpayers through the government budget"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The FSB framework wants losses borne first by the owners and then by unsecured or uninsured creditors, following their legal ranking. Option D is exactly what the framework tries to avoid, option B reverses the protection given to insured depositors, and option A would shift private losses onto public safety-net bodies."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 435, $official_bank_source${"itemId":"252f4c46-a514-5f04-aa90-bade6a6abc8d","questionId":"a0a2e089-b27a-518c-be38-68529101214e","sourceKey":"bank:FIN216:LIQ-008","payload":{"prompt":"Which of the following is NOT one of the FSB Key Attributes of Effective Resolution Regimes for Financial Institutions?","options":["Risk-based deposit insurance premiums","Crisis Management Groups (CMGs)","Recovery and resolution planning","Resolvability assessments"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Risk-based premiums are a funding design feature of deposit insurance systems, not one of the twelve FSB Key Attributes. Options B, C and D all appear on the FSB list, alongside items such as scope, resolution authority, resolution powers and safeguards."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 436, $official_bank_source${"itemId":"e499a005-e2a0-5684-93c2-4e5df3eb6d6b","questionId":"f2ea894a-9f71-5dda-8892-b472a73653dd","sourceKey":"bank:FIN216:LIQ-009","payload":{"prompt":"How many key attributes are listed in the FSB Key Attributes of Effective Resolution Regimes for Financial Institutions?","options":["16","18","10","12"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The FSB framework lists twelve key attributes, from scope and resolution authority through to access to information and information sharing. Options A and B are the numbers of IADI Core Principles for deposit insurance in the 2014 and 2025 versions, which is a common mix-up, and option C is simply too few."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 437, $official_bank_source${"itemId":"be0c534d-95b9-5cba-9ea4-9862d56ba754","questionId":"2f88f573-c0e6-5b79-b05a-8fbd77142fbd","sourceKey":"bank:FIN216:LIQ-010","payload":{"prompt":"The FSB Key Attributes are mainly designed to let authorities manage the failure of which type of institution without severe disruption or use of public funds?","options":["Large, complex and internationally active financial institutions","Small unit microfinance banks only","State-owned development finance institutions only","Insurance brokers and agents only"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The FSB framework targets big, complicated, cross-border financial firms whose failure could cause severe disruption, aiming to resolve them without taxpayer support. Options B, C and D wrongly restrict the framework to small or narrow groups that are not its main focus."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 438, $official_bank_source${"itemId":"91acbb4e-85fe-5a5c-8698-4aabcd0684e1","questionId":"e9495f25-bf8b-5568-b9aa-264ba4bcd158","sourceKey":"bank:FIN216:LIQ-011","payload":{"prompt":"Which FSB Key Attribute requires authorities to regularly check whether the resolution strategy for a firm is feasible and credible?","options":["Resolvability assessments","Funding of firms in resolution","Safeguards","Set-off, netting and collateralisation"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Resolvability assessments test whether a firm could actually be resolved under the chosen strategy, and the framework expects these feasibility checks to be reviewed regularly. Option C protects creditors' rights during resolution, option D concerns how financial contracts are treated, and option B deals with financing a firm while it is being resolved."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 439, $official_bank_source${"itemId":"86af6e28-c42e-5662-882b-93bab42dfff4","questionId":"d21925e9-83f7-54ae-9cb0-763ecb099cec","sourceKey":"bank:FIN216:LIQ-012","payload":{"prompt":"Which FSB Key Attribute deals with agreements between home and host authorities on how a particular cross-border financial firm will be resolved?","options":["Institution-specific cross-border cooperation agreements","Safeguards","Scope","Resolution authority"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Institution-specific cross-border cooperation agreements set out how authorities in different countries will work together on one named firm. Option C defines which institutions the regime covers, option D is about having a designated body with resolution powers, and option B concerns protections for creditors and counterparties."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 440, $official_bank_source${"itemId":"d4c05308-53eb-541d-bfea-0194ca13e9a8","questionId":"0c053443-79aa-5059-802e-139ae44b77cb","sourceKey":"bank:FIN216:LIQ-013","payload":{"prompt":"In Nigeria, which body shares bank failure resolution responsibility with the NDIC?","options":["Corporate Affairs Commission (CAC)","National Insurance Commission (NAICOM)","Securities and Exchange Commission (SEC)","Central Bank of Nigeria (CBN)"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The NDIC resolves failing banks together with the CBN, which licenses banks and acts as lender of last resort. The SEC regulates capital markets, NAICOM regulates insurance companies and the CAC registers companies, so options A, B and C do not resolve failing banks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 441, $official_bank_source${"itemId":"4d26c079-7e81-5033-be09-bde9a8da0fbc","questionId":"069d0fbe-ebcc-5303-a716-685327206122","sourceKey":"bank:FIN216:LIQ-014","payload":{"prompt":"Which of the following resolution tools belongs to the NDIC rather than to the CBN or AMCON?","options":["Lender of last resort facilities","Purchase of non-performing loans","Bridge bank mechanism","Revocation of banking licences"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The NDIC has the power to set up and run a bridge bank to take over a failed bank's business. Option A is the CBN's role, option B is AMCON's mandate, and option D is done by the CBN, after which the NDIC steps in as liquidator."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 442, $official_bank_source${"itemId":"142565aa-2a12-5518-9c05-2e2b4409b155","questionId":"ce72c082-914c-5547-98a4-b9bd062d5a78","sourceKey":"bank:FIN216:LIQ-015","payload":{"prompt":"A solvent Nigerian bank faces a sudden, temporary cash shortage and obtains short-term funding from the CBN to tide it over. This is an example of:","options":["Bridge bank resolution","Lender of last resort support","Purchase and assumption","Deposit payoff"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Lending to a solvent bank facing temporary liquidity pressure is the CBN's lender of last resort role. Options A and C involve transferring a failed bank's business to another entity, and option D is the reimbursement of insured depositors after closure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 443, $official_bank_source${"itemId":"fefaa744-f943-5174-8bd5-29dd383e787f","questionId":"dadd4eee-cb0a-5425-a1e8-6226a282e329","sourceKey":"bank:FIN216:LIQ-016","payload":{"prompt":"In Nigeria's bank resolution framework, the main resolution role of the Asset Management Corporation of Nigeria (AMCON) is to:","options":["Act as lender of last resort to solvent banks","Revoke the licences of insolvent banks","Pay insured depositors of closed banks","Purchase non-performing loans and recapitalise distressed banks"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"AMCON was set up to buy bad loans from banks and inject capital into technically insolvent banks. Option C is the NDIC's deposit guarantee role, while options A and B are functions of the CBN."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 444, $official_bank_source${"itemId":"1c1b9522-eedd-5a2f-bc19-ac88c95d71cf","questionId":"68aabbf5-aaeb-51a8-bb17-b1c7dac0fdb7","sourceKey":"bank:FIN216:LIQ-017","payload":{"prompt":"AMCON, which bought non-performing loans and recapitalised distressed Nigerian banks, was established by an Act in:","options":["2018","2010","2011","2006"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"AMCON was created by the AMCON Act of 2010 in response to the 2009 banking crisis. Option D is the year banks that failed consolidation were resolved, option C is when the three bridge banks were set up, and option A is when Skye Bank was resolved through Polaris Bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 445, $official_bank_source${"itemId":"8e7b4d37-9e6f-5d8c-86ad-09e8f53c259b","questionId":"15e89886-bdaa-5b23-9efb-8cf6760835f9","sourceKey":"bank:FIN216:LIQ-018","payload":{"prompt":"Under the NDIC Act 2006, an insured institution whose licence has been withdrawn is described as a:","options":["Distressed insured institution","Failing insured institution","Failed insured institution","Bridge institution"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Under the 2006 Act a 'failed' insured institution is one whose licence has been withdrawn. Option B is the term for a bank whose capital ratio has fallen below the CBN minimum but which still holds its licence, while options A and D were not the statutory terms for a bank that has lost its licence."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 446, $official_bank_source${"itemId":"1faf0ce0-51f9-5bd4-bd5b-5535c4a84165","questionId":"92da94db-4889-5e5e-b11f-032d581ff2a7","sourceKey":"bank:FIN216:LIQ-019","payload":{"prompt":"Under the NDIC Act 2006, Bank Q still holds its licence but its capital adequacy ratio has fallen below the minimum prescribed by the CBN. Bank Q is a:","options":["Bridge bank","Bank in liquidation","Failed insured institution","Failing insured institution"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A 'failing' insured institution under the 2006 Act is one whose capital adequacy ratio is below the CBN minimum while it is still licensed. Option C applies only once the licence has been withdrawn, option B follows licence revocation, and option A is a temporary bank set up by the deposit insurer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 447, $official_bank_source${"itemId":"6c9deea6-4968-5a3b-8201-ff605c672af5","questionId":"108facfd-df94-5223-8da7-4befda00d789","sourceKey":"bank:FIN216:LIQ-021","payload":{"prompt":"Which resolution option helps a distressed bank while it remains open and licensed, for example through financial assistance, holding actions or a takeover of its management?","options":["Purchase and assumption","Liquidation","Deposit payoff","Open bank assistance"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Open bank assistance supports a troubled bank without closing it, so it keeps its licence and continues serving customers. Option A transfers a failed bank's business to another institution, while options B and C follow the closure of the bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 448, $official_bank_source${"itemId":"fd022445-2efa-5edf-9ac2-d59bca1e2482","questionId":"b105d5ac-e0d1-5d89-be1d-8f5cac1d8d08","sourceKey":"bank:FIN216:LIQ-022","payload":{"prompt":"In 1989 the NDIC granted accommodation facilities of N2.3 billion to 10 banks that had serious liquidity problems. This was an example of:","options":["Purchase and assumption","Open bank assistance through financial assistance","Liquidation and deposit payoff","Bridge bank resolution"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The 1989 facilities were money given to banks that stayed open, which is financial assistance under open bank assistance. Options A and D involve moving a failed bank's assets and liabilities to another entity, and option C involves closing the banks, which did not happen here."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 449, $official_bank_source${"itemId":"67f43232-70b1-545d-b3e6-f62c2202514b","questionId":"23ed8b31-d950-5c0c-89c3-a2fbc8d7e9aa","sourceKey":"bank:FIN216:LIQ-023","payload":{"prompt":"Corrective or self-restructuring measures imposed on a distressed bank, such as restrictions on its activities until it improves, are called:","options":["Bridge banking","Holding actions","Insured deposit transfers","Liquidation dividends"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Holding actions are restrictive, corrective measures placed on a distressed bank so it can restructure while still open. Option D is a payment to uninsured depositors and creditors after closure, option A is a temporary bank run by the deposit insurer, and option C moves insured deposits of a closed bank to another bank."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 450, $official_bank_source${"itemId":"4ddf7c53-3288-5479-b302-470a0072f5aa","questionId":"017aa9fd-e959-5b65-9a95-d63a64d620ac","sourceKey":"bank:FIN216:LIQ-024","payload":{"prompt":"Regulators order distressed Bank R to stop opening new branches, stop granting new loans and cut its expenses until it restructures, while it continues to serve customers. Which resolution measure is this?","options":["Assisted merger","Insured deposit transfer","Imposition of holding actions","Purchase and assumption"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Restricting a bank's activities while it stays open so it can put its house in order is a holding action, a form of open bank assistance. Options A and D transfer the bank's business to another institution, and option B applies only after a bank is closed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 451, $official_bank_source${"itemId":"fc1f62b4-1dec-5273-83a8-edc8850bd2b7","questionId":"a2417262-5bcf-534d-b9ab-e09044897ee8","sourceKey":"bank:FIN216:LIQ-025","payload":{"prompt":"Which of the following is NOT a form of open bank assistance?","options":["Deposit payoff after licence revocation","Imposition of holding actions","Takeover of management and control by CBN/NDIC","Financial assistance to an illiquid bank"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A deposit payoff happens after a bank has been closed, so it is not open bank assistance. Options B, C and D are all ways of helping or controlling a distressed bank while it stays open."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 452, $official_bank_source${"itemId":"1b8ea64a-9afd-51d3-bf30-c28325383d2d","questionId":"c1450c5f-9c2a-5682-adbb-bc5eee908b2b","sourceKey":"bank:FIN216:LIQ-026","payload":{"prompt":"When the NDIC or CBN removes the board and management of a distressed bank and runs the bank itself to safeguard its assets, the measure is known as:","options":["Assumption of management and control","Purchase and assumption","Deposit payoff","Liquidation"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Taking over management and control means the regulators run the distressed bank directly while it remains open, which protects its assets from further abuse. Option B involves another bank buying assets and assuming liabilities, and options C and D follow closure of the bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 453, $official_bank_source${"itemId":"2db53cec-c20c-54f2-bd78-434fd2ea1da7","questionId":"81b4e830-6b09-5e15-add6-c18abeca3f38","sourceKey":"bank:FIN216:LIQ-027","payload":{"prompt":"In 2009, after a special examination of 24 banks, the authorities injected about N620 billion into troubled banks as loan capital and liquidity support and guaranteed their interbank takings. Which resolution approach was this?","options":["Bridge bank resolution","Bail-in of creditors","A government bailout through the CBN","Liquidation and deposit payoff"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Injecting public money and giving guarantees to keep troubled banks open is a bailout, carried out through the CBN. Option D would have closed the banks, option A came later in 2011 for three banks that could not recapitalise, and option B imposes losses on creditors rather than injecting public funds."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 454, $official_bank_source${"itemId":"280e71c3-c668-5774-aaf5-1b2cb2360e52","questionId":"b9485950-6abe-57ff-83c8-d3614d3d8609","sourceKey":"bank:FIN216:LIQ-028","payload":{"prompt":"What is the key difference between a bailout and a bail-in?","options":["A bailout protects only shareholders while a bail-in protects only insured depositors","A bailout closes the bank while a bail-in always sells it to a foreign bank","A bailout uses outside, often public, funds while a bail-in imposes losses on the bank's shareholders and creditors","A bailout is done only by the deposit insurer while a bail-in is done only by courts"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"In a bailout, money from outside the bank, usually the government, is injected to rescue it, whereas a bail-in writes down or converts claims of shareholders and unsecured creditors to absorb losses. Options A, B and D misdescribe both tools, and none of them captures the question of who bears the loss."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 455, $official_bank_source${"itemId":"22048494-dccc-572f-8b88-834772a493ac","questionId":"6bc4798a-66aa-5f74-ab1b-ca5d95a3769a","sourceKey":"bank:FIN216:LIQ-029","payload":{"prompt":"A resolution measure in which a failing bank's losses are absorbed by writing down or converting the claims of its shareholders and unsecured creditors, instead of using public funds, is called:","options":["Bailout","Holding action","Bail-in","Deposit payoff"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A bail-in recapitalises a failing bank from within by making its owners and unsecured creditors absorb losses. Option A is the opposite approach, rescuing the bank with outside money, option B restricts a distressed bank's activities, and option D reimburses insured depositors after closure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 456, $official_bank_source${"itemId":"9b72bf27-3402-58c7-b980-463d9330c9da","questionId":"bc72887a-b7df-5884-94af-6a18272e558b","sourceKey":"bank:FIN216:LIQ-030","payload":{"prompt":"The 2009 public assurance that 'no bank would be allowed to fail', together with large public rescues, raises which concern for future bank behaviour?","options":["Moral hazard","Systemic liquidity surplus","Market discipline","Adverse currency risk"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"When bankers expect to be rescued, they have an incentive to take more risk because others will bear the cost, which is moral hazard. Option C is the healthy pressure from depositors and creditors that such assurances actually weaken, while options B and D are unrelated to rescue expectations."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 457, $official_bank_source${"itemId":"4804bb9f-26a7-5811-8b65-0857650590df","questionId":"03c91494-e113-5ab5-8974-a7511670c479","sourceKey":"bank:FIN216:LIQ-031","payload":{"prompt":"A resolution method in which a healthy financial institution or a group of investors buys some or all of the assets and assumes some or all of the obligations of a failed institution is called:","options":["Holding action","Open bank assistance","Purchase and assumption","Deposit payoff"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Purchase and assumption (P&A) transfers a failed bank's assets and liabilities, especially deposits, to a healthy acquirer. Option B helps a bank while it remains open, option A restricts a distressed bank's activities, and option D simply pays insured depositors without any acquirer taking over the business."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 458, $official_bank_source${"itemId":"fb21d855-50c4-589d-a3dd-abedc02f42dc","questionId":"f1a026df-9397-5990-a9a1-cf50c38b6047","sourceKey":"bank:FIN216:LIQ-032","payload":{"prompt":"In a purchase and assumption transaction, the acquiring institution:","options":["Pays insured depositors in cash and takes no assets","Buys some or all of the failed bank's assets and assumes some or all of its liabilities","Lends money to the failed bank so that it can stay open","Runs the failed bank temporarily on behalf of the deposit insurer"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"In P&A a healthy bank or investor group purchases assets and assumes obligations, usually including deposits, of the failed bank. Option C describes open bank assistance or lender of last resort lending, option A describes a deposit payoff, and option D describes a bridge bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 459, $official_bank_source${"itemId":"157e8928-9acf-59f2-ad78-a17a5628809a","questionId":"27489383-9476-5ed3-bff0-7afa53d55761","sourceKey":"bank:FIN216:LIQ-033","payload":{"prompt":"Purchase and assumption was first used in Nigeria in 2006 to resolve banks that:","options":["Were found in grave condition in the 2009 special examination","Were later taken over by AMCON as bridge banks","Received accommodation facilities from the NDIC in 1989","Failed to meet the N25 billion minimum capital requirement of the banking consolidation"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The 2004-2005 consolidation required banks to have N25 billion capital, and in 2006 P&A was used to resolve those that failed to meet it. Option C refers to open bank assistance in 1989, while options A and B relate to the 2009 crisis and the 2011 bridge banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 460, $official_bank_source${"itemId":"6c7f2a5d-b88f-5847-ae1c-9c0e6d189bb3","questionId":"729a2471-30c4-5c43-8055-b15e0990b11f","sourceKey":"bank:FIN216:LIQ-034","payload":{"prompt":"Which of the following was NOT a reason the NDIC adopted purchase and assumption for banks that failed the 2005 consolidation?","options":["To encourage depositors to build relationships with the acquiring banks","To allow the failed banks' shareholders to keep control of their banks","To keep banking services running in the failed banks' premises","To give depositors easy access to their funds without disruption"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"P&A moves the failed bank's business to an acquirer, so the old shareholders lose control rather than keep it. Options A, C and D are the stated benefits: easy access to funds, continuity of service in the same premises, and promoting banking relationships with the acquiring bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 461, $official_bank_source${"itemId":"dc18656e-6045-56f6-8596-1f30b7651d28","questionId":"c5e0d506-87a0-5134-afcf-c737804eb025","sourceKey":"bank:FIN216:LIQ-036","payload":{"prompt":"How does purchase and assumption differ from open bank assistance?","options":["In P&A the failed bank's business passes to an acquirer, while in open bank assistance the troubled bank itself stays open","In P&A the deposit insurer lends to the bank, while open bank assistance closes it","In P&A depositors lose all funds, while open bank assistance pays them in full","In P&A the bank keeps its management, while open bank assistance replaces its owners with AMCON"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Open bank assistance supports a distressed bank while it continues to operate, whereas P&A follows failure and transfers assets and liabilities to a healthy institution. Option B reverses the two methods, option C is wrong because P&A is designed to protect depositors, and option D is not how either method works."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 462, $official_bank_source${"itemId":"28d521c6-9915-5b8a-9154-66990336ec2b","questionId":"eacec078-6402-5071-8bbd-e6981025412e","sourceKey":"bank:FIN216:LIQ-037","payload":{"prompt":"From a depositor's point of view, why is purchase and assumption usually less disruptive than a deposit payoff?","options":["Depositors receive payments above the coverage limit from the deposit insurer","The failed bank's shareholders guarantee all deposits personally","Depositors receive liquidation dividends before insured payments","Deposits move to the acquiring bank, so customers keep banking without waiting for payment from the insurer"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"In P&A the acquirer assumes the deposits, so customers continue banking, often in the same premises, with no break in service. Option A is wrong because coverage limits still apply to insurer payments, option B has no basis, and option C reverses the normal order in which insured sums are paid first."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 463, $official_bank_source${"itemId":"99de6583-2508-52a3-a526-7980f34280d6","questionId":"3cccab3f-238b-53e1-aa8a-8ab35a5d33ff","sourceKey":"bank:FIN216:LIQ-038","payload":{"prompt":"A temporary bank set up and operated by the deposit insurer to acquire the assets and assume the liabilities of a failed bank until a final resolution can be achieved is called a:","options":["Correspondent bank","Agent bank","Bridge bank","Acquiring bank"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A bridge bank is a temporary institution run by the deposit insurer that keeps a failed bank's business going until a buyer or permanent solution is found. Option B only helps pay depositors on the insurer's behalf, option D is a healthy permanent buyer in a P&A, and option A provides services to other banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 464, $official_bank_source${"itemId":"fe32ddef-9867-583a-92a2-f113ea8b4e74","questionId":"e1fbb9e3-be46-5bbf-a042-444fb7eb75f8","sourceKey":"bank:FIN216:LIQ-039","payload":{"prompt":"Which word best captures the intended life of a bridge bank?","options":["Mutual","Temporary","Permanent","Voluntary"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A bridge bank is meant to be temporary, bridging the gap until the failed bank's business can be sold or otherwise finally resolved. Option C is the opposite of its purpose, and options A and D describe types of arrangements or ownership unrelated to how a bridge bank works."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 465, $official_bank_source${"itemId":"03171c8b-fe15-5458-ae2e-b687ab61d3d4","questionId":"505f7e58-b591-5608-ad50-603c03e2dd7f","sourceKey":"bank:FIN216:LIQ-040","payload":{"prompt":"Under the NDIC Act 2006, a bridge bank was to last for how long from the date of its licensing, before any extension?","options":["Ten years","Five years","Two years","Six months"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Under the 2006 Act a bridge bank had an initial life of two years, which could be extended by up to three one-year periods. Option A is far too long for a temporary bank, option D is too short, and option B is the maximum reached only if all three extensions were granted."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 466, $official_bank_source${"itemId":"2329913b-e96d-502d-9da1-84d5af222c32","questionId":"d94eab70-a977-574e-a2f2-87c40991e09e","sourceKey":"bank:FIN216:LIQ-041","payload":{"prompt":"Under the NDIC Act 2006, a bridge bank lasted two years from licensing and could be extended by up to three one-year periods. What was the maximum total life of a bridge bank?","options":["Five years","Two years","Six years","Three years"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The initial two years plus three possible one-year extensions gives 2 + 3 = 5 years. Option B ignores the extensions, option D counts only the extensions, and option C wrongly adds an extra year."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 467, $official_bank_source${"itemId":"7373fbee-15a8-5442-ae56-4507fbd7fb17","questionId":"d1b300cb-2678-5a55-ab5a-8a29eb6d888c","sourceKey":"bank:FIN216:LIQ-042","payload":{"prompt":"Under the NDIC Act 2006, which section gave the NDIC power to establish a bridge bank?","options":["Section 39","Section 38","Section 59","Section 37"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Section 39 of the 2006 Act provided for bridge banks and was the basis for the 2011 bridge banks. Options B, C and D are other sections of the Act that deal with different matters."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 468, $official_bank_source${"itemId":"8c6144c6-632f-5447-9f7d-dfac6b19737b","questionId":"d8250067-73b7-5fbf-a0ce-e663a8c5d8ed","sourceKey":"bank:FIN216:LIQ-043","payload":{"prompt":"In August 2011, which bridge bank was set up by the NDIC to take over the business of the failed Bank PHB?","options":["Mainstreet Bank","Polaris Bank","Enterprise Bank","Keystone Bank"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Keystone Bank was the bridge bank for Bank PHB. Option A took over Afribank, option C took over Spring Bank, and option B was the 2018 bridge bank for Skye Bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 469, $official_bank_source${"itemId":"827a518a-7f0f-5be4-9e86-2c6af6c704ec","questionId":"5fc754a6-27ea-5d52-a56f-c4858f773493","sourceKey":"bank:FIN216:LIQ-044","payload":{"prompt":"Why did the NDIC set up bridge banks for Afribank, Bank PHB and Spring Bank in 2011?","options":["They had voluntarily asked to be wound up by their shareholders","They had been sold to foreign investors who later withdrew","They could not recapitalise, merge or find an acquirer by the September 30, 2011 deadline","They had refused to pay their deposit insurance premiums"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The three banks were among those found in grave condition in 2009 and failed to recapitalise, merge or find a buyer by the 30 September 2011 deadline, so a bridge bank was used. Options A, B and D are not the reasons given for these resolutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 470, $official_bank_source${"itemId":"fa15eae1-9b58-515d-be39-88a7f3164506","questionId":"54e9c0ca-3421-5c69-8544-fef3b7b09bb5","sourceKey":"bank:FIN216:LIQ-045","payload":{"prompt":"Which of the following was NOT a reason for adopting the bridge bank option for the three troubled banks in 2011?","options":["The banks' shareholders had injected enough fresh capital","The banks had attractive franchises that deterioration would make harder to sell","Outright liquidation would have had dire consequences for stakeholders","Continuity of banking services would protect depositors and confidence"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"If the shareholders had recapitalised the banks, there would have been no need for a bridge bank at all; the banks failed precisely because they could not recapitalise. Options B, C and D are the reasons given: preserving franchise value, protecting depositors through continuity, and avoiding the harm of outright liquidation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 471, $official_bank_source${"itemId":"30b9f0b6-0029-5bee-a19a-d4a948d80f46","questionId":"6fba75ec-0dec-56b2-a393-aaac1b5b0923","sourceKey":"bank:FIN216:LIQ-046","payload":{"prompt":"In 2018 the CBN revoked the licence of Skye Bank Plc, and a new bank took over all its assets and liabilities so customers kept operating their accounts and over 6,000 jobs were saved. Which resolution option was used?","options":["Insured deposit transfer","Open bank assistance","Liquidation with deposit payoff","Bridge bank mechanism"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Polaris Bank was set up as a bridge bank to take over Skye Bank's entire assets and liabilities, keeping services running. Option C would have closed the bank and paid insured depositors only, option B applies while the original bank is still licensed, and option A would have transferred only insured deposits."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 472, $official_bank_source${"itemId":"565fef9c-0022-5d7d-9716-229f83cfc6f9","questionId":"e92484a9-cc27-5817-b965-710904ba6a08","sourceKey":"bank:FIN216:LIQ-047","payload":{"prompt":"Since a bridge bank is temporary, how does its life normally end?","options":["Its business is sold to, or merged with, a private acquirer as the final resolution","It is converted into the deposit insurance fund","It automatically becomes a permanent government-owned bank","Its depositors are paid off and it is renamed an agent bank"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A bridge bank holds the failed bank's business only until a final resolution, usually a sale to investors; Polaris Bank, for example, was eventually sold to private investors (completed in 2022). Option C contradicts its temporary nature, and options B and D do not describe how bridge banks are wound up."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 473, $official_bank_source${"itemId":"4d825acd-3736-5cb5-9954-b617966c9a6e","questionId":"2fcdf364-235d-5677-ba4f-75e5d533523c","sourceKey":"bank:FIN216:LIQ-048","payload":{"prompt":"How does a bridge bank differ from a purchase and assumption transaction?","options":["A bridge bank is a temporary bank run by the deposit insurer, while P&A transfers the business to an existing healthy acquirer","A bridge bank is used only for microfinance banks, while P&A is used only for large banks","A bridge bank pays only insured deposits, while P&A pays only uninsured deposits","A bridge bank is created by shareholders, while P&A is ordered by the courts"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A bridge bank is set up and operated by the deposit insurer as a stopgap when no buyer is ready, whereas in P&A a healthy institution or investor group takes over immediately. Options B, C and D invent restrictions that do not exist for either method."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 474, $official_bank_source${"itemId":"85821d39-3fcc-5541-93da-013746bc8e7c","questionId":"854b893f-36ec-588d-9639-d343478c69b4","sourceKey":"bank:FIN216:LIQ-049","payload":{"prompt":"When regulators arrange for a healthy bank to acquire a distressed bank and support the deal with capital injections, the resolution method is called:","options":["Holding action","Assisted merger","Liquidation","Deposit payoff"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"An assisted merger is an acquisition of a weak bank by a stronger one, facilitated and financially supported by the authorities. Option D pays insured depositors after closure, option A restricts a bank's activities while it stays open, and option C winds the bank up."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 475, $official_bank_source${"itemId":"187b3993-5285-51f7-93da-6212b409a8d7","questionId":"af46c309-83ad-59f2-948d-6da90fbef0a3","sourceKey":"bank:FIN216:LIQ-050","payload":{"prompt":"In the 2011 assisted mergers in Nigeria, Intercontinental Bank was acquired by:","options":["FCMB","Access Bank","Sterling Bank","Ecobank"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Access Bank acquired Intercontinental Bank in the 2011 assisted mergers, with AMCON providing capital injection. Option D acquired Oceanic Bank, option A acquired Finbank, and option C acquired Equitorial Trust Bank."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 476, $official_bank_source${"itemId":"eddfb9b8-a782-5505-8cb6-e668242bd037","questionId":"e6c22eb3-da43-55d6-a53b-50adc95b9278","sourceKey":"bank:FIN216:LIQ-051","payload":{"prompt":"In 2011, AMCON injected capital into the troubled Oceanic Bank so that Ecobank could acquire it. This is an example of:","options":["A deposit payoff","A bridge bank resolution","An assisted merger","A holding action"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Regulators facilitated Ecobank's acquisition of Oceanic Bank with AMCON capital support, which is an assisted merger. Option B would involve a temporary NDIC-run bank, option A would close the bank and pay insured depositors, and option D only restricts a bank's activities."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 477, $official_bank_source${"itemId":"1e6ce876-6ba7-50a5-a4ba-704411a5d257","questionId":"7af001fe-cdde-5411-bd08-4053908da62c","sourceKey":"bank:FIN216:LIQ-052","payload":{"prompt":"When a failed bank is closed and the deposit insurer directly pays each insured depositor up to the coverage limit, the method is called:","options":["Bridge bank","Purchase and assumption","Open bank assistance","Deposit payoff"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"In a deposit payoff the insurer works out each depositor's insured amount and pays it directly, while the failed bank's assets stay with the liquidator. Options A and B transfer the bank's business to another institution, and option C keeps the troubled bank open."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 478, $official_bank_source${"itemId":"b3457d53-980c-54cb-b891-244d9121eca6","questionId":"523e2cde-c74b-5dbb-805e-2b3775ca24da","sourceKey":"bank:FIN216:LIQ-053","payload":{"prompt":"A resolution method in which the insured deposits of a closed bank are moved to a healthy agent bank, which then pays the depositors or opens new accounts for them, is called:","options":["Purchase and assumption","Insured deposit transfer","Holding action","Assisted merger"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"In an insured deposit transfer only the insured deposits are moved to an agent bank that makes them available to depositors. Option A usually involves the acquirer buying assets and assuming a wider set of liabilities, option C applies to a bank that is still open, and option D combines a weak bank with a healthy one."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 479, $official_bank_source${"itemId":"6e1003ef-a14c-54f1-8890-8eb741753999","questionId":"f3b3b901-7fd6-5a57-a622-54bdd0529282","sourceKey":"bank:FIN216:LIQ-054","payload":{"prompt":"What is the main difference between a straight deposit payoff and an insured deposit transfer?","options":["A payoff is done by the CBN, while a transfer is done by AMCON","A payoff covers uninsured deposits, while a transfer covers only insured deposits","A payoff keeps the failed bank open, while a transfer closes it","In a payoff the insurer pays depositors directly, while in a transfer the insured deposits are moved to another bank for depositors"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Both methods follow closure and protect only insured deposits; the difference is that in a payoff the insurer pays each depositor itself, while in a transfer the insured balances are placed in a healthy bank. Option B is wrong because neither pays uninsured sums from the insurance fund, option C is wrong because both apply to closed banks, and option A names the wrong bodies."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 480, $official_bank_source${"itemId":"8399ebd4-d12f-5045-858c-13a9f0334b68","questionId":"1a4c0fd0-26fc-5d38-8053-78f91e4b1287","sourceKey":"bank:FIN216:LIQ-055","payload":{"prompt":"How does an insured deposit transfer differ from a purchase and assumption?","options":["An insured deposit transfer is a form of lender of last resort, while P&A is a form of bail-in","An insured deposit transfer moves only insured deposits, while in P&A the acquirer buys assets and assumes a wider set of liabilities","An insured deposit transfer keeps the failed bank open, while P&A closes it","An insured deposit transfer pays shareholders first, while P&A pays depositors first"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"In an insured deposit transfer the healthy bank only takes the insured deposits to pay out or hold for customers, whereas in P&A it purchases assets and assumes liabilities of the failed bank. Option C is wrong since both follow closure, option A confuses the methods with unrelated tools, and option D reverses the priority of depositors over shareholders."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 481, $official_bank_source${"itemId":"d4a46fca-21ff-5da8-9934-72187a6efc4f","questionId":"eee94acd-9c7e-5adf-925e-03a6bab54e7b","sourceKey":"bank:FIN216:LIQ-056","payload":{"prompt":"In Nigeria's resolution framework, liquidation of a failed bank is regarded as:","options":["The last option, used when all other resolution options have failed","The first option, applied as soon as a bank shows any weakness","A form of open bank assistance granted by the CBN","An option reserved for profitable banks wishing to exit"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The NDIC and CBN treat liquidation as a last resort after other options such as open bank assistance, P&A or bridge banks have been tried in vain. Option B reverses this, option D describes a voluntary exit rather than resolution of a failed bank, and option C is wrong because liquidation closes the bank."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 482, $official_bank_source${"itemId":"c79c6bd6-0a88-5784-baa3-411ad05631ee","questionId":"0ff7c069-73e4-50c3-bcc9-b1902bf2f37c","sourceKey":"bank:FIN216:LIQ-057","payload":{"prompt":"The liquidation of a failed bank in Nigeria aims at an orderly and efficient closure that ensures:","options":["Continued operation of the failed bank under its old management","Transfer of the failed bank's losses to taxpayers","Full repayment of shareholders before any depositor","Little or no disruption to the banking system and cost-effective realisation of assets"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Liquidation seeks an orderly closure with minimal disruption, cost-effective sale of assets and settlement of claims of uninsured depositors, creditors and, where possible, shareholders. Option C reverses the order of payment, option A contradicts closure, and option B goes against a key aim of resolution."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 483, $official_bank_source${"itemId":"0bcdf33b-1639-5e90-9542-6535b03306fe","questionId":"3c948e50-35c4-54a7-be53-6cdba3a04731","sourceKey":"bank:FIN216:LIQ-058","payload":{"prompt":"Which of the following is NOT one of the bank failure resolution options that have been used in Nigeria?","options":["Assisted mergers","Purchase and assumption","Bridge bank mechanism","Nationalisation of all banks by the Ministry of Finance"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Nigeria has not resolved failing banks by nationalising the whole banking system. Options A, B and C have all been used, alongside open bank assistance and deposit payoff with liquidation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 484, $official_bank_source${"itemId":"38ecc8f1-c0ce-54ae-9a71-98db9d2d3ee1","questionId":"79451b64-c1bf-5dc3-93a6-92b6eea9ca72","sourceKey":"bank:FIN216:LIQ-059","payload":{"prompt":"On 16 January 1998 the CBN revoked the licences of 26 banks at once and the NDIC was appointed to wind them up and pay their depositors. Which resolution option was applied to these banks?","options":["Open bank assistance","Assisted merger","Liquidation with deposit payoff","Bridge bank mechanism"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The 1998 banks lost their licences and were wound up by the NDIC as liquidator, with insured depositors paid off. Option D would have kept their business running through a temporary bank, option B would have combined them with healthy banks, and option A applies only to banks that remain open."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 485, $official_bank_source${"itemId":"1e615e2c-b843-55f8-95f4-78618b05afae","questionId":"c8007c73-627a-5446-aeda-93dbc41c7daf","sourceKey":"bank:FIN216:LIQ-060","payload":{"prompt":"Skye Bank (2018) and Heritage Bank (2024) both had their licences revoked by the CBN. How were they resolved?","options":["Both through liquidation by the NDIC","Both through bridge banks set up by AMCON","Skye Bank through liquidation; Heritage Bank through an assisted merger","Skye Bank through a bridge bank (Polaris Bank); Heritage Bank through liquidation by the NDIC"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Skye Bank's business was moved to Polaris Bank, a bridge bank, while Heritage Bank was placed in liquidation with the NDIC as liquidator and insured depositors paid off. Options A and B wrongly treat the two cases as the same, and option C reverses and misnames the methods."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 486, $official_bank_source${"itemId":"bb031a72-bf6f-57e0-91d6-0488a9dc7a71","questionId":"f847ebc2-61ee-5ee3-b978-ec2d6de04010","sourceKey":"bank:FIN216:LIQ-061","payload":{"prompt":"As at September 2024, the NDIC had liquidated 651 failed institutions. Which category made up the largest number?","options":["Payment service banks","Deposit money banks","Microfinance banks","Primary mortgage banks"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Of the 651 institutions liquidated by September 2024, 546 were microfinance banks, compared with 55 primary mortgage banks and 50 deposit money banks. Options B and D are much smaller groups, and option A did not feature in that total."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 487, $official_bank_source${"itemId":"be86b1fb-7e90-5618-97cf-d4761af54b6f","questionId":"832374ff-bff0-552d-8d68-d69a83aac4c5","sourceKey":"bank:FIN216:LIQ-062","payload":{"prompt":"The rule that a deposit insurer should choose the resolution option that costs its fund the least, compared with all alternatives including liquidation, is known as the:","options":["Subrogation principle","Pro rata principle","Least-cost principle","Pass-through principle"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The least-cost principle compares the expected cost of each resolution option and selects the cheapest for the insurance fund. Option D relates to insuring each beneficiary of a pooled account, option B is about sharing proceeds in proportion to claims, and option A is the insurer stepping into depositors' shoes after paying them."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 488, $official_bank_source${"itemId":"4fa5d3c6-222f-5d8d-85b6-be99783c71be","questionId":"0a4842b3-ca34-553f-889b-f42c63024ddb","sourceKey":"bank:FIN216:LIQ-063","payload":{"prompt":"Under the 2014 IADI Core Principles, a resolution regime should include at least one resolution option whose cost to the deposit insurer is lower than that of:","options":["Merging the bank with a healthy acquirer","Granting the bank a lender of last resort loan","Paying out insured depositors and liquidating the bank","Keeping the bank open with holding actions"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"IADI uses the cost of liquidation, meaning paying out insured depositors and winding up the bank, as the benchmark that at least one other resolution method should beat. Options A, B and D are themselves alternative tools, not the benchmark used for the least-cost comparison."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 489, $official_bank_source${"itemId":"35e5602b-32ae-52b2-b623-9766fc1bc93f","questionId":"0d9926a0-7215-5ac3-86fc-933d86bde7a9","sourceKey":"bank:FIN216:LIQ-064","payload":{"prompt":"A failed bank has insured deposits of N40 billion. The NDIC estimates: deposit payoff would cost N40 billion with expected recoveries of N25 billion from the estate; a P&A would require the NDIC to pay the acquirer N12 billion; a bridge bank would cost N18 billion; and open bank assistance would cost N20 billion. Under the least-cost principle, which option should be chosen?","options":["Bridge bank","Purchase and assumption","Deposit payoff","Open bank assistance"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The net cost of the payoff is N40bn - N25bn = N15bn, so the options cost N15bn, N12bn, N18bn and N20bn, and P&A at N12bn is cheapest. Option C looks cheapest only if you forget it costs N15bn after recoveries, and options A and D are more expensive."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 490, $official_bank_source${"itemId":"6399ac17-9df6-59e9-a775-6e8a318ae48c","questionId":"5e6cc339-ee29-5606-9f98-fb00e8600c94","sourceKey":"bank:FIN216:LIQ-065","payload":{"prompt":"When a bank fails, the NDIC pays insured deposits of N8 billion and expects to recover 65% of that amount from the liquidation estate through its subrogated claim. What is the NDIC's expected net cost of the payoff?","options":["N13.2 billion","N8.0 billion","N5.2 billion","N2.8 billion"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Net cost equals the amount paid minus expected recoveries: N8bn - (65% x N8bn) = N8bn - N5.2bn = N2.8bn. Option C is the amount recovered, not the cost, option B ignores recoveries entirely, and option A wrongly adds the recovery to the payout."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 491, $official_bank_source${"itemId":"2041f570-1dd8-5e9d-b6c0-d72bda120cd2","questionId":"de7634d4-faae-528c-97b0-57c06819b7cd","sourceKey":"bank:FIN216:LIQ-067","payload":{"prompt":"Which event formally starts the liquidation of a failed deposit money bank in Nigeria?","options":["Revocation of the bank's licence by the CBN","A court order obtained by the bank's shareholders","Expiry of the bank's deposit insurance premium","A vote by the bank's depositors"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Liquidation follows once the CBN revokes the bank's licence, after which the NDIC acts as liquidator. Option B is wrong because the bank's owners do not trigger it, and they often challenge revocations in court instead, while options C and D are not the legal trigger."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 492, $official_bank_source${"itemId":"bdf4fbca-2745-582f-b21a-75d688bf8018","questionId":"dbcb15a0-9092-5f8f-92b7-67835aca8171","sourceKey":"bank:FIN216:LIQ-068","payload":{"prompt":"Under the NDIC Act 2023, who acts as liquidator of an insured bank whose licence has been revoked by the CBN?","options":["A liquidator elected by the shareholders","The CBN","AMCON","The NDIC"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The 2023 Act names the NDIC as liquidator of failed insured institutions, as it did for Heritage Bank in 2024. Option B revokes the licence but does not wind up the bank, option C buys bad loans and recapitalises banks, and option A reflects ordinary company winding-up, which does not apply to failed banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 493, $official_bank_source${"itemId":"4a19e6db-9570-5742-bf4e-66a180abe378","questionId":"4be359dd-cb03-5e65-b846-fe92cf16999f","sourceKey":"bank:FIN216:LIQ-069","payload":{"prompt":"Under the NDIC Act 2023, the winding up of a failed insured bank follows the NDIC Act rather than the general winding-up rules of which law?","options":["Companies and Allied Matters Act (CAMA) 2020","AMCON Act 2010","Central Bank of Nigeria Act 2007","Failed Banks (Recovery of Debts) Act 1994"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Section 56 of the NDIC Act 2023 disapplies the winding-up provisions of CAMA 2020 for banks, so liquidation is run under the NDIC Act. Option C governs the central bank, option B created AMCON, and option D dealt with recovering debts owed to failed banks rather than the winding-up rules."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 494, $official_bank_source${"itemId":"933a00d4-9307-515d-bd7e-48699c80c5c1","questionId":"f69f5b71-ddc5-5fc3-bb24-078393e49392","sourceKey":"bank:FIN216:LIQ-070","payload":{"prompt":"Which of the following shows the correct order of the main steps in the liquidation of a failed bank in Nigeria?","options":["Sale of assets; liquidation dividends; licence revocation; NDIC appointed liquidator; payment of insured deposits","Licence revocation; NDIC appointed liquidator; verification and payment of insured deposits; sale of assets and liquidation dividends; closure","Verification of claims; licence revocation; closure; liquidation dividends; payment of insured deposits","NDIC appointed liquidator; sale of assets; licence revocation; payment of insured deposits; closure"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The CBN first revokes the licence, the NDIC takes over as liquidator, verifies claims and pays insured sums, then realises the assets to pay liquidation dividends before the estate is finally closed. Options A, C and D each put a step out of place, for example selling assets or appointing the liquidator before the licence has been revoked."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 495, $official_bank_source${"itemId":"bf9fa7c6-aedb-5e7b-b329-20fbea896972","questionId":"7251c408-6997-5947-9850-0409f9b6abdd","sourceKey":"bank:FIN216:LIQ-071","payload":{"prompt":"During liquidation, the stage at which the NDIC checks each depositor's identity and balance against the failed bank's records before paying is called:","options":["Verification of claims","Declaration of liquidation dividends","Premium assessment","Realisation of assets"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Verification confirms who the depositors are and how much each is owed, so that only valid claims are paid; insured sums are paid to verified depositors. Option D is the sale of the failed bank's assets, option B comes later once assets have been sold, and option C relates to charging premiums to insured banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 496, $official_bank_source${"itemId":"cdf74d20-c9ba-5e7b-81b1-a18ee436fe39","questionId":"dd4f1388-2472-5482-8d30-bee3cffc3bef","sourceKey":"bank:FIN216:LIQ-072","payload":{"prompt":"Which of the following is NOT a reason the NDIC has struggled to settle insured deposit claims promptly in some failed banks?","options":["Poor state of the records of many closed banks","Banks that stopped operating long before their licences were revoked","Too much accurate and up-to-date information in the failed banks' records","Banks that were not fully computerised and had wide branch networks"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Delays came from poor or missing records, not from having too much accurate information. Options A, B and D are genuine causes: bad records, long gaps before revocation, and manual systems spread over many branches, such as the 26 banks closed in 1998 with about 342 branches."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 497, $official_bank_source${"itemId":"3a8f516f-d383-5a08-942b-6111707a18f1","questionId":"e0fc1e3e-190d-515b-b8e8-8609d239d69d","sourceKey":"bank:FIN216:LIQ-073","payload":{"prompt":"When the NDIC pays the insured deposits of a failed deposit money bank under the NDIC Act 2023, the money comes from:","options":["The failed bank's shareholders' fresh capital","CBN lender of last resort facilities","The Deposit Insurance Fund built from premiums","The NDIC's Operating Fund"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Insured deposits of DMBs are paid from the Deposit Insurance Fund, which is held in trust for depositors and built from premiums paid by insured banks. Option D meets the NDIC's running costs and is kept separate, option A is not available once a bank has failed, and option B is a liquidity loan to solvent banks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 498, $official_bank_source${"itemId":"0355f726-9fbb-5ae3-896b-4a018834f60a","questionId":"8bce59f9-b24c-5207-9cd7-df4d10188c9c","sourceKey":"bank:FIN216:LIQ-074","payload":{"prompt":"After paying insured depositors of a failed bank, the NDIC takes over their rights to claim that amount from the liquidation estate. This is called:","options":["Set-off","Bail-in","Pass-through","Subrogation"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Subrogation means the insurer steps into the shoes of the insured depositors it has paid and recovers from the failed bank's estate. Option A is offsetting a depositor's balance against a debt, option C insures each beneficiary of a pooled account, and option B imposes losses on shareholders and creditors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 499, $official_bank_source${"itemId":"588880d1-4014-5dc1-924d-f6647f1dafdb","questionId":"7ea4dbfc-18f2-5064-b345-304cb3a4de24","sourceKey":"bank:FIN216:LIQ-075","payload":{"prompt":"Pro rata payments made to uninsured depositors and other creditors as the assets of a failed bank are sold are called:","options":["Liquidation dividends","Accommodation facilities","Insured deposit payments","Premium rebates"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Liquidation dividends are shares of the proceeds from selling a failed bank's assets, paid to uninsured depositors and creditors in proportion to their claims. Option C comes from the insurance fund up to the coverage limit, option D is a refund of premiums to insured banks, and option B is assistance to banks still operating."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 500, $official_bank_source${"itemId":"f9e40201-790f-50f4-87e9-b226cc103a5d","questionId":"a8e596d7-f93c-5300-ad0e-86e5882b7d71","sourceKey":"bank:FIN216:LIQ-076","payload":{"prompt":"Liquidation dividends are paid to uninsured depositors 'on a pro rata basis'. This means each depositor receives:","options":["The same naira amount regardless of the size of the claim","The same percentage of his or her outstanding claim as every other depositor in the class","Payment in order of who filed a claim first","Payment only if the claim is below the coverage limit"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Pro rata means in proportion, so if a 40% dividend is declared every uninsured depositor receives 40% of what is owed to him or her. Option A ignores claim size, option C describes first-come payment, and option D confuses dividends with insured payments."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 501, $official_bank_source${"itemId":"36497674-779b-51e1-a102-441d71e901fc","questionId":"fde99515-ae3d-530d-958c-339f939bda66","sourceKey":"bank:FIN216:LIQ-077","payload":{"prompt":"Under the NDIC Act 2023, how do deposit liabilities rank when a failed bank is liquidated?","options":["They are paid only after liquidation expenses and taxes","They rank equally with shareholders' capital","They rank after all unsecured creditors","They have priority over all other liabilities"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The 2023 Act gives deposit liabilities priority over all other liabilities of the failed bank, so depositors are paid ahead of other creditors. Options A, B and C all place depositors lower than the law does, and shareholders in particular rank last."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 502, $official_bank_source${"itemId":"9a8a2a6b-61db-53fb-aa6a-2ebf335801ed","questionId":"b3786337-c30c-523d-b2a3-0a5256fff50f","sourceKey":"bank:FIN216:LIQ-078","payload":{"prompt":"In the liquidation of a failed bank, which group is paid only if something remains after depositors and creditors have been settled?","options":["Insured depositors","Shareholders","Uninsured depositors","Other creditors of the bank"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Shareholders are the owners and residual claimants, so they receive something only where possible, after depositors and creditors. Options A and C rank ahead because deposit liabilities have priority, and option D is also settled before shareholders."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 503, $official_bank_source${"itemId":"9dc6427f-9b21-5566-8c75-59da17a81753","questionId":"7e02c1f8-4cff-523f-9197-4e550703d578","sourceKey":"bank:FIN216:LIQ-079","payload":{"prompt":"A liquidator announces a 'final liquidation dividend of 100%' for a closed bank. What does this mean for its uninsured depositors?","options":["They have received only the insured portion of their deposits","They have recovered the full amount of their deposits","They must pay back 100% of any loans before receiving anything","They will receive nothing because assets were exhausted"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A 100% final dividend means the sale of the bank's assets was enough to repay depositors' claims in full. Option A describes the insured payment only, option D is the opposite outcome, and option C confuses dividends with loan repayment."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 504, $official_bank_source${"itemId":"d2b743ee-4604-50f2-a863-87e4917b6271","questionId":"c703ee09-4490-5269-82bc-300736fa8626","sourceKey":"bank:FIN216:LIQ-080","payload":{"prompt":"Mrs Bello has N7.5 million in a single savings account with a deposit money bank whose licence is revoked in 2025. With the NDIC coverage limit for DMBs of N5 million (set in May 2024), how much will the NDIC pay her as insured deposit?","options":["N2,500,000","N7,500,000","N2,000,000","N5,000,000"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Insured payment is the smaller of the balance and the coverage limit, so Mrs Bello receives N5m from the NDIC. Option B ignores the limit, option A is her uninsured balance, which she can recover only through liquidation dividends, and option C is the limit for MFBs, PMBs and PSBs, not DMBs."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 505, $official_bank_source${"itemId":"7006e66f-1a1f-56f6-acde-323e0487d970","questionId":"9cec3b2e-e8fe-58f6-93a8-6e003434dae8","sourceKey":"bank:FIN216:LIQ-081","payload":{"prompt":"Mrs Bello had N7.5 million in a deposit money bank that failed in 2025 and received the N5 million insured amount (May 2024 DMB limit). The liquidator later declares a total liquidation dividend of 40% on uninsured deposits. How much does she recover in total?","options":["N6,000,000","N8,000,000","N5,000,000","N3,000,000"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Her uninsured balance is N7.5m - N5m = N2.5m, and 40% of that is N1.0m, so her total recovery is N5m + N1m = N6m. Option C ignores the dividend, option B wrongly applies 40% to the whole N7.5m and adds it to N5m, and option D is just 40% of N7.5m."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 506, $official_bank_source${"itemId":"c756830f-ce46-5fb6-b983-4a88871e4804","questionId":"b360e263-a93b-58ec-af9c-9ce0ddc7bc83","sourceKey":"bank:FIN216:LIQ-082","payload":{"prompt":"Mr Okafor has N3.2 million in a microfinance bank whose licence is revoked in 2025. Under the coverage limits set in May 2024, how much of his deposit is uninsured and must be recovered through liquidation dividends?","options":["N1,200,000","N3,200,000","N2,000,000","N0"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The MFB limit since May 2024 is N2m, so N3.2m - N2m = N1.2m is uninsured. Option C is the insured amount, option D wrongly applies the N5m DMB limit, and option B assumes no cover at all."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 507, $official_bank_source${"itemId":"0b5c8b23-0876-5820-ae4b-12a4b219efc0","questionId":"530cd24c-8351-54af-97f9-acd44d4239d6","sourceKey":"bank:FIN216:LIQ-084","payload":{"prompt":"Assume a coverage limit of N5 million per depositor and that all accounts held by one depositor in the same right and capacity in a failed bank are added together. Mr Musa has N3 million in savings and N4 million in a current account, both in his own name, at a deposit money bank that fails in 2025. How much is insured?","options":["N10,000,000","N7,000,000","N5,000,000","N4,000,000"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Because the two accounts are in the same right and capacity, they are added to N7m and the limit of N5m applies to the total, so N5m is insured. Option B ignores the limit, option A wrongly applies the limit to each account separately, and option D insures only the larger account."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 508, $official_bank_source${"itemId":"807893ec-78bf-5ece-bdb3-ddeab3162ed5","questionId":"5f7bc324-4765-5509-b06e-1673f0e46e7a","sourceKey":"bank:FIN216:LIQ-085","payload":{"prompt":"A failed bank's uninsured depositors have total verified claims of N60 billion, and N24 billion is available from the sale of its assets for distribution to them. If Chinedu has an uninsured claim of N3 million, what liquidation dividend should he receive?","options":["N1,800,000","N3,000,000","N400,000","N1,200,000"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The dividend rate is N24bn / N60bn = 40%, and 40% of N3m is N1.2m. Option B assumes full repayment, option A is the 60% he does not recover, and option C wrongly divides 24 by 60 to get 0.4 and then treats it as N0.4m."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 509, $official_bank_source${"itemId":"a5ffe21f-19cb-550e-8cff-b364457d702a","questionId":"d49f3b64-4dd7-52fa-8645-634382d3a267","sourceKey":"bank:FIN216:LIQ-086","payload":{"prompt":"A liquidator pays an interim liquidation dividend of 25% and later a final dividend of 15% on uninsured claims. Funmi's uninsured claim is N4 million. How much does she receive in liquidation dividends altogether?","options":["N1,000,000","N2,400,000","N1,600,000","N600,000"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Total dividends equal (25% + 15%) x N4m = 40% x N4m = N1.6m. Option A counts only the interim dividend, option D counts only the final dividend, and option B is the 60% of her claim that remains unpaid."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 510, $official_bank_source${"itemId":"b5e323b6-9ca3-5e07-b87c-6381e0b2230b","questionId":"fd0123ce-5353-5c61-81f8-8590e3aa8d65","sourceKey":"bank:FIN216:LIQ-087","payload":{"prompt":"Under the NDIC Act 2023, assistance funding from an insurance fund is capped at 10% of the fund's balance unless the Board prescribes otherwise. If the fund balance is N1.2 trillion, what is the maximum assistance under this default cap?","options":["N1.08 trillion","N12 billion","N1.2 billion","N120 billion"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Ten per cent of N1.2 trillion is N120 billion. Option B uses 1% instead of 10%, option C uses 0.1%, and option A is the 90% that remains in the fund after the cap."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 511, $official_bank_source${"itemId":"6f708e24-70cc-5e01-9f6a-f047a769bc09","questionId":"1cf376cc-8734-513d-b595-41823d09426e","sourceKey":"bank:FIN216:LIQ-089","payload":{"prompt":"Under the NDIC Act 2006, the NDIC was required to pay insured depositors within how many days of the revocation of a bank's licence?","options":["30 days","7 working days","6 years","90 days"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Section 21(1) of the 2006 Act required payment within 90 days of licence revocation. Option B is the IADI best-practice standard, option A is the NDIC's 2023 Service Charter target, and option C was the period after which unclaimed insured deposits were forfeited under the 2006 Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 512, $official_bank_source${"itemId":"22e7414e-29e6-5335-9df8-cf7ba6b419f8","questionId":"9a7c46f1-62df-5d68-8fe5-c0faff9735fe","sourceKey":"bank:FIN216:LIQ-090","payload":{"prompt":"Under the 1988 NDIC Decree, insured depositors of a failed bank were to be paid as soon as possible but not later than:","options":["30 days after NDIC's appointment","3 months after the failure","6 years after the failure","7 working days after the failure"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The 1988 Decree required payment as soon as possible and within three months of the bank's failure. Option D is the later IADI standard, option A is the NDIC's 2023 Service Charter target, and option C relates to forfeiture of unclaimed deposits under the 2006 Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 513, $official_bank_source${"itemId":"f1a370a1-9fe5-52f3-af28-af1f98a8071a","questionId":"9b4fcc9b-036a-5dc5-b877-afa9d3c0538e","sourceKey":"bank:FIN216:LIQ-091","payload":{"prompt":"Under the NDIC Service Charter of 2023, the NDIC aims to pay insured depositors within how long?","options":["18 months of closure","30 days of its appointment as liquidator","90 days of licence revocation","3 months after failure"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The 2023 Service Charter sets a target of paying insured depositors within 30 days of the NDIC's appointment as liquidator. Option C was the NDIC Act 2006 rule, option D was the 1988 Decree rule, and option A was the old period for filing claims."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 514, $official_bank_source${"itemId":"a7d7513d-42da-517f-973f-ed56e51e40de","questionId":"5c70d9b4-928e-5b94-9195-6bf9b9d3bf4e","sourceKey":"bank:FIN216:LIQ-092","payload":{"prompt":"Which of the following ranks Nigeria's reimbursement deadlines from the LONGEST to the SHORTEST?","options":["NDIC Act 2006 (90 days); NDIC Service Charter 2023 (30 days); IADI 2014 standard (7 working days)","IADI 2014 standard (7 working days); NDIC Act 2006 (90 days); NDIC Service Charter 2023 (30 days)","NDIC Service Charter 2023 (30 days); NDIC Act 2006 (90 days); IADI 2014 standard (7 working days)","NDIC Act 2006 (90 days); IADI 2014 standard (7 working days); NDIC Service Charter 2023 (30 days)"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"90 days is longer than 30 days, which is longer than 7 working days, showing how payout targets have tightened over time. Options B, C and D each place at least one deadline in the wrong position."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 515, $official_bank_source${"itemId":"1ed57656-ad2a-5aea-ba34-cb237bba3b60","questionId":"b47a708f-03d4-51a9-ab19-c26ffd5a97ea","sourceKey":"bank:FIN216:LIQ-094","payload":{"prompt":"After Heritage Bank's licence was revoked on 3 June 2024, the NDIC began paying insured depositors within days. What mainly made this speed possible?","options":["Requiring every depositor to file a paper claim within 18 months","Transferring Heritage Bank to AMCON as a bridge bank","Waiting for the sale of Heritage Bank's assets before paying anyone","Paying insured sums into depositors' other bank accounts linked by their BVN"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The NDIC used Bank Verification Numbers to identify depositors' alternative accounts and credit their insured sums quickly. Option C describes how liquidation dividends, not insured payments, are funded, option A reflects the old slow claim-filing approach, and option B is wrong because Heritage Bank was liquidated."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 516, $official_bank_source${"itemId":"49d1b764-9fb9-578c-be05-746a327e7dcc","questionId":"3174339d-0d57-566e-9409-5d8af829feeb","sourceKey":"bank:FIN216:LIQ-095","payload":{"prompt":"Why is prompt reimbursement of insured depositors important when a bank fails?","options":["It allows the failed bank's shareholders to recover their capital first","It cushions the effects of failure and reduces the chance of runs on other banks","It removes the need to sell the failed bank's assets","It makes the coverage limit unnecessary for small depositors"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Quick payment softens the shock to depositors and keeps confidence high, so customers of other banks are less likely to panic and withdraw. Option A ignores that shareholders rank last, option C is wrong because assets must still be realised to pay uninsured depositors and creditors, and option D confuses speed with the amount covered."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 517, $official_bank_source${"itemId":"307f2d06-e301-543e-a711-c399d60fd905","questionId":"7b212205-519d-5d59-a863-65d1c3b4bb4f","sourceKey":"bank:FIN216:LIQ-096","payload":{"prompt":"Under the NDIC Act 2006, insured deposits that were not claimed within what period after a bank's closure were forfeited?","options":["Eighteen months","Six years","Seven working days","Ninety days"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Section 22(4) of the 2006 Act provided for forfeiture of insured deposits not claimed within six years. Option A was the rule under the earlier 1988 Decree, option D was the 2006 Act's deadline for the NDIC to pay, and option C is the IADI payout standard."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 518, $official_bank_source${"itemId":"426a7336-5af3-5153-b580-b16b6d274a64","questionId":"4c13c6b3-11f1-561b-a408-caf4e9d35027","sourceKey":"bank:FIN216:LIQ-098","payload":{"prompt":"In the past, insured depositors had to file claims with the NDIC, and many never did even where 100% liquidation dividends were declared. Which factor best explains this low response?","options":["Absence of any coverage limit for small depositors","Prohibition on depositors filing claims through agent banks","Depositor ignorance and apathy, especially among those with small balances","A rule that only shareholders could file claims"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Many depositors did not claim because they were unaware, unconcerned, or had small balances, despite public enlightenment efforts. Option B is wrong because agent banks were appointed to help pay claims, option A is false since limits have always existed, and option D has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 519, $official_bank_source${"itemId":"b4eb017b-dcf1-594d-84a5-e2161ac9df57","questionId":"1d9ab7c1-d8d5-5fb1-90fa-9ff13c2c9ebb","sourceKey":"bank:FIN216:LIQ-099","payload":{"prompt":"Apart from paying insured depositors directly, the NDIC has also reimbursed depositors of closed banks through:","options":["Agent banks appointed to pay claims on its behalf","The failed bank's former directors","AMCON's bad-loan purchases","The CBN's lender of last resort window"],"correctOption":0,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The NDIC has paid insured deposits both directly and through agent banks that pay depositors on its behalf. Option B is wrong because directors of failed banks play no role in paying depositors, and options C and D are different safety-net functions, not payout channels."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 520, $official_bank_source${"itemId":"53e6bc38-6162-5122-84c3-08c885f77a94","questionId":"b3babe68-86dd-59af-9624-253c516461a4","sourceKey":"bank:FIN216:LIQ-100","payload":{"prompt":"Which of the following is NOT a challenge faced in bank failure resolution and liquidation in Nigeria?","options":["Court actions by former shareholders","A deep secondary market for the risk assets of failed banks","Poor record keeping in failed banks","Cumbersome judicial process and long litigation"],"correctOption":1,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"A deep secondary market would make asset sales easier; in fact the lack of a secondary market for risk assets is one of the problems. Options A, C and D are genuine challenges that slow down liquidation and recoveries."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 521, $official_bank_source${"itemId":"6351c0f2-3b37-5567-aeb1-c7a0cd17100f","questionId":"0bdb23c7-c3ef-5514-a158-bc29bc396910","sourceKey":"bank:FIN216:LIQ-101","payload":{"prompt":"Which of the following best explains why the NDIC finds it hard to realise the loans and other assets of failed banks?","options":["Strict IFRS rules that forbid asset sales","The coverage limit on insured deposits","Large insider loans, poor loan documentation and lack of a secondary market","Excess demand from investors for failed banks' loans"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Asset realisation is difficult because many loans went to insiders, were poorly documented, are of low quality and have no ready market. Option D is the opposite of the real situation, option A has no basis, and option B concerns depositor protection, not asset sales."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 522, $official_bank_source${"itemId":"78399016-3821-5034-90a3-baa054696612","questionId":"2b440a50-9944-5ab5-a077-318bedf89c74","sourceKey":"bank:FIN216:LIQ-102","payload":{"prompt":"Which law was introduced in 1994 to help recover debts owed to failed banks and deal with financial malpractices in banks?","options":["Companies and Allied Matters Act 1990","Asset Management Corporation of Nigeria Act 2010","Banks and Other Financial Institutions Act 2020","Failed Banks (Recovery of Debts) and Financial Malpractices in Banks Decree/Act 1994"],"correctOption":3,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The 1994 Failed Banks law created a faster route to recover debts owed to failed banks, which helps liquidators realise assets. Option A is general company law, option B created AMCON to buy bad loans, and option C is the later banking law under which banks are licensed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 523, $official_bank_source${"itemId":"15f570bd-20ed-5768-b451-09084e147997","questionId":"0f26d054-be28-5065-b409-dfa7ea68db9f","sourceKey":"bank:FIN216:LIQ-103","payload":{"prompt":"Which resolution-related challenge in Nigeria is linked to the establishment of AMCON?","options":["The lack of a deposit insurance coverage limit","The absence of any body to buy non-performing loans","The moral hazard it may create by encouraging banks to expect bad loans to be bought","The prohibition of bridge banks by AMCON law"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"Because AMCON buys non-performing loans and recapitalises distressed banks, bankers may take more risk expecting a rescue, which is moral hazard. Option B is wrong because AMCON is exactly such a body, and options A and D are false statements."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 524, $official_bank_source${"itemId":"bcd926b0-4d5a-555e-8ba7-df235fe09eb5","questionId":"a84e89ce-1971-551b-bec4-11df7b093144","sourceKey":"bank:FIN216:LIQ-104","payload":{"prompt":"In every case, Nigeria's choice of a particular resolution measure has been largely guided by the need to:","options":["Avoid ever paying out insured depositors","Preserve the jobs of the failed bank's directors","Ensure cost-effectiveness, protect depositors and limit the use of taxpayers' funds","Maximise the fees earned by the deposit insurer"],"correctOption":2,"section":"Bank Liquidation and Failure Resolution by the NDIC","explanation":"The guiding considerations are cost-effectiveness, confidence, depositor protection, minimal disruption and limited recourse to taxpayers' money. Option D is not an aim of a public deposit insurer, option B conflicts with holding parties at fault responsible, and option A is wrong because deposit payout is itself one of the options used."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 525, $official_bank_source${"itemId":"a661f855-187a-5089-a2cc-20c35b497a25","questionId":"6b982db2-b974-5a7a-82d7-18211e7cb8ad","sourceKey":"bank:FIN216:F216-0008","payload":{"prompt":"Under the 1988 decree that established the NDIC, insured banks paid an annual premium equal to ____ of their total deposit liabilities.","options":["1/4 of 1 percent","15/16 of 1 percent","2 percent","8/16 of 1 percent"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"The original decree set a flat annual premium of 15/16 of 1 percent (about 0.9375 percent) of total deposit liabilities. Option D, 8/16 of 1 percent, was the ceiling the 2006 Act set for other deposit-taking institutions such as microfinance and mortgage banks, not the 1988 rate for banks. The other figures were never the statutory premium rate."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 526, $official_bank_source${"itemId":"ad24517e-0d29-5562-bf1b-a462a7278653","questionId":"d178fa34-ca25-58d3-b56c-97c5a41c7a91","sourceKey":"bank:FIN216:FND-001","payload":{"prompt":"A deposit insurance scheme that collects premiums from member banks regularly, so that a fund is built up before any bank fails, is said to be funded:","options":["Implicitly","Ex ante","Ex post","Through a blanket guarantee"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Ex ante funding means the money is collected in advance and accumulated in a fund that is ready before any failure happens. Option C, ex post funding, is the opposite: money is raised from surviving banks only after a failure. Options A and D describe forms of protection, not a way of building up a fund."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 527, $official_bank_source${"itemId":"3ad6a9a8-8f36-5530-981a-e7cb48d0b1f8","questionId":"a0d6320c-12be-5e27-83ea-17a69798dfbd","sourceKey":"bank:FIN216:FND-002","payload":{"prompt":"Under which funding method does a deposit insurer raise the money needed to pay depositors from the surviving member institutions only after a bank has failed?","options":["Ex ante funding","Target fund accumulation","Differential premium assessment","Ex post funding"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Ex post funding means nothing is set aside in advance; the cost of a failure is recovered afterwards by levying the banks that are still standing. Option A is the reverse, with money collected before failures. Options B and C both belong to an ex ante system that charges premiums and builds a fund over time."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 528, $official_bank_source${"itemId":"dd2c0867-9b50-56da-a6bb-e6024e296b44","questionId":"03f33f78-a02e-5c79-8c1c-257e417c1caf","sourceKey":"bank:FIN216:FND-003","payload":{"prompt":"In the country of Zamora there is no standing deposit insurance fund. When Prime Bank failed, the government paid insured depositors and then imposed a special levy on the remaining banks to recover the money. Zamora's scheme is best described as:","options":["Funded by a risk-based premium","Funded by a flat-rate premium","Ex ante funded","Ex post funded"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Paying first and collecting from the surviving banks afterwards is the mark of ex post funding. Option C would require a fund built up in advance, which Zamora does not have. Options A and B are ways of pricing regular premiums in an ex ante fund, and no regular premium is charged here."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 529, $official_bank_source${"itemId":"04a98aab-ac63-5ea7-aae5-9fc2c8d1d88b","questionId":"6b70c8b9-093e-5553-aafc-fe7ee9d33b36","sourceKey":"bank:FIN216:FND-004","payload":{"prompt":"Australia's Financial Claims Scheme, set up in 2008, pays depositors with government money when an authorised deposit-taking institution fails and then recovers the cost from the liquidation and, if needed, a levy on the industry. This is an example of:","options":["Ex ante funding","Ex post funding","A pay box funded by premiums","An implicit guarantee with no legal basis"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Because no fund is accumulated beforehand and costs are recovered after the event, the Australian scheme is funded ex post. Option A is wrong because there is no pre-built fund from premiums, which also rules out option C. Option D is wrong because the scheme is set out in law, so it is explicit, not implicit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 530, $official_bank_source${"itemId":"67cd0bc2-5ce3-5592-b909-425c9a0e8283","questionId":"c9b7e31d-a09b-5950-811d-7d44f1d634d8","sourceKey":"bank:FIN216:FND-005","payload":{"prompt":"Which of the following is a weakness of ex post funding of deposit insurance?","options":["Banks pay premiums even in years when no bank fails","The failed bank itself never contributes to the cost of its own failure","Money collected in advance lies in a fund and has to be invested","The insurer holds a ready pool of cash when a bank fails"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Under ex post funding the levy is collected only after a failure, so the bank that failed escapes paying and the surviving, often healthier, banks carry the cost. Options A and C are features of ex ante funding, not ex post. Option D is actually a strength of ex ante funding."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 531, $official_bank_source${"itemId":"d2af2f68-06d5-5d11-8d25-bbfe2d7fd327","questionId":"7e802fe1-7dab-5b49-aa61-6c51968357c6","sourceKey":"bank:FIN216:FND-006","payload":{"prompt":"Which of the following is the main advantage of ex ante funding of a deposit insurance scheme?","options":["Banks pay nothing at all until a failure actually occurs","Money is already available to reimburse depositors promptly when a bank fails","Surviving banks bear the whole cost after each failure","The insurer never has to manage or invest any funds"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"With ex ante funding the fund exists before the failure, so the insurer can pay insured depositors quickly and boost public confidence. Options A and D describe ex post funding, where nothing is collected or invested in advance. Option C is a drawback of ex post funding, not an advantage of ex ante."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 532, $official_bank_source${"itemId":"0dd63fb9-2e64-5376-adf1-a2076493c05a","questionId":"21060cc1-0ccd-50ed-93d4-de488fa5b5ef","sourceKey":"bank:FIN216:FND-007","payload":{"prompt":"A levy charged on surviving banks during a banking crisis, exactly when they are under the greatest strain, can deepen the crisis. Because of this, ex post funding is described as:","options":["Counter-cyclical","Cross-border","Risk-adjusted","Pro-cyclical"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Pro-cyclical means a measure moves with the cycle and makes a downturn worse, which is what happens when weak banks must pay large levies in a crisis. Option A, counter-cyclical, describes ex ante funding, where money is gathered in good times and used in bad times. Options B and C are unrelated ideas about premium pricing and international cooperation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 533, $official_bank_source${"itemId":"e1e2164d-3c96-5b12-9ede-6f9356fc23bf","questionId":"174d2c68-d904-5f58-839c-fe899e8b66bb","sourceKey":"bank:FIN216:FND-008","payload":{"prompt":"Under the 2014 IADI Core Principles, which funding arrangement is recommended for a deposit insurer?","options":["Ex post funding only, levied after each failure","Voluntary donations from the largest banks","Annual appropriations from the national budget","Ex ante funding built up towards a target fund size"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"IADI's 2014 funding principle (Core Principle 9) calls for ex ante funding with a target fund size, so money is ready before failures occur. Option A is wrong because relying only on levies after each failure leaves no money ready when a bank fails. Options B and C are not the regular, member-funded arrangement IADI recommends."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 534, $official_bank_source${"itemId":"468217f7-c801-56f1-80f2-150bc157f8ff","questionId":"d00b800c-fd66-5e92-b746-4978fa821b81","sourceKey":"bank:FIN216:FND-009","payload":{"prompt":"Under the 2014 IADI Core Principles, the principle titled 'Sources and uses of funds' is Core Principle:","options":["8","9","14","10"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Core Principle 9 of the 2014 set deals with how a deposit insurer is funded and how it may use its funds. Option A, Core Principle 8, is about coverage, option D, Core Principle 10, is about public awareness, and option C, Core Principle 14, covers failure resolution."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 535, $official_bank_source${"itemId":"8feef880-ad69-58fb-8f3d-25cfabc93902","questionId":"555f79fa-c489-5b3e-acd5-c793cc1dd907","sourceKey":"bank:FIN216:FND-010","payload":{"prompt":"Under the 2014 IADI Core Principles, which statement about a deposit insurer's emergency or back-up funding is correct?","options":["Borrowing in the market should be the insurer's only back-up","Emergency funding should be arranged only after a failure occurs","Emergency funding should be pre-arranged, for example with the government or the central bank","A deposit insurer should never be allowed to borrow"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"IADI wants emergency liquidity lined up in advance from the government, the central bank or market borrowing, so the insurer is not caught short in a crisis. Option A is wrong because market borrowing should not be the sole back-up. Option B defeats the purpose of pre-arranged funding, and option D contradicts the principle."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 536, $official_bank_source${"itemId":"cdd2622e-8c7d-5086-b3b3-5cf583be0093","questionId":"66e0551e-a641-5953-a759-1048386d2202","sourceKey":"bank:FIN216:FND-011","payload":{"prompt":"The NDIC builds up its deposit insurance funds from premiums collected every year from insured institutions, whether or not any bank fails in that year. This means the NDIC's deposit insurance is funded:","options":["Ex ante","Ex post","Implicitly","Through government subvention"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"Collecting premiums every year to build a standing fund before failures happen is ex ante funding. Option B would mean raising money only after a failure. Option D is wrong because the NDIC does not depend on government subvention, and option C describes an informal scheme with no fund at all."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 537, $official_bank_source${"itemId":"cfa02d35-f003-5d14-9e2e-9a2505c201fd","questionId":"ac256b48-ca62-5d23-8424-84d705a451d6","sourceKey":"bank:FIN216:FND-012","payload":{"prompt":"Which of the following is NOT a source of funds for the NDIC?","options":["Recoveries from the assets of failed banks","Income from investing its funds in government securities","Premiums paid by insured institutions","Annual government subvention for its operations"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"The NDIC is self-financing and does not receive government subvention for its operations. Options A, B and C are genuine inflows: premiums build the deposit insurance funds, investment income pays for operations, and recoveries come back to the NDIC after it pays depositors of failed banks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 538, $official_bank_source${"itemId":"5b8ea22e-fcc6-5a6e-af3f-8f482a54f414","questionId":"66b40b36-b150-5fba-bf1c-29667d477091","sourceKey":"bank:FIN216:FND-013","payload":{"prompt":"Which of the following is a genuine source of income for the NDIC?","options":["Income earned from investing its funds in Federal Government securities","An annual allocation from the federal budget","Premiums paid directly by individual depositors","A charge on every customer's ATM withdrawal"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"The NDIC invests its funds in government securities and uses the income to run the Corporation. Option B is wrong because the NDIC gets no budget subvention, and option C is wrong because premiums are paid by the insured banks, not by depositors. Option D is invented and has no basis in NDIC law."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 539, $official_bank_source${"itemId":"022d015c-eaa1-5b12-94f7-e0bff544572f","questionId":"d95aa896-59c4-5bcb-9ef9-3ba4a1a30d78","sourceKey":"bank:FIN216:FND-014","payload":{"prompt":"The initial take-off capital of the NDIC was contributed by:","options":["The Central Bank of Nigeria (60%) and the Federal Ministry of Finance (40%)","The Central Bank of Nigeria (50%) and the insured banks (50%)","The Central Bank of Nigeria alone (100%)","The Central Bank of Nigeria (40%) and the Federal Ministry of Finance (60%)"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"The NDIC is publicly owned, with its capital provided 60 percent by the CBN and 40 percent by the Federal Ministry of Finance. Option D reverses the shares, and option C leaves out the Ministry of Finance. Option B is wrong because the insured banks pay premiums but do not own the NDIC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 540, $official_bank_source${"itemId":"922ce3cc-0ace-559e-908c-a9a9a74cc212","questionId":"e49f7a24-29c5-5c9b-b7e0-09847f8e7e70","sourceKey":"bank:FIN216:FND-015","payload":{"prompt":"Under the NDIC Act 2023, the authorised capital of the NDIC is:","options":["N50 billion","N500 billion","N5 billion","N2 trillion"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"Section 16 of the NDIC Act 2023 fixes the NDIC's authorised capital at N50 billion, paid up by the CBN and the Federal Ministry of Finance in a 60:40 ratio. Option B, N500 billion, is ten times that figure, the level that matters for the General Reserve Fund. Option D is close to the combined balance of the deposit insurance funds in 2024, not the capital."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 541, $official_bank_source${"itemId":"975cd0b0-542d-5f92-95f1-74d501c24db8","questionId":"aeea8578-2b13-5d8e-bd65-6d1183929b28","sourceKey":"bank:FIN216:FND-016","payload":{"prompt":"Suppose the NDIC's paid-up capital is N20 billion, shared between its two owners in the proportion fixed by the NDIC Act 2023. How much of this would the Central Bank of Nigeria have paid?","options":["N8 billion","N12 billion","N20 billion","N10 billion"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"The CBN holds 60 percent of the NDIC's paid-up capital, so 60% x N20 billion = N12 billion. Option A, N8 billion, is the 40 percent share of the Federal Ministry of Finance. Option D assumes an equal split, and option C wrongly gives the whole capital to the CBN."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 542, $official_bank_source${"itemId":"476f8292-2a22-5ee9-9fa2-2dd5c884458e","questionId":"bdca5203-ca7b-54b6-9d8d-eb18d0a7cb13","sourceKey":"bank:FIN216:FND-017","payload":{"prompt":"The NDIC is described as 'self-financing' because:","options":["Its staff salaries are paid from the Deposit Insurance Fund","Depositors pay a fee each time they open an account","It does not receive government subvention to run its operations","It finances its operations by borrowing from the CBN every year"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"Self-financing means the NDIC meets its running costs from its own income, mainly from investing its funds, rather than from government grants. Option D is wrong because borrowing is not its regular way of paying for operations. Option A is wrong because the deposit insurance funds cannot be used for running costs, and option B has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 543, $official_bank_source${"itemId":"f2810ee3-c4b0-5704-886e-56ab9d3c89f6","questionId":"f2dd7f38-f4de-5c4f-a22f-bfb06d31ef3d","sourceKey":"bank:FIN216:FND-018","payload":{"prompt":"Under the NDIC Act 2023, the salaries and allowances of NDIC staff are charged to the:","options":["Deposit Insurance Fund","Operating Fund","General Reserve Fund","Payment Service Banks Insurance Fund"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Section 18 of the 2023 Act sets up an Operating Fund, and staff pay, Board allowances and administrative costs are charged to it. Options A and D are deposit insurance funds held for depositors and cannot be used for running costs. Option C holds year-end surpluses to support depositor payments."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 544, $official_bank_source${"itemId":"7846a032-8831-5726-8e8c-e5ef5ba401f3","questionId":"4145a91a-ee0d-5819-8097-1b77a0a8eeea","sourceKey":"bank:FIN216:FND-019","payload":{"prompt":"Under the NDIC Act 2023, which of the following is NOT credited to the NDIC's Operating Fund?","options":["Money borrowed with the approval of the Board","Investment income other than income of the deposit insurance funds","The Corporation's capital","Premiums assessed on deposit money banks"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Premiums from deposit money banks go into the Deposit Insurance Fund, which is held for depositors, not into the Operating Fund. Options A, B and C are all listed in section 18 as amounts credited to the Operating Fund."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 545, $official_bank_source${"itemId":"2e926a90-ab6f-5842-bfbf-31dde3346dff","questionId":"f0ef4b00-3f9f-5637-aa8a-9eddb850943b","sourceKey":"bank:FIN216:FND-020","payload":{"prompt":"The NDIC has long been barred by law from paying its operating expenses out of the Deposit Insurance Fund. From what is it expected to meet these expenses?","options":["Fresh premiums charged on depositors","Fines imposed on failed banks' customers","Income generated by investing its funds","Grants from the Federal Ministry of Finance"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"Operating costs are paid from the income earned by investing the NDIC's funds, while the premium pool itself is kept for depositors. Option A is wrong because depositors do not pay premiums. Option D is wrong because the NDIC receives no government subvention, and option B is invented."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 546, $official_bank_source${"itemId":"0c771c7b-bb1f-5884-8368-cdfcb0e19497","questionId":"0cf9d7c3-8d02-5449-bdc0-c25618e1a5a2","sourceKey":"bank:FIN216:FND-021","payload":{"prompt":"The NDIC Act 2023 specifically names which class of securities for investing NDIC funds not immediately required?","options":["Shares of listed deposit money banks","Federal Government securities","Foreign currency deposits in insured banks","Commercial papers issued by microfinance banks"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Section 20 allows the NDIC to invest idle funds in Federal Government securities, or other securities the Board approves. Government securities are chosen because they are safe and easy to sell. Options A, C and D would expose the fund to the very banks it insures, which would defeat its purpose."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 547, $official_bank_source${"itemId":"5b709ed0-f041-5b47-b2f1-6b5b9e117783","questionId":"5f06117f-3365-5065-b2ea-76c6d996aa73","sourceKey":"bank:FIN216:FND-022","payload":{"prompt":"Why has the NDIC's revenue base been described as vulnerable?","options":["Insured banks often refuse to pay their premiums","Its funds are restricted to treasury instruments whose yields swing with economic conditions","Depositors' premium contributions are too small","Its government subvention is irregular and often delayed"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Because operating costs are paid from investment income, and the fund may only be invested in treasury instruments, falling or volatile yields directly shrink the NDIC's income. Option D is wrong because the NDIC receives no subvention at all. Option C is wrong because depositors do not pay premiums, and option A is not the reason given."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 548, $official_bank_source${"itemId":"f368dace-8861-5414-bff7-3ce18d5dc259","questionId":"3eb98884-abfa-5fcc-bc55-a5c80e89903f","sourceKey":"bank:FIN216:FND-023","payload":{"prompt":"The main reason a deposit insurer invests its fund in government securities rather than in high-yield assets is to ensure:","options":["Control over the insured banks' boards","Support for share prices on the stock exchange","Safety and liquidity, so the money is available when banks fail","The highest possible return in every year"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"A deposit insurance fund must be there, in cash, when a bank fails, so safety and liquidity come before yield. Option D is wrong because chasing high returns adds risk to money held for depositors. Options A and B are not the purpose of investing the fund."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 549, $official_bank_source${"itemId":"9a6e0204-762a-56a7-bbf8-6e0574d07b25","questionId":"671ac1d8-ace0-5ec4-97d0-543bd3568233","sourceKey":"bank:FIN216:FND-025","payload":{"prompt":"How many separate deposit insurance funds does section 17 of the NDIC Act 2023 establish?","options":["Five","Six","Four","Three"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"The 2023 Act sets up five funds: the DIF, NIDIF, SIIF, NISIIF and PSBIF, each for a different category of insured institution. The Board may create more, but the Act itself establishes five. Options B, C and D miscount them."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 550, $official_bank_source${"itemId":"9247bf4c-0b24-5095-8a2e-12f4fb3d5ef7","questionId":"86279a4d-cd4e-50cf-968f-9c0b6423bd93","sourceKey":"bank:FIN216:FND-026","payload":{"prompt":"Under the NDIC Act 2023, the Deposit Insurance Fund (DIF) is the fund for:","options":["Deposit money banks and mobile money operators","Non-interest deposit money banks only","Microfinance banks and primary mortgage banks","Payment service banks only"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"Section 17 says the DIF covers deposit money banks and mobile money operators. Option C describes the SIIF, option D the PSBIF, and option B the NIDIF."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 551, $official_bank_source${"itemId":"0da26d42-e626-5e61-92c3-c39bb6f744b6","questionId":"5f370992-161a-5549-a664-1a5dec62f197","sourceKey":"bank:FIN216:FND-027","payload":{"prompt":"Swiftpay Payment Service Bank pays its annual deposit insurance premium to the NDIC in 2025. Under the NDIC Act 2023, the premium is credited to the:","options":["Special Insured Institutions Fund (SIIF)","Non-Interest Deposit Insurance Fund (NIDIF)","Deposit Insurance Fund (DIF)","Payment Service Banks Insurance Fund (PSBIF)"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Each fund receives the premiums of its own category, and payment service banks have a separate fund, the PSBIF. Option C is for deposit money banks and mobile money operators, option A is for microfinance and primary mortgage banks, and option B is for non-interest deposit money banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 552, $official_bank_source${"itemId":"df06af9e-cdc6-575a-9b54-1e1ff62d6911","questionId":"d8f88fde-0f1f-5b23-ba2e-f3f6f6bfc1ba","sourceKey":"bank:FIN216:FND-028","payload":{"prompt":"Under the NDIC Act 2023, the premiums paid by a conventional microfinance bank in Ibadan are credited to the:","options":["NIDIF","PSBIF","DIF","SIIF"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Microfinance banks and primary mortgage banks are 'special insured institutions', and their conventional members pay into the SIIF. Option C is for deposit money banks and mobile money operators, option A is for non-interest deposit money banks, and option B is for payment service banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 553, $official_bank_source${"itemId":"23f6e18b-9c5f-5353-ba14-aa01fe0b5bc6","questionId":"f15efb35-8d87-5f6a-a5d3-381ec08de767","sourceKey":"bank:FIN216:FND-029","payload":{"prompt":"Under the NDIC Act 2023, the premiums of a non-interest (Islamic) deposit money bank are credited to the:","options":["Deposit Insurance Fund (DIF)","Non-Interest Special Insured Institutions Fund (NISIIF)","Non-Interest Deposit Insurance Fund (NIDIF)","Payment Service Banks Insurance Fund (PSBIF)"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"The 2023 Act keeps non-interest deposit money banks in their own fund, the NIDIF, separate from conventional banks. Option A is for conventional deposit money banks and mobile money operators. Option B is for non-interest microfinance and mortgage institutions, and option D is for payment service banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 554, $official_bank_source${"itemId":"6441b8bb-cee9-51d8-af1c-c53338ea60db","questionId":"47038771-76d4-5997-a91a-afbf73652777","sourceKey":"bank:FIN216:FND-030","payload":{"prompt":"Which of the following is NOT one of the deposit insurance funds established under section 17 of the NDIC Act 2023?","options":["Non-Interest Deposit Insurance Fund","Deposit Insurance Fund","Operating Fund","Payment Service Banks Insurance Fund"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"The Operating Fund is created separately under section 18 to pay the NDIC's running costs, so it is not a deposit insurance fund. Options A, B and D are among the five insurance funds in section 17, along with the SIIF and NISIIF."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 555, $official_bank_source${"itemId":"d1e33a04-2ad8-5faa-831c-a777366b97e2","questionId":"ea17782b-7ad1-5843-a020-7189ef1234e5","sourceKey":"bank:FIN216:FND-031","payload":{"prompt":"Under the NDIC Act 2023, the NDIC manages each deposit insurance fund:","options":["On behalf of its shareholders, the CBN and the Ministry of Finance","As part of the Federation's Consolidated Revenue Fund","For the benefit of the insured banks' shareholders","In trust for depositors of the corresponding category of insured institutions"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"The 2023 Act says each fund is held in trust for the depositors of its own category, which stresses that the money belongs to the protection of depositors. Option A is wrong because the owners' stake is the capital, not the insurance funds. Options B and C would put the money outside depositor protection."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 556, $official_bank_source${"itemId":"406f3374-0874-54b5-8dff-cbdc8e892131","questionId":"ce6b02ca-2193-53ca-b096-7ffb3c356276","sourceKey":"bank:FIN216:FND-032","payload":{"prompt":"Under the NDIC Act 2023, each insurance fund is held for depositors of its own category of institution. A key effect of this arrangement is that:","options":["Mobile money subscribers lose cover under pass-through insurance","Deposit money bank premiums are used to pay the NDIC's staff","Premiums paid by microfinance banks are kept to protect microfinance depositors rather than mixed with deposit money bank premiums","All insured institutions pay the same premium rate"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"Separate funds held in trust for each category keep each group's premiums for its own depositors, which limits cross-subsidy between, for example, microfinance banks and deposit money banks. Option D is wrong because rates differ by category and by risk. Option B is wrong because staff costs come from the Operating Fund, and option A is wrong because mobile money operators sit in the DIF."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 557, $official_bank_source${"itemId":"5432a3cb-90dd-5e95-8cf9-32ba24f7abe0","questionId":"b98b3f69-d09a-5ae9-be61-0516ca64f0c6","sourceKey":"bank:FIN216:FND-033","payload":{"prompt":"Under the NDIC Act 2023, which of the following is NOT a permitted use of a deposit insurance fund?","options":["Refunding excess premiums paid by insured institutions","Paying insured depositors of a failed insured institution","Paying salaries and allowances of NDIC staff","Giving financial assistance to a failing insured institution, within a set cap"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"Staff pay is charged to the Operating Fund, not to the insurance funds. Options A, B and D are the uses allowed by section 17: paying deposit insurance obligations, assisting institutions within a cap, and refunding excess premiums or special contributions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 558, $official_bank_source${"itemId":"eb4acc21-d59c-53e7-9434-642bbcb2d83f","questionId":"5d0bd8aa-8da7-5a22-a790-424dafcc6f7f","sourceKey":"bank:FIN216:FND-034","payload":{"prompt":"Under the NDIC Act 2023, unless the Board prescribes otherwise, financial assistance to insured institutions from a deposit insurance fund is capped at what percentage of that fund's balance?","options":["10 percent","50 percent","5 percent","25 percent"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"Section 17(7)(b) limits assistance to 10 percent of the fund's balance unless the Board sets a different percentage. The cap protects money that is meant first of all for paying insured depositors. Options B, C and D are not the figure in the Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 559, $official_bank_source${"itemId":"350fc63d-4ab3-5a91-84e8-cbf29dbcaeb4","questionId":"3de9dbe6-db21-59c7-ac62-02ffd53bd0ef","sourceKey":"bank:FIN216:FND-035","payload":{"prompt":"Under the NDIC Act 2023, if the Deposit Insurance Fund stands at N1.8 trillion and the Board has not prescribed a different limit, what is the most the NDIC may give a failing deposit money bank as assistance from the fund?","options":["N180 billion","N1.8 billion","N18 billion","N450 billion"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"The default cap is 10 percent of the fund balance, so 10% x N1.8 trillion = N180 billion. Option C uses 1 percent instead of 10 percent. Option D uses 25 percent, and option B slips by two decimal places."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 560, $official_bank_source${"itemId":"89e14856-7fd8-5bff-ae2e-726caec7395e","questionId":"e9d3697d-340f-5095-b963-2892d89f25c1","sourceKey":"bank:FIN216:FND-036","payload":{"prompt":"Under the NDIC Act 2023, which of the following is NOT credited to a deposit insurance fund?","options":["Money borrowed by the NDIC with the Board's approval","Special contributions required from insured institutions","The share of investment income the Board needs to keep the fund at its target","Premiums assessed on institutions in that category"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"Borrowed money goes into the Operating Fund under section 18. Options B, C and D are all credited to the insurance funds by section 17, together with any share of general reserves the Board allocates."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 561, $official_bank_source${"itemId":"4b5648ae-69aa-520b-8c09-9b8ba38a6024","questionId":"fa2e0034-ddf6-58fd-8274-3b6eb1054adc","sourceKey":"bank:FIN216:FND-037","payload":{"prompt":"Under the NDIC Act 2023, who sets the minimum target size of each deposit insurance fund and the timeframe for reaching it?","options":["The International Association of Deposit Insurers","The Governor of the CBN","The National Assembly","The Board of the NDIC"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Section 17 leaves the minimum target fund size, its timeframe and its periodic review to the NDIC Board. Option C passes laws but does not set the target. Option B heads the regulator, and option A issues international guidance but does not set targets for member insurers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 562, $official_bank_source${"itemId":"1563fce2-9b13-523e-a0eb-84e12074f08b","questionId":"c9405347-87bd-5b9f-8059-70ddb49d7f41","sourceKey":"bank:FIN216:FND-038","payload":{"prompt":"A deposit insurer's target fund ratio expresses the size of its fund as a percentage of:","options":["Its own authorised capital","The country's gross domestic product","Total (or insured) deposits of the institutions it covers","The total loans of insured banks"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"A target fund ratio measures the fund against the deposits it must protect; under the NDIC Act 2023 the target is tied to total deposits of each category. Option A is the basis for the General Reserve Fund rule, not the fund target. Options B and D are not the measure of what the fund may have to pay."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 563, $official_bank_source${"itemId":"9824d60b-f114-55ca-8490-4d25e46aabd2","questionId":"b6819665-263e-54cd-ae47-606e6d012b40","sourceKey":"bank:FIN216:FND-039","payload":{"prompt":"Suppose the NDIC Board set a minimum target of 5 percent of total deposits for a category whose total deposits are N40 trillion, and that category's fund stood at N1.6 trillion. By how much would the fund fall short of its target?","options":["N2 trillion","N1.6 trillion","N400 billion","N4 trillion"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"The target is 5% x N40 trillion = N2 trillion, and N2 trillion - N1.6 trillion = N400 billion still to be built up. Option A is the target itself, not the shortfall. Option B is the existing balance, and option D uses 10 percent instead of 5 percent."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 564, $official_bank_source${"itemId":"3c29420f-a4d9-5f5d-8b71-581cb6a10125","questionId":"00cee9a7-e5e5-57ed-a812-2e23e350f976","sourceKey":"bank:FIN216:FND-040","payload":{"prompt":"The European Union's Single Resolution Fund, built up between 2016 and 2023, had a target size of at least what share of covered deposits in the Banking Union?","options":["10 percent","1 percent","0.5 percent","5 percent"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"The Single Resolution Fund had a target of at least 1 percent of covered deposits, about EUR 80 billion by end-2023. It is a good example of a fund built up ex ante towards a target. Options A, C and D are not the target that was set."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 565, $official_bank_source${"itemId":"c68bd204-d179-50c2-9d9a-0747e6927a91","questionId":"7b826a7c-cb19-5ead-8333-220350590941","sourceKey":"bank:FIN216:FND-041","payload":{"prompt":"In May 2024, the NDIC announced that the combined balance of its deposit insurance funds had exceeded:","options":["N2 trillion","N50 billion","N200 billion","N20 trillion"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"In May 2024 the NDIC's Managing Director said the deposit insurance funds together exceeded N2 trillion. Option C is ten times too small and option D ten times too large. Option B, N50 billion, is the NDIC's authorised capital under the 2023 Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 566, $official_bank_source${"itemId":"2e58cec2-7bbc-55bd-8567-819527d1ad12","questionId":"f3ba0e8d-04e7-5119-9b0d-d720236c2f23","sourceKey":"bank:FIN216:FND-042","payload":{"prompt":"Under the NDIC Act 2023, the General Reserve Fund receives the NDIC's year-end surplus mainly so that it can:","options":["Pay the annual salaries of NDIC staff","Fund the CBN's lender of last resort loans","Buy shares in distressed deposit money banks","Support payments to insured depositors when a deposit insurance fund falls short"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"The General Reserve Fund builds a cushion from surpluses that can be drawn on to maintain the insurance funds or cover a shortfall in paying depositors. Option A belongs to the Operating Fund. Options B and C are not functions of the reserve."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 567, $official_bank_source${"itemId":"a9423b27-b84b-535d-9ca2-33999256a59e","questionId":"e0ad5373-6a20-519a-8a24-89800a33e707","sourceKey":"bank:FIN216:FND-043","payload":{"prompt":"Under the NDIC Act 2023, the special rule for sharing the NDIC's net operating surplus applies once the General Reserve Fund is more than ten times the authorised capital. With an authorised capital of N50 billion, this threshold is:","options":["N5 billion","N5 trillion","N50 billion","N500 billion"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Ten times the N50 billion authorised capital is 10 x N50 billion = N500 billion. Option C is the capital itself, option A divides by ten instead of multiplying, and option B multiplies by one hundred."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 568, $official_bank_source${"itemId":"94a85a2c-22d1-5b50-98f5-9a7d9c15a704","questionId":"5b059b72-619b-513d-828c-9e80208bb90c","sourceKey":"bank:FIN216:FND-044","payload":{"prompt":"Under the NDIC Act 2023, once the General Reserve Fund exceeds ten times the authorised capital, what share of the net operating surplus must go to the General Reserve Fund?","options":["50 percent","75 percent","25 percent","100 percent"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Section 19(2) sends 75 percent of the net operating surplus to the reserve; the remaining 25 percent is split between premium reduction and the shareholders. Option C is the balance that is shared, not the reserve's portion. Options A and D do not match the Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 569, $official_bank_source${"itemId":"ccbe4cb0-cde6-5021-bba2-a044d6e4ab14","questionId":"c2c860d8-95bc-5009-97c5-c0e5e14da655","sourceKey":"bank:FIN216:FND-045","payload":{"prompt":"Under the NDIC Act 2023, assume the General Reserve Fund is already above ten times the authorised capital and the NDIC makes a net operating surplus of N60 billion. How much goes to the shareholders?","options":["N7.5 billion","N30 billion","N45 billion","N15 billion"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"75 percent (N45 billion) goes to the reserve, and the remaining 25 percent (N15 billion) is split in half, so N7.5 billion may go to premium reduction and N7.5 billion to the shareholders. Option D gives the shareholders the whole 25 percent. Option C is the reserve's share, and option B is half of the entire surplus."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 570, $official_bank_source${"itemId":"4272cca6-0001-5969-b62d-e87464f8a9aa","questionId":"cb5a18a1-1627-52b8-b64d-0ffc14d15222","sourceKey":"bank:FIN216:FND-046","payload":{"prompt":"Under the NDIC Act 2023, the General Reserve Fund already exceeds ten times the authorised capital and the year's net operating surplus is N24 billion. How much must go to the General Reserve Fund?","options":["N6 billion","N12 billion","N18 billion","N24 billion"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"When the reserve is above the threshold, 75 percent of the surplus goes to it: 75% x N24 billion = N18 billion. Option A is the 25 percent balance that is shared out. Option B assumes a 50:50 split, and option D sends the whole surplus to the reserve."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 571, $official_bank_source${"itemId":"b7512a82-0062-5990-baaf-55b2e32d9382","questionId":"669d8932-eecc-5be3-8336-7af6da05bd51","sourceKey":"bank:FIN216:FND-047","payload":{"prompt":"Under the NDIC Act 2023, part of the NDIC's surplus may be used to reduce the annual premiums of insured institutions. This shows that:","options":["Depositors receive a cash refund from the NDIC each year","Premiums are fixed by the Act and can never change","The Federal Government pays part of every bank's premium","A well-funded insurer can pass some of its surplus back to the banks that pay premiums"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Once the reserve is large enough, half of the 25 percent surplus balance may go to lowering premiums, which eases the burden on the institutions that fund the scheme. Option B is wrong because rates can be changed and differ by risk. Option A is wrong because depositors do not pay premiums, and option C has no basis."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 572, $official_bank_source${"itemId":"82a25c2c-f6ca-5f2d-aaf1-c80c32861d30","questionId":"7d231834-4fca-5a8a-a3da-817ab9c41f7c","sourceKey":"bank:FIN216:FND-048","payload":{"prompt":"Under the 1988 Decree and the NDIC Act 2006, the NDIC was specifically empowered to borrow from:","options":["Insured depositors of failed banks","The International Monetary Fund only","The Central Bank of Nigeria","The Nigerian Exchange"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"Both the 1988 Decree and the 2006 Act let the NDIC borrow from the CBN, and from other lenders with Board approval, if its funds ran short. Option B is not the named lender. Option A would make no sense because depositors are the people the NDIC protects, and option D is a stock exchange, not a lender."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 573, $official_bank_source${"itemId":"34a1293d-ee4d-53a0-90e6-1461c7ad2e7f","questionId":"4b34ff75-806d-55ad-b8b8-14c7171e6f9a","sourceKey":"bank:FIN216:FND-049","payload":{"prompt":"Under the NDIC Act 2023, money the NDIC borrows with the approval of its Board is credited to the:","options":["Operating Fund","General Reserve Fund","Special Insured Institutions Fund","Deposit Insurance Fund"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"Section 18 lists money borrowed from any lender with Board approval among the items credited to the Operating Fund, and repaying it with interest is charged to the same fund. Options C and D receive premiums, special contributions and allocated income. Option B receives year-end surpluses."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 574, $official_bank_source${"itemId":"921f43ec-f86d-5747-a046-d8a9045778dc","questionId":"e5101037-94aa-5994-bb36-b10e4853b548","sourceKey":"bank:FIN216:FND-051","payload":{"prompt":"Under the 1988 Decree the premium rate was 15/16 of 1 percent. Expressed in basis points, this is:","options":["93.75 basis points","15.16 basis points","9.375 basis points","937.5 basis points"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"One percent is 100 basis points, so 15/16 x 100 = 93.75 basis points. Option C is ten times too small, option D ten times too large, and option B simply writes the fraction as a number."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 575, $official_bank_source${"itemId":"448d3d93-b31b-58ed-b73e-51380252237b","questionId":"9781544d-97da-551d-b75b-de5f93f00ca4","sourceKey":"bank:FIN216:FND-052","payload":{"prompt":"In 1990, Unity Commercial Bank had total deposit liabilities of N600 million. Under the flat-rate premium of the 1988 Decree, what annual premium would it pay the NDIC?","options":["N5.625 million","N562,500","N56.25 million","N3 million"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"Premium = 0.9375% x N600 million = N5,625,000, or N5.625 million. Option C uses 9.375 percent, option B uses 0.09375 percent, and option D wrongly uses 0.5 percent."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 576, $official_bank_source${"itemId":"1ca8afae-c38e-52aa-8c0c-263527a6f16d","questionId":"d7d83c07-3e28-50c4-9d72-6d2a50859cec","sourceKey":"bank:FIN216:FND-053","payload":{"prompt":"Under the NDIC Act 2006, the annual premium of an insured institution was assessed on its:","options":["Total assets as at 31 December of the current year","Total deposit liabilities as at 31 December of the preceding year","Insured deposits only, on the date its licence is revoked","Paid-up share capital at the date of assessment"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"The 2006 Act based the premium on total deposit liabilities as shown at 31 December of the previous year. Option A confuses the premium base with the total-asset levy used for the bank resolution cost fund. Options C and D are not the assessment base in the Act."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 577, $official_bank_source${"itemId":"1f020bda-a341-591f-8435-4b1ae418352f","questionId":"e1a378a3-9c08-55f3-96ab-897f37d8c063","sourceKey":"bank:FIN216:FND-054","payload":{"prompt":"Under the NDIC Act 2006, the maximum premium rate for licensed banks was 15/16 of 1 percent. What was the maximum rate for other deposit-taking institutions such as microfinance banks?","options":["1/16 of 1 percent (0.0625 percent)","8 percent","8/16 of 1 percent (0.5 percent)","15/16 of 1 percent (0.9375 percent)"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"The 2006 Act set a lower ceiling, 8/16 of 1 percent or 0.5 percent, for other deposit-taking institutions. Option D is the ceiling for licensed banks. Option A is not in the Act, and option B misreads the fraction as 8 percent."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 578, $official_bank_source${"itemId":"ad53b9f7-14c7-5d7b-beec-c31383a732a8","questionId":"d08f26e6-f2e0-5afb-bf46-c2b7d078c3ec","sourceKey":"bank:FIN216:FND-055","payload":{"prompt":"Under the NDIC Act 2006, a microfinance bank with total deposit liabilities of N2.4 billion is charged the maximum premium rate allowed for other deposit-taking institutions. What is its annual premium?","options":["N22.5 million","N1.2 million","N12 million","N120 million"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"The maximum for other deposit-taking institutions was 8/16 of 1 percent, or 0.5 percent, so 0.5% x N2.4 billion = N12 million. Option A wrongly applies the bank ceiling of 0.9375 percent. Options B and D are decimal slips of ten times too much and ten times too little."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 579, $official_bank_source${"itemId":"03bc5257-b302-5063-86cc-1181094bf326","questionId":"020202ed-431f-5a50-a1ea-602216d50f47","sourceKey":"bank:FIN216:FND-056","payload":{"prompt":"What is the main weakness of a flat-rate deposit insurance premium?","options":["It makes premium income impossible to forecast","It is too complicated for banks to calculate","Sound banks end up subsidising risky banks, which encourages moral hazard","It charges the riskiest banks the highest rates"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"A flat rate charges every bank the same percentage whatever its risk, so careful banks pay for the extra risk taken by reckless ones, and risk-taking goes unpenalised. Option B is wrong because a flat rate is the simplest system. Option D describes a risk-based system, and option A is not the main problem."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 580, $official_bank_source${"itemId":"8d83cc77-85e2-5e6e-9bf6-f98094873bbb","questionId":"55a5f9f6-d7c8-5967-a65f-93ea47e4bcec","sourceKey":"bank:FIN216:FND-057","payload":{"prompt":"Bank A is well run and Bank B takes heavy risks, but both have N100 billion of deposits and both pay exactly the same deposit insurance premium. The premium system in use is:","options":["A risk-based premium system","An ex post levy system","A differential premium assessment system","A flat-rate premium system"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"Charging every bank the same rate on its deposits, regardless of its risk, is a flat-rate system. Options A and C are the same idea, a risk-based approach that would charge Bank B more. Option B is wrong because premiums are being charged in advance, not levied after a failure."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 581, $official_bank_source${"itemId":"1b5f4753-2dcb-528a-82fb-af07fc7fa765","questionId":"502d0633-84de-510e-9cf1-0db78f8aa819","sourceKey":"bank:FIN216:FND-058","payload":{"prompt":"In NDIC premium assessment, DPAS stands for:","options":["Deposit Premium Adjustment Structure","Differential Payout Assessment System","Differential Premium Assessment System","Deposit Protection Assessment Scheme"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"DPAS is the Differential Premium Assessment System, under which each bank's premium depends on its risk. Options A, B and D are look-alike expansions that do not exist."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 582, $official_bank_source${"itemId":"02d69398-8bc7-56cb-bc12-79d6d4da4966","questionId":"fcd3ec7f-b27a-5d3f-9ec0-409678ad5a4b","sourceKey":"bank:FIN216:FND-059","payload":{"prompt":"In which year did the NDIC adopt the Differential Premium Assessment System (DPAS) in place of the flat-rate premium?","options":["2008","2015","2006","1989"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"After a framework issued in 2007, the NDIC adopted DPAS in 2008. Option D is when the NDIC started, with a flat rate. Option C is the year of the NDIC Act that allowed risk-reflecting rates, and option B is when the DPAS base rate was cut to 35 basis points."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 583, $official_bank_source${"itemId":"489ccec2-d547-5062-adf6-ba4494257ba3","questionId":"28c70305-c73c-55a6-897b-15bf435f5620","sourceKey":"bank:FIN216:FND-060","payload":{"prompt":"Under the NDIC's Differential Premium Assessment System, a bank's premium rate is made up of:","options":["A base rate plus an add-on that depends on the bank's riskiness","A single flat rate charged to every bank","A rate set by the bank's own board each year","The CBN's monetary policy rate plus a margin"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"DPAS starts with a base rate that all banks pay and adds an extra charge that rises with the bank's risk rating. Option B is the old flat-rate system. Options C and D have nothing to do with how deposit insurance premiums are set."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 584, $official_bank_source${"itemId":"6f00f094-5498-5011-a7df-a4f7ef7be094","questionId":"15e2a22c-2a7f-5d90-8708-e8573dea4dde","sourceKey":"bank:FIN216:FND-061","payload":{"prompt":"When the NDIC's Differential Premium Assessment System began in 2008, the base rate was:","options":["40 basis points (0.40 percent)","50 basis points (0.50 percent)","93.75 basis points (0.9375 percent)","35 basis points (0.35 percent)"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"DPAS started with a base rate of 0.50 percent, or 50 basis points. Option A came after the first cut, and option D after the cut that took effect in January 2015. Option C is the old flat rate under the 1988 Decree."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 585, $official_bank_source${"itemId":"d22850a2-305a-51ef-bc2b-95e307aa9c8e","questionId":"b19d664b-b953-55eb-ac79-346c33d5e92a","sourceKey":"bank:FIN216:FND-062","payload":{"prompt":"Effective January 2015, the NDIC reduced the DPAS base rate for deposit money banks to:","options":["65 basis points","35 basis points","40 basis points","50 basis points"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"The NDIC Board cut the base rate from 40 to 35 basis points with effect from January 2015. Option C was the rate before that cut, and option D was the starting rate in 2008. Option A is the top of the range charged to riskier banks in 2024."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 586, $official_bank_source${"itemId":"a0aea42b-6737-5500-9b9b-8343ee5b8bc7","questionId":"d5eb4840-7715-5311-98de-b2ea57955e1a","sourceKey":"bank:FIN216:FND-063","payload":{"prompt":"As at May 2024, the DPAS premium rates paid by deposit money banks ranged from:","options":["A flat 93.75 basis points for every bank","35 basis points for the soundest banks up to 65 basis points for riskier banks","10 basis points up to 35 basis points","50 basis points up to 100 basis points"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"In 2024 the NDIC said deposit money banks paid a base rate of 35 basis points, rising to as much as 65 basis points for riskier banks. Option A is the 1988 flat rate. Options C and D do not match the published range."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 587, $official_bank_source${"itemId":"6d1e2e50-73c9-5749-93c0-f3eec3362d42","questionId":"4eee8a36-50f2-5253-8593-d34b10ce9458","sourceKey":"bank:FIN216:FND-064","payload":{"prompt":"In 2024 a deposit money bank under DPAS pays the 35 basis point base rate plus a risk add-on of 20 basis points. If its assessable deposits are N3.2 trillion, what is its annual premium?","options":["N11.2 billion","N1.76 billion","N17.6 billion","N176 billion"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"The total rate is 35 + 20 = 55 basis points, or 0.55 percent, and 0.55% x N3.2 trillion = N17.6 billion. Option A charges only the 35 basis point base rate and forgets the add-on. Options B and D are decimal slips."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 588, $official_bank_source${"itemId":"b5598d31-9eeb-57dd-982c-7b3de9652c50","questionId":"1be1497c-f67b-536c-ae5b-d3f291efe153","sourceKey":"bank:FIN216:FND-065","payload":{"prompt":"In 2024, under DPAS rates of 35 to 65 basis points, how much more premium would a deposit money bank at the top of the range pay than one at the bottom, if each had assessable deposits of N1 trillion?","options":["N30 billion","N300 million","N6.5 billion","N3 billion"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"The gap is 65 - 35 = 30 basis points, or 0.30 percent, and 0.30% x N1 trillion = N3 billion. Option C is the full premium of the riskier bank, not the difference. Options A and B are decimal slips."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 589, $official_bank_source${"itemId":"9d97eaf1-b49a-52de-8486-c45f96c541c0","questionId":"15f698cd-c486-5187-8cc5-72e1d927ab6f","sourceKey":"bank:FIN216:FND-066","payload":{"prompt":"When the DPAS base rate fell from 40 to 35 basis points in January 2015, how much would a group of deposit money banks with N12 trillion of assessable deposits save on base-rate premiums each year?","options":["N42 billion","N60 billion","N600 million","N6 billion"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"The cut is 5 basis points, or 0.05 percent, and 0.05% x N12 trillion = N6 billion. Option A is the full premium still payable at 35 basis points, not the saving. Options B and C are decimal slips."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 590, $official_bank_source${"itemId":"b8831262-8f78-57b0-9ead-3ff1f4428d1f","questionId":"fb8be746-510c-5b39-9d09-c920181f1a80","sourceKey":"bank:FIN216:FND-067","payload":{"prompt":"A deposit money bank with assessable deposits of N500 billion compares the 1988 flat premium rate (15/16 of 1 percent) with the 35 basis point DPAS base rate in force from 2015. How much more would it pay a year at the 1988 flat rate?","options":["N29.375 billion","N4.6875 billion","N1.75 billion","N2.9375 billion"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"The difference in rates is 0.9375% - 0.35% = 0.5875%, and 0.5875% x N500 billion = N2.9375 billion. Option B is the whole premium at the flat rate, and option C is the whole premium at 35 basis points. Option A is a decimal slip."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 591, $official_bank_source${"itemId":"170212ba-eccd-55bb-81aa-f3550b826f43","questionId":"2e481cd8-8f4e-56fd-8a5c-c004734219eb","sourceKey":"bank:FIN216:FND-068","payload":{"prompt":"In 2016 a deposit money bank rated in the lowest-risk category paid only the 35 basis point DPAS base rate, and its premium came to N4.2 billion. What were its assessable deposits?","options":["N1.2 trillion","N120 billion","N14.7 billion","N12 trillion"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"Deposits = premium / rate = N4.2 billion / 0.0035 = N1.2 trillion. Options B and D are off by a factor of ten. Option C wrongly multiplies the premium by the rate in basis points instead of dividing."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 592, $official_bank_source${"itemId":"365f3fb3-fb64-5ee6-b088-b971d52683a6","questionId":"8f52a690-5189-5a86-9d78-5d46a68bbca9","sourceKey":"bank:FIN216:FND-069","payload":{"prompt":"Why does IADI encourage differential (risk-based) premiums such as the NDIC's DPAS?","options":["They guarantee that every bank pays exactly the same premium","They make riskier banks pay more and so help reduce moral hazard","They remove the need for any bank supervision","They allow depositors to choose how much premium to pay"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"Risk-based premiums put a price on risk-taking, so banks have a reason to behave prudently, and IADI lists them among tools that reduce moral hazard. Option A describes a flat rate. Option C is wrong because premiums work alongside supervision, and option D is wrong because banks, not depositors, pay premiums."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 593, $official_bank_source${"itemId":"898cae25-623a-5cf2-8f48-4a573b27c446","questionId":"4083a520-a6a2-5478-a3c0-0f499b2df2a5","sourceKey":"bank:FIN216:FND-070","payload":{"prompt":"Around 2020, which category of insured institutions still paid a flat-rate premium rather than risk-based DPAS premiums?","options":["Primary mortgage banks","Commercial banks with national licences","Deposit money banks","Microfinance banks"],"correctOption":3,"section":"Funding and Funding Management of the NDIC","explanation":"NDIC reported that microfinance banks paid a flat-rate premium while deposit money banks and primary mortgage banks were on risk-based premiums. Options A and C were on risk-based premiums, and option B, commercial banks with national licences, are themselves deposit money banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 594, $official_bank_source${"itemId":"2186fd2e-f922-5514-b09f-39b9ab8103fa","questionId":"2f04ba20-3b86-5806-981d-3b4930f55898","sourceKey":"bank:FIN216:FND-071","payload":{"prompt":"The NDIC cut the DPAS base rate from 50 to 40 basis points after the 2009 banking crisis mainly to:","options":["Punish banks that had taken excessive risks","Ease the burden on banks that were also contributing to a new fund for bank resolution costs","Raise more money for the Deposit Insurance Fund","Bring the rate back to the 1988 flat level"],"correctOption":1,"section":"Funding and Funding Management of the NDIC","explanation":"After the 2009 crisis, banks began paying an annual levy into a fund set up with the CBN to meet resolution costs, so the NDIC lowered the base rate to reduce their combined burden. Option C is the opposite effect of a cut. Option A would call for higher, not lower, rates, and option D is wrong because the 1988 rate was much higher."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 595, $official_bank_source${"itemId":"d5f187d5-8041-5b29-b80b-fbd52ac6e8aa","questionId":"34588c60-25db-5f49-ad11-6cab51840321","sourceKey":"bank:FIN216:FND-072","payload":{"prompt":"To meet the cost of resolving banks after the 2009 crisis, the CBN agreed with the banks to set up a fund (variously called the Financial Stability Fund or the AMCON Resolution Cost Fund). How much was the CBN to contribute each year for ten years?","options":["N50 billion","N5 billion","N500 billion","N150 billion"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"The CBN committed N50 billion a year for ten years, while each bank paid an annual levy based on its total assets. Option C, N500 billion, is roughly the CBN's total over the whole ten years, not its yearly share. Options B and D are not the agreed figure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 596, $official_bank_source${"itemId":"8989f193-9990-5448-b1c4-689bc0f3d90c","questionId":"8fbe1e3e-ecd1-5d4b-a65f-1a0f087c0975","sourceKey":"bank:FIN216:FND-073","payload":{"prompt":"The banks' annual contribution to the post-2009 bank resolution cost fund was calculated on their total assets. NDIC deposit insurance premiums, by contrast, are calculated on:","options":["Profit after tax","Total assets","Deposit liabilities","Paid-up capital"],"correctOption":2,"section":"Funding and Funding Management of the NDIC","explanation":"Deposit insurance premiums are a rate applied to a bank's deposit liabilities, because deposits are what the NDIC insures. Option B is the base of the resolution cost fund levy, which is exactly the contrast in the question. Options A and D are not used as the premium base."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 597, $official_bank_source${"itemId":"92b5fecf-d98b-542f-b0f1-09f349aae739","questionId":"64daebf3-beaa-53ab-8a0f-2d6c25ba968f","sourceKey":"bank:FIN216:FND-074","payload":{"prompt":"Mr Okafor keeps N3 million in a deposit money bank in Enugu and asks who pays the premium for the NDIC cover on his account. The correct answer is that:","options":["The bank pays the premium; Mr Okafor pays nothing for the cover","The Federal Government pays the premium on behalf of depositors","Mr Okafor pays the premium through a monthly charge","The CBN pays the premium out of its own profits"],"correctOption":0,"section":"Funding and Funding Management of the NDIC","explanation":"In deposit insurance the insured institution pays the premium, while the depositor is protected without paying, which is why there are three parties rather than two. Option C confuses deposit insurance with ordinary insurance, where the insured person pays. Options B and D are wrong because neither the government nor the CBN pays bank premiums."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 598, $official_bank_source${"itemId":"a60bcb5c-4481-509a-8b27-87b2cfdaa09f","questionId":"f63d0377-3d54-55f3-af4d-aae783d8a69d","sourceKey":"bank:FIN216:F216-0045","payload":{"prompt":"Which of the following is NOT a challenge of public awareness of deposit insurance?","options":["Literacy levels in the country","Radio waves","Budgetary constraints","Scarcity of data to measure awareness progress"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"Radio is simply one channel deposit insurers use to reach people, so 'radio waves' is not a challenge to public awareness. Real challenges include limited budgets for campaigns (option C), low literacy levels that make messages hard to understand (option A), and the lack of good data for measuring whether awareness is actually improving (option D)."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 599, $official_bank_source${"itemId":"9d6c9690-2b3c-557b-90c4-5d31ee956449","questionId":"654f4aaf-6599-57f4-82ad-7a2fe8440b34","sourceKey":"bank:FIN216:F216-0052","payload":{"prompt":"The NDIC has identified public awareness of deposit insurance in Nigeria as generally ____","options":["Universal","High","Excessive","Low"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"Low public awareness is one of the challenges the NDIC itself lists: many depositors do not know their deposits are insured or how to claim, which is one reason many small insured balances go unclaimed after a bank closes. Options B, A and C all suggest awareness is already good, which is why the NDIC keeps running awareness campaigns."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 600, $official_bank_source${"itemId":"da545999-9f46-5f95-84e7-f815bb065fc3","questionId":"f7d2f898-3108-5864-8456-fd97f3b07c49","sourceKey":"bank:FIN216:F216-0085","payload":{"prompt":"Some of the key challenges of public awareness programmes for deposit insurance include:","options":["Budgetary constraints","Literacy levels in the country","Scarcity of relevant information to measure public awareness progress","All of the above"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"Running a public awareness campaign is not easy: money is limited, so budgets restrict how widely a deposit insurer can advertise, and low literacy levels mean messages must be simplified or delivered through radio, local languages and other channels. Measuring progress is also hard, because there is often little reliable information to show whether awareness has actually improved. Since options A, B and C are all genuine challenges, D is the best answer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 601, $official_bank_source${"itemId":"bcabbf22-2711-5341-bf5c-470d5b38160c","questionId":"accd1daf-636b-554d-ae87-66d7dc1b346a","sourceKey":"bank:FIN216:CHL-002","payload":{"prompt":"After a government agency was set up to buy bad loans from distressed banks, the managers of Kogi Trust Bank began granting large risky insider loans, expecting that any losses would be absorbed by the agency. This behaviour is an example of:","options":["Moral hazard","Depositor apathy","Adverse selection","Credit rationing"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"The managers take extra risk because they expect someone else to carry the losses, which is exactly moral hazard; this is why the creation of AMCON is listed as a challenge in Nigerian bank resolution. Option C is about who chooses to join a scheme, D means lenders limiting loans, and B refers to depositors failing to claim their money."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 602, $official_bank_source${"itemId":"fc677bf8-99de-563b-8d7f-2cb5957ec744","questionId":"18247367-c59e-5fd9-8289-0889e12d51f9","sourceKey":"bank:FIN216:CHL-003","payload":{"prompt":"Which institution's establishment is listed among the challenges of bank failure resolution in Nigeria because of the moral hazard it created?","options":["Asset Management Corporation of Nigeria (AMCON)","National Identity Management Commission (NIMC)","Financial Services Regulation Coordinating Committee (FSRCC)","National Insurance Commission (NAICOM)"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"AMCON was created by the AMCON Act 2010 to buy non-performing loans and recapitalise distressed banks, and bank managers expecting such rescues may take excessive risks. Option C is a coordinating forum for regulators, B issues national identity numbers, and D regulates insurance companies; none of them buys bad bank loans."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 603, $official_bank_source${"itemId":"c844e497-c630-50d7-bc0d-e9f6b1110303","questionId":"94e9b329-8361-5841-8178-e70e07b77e2b","sourceKey":"bank:FIN216:CHL-005","payload":{"prompt":"Allowing a deposit insurer to take legal action against directors and other parties at fault in a bank's failure mainly helps to:","options":["Shift supervision of banks from the CBN to the courts","Hold culpable insiders responsible and discourage reckless banking","Increase the coverage limit for insured depositors","Reduce the premium rates paid by healthy banks"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"When those who caused a failure can be pursued for losses, insiders have less incentive to abuse the bank, which reduces moral hazard; this was one of the gaps NDIC wanted closed in its law ('dealing with parties at fault'). Option C concerns coverage, not accountability. Options A and D are not effects of suing parties at fault."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 604, $official_bank_source${"itemId":"52c59b15-0965-57c5-95e2-3a2daf7757ea","questionId":"65ca8cf9-77f2-5f7a-a947-3110a552e2a3","sourceKey":"bank:FIN216:CHL-006","payload":{"prompt":"The 'cumbersome judicial process' challenge faced by the NDIC mainly results in:","options":["Long-drawn-out litigation on winding-up actions and debt recovery","Automatic revocation of bank licences by the courts","Higher premium rates for all insured banks","Payment of depositors above the coverage limit"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Slow and cumbersome court procedures mean that winding-up cases and suits to recover debts owed to failed banks drag on for years, delaying liquidation and dividends. Option B is wrong because licences are revoked by the CBN, not the courts. Options C and D have nothing to do with court delays."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 605, $official_bank_source${"itemId":"383b4a4e-d8d5-551d-9f6d-3f4674c675a3","questionId":"2c4fce39-b295-5d0a-9984-d84c78d259db","sourceKey":"bank:FIN216:CHL-007","payload":{"prompt":"Which of the following is NOT one of the challenges Nigeria has faced in resolving failed banks?","options":["Poor record keeping in the failed banks","Problems of realising the failed banks' assets","Court action by erstwhile shareholders","Too many investors competing to buy failed banks' loans"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"The real difficulty was the opposite: there was no secondary market for risk assets, so failed banks' loans were hard to sell. Options A, B and C are all genuine challenges: broken IT systems and missing records, lawsuits by former owners, and difficulty turning loans and physical assets into cash."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 606, $official_bank_source${"itemId":"7b48c404-f69c-5106-bce2-ea20ea64e6eb","questionId":"e6a6d42e-942b-5dd4-adba-1ce8a312e235","sourceKey":"bank:FIN216:CHL-009","payload":{"prompt":"As liquidator of a failed bank, the NDIC tries to sell the bank's portfolio of loans but finds there is no secondary market for such risk assets in Nigeria. This is an example of which challenge?","options":["Vulnerable revenue base","Inadequate information disclosure","Depositor apathy","Problems of asset realisation"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"Asset realisation means turning a failed bank's loans and property into cash to pay depositors and creditors; without buyers for risk assets, this becomes slow and recoveries fall. Option C is about depositors not filing claims, B is about unreliable data from banks, and A is about NDIC's own income."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 607, $official_bank_source${"itemId":"58a8427f-5c56-594f-b134-36e6c0dcf34c","questionId":"8da40e07-bcf3-5ae1-bc74-086a968db6e3","sourceKey":"bank:FIN216:CHL-010","payload":{"prompt":"After the CBN revoked the licence of a bank, its former shareholders went to court to challenge the revocation, stalling the liquidation for years. This illustrates which challenge facing the NDIC?","options":["Legal actions by owners of closed banks","Inadequate information disclosure","Moral hazard created by deposit insurance","Depositor apathy and ignorance"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Suits by erstwhile shareholders and owners of closed banks are listed as a legal constraint because they delay the winding-up and recovery process. Option C is about excessive risk-taking, B is about poor quality data from banks, and D is about depositors failing to claim; none involves a court challenge by owners."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 608, $official_bank_source${"itemId":"8fbda5fd-da86-5b6b-a70e-0995c45529f5","questionId":"d4bdb739-d021-5d18-b263-acc8870430e6","sourceKey":"bank:FIN216:CHL-011","payload":{"prompt":"The 'inadequate legal provisions' challenge refers to the view that a deposit insurer acting as liquidator of a closed bank should be vested with:","options":["Power to set the monetary policy rate","Power to guarantee all deposits without limit","Special powers suited to winding up banks","Power to issue and revoke banking licences"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"A liquidator that works only through ordinary company law and courts is slow, so deposit insurers argue they need special powers when winding up banks. Option A belongs to the CBN, and D is also a CBN power in Nigeria. Option B would be blanket cover, which creates moral hazard and is not what the challenge is about."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 609, $official_bank_source${"itemId":"2a49d6cb-677e-5616-8922-acecaf22d004","questionId":"31dfe70a-3be1-54d4-8d28-ab5cf0c174ca","sourceKey":"bank:FIN216:CHL-012","payload":{"prompt":"The Failed Banks (Recovery of Debts) and Financial Malpractices in Banks Decree of 1994 was mainly a response to which problem?","options":["Lack of a regional deposit insurance body in Africa","Delays by insured banks in paying annual premiums","Low coverage limits for small savers in insured banks","Slow recovery of failed banks' debts in the regular courts"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"Debtors of failed banks were exploiting slow regular courts, so the 1994 Decree set up special arrangements for recovering such debts and punishing malpractice. Options A, B and C are not problems that a debt-recovery law addresses."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 610, $official_bank_source${"itemId":"137df579-6bcf-5000-aace-e3d71b5b6529","questionId":"e95953f7-037a-5c85-8c8e-80deb0df444d","sourceKey":"bank:FIN216:CHL-015","payload":{"prompt":"Before the NDIC Act 2023, NDIC proposed a provision allowing it to pay insured deposits 'pending action in court'. The aim was to:","options":["Reimburse depositors without waiting for court cases to end","Stop former shareholders from going to court at all","Allow courts to fix the coverage limit in each case","Pay uninsured creditors ahead of insured depositors"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Court cases by owners of closed banks could hold up payments for years, so the proposal let NDIC pay insured depositors while the litigation continued. Option B is wrong because the provision does not take away anyone's right to sue. Options D and C would reverse depositor priority and remove the fixed statutory limit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 611, $official_bank_source${"itemId":"6d2cb097-7898-5a9e-811b-d11bf4775087","questionId":"cdba7d78-0114-59ef-8045-9f302b06b644","sourceKey":"bank:FIN216:CHL-016","payload":{"prompt":"One reason the public misunderstands deposit insurance is that it differs from conventional insurance. How many parties are involved in a deposit insurance arrangement, and who are they?","options":["Two: the insurer and the insured depositor","Two: the insured bank and the CBN","Three: the deposit insurer, the depositor and the insured bank","Three: the depositor, the bank and the CBN"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"Conventional insurance is a contract between two parties, but deposit insurance has three: the insurer (NDIC), the depositor who is protected, and the bank that pays the premium. Option A describes ordinary insurance, while D and B wrongly put the CBN in the insurer's place."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 612, $official_bank_source${"itemId":"c2be4fd3-233f-52c7-b164-42be0ed698dd","questionId":"d3fb9cd2-6bc2-529e-9902-f135a39ac8a3","sourceKey":"bank:FIN216:CHL-017","payload":{"prompt":"Unlike in motor or life insurance, in a deposit insurance scheme the premium is paid by the:","options":["Depositor","Federal Ministry of Finance","Central Bank of Nigeria","Insured bank"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"In deposit insurance the bank pays the premium while the depositor enjoys the protection without paying anything directly. Option A is the common misunderstanding that comes from comparing it with conventional insurance. Options C and B are NDIC's owners, not premium payers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 613, $official_bank_source${"itemId":"330a4dea-26fe-5dac-8985-7495319719df","questionId":"e01400d0-c21a-557a-9c19-1c012411f0fb","sourceKey":"bank:FIN216:CHL-022","payload":{"prompt":"Unreliable returns submitted by insured banks most directly weaken which NDIC supervisory tool?","options":["Lender of last resort facility","Premium rebate scheme","Off-site surveillance","Licensing of new banks"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"Off-site surveillance analyses the periodic returns banks submit, so poor data hides problems and delays early warning. Options A and D are CBN functions, not NDIC supervisory tools. Option B is about refunds of premiums, not monitoring bank health."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 614, $official_bank_source${"itemId":"89f72bcb-7429-5d2d-b620-5100d6961040","questionId":"d236a2d8-8c62-5c1d-a330-cdd094b236ae","sourceKey":"bank:FIN216:CHL-023","payload":{"prompt":"Many insured depositors of closed banks never file claims for their money, even where a 100 percent liquidation dividend has been declared. This challenge is known as:","options":["Depositor apathy and ignorance","Contagion among depositors","Adverse selection of depositors","Moral hazard by depositors"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Despite public enlightenment efforts, many depositors, often with small balances, simply do not come forward, which NDIC attributes largely to ignorance and apathy. Option D is about excessive risk-taking, C about who joins a scheme, and B about depositors rushing to withdraw, the opposite of not claiming."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 615, $official_bank_source${"itemId":"975d45e1-3449-5700-b6dc-10a131ac702e","questionId":"b1aa9c3e-7c52-5180-a13f-6a3c1bf828d2","sourceKey":"bank:FIN216:CHL-024","payload":{"prompt":"Which group was noted to default in filing their own claims against closed banks, even though they had been appointed to pay depositors' claims on behalf of the NDIC?","options":["Pension fund administrators","Microfinance banks","Insurance companies","Agent banks"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"NDIC appoints healthy banks as agent banks to pay depositors of closed banks, yet some of these same agent banks failed to file their own claims. Options A, B and C are not the institutions that act as NDIC's paying agents."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 616, $official_bank_source${"itemId":"80c3cc04-307b-5375-85f5-8bd0bc7a5bcc","questionId":"403bad05-5a7b-5d05-b6ff-0449e1af491b","sourceKey":"bank:FIN216:CHL-027","payload":{"prompt":"Mr Okafor had N3.2 million in a microfinance bank whose licence was revoked in 2025. He is paid his insured deposit under the May 2024 limits, and the liquidator later declares a 25 percent liquidation dividend on uninsured claims. What is the total he receives?","options":["N2,800,000","N2,000,000","N2,300,000","N2,500,000"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"The MFB cover since May 2024 is N2m, leaving an uninsured claim of N1.2m; a 25% dividend on that is N300,000, so he gets N2.3m in total. Option A wrongly applies 25% to the whole N3.2m, B ignores the dividend, and D wrongly applies 25% to the insured N2m."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 617, $official_bank_source${"itemId":"6d04f1c3-b945-5ce4-bd08-d12d586450ab","questionId":"37946c00-ca85-5632-ac45-0ae5bf970dae","sourceKey":"bank:FIN216:CHL-028","payload":{"prompt":"In 2025, Aisha holds N6 million in her wallet with a mobile money operator, whose pooled trust account is kept at a deposit money bank. If that bank fails, how much of Aisha's money is protected under the pass-through cover set in May 2024?","options":["N6,000,000","N2,000,000","N5,000,000","N500,000"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"Pass-through cover treats each subscriber as if they held the deposit directly, and since May 2024 the limit is N5m per subscriber per mobile money operator, so N5m of her N6m is protected. Option D is the pre-2024 limit, B is the limit for MFBs, PMBs and payment service banks, and A assumes unlimited cover."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 618, $official_bank_source${"itemId":"ad775087-f873-56fd-8aab-ba973433fe83","questionId":"2fe2fcb9-e242-53dd-84fc-768c91fd6462","sourceKey":"bank:FIN216:CHL-031","payload":{"prompt":"Which was a major reason the NDIC could not meet target periods for paying insured depositors of many closed banks?","options":["Poor records in banks closed long before licence revocation","Coverage limits that were too complex to compute","Excess capital still held by the failed banks","Too many healthy banks bidding for the failed banks"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Many closed banks had incomplete records, were not fully computerised and had wide branch networks, so compiling depositor information was slow. Option B is wrong because a fixed limit is easy to apply, D would speed up resolution rather than delay payout, and C is the opposite of a failed bank's condition."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 619, $official_bank_source${"itemId":"0104b886-e90f-5801-98d8-c261dbd5991f","questionId":"2c21d61f-e6b0-5f32-97fd-2e22dcbd2643","sourceKey":"bank:FIN216:CHL-032","payload":{"prompt":"NDIC liquidators taking over a closed bank find broken-down IT systems and missing mandate records, making it hard to confirm who owns which account. This is the challenge of:","options":["Poor record keeping","Cross-border banking","Moral hazard","Vulnerable revenue base"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Poor record keeping covers missing financial records, mandate records and broken IT systems in failed banks, and it slows verification of claims and payout. Option C is about excess risk-taking, D about NDIC's income, and B about banks operating in several countries."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 620, $official_bank_source${"itemId":"2dc63707-1d09-53aa-a2b1-0ae8948f2484","questionId":"040394d6-c645-5be3-84ad-9b02d6c1dc50","sourceKey":"bank:FIN216:CHL-034","payload":{"prompt":"Prompt reimbursement of insured depositors contributes to financial stability mainly by:","options":["Allowing the failed bank's shareholders to recover their capital","Reducing the likelihood of runs on other banks","Removing the need for bank supervision","Increasing the profits of the failed bank"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"When depositors of a failed bank are paid quickly, the public sees the guarantee working, which cushions the effects of the failure and discourages panic withdrawals from other banks. Options D and A are not effects of payout, and C is wrong because supervision remains essential."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 621, $official_bank_source${"itemId":"5f5260c9-a28e-5c9a-b725-1023eb5dac4d","questionId":"4bb093f0-b9d1-5ea3-b1ac-e3fc3f9677a6","sourceKey":"bank:FIN216:CHL-035","payload":{"prompt":"Under the NDIC Act 2006, the Corporation's operating expenses were to be met from:","options":["Annual grants from the Central Bank of Nigeria","Income earned from investing the Deposit Insurance Fund","Charges deducted from depositors' accounts","The premium balances in the Deposit Insurance Fund itself"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"NDIC was prohibited from spending the Deposit Insurance Fund on running costs; those had to come from the income generated by investing the fund. Option D is the very thing the law forbade, A is not how running costs were funded, and C is wrong because depositors pay nothing for the cover."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 622, $official_bank_source${"itemId":"43195b51-de61-58f8-b5c4-54e30021fba0","questionId":"0067a054-5314-5b25-b4c8-7af06dadb8db","sourceKey":"bank:FIN216:CHL-037","payload":{"prompt":"The proposal for a General Reserve Fund, now provided for in section 19 of the NDIC Act 2023, was meant to:","options":["Replace premiums as NDIC's main inflow of funds","Finance the CBN's lender of last resort operations","Build a reserve that backs up payments to insured depositors","Pay dividends to shareholders of failed banks first"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"Year-end surpluses go to the General Reserve Fund so that NDIC can meet depositor payments if an insurance fund is short, addressing the risk of an inadequate fund. Option B is a CBN function, D is wrong because failed banks' shareholders rank last, and A is wrong because premiums remain a key inflow."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 623, $official_bank_source${"itemId":"d688663e-90f9-5837-b1f9-53ad4dc59103","questionId":"3a062193-3e97-5a25-8a58-e3ca12106459","sourceKey":"bank:FIN216:CHL-038","payload":{"prompt":"To guard against a deposit insurance fund that is too small relative to insured deposits, the 2014 IADI Core Principles expect a deposit insurer to have:","options":["An ex ante fund with a target size, plus pre-arranged emergency funding","A fund raised only after a bank has failed (ex post)","Unlimited access to taxpayers' money for every failure","Borrowing from the market as its only backup funding"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"IADI's funding principle favours collecting premiums in advance towards a target fund size and having emergency liquidity lined up, for example from the central bank or government. Option B is the ex post approach, C would create moral hazard, and D is wrong because market borrowing should not be the only backup."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 624, $official_bank_source${"itemId":"3be88177-720a-53be-a2e8-28e66ee9b282","questionId":"10ef7e35-b987-5a6f-9a9d-a4bbd4f01d90","sourceKey":"bank:FIN216:CHL-039","payload":{"prompt":"IADI requires the public to be informed of both the benefits and the LIMITATIONS of deposit insurance. Which of these is a limitation?","options":["Small savers are protected against loss","Deposits above the coverage limit are not fully protected","Insured depositors are paid promptly when a bank fails","Membership is compulsory for all licensed banks"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"A limitation is something deposit insurance does not do; balances above the cover limit may be lost in part, so depositors should know this. Options C and A are benefits of the scheme, and D is a feature that strengthens the scheme rather than a limitation on depositors."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 625, $official_bank_source${"itemId":"4225263e-65ad-5d39-8e3b-73abb57d083b","questionId":"d637fddd-5a92-53c0-9029-43009b4d9ab3","sourceKey":"bank:FIN216:CHL-040","payload":{"prompt":"A public awareness programme of a deposit insurer conveys all the following EXCEPT:","options":["Which types of deposits and depositors are covered","The monthly profit figures of each member bank","Which banks are members and how they can be identified","The coverage limits"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"IADI says awareness programmes cover the scope of cover, the list of member banks and how to identify them, the coverage limits and other information such as the insurer's mandate. Bank profit figures are a matter of financial disclosure, not deposit insurance awareness, while A, C and D are all required content."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 626, $official_bank_source${"itemId":"5f414988-8c28-5846-8149-0b5cef2cd875","questionId":"fa9ba20a-5e0d-599b-9054-2bf514295f26","sourceKey":"bank:FIN216:CHL-041","payload":{"prompt":"A bank has just failed and the NDIC is issuing press releases and newspaper adverts to its depositors. Which of the following MUST the notice tell insured depositors?","options":["How to apply to the CBN for a new banking licence","The new lending rates the bridge bank will charge","How they can buy shares in the failed bank's successor","Where, how and when they will get access to their funds"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"When a bank fails, IADI requires the deposit insurer to tell depositors where, how and when they can access their funds, what information they must provide, whether interim payments are made, and whether anyone will lose money. Options A, B and C are not part of a payout notice."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 627, $official_bank_source${"itemId":"bfdc363b-2d0b-57b7-b08d-0d997791ba31","questionId":"cac73359-b942-5246-8908-d33f78e7abf9","sourceKey":"bank:FIN216:CHL-042","payload":{"prompt":"Which of the following is the best example of a clearly defined public awareness objective for the NDIC?","options":["Advertise in as many newspapers and radio stations as possible","Raise awareness that deposits are insured to a set target level","Tell people more about banking and finance in general","Make the NDIC more popular than all other regulators"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"IADI expects awareness objectives to be clearly defined, for example as target awareness levels, and consistent with the scheme's public policy objectives. Option A is an activity rather than an objective, while D and C are vague and cannot be measured."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 628, $official_bank_source${"itemId":"f7294143-452d-5a5c-8013-181071e4d30e","questionId":"ac436af9-c92e-56dd-89bb-48790412c761","sourceKey":"bank:FIN216:CHL-043","payload":{"prompt":"Requiring insured banks to display the NDIC 'insured' sign or logo in their banking halls and on their websites mainly helps the public to:","options":["Know the CAMEL rating of each bank","Identify which institutions are insured members","Find out the bank's lending limits","Compare the interest rates of different banks"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"Signs and logos are a simple awareness tool that tells depositors their bank is a member and their deposits are insured. Banks are also expected to present deposit insurance information in the format the insurer prescribes. Options A, C and D are not what the insured sign communicates; supervisory ratings in particular are confidential."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 629, $official_bank_source${"itemId":"a900b86e-7ddc-51b1-9dff-86981d3147c4","questionId":"20f462f4-4462-5339-869a-c34bf48c2740","sourceKey":"bank:FIN216:CHL-044","payload":{"prompt":"According to IADI guidance, the most practical way for a deposit insurer to measure whether a public awareness campaign has worked is to:","options":["Ask member banks to rate how good the campaign was","Compare the campaign budget with last year's budget","Count the number of brochures and adverts produced","Survey awareness independently before and after the campaign"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"A before-and-after survey shows whether people's knowledge actually changed, and IADI also calls for periodic independent evaluations. Option C is only an output measure of activity, and A and B do not tell you whether depositors' awareness improved."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 630, $official_bank_source${"itemId":"818948c2-5d6a-5128-9339-f1936b336f66","questionId":"02202b4b-9685-54cc-9e2f-155788cebf93","sourceKey":"bank:FIN216:CHL-046","payload":{"prompt":"Which of the following is NOT a challenge for deposit insurance public awareness programmes?","options":["Compulsory membership of all licensed deposit takers","Awareness levels that fall quickly after a campaign","Low literacy levels among depositors","Budgetary constraints and the high cost of mass media"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Compulsory membership is a design feature that makes the scheme simpler to explain, not an obstacle to awareness. Options B, C and D are recognised challenges: limited budgets, literacy barriers and the fact that awareness fades unless it is maintained."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 631, $official_bank_source${"itemId":"1534c45c-947f-5621-8e4a-403a8d975ecf","questionId":"5fd9046e-45eb-5ba1-9d40-f498d6f79e8b","sourceKey":"bank:FIN216:CHL-047","payload":{"prompt":"After a slow and confusing payout to depositors of a failed bank, a survey shows public confidence in deposit insurance has fallen, despite a costly advertising campaign. This shows that:","options":["Advertising alone guarantees public confidence","Depositors never pay attention to bank failures","Public confidence depends heavily on the actual payout experience","Payout speed has no link to public awareness"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"IADI observes that one poor payout can undo the gains of an awareness campaign, because people judge the scheme by how it performs when a bank fails. Options A, B and D all contradict what the survey revealed."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 632, $official_bank_source${"itemId":"c21a35b0-28e2-5457-80db-e7bf0b897fec","questionId":"fe38121a-c46e-5195-a9df-6cbb6f8f12fb","sourceKey":"bank:FIN216:CHL-048","payload":{"prompt":"Low public awareness of deposit insurance can make bank runs MORE likely because:","options":["Unaware depositors panic and withdraw at the first rumour","Insured banks stop paying their deposit premiums","The CBN can no longer act as lender of last resort","Coverage limits automatically fall to lower levels"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Deposit insurance prevents runs only if depositors know their money is protected; without that knowledge, small depositors may rush to withdraw at the first rumour. Options B, C and D are not consequences of low public awareness."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 633, $official_bank_source${"itemId":"2f308d8a-5122-5331-8e47-167c46507a87","questionId":"7751e665-c5fc-5a95-9365-d6b22296ce91","sourceKey":"bank:FIN216:CHL-051","payload":{"prompt":"Many Nigerian banks now operate subsidiaries in other African countries. What challenge does this create for the NDIC?","options":["Insuring the deposits of all foreign banks worldwide","Having to adopt the currency of every host country","Coordination and information-sharing with foreign authorities","Losing its power to liquidate banks in Nigeria"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"Cross-border groups expose Nigerian banks to risks abroad, so supervisors need consolidated and cross-border supervision and formal arrangements with foreign authorities; IADI's 2014 Core Principle 5 deals with these cross-border issues. Options A, B and D are not consequences of cross-border banking."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 634, $official_bank_source${"itemId":"d94fb780-50f0-550e-bf22-6a38fb3b5d37","questionId":"53573627-4f17-54a8-9b4e-4c189af564aa","sourceKey":"bank:FIN216:CHL-052","payload":{"prompt":"Where banks operate across borders through foreign branches or subsidiaries, IADI's 2014 public awareness principle requires that depositors be clearly told:","options":["Which deposit insurer covers them, and the cover's limits and scope","How to open an account in the parent bank's home country","The exchange rate policy of the parent bank's home country","The names and nationalities of the bank's foreign shareholders"],"correctOption":0,"section":"Challenges of the NDIC","explanation":"Depositors of cross-border banks can be confused about who protects them, so they must be told which deposit insurer is responsible and what the cover is. Options B, C and D do not help a depositor know whether and how much of their money is protected."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 635, $official_bank_source${"itemId":"82072a78-8d33-5002-a4b6-d28e5dcf6f24","questionId":"1412c6c1-a964-5708-8c89-8390fa0a5034","sourceKey":"bank:FIN216:CHL-053","payload":{"prompt":"The NDIC responded to the growth of mobile money by extending protection to subscribers through:","options":["Co-insurance in which subscribers bear the first loss","Pass-through cover on operators' pooled trust accounts","A blanket government guarantee of all e-wallets","An implicit promise with no written rules"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"Under pass-through cover, introduced by NDIC guidelines in 2016, a mobile money operator's pooled trust account at a bank is insured as if each subscriber held the deposit directly, up to the limit per subscriber. Option C would be unlimited cover, A is a different design not used here, and D describes implicit protection, whereas Nigeria's scheme is explicit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 636, $official_bank_source${"itemId":"70a3316a-094b-5c6a-b775-379d6561d82c","questionId":"7a113148-6d0f-5d21-aefa-9809f8904ffb","sourceKey":"bank:FIN216:CHL-054","payload":{"prompt":"Rapid growth of fintech apps and digital wallets creates a public awareness challenge for the NDIC mainly because:","options":["Fintech apps make bank supervision unnecessary","Digital wallets are unable to hold naira balances","Fintech firms do not pay company income tax","Users may wrongly assume every digital wallet is insured"],"correctOption":3,"section":"Challenges of the NDIC","explanation":"Deposit insurers must tell the public which products and institutions are covered and which are not; new products blur this line, so people may believe funds are protected when they are not. Options C and B are untrue or irrelevant, and A is wrong because innovation increases rather than removes the need for supervision."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 637, $official_bank_source${"itemId":"2d6f4191-db81-586e-8e59-6c327855d23b","questionId":"6fff0e1e-fb78-5c89-a6fc-42bc8c53fe70","sourceKey":"bank:FIN216:CHL-055","payload":{"prompt":"A cyber attack that corrupts a bank's customer account database would most directly threaten the NDIC's ability to:","options":["Set the coverage limit for deposit money banks","Choose which agencies sit on the FSRCC","Determine and pay insured amounts promptly on failure","Fix the CBN's monetary policy rate"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"Fast payout depends on accurate, complete depositor records; if those records are lost or corrupted, NDIC cannot quickly confirm balances, just as poor record keeping delayed payouts in the past. Options A and B are policy matters unaffected by one bank's data, and D is a CBN function."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 638, $official_bank_source${"itemId":"c51c865c-babe-5567-b6cd-fe7a91e33a79","questionId":"2abbb49e-f6fb-54b8-a1ee-6b7f221aa533","sourceKey":"bank:FIN216:CHL-056","payload":{"prompt":"Which of the following is NOT one of the ways the NDIC supports financial inclusion in Nigeria?","options":["Providing consumer protection","Issuing unique national identification numbers","Guaranteeing deposits, especially of small and poor savers","Continuous public education"],"correctOption":1,"section":"Challenges of the NDIC","explanation":"NDIC supports financial inclusion by guaranteeing deposits of small savers, protecting consumers, resolving distress and educating the public. Issuing national identity numbers is the job of the National Identity Management Commission (NIMC), while C, A and D are genuine NDIC roles."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 639, $official_bank_source${"itemId":"9bbf2e2a-d9af-5eee-9988-f1b912a3ebd8","questionId":"28c343f4-2cfe-516f-bce7-dc9dda1ce9f8","sourceKey":"bank:FIN216:CHL-060","payload":{"prompt":"Why do financial literacy and consumer protection matter for financial inclusion and depositor protection in Nigeria?","options":["Nigeria has one central consumer council for finance","Financial literacy removes the need for deposit insurance","Information imbalance puts consumers at a disadvantage","Consumers usually know more about products than banks"],"correctOption":2,"section":"Challenges of the NDIC","explanation":"Providers know far more about their products than ordinary customers, so literacy and consumer protection are needed to correct the imbalance; this is why they complement financial inclusion. Option D reverses the imbalance, A is wrong because no such central council exists and each regulator covers its own sector, and B is wrong because the two work together."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 640, $official_bank_source${"itemId":"d6c2cd12-baf8-57e0-92f3-a3e82ef9f461","questionId":"4e4dd992-9ac7-5113-b33d-72643aa26419","sourceKey":"bank:FIN216:F216-0035","payload":{"prompt":"____ is an international body that monitors and makes recommendations about the global financial system.","options":["World Bank","International Monetary Fund","International Association of Deposit Insurers","Financial Stability Board"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The Financial Stability Board (FSB) brings together national authorities and standard-setters to monitor the global financial system and make recommendations to keep it stable, and it lists the IADI Core Principles among the standards it promotes for sound financial systems. Option C, IADI, sets standards only for deposit insurance, not the whole financial system. Options A and B are lending and economic institutions; the IMF does monitor economies, but the body described in these exact terms is the FSB."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 641, $official_bank_source${"itemId":"cd100628-7bce-5c77-92cf-fb7d39aa1f5d","questionId":"f55a5b11-e174-5e0e-bac2-84b873ba919a","sourceKey":"bank:FIN216:F216-0036","payload":{"prompt":"Which of the following is NOT a component of the financial safety net?","options":["Lender of last resort","Disclosure","Prudential regulation","Deposit insurance"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The financial safety net is made up of functions such as prudential regulation and supervision, the lender of last resort, failure resolution and deposit insurance, and in many countries the Ministry of Finance also plays a part. Disclosure is a useful tool for transparency and market discipline, but it is not one of the safety-net functions. Options D, C and A are all core parts of the net; in Nigeria, for example, the NDIC provides deposit insurance and the CBN acts as lender of last resort."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 642, $official_bank_source${"itemId":"af012deb-6d00-5866-b464-5455e52e673f","questionId":"f7a51442-f22e-5d37-8608-d83979f782c5","sourceKey":"bank:FIN216:F216-0053","payload":{"prompt":"Membership of the FSRCC includes all the following EXCEPT:","options":["NDDC","CBN","NDIC","SEC"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The Financial Services Regulation Coordinating Committee (FSRCC) brings together Nigeria's financial regulators, including the CBN (whose Governor chairs it), the NDIC, the SEC, NAICOM and PenCom. The NDDC (Niger Delta Development Commission) is a regional development agency, not a financial regulator, so it is not a member. Options B, C and D are all members."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 643, $official_bank_source${"itemId":"8cf6419d-5913-5db3-bac6-6400089a3916","questionId":"7de90e9e-d0e4-5343-896e-7094812ca66e","sourceKey":"bank:FIN216:F216-0054","payload":{"prompt":"The financial safety-net participants in Nigeria collectively interact through a common organ called the:","options":["Financial Services Regulation Coordinating Committee (FSRCC)","Bankers' Committee","Monetary Policy Committee (MPC)","Financial Stability Board (FSB)"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The FSRCC is the forum where Nigeria's financial regulators, including the CBN, NDIC, SEC, NAICOM and PenCom, coordinate and share information; it was renamed FSRCC in 1994 and given legal backing in 1998. Option C is the CBN committee that sets interest rates, option D is an international body rather than a Nigerian one, and option B is a forum of the CBN and bank chief executives, not of the regulators."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 644, $official_bank_source${"itemId":"6ffc0d92-9efd-5635-a419-d5d474777cee","questionId":"8cade3ac-a799-5283-b618-557f26990772","sourceKey":"bank:FIN216:F216-0063","payload":{"prompt":"In deposit insurance and financial stability work, FSAP refers to:","options":["Financial Sector Assessment Program","Financial System and Associated Programs","Financial Sector and Assisted Program","Financial Sector and Associated Program"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"FSAP stands for Financial Sector Assessment Program, an in-depth review of a country's financial sector, including how well its deposit insurance and supervision meet international standards. The important word is 'assessment', because the program assesses the stability and soundness of the sector. Options D, B and C sound similar but do not describe what the program actually does."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 645, $official_bank_source${"itemId":"926a15f0-852d-568b-866f-404028316ffe","questionId":"edca76f3-632d-56a4-b099-b31516d9f6b2","sourceKey":"bank:FIN216:F216-0064","payload":{"prompt":"The Financial Sector Assessment Program (FSAP), launched in 1999, is a joint programme of:","options":["the IMF alone","the World Bank (IBRD) alone","the Bank for International Settlements","the IMF and the World Bank"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The FSAP was set up in 1999 as a joint effort of the International Monetary Fund and the World Bank to assess countries' financial sectors. In developing and emerging economies such as Nigeria, both institutions take part in the review. Options A and B each name only one of the two partners, and option C names the body that hosts IADI and the Basel Committee, not the FSAP."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 646, $official_bank_source${"itemId":"1466326b-27e6-5c65-9db6-c386b2dc8a46","questionId":"84b09b28-77ec-5696-b4f3-84963b399cb5","sourceKey":"bank:FIN216:F216-0069","payload":{"prompt":"CBRG is an acronym for:","options":["Cross-border Bank Resolution Group","Cross-border Before Resolution Group","Crisis Before Bank Resolution Group","Crisis Backed by Bank Resolution Group"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"CBRG is the Cross-border Bank Resolution Group of the Basel Committee on Banking Supervision, which studied how to resolve banks operating in more than one country. Its name reflects the problem it tackled: cross-border banks need coordinated resolution. Options C, D and B mix up the words and do not describe a real body."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 647, $official_bank_source${"itemId":"fce36590-9b76-547c-9b04-e78175db4758","questionId":"5f5d869e-9739-5ef9-848c-d9f0a1108b67","sourceKey":"bank:FIN216:F216-0087","payload":{"prompt":"Financial system stability requires ________ among the various safety-net participants.","options":["Competition for supervisory powers","Strict separation with no information sharing","Duplication of each other's roles","Close collaboration and inter-agency cooperation"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The safety net only works when the deposit insurer, the central bank and the supervisors coordinate closely and share information, because a bank problem spotted by one agency often needs action by another. Option B is wrong because withholding information is exactly what weakens crisis response. Options A and C describe rivalry and wasted effort, which create gaps and confusion rather than stability."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 648, $official_bank_source${"itemId":"c80e2c75-3181-594f-9a23-49ef0268f1d4","questionId":"38f80184-04a8-542b-94bd-ea981b4bfd1b","sourceKey":"bank:FIN216:F216-0091","payload":{"prompt":"The main purpose of financial safety-net arrangements is to:","options":["Guarantee that every bank makes a profit","Ensure the stability and integrity of the financial system and protect depositors","Prevent any bank from ever failing","Replace the need for bank supervision"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A financial safety net (deposit insurance, supervision and the lender of last resort) exists to keep the financial system stable and to protect depositors and other consumers of financial services. Option C is wrong because the safety net cannot stop all failures; it limits the damage when they happen. Option A is not a policy goal, and option D is wrong because supervision is itself part of the safety net."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 649, $official_bank_source${"itemId":"a1366295-3f83-5d39-9aa2-e8fb408ffe6b","questionId":"e81ddb25-c29b-5c9d-b1fa-bfb8bacc7eb8","sourceKey":"bank:FIN216:F216-0092","payload":{"prompt":"The component(s) of the financial safety net in Nigeria is/are:","options":["Lender of last resort facility of the CBN to address financial institutions' liquidity problems","Deposit insurance provided by the NDIC","Bank supervision","All of the above"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A financial safety net usually has three parts: a lender of last resort to handle liquidity problems (the CBN), deposit insurance to protect depositors (the NDIC), and bank supervision to spot problems early (done jointly by the CBN and NDIC). Because A, B and C are each one of these parts, D is correct; picking only one of them leaves out the other two pillars."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 650, $official_bank_source${"itemId":"8fed2cce-e805-527c-a248-cd7df3f38af3","questionId":"2e76a365-a487-5a00-9bdb-781608c83d3e","sourceKey":"bank:FIN216:F216-0092-b","payload":{"prompt":"In Nigeria's financial safety net, which institution acts as the lender of last resort?","options":["Nigeria Deposit Insurance Corporation (NDIC)","Asset Management Corporation of Nigeria (AMCON)","Securities and Exchange Commission (SEC)","Central Bank of Nigeria (CBN)"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The lender of last resort lends to solvent banks facing a temporary shortage of cash, and in Nigeria that role belongs to the CBN as the bank of banks. Option A is wrong because the NDIC provides deposit insurance and handles failure resolution, not emergency central bank liquidity. Options B and C buy bad loans and regulate the capital market respectively."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 651, $official_bank_source${"itemId":"427039bb-9729-5504-9f2f-138e22c43882","questionId":"fdfcee7f-caf7-54e7-ba43-855230ca98eb","sourceKey":"bank:FIN216:F216-0094","payload":{"prompt":"The interrelationship between financial safety-net players is:","options":["Unique, and therefore managed by a single agency or the central bank","Irrelevant, because each agency works in isolation","Multi-dimensional, and therefore managed by more than one agency","Limited to the NDIC and commercial banks only"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The safety net involves several players with different roles, such as the CBN (lender of last resort and regulator), the NDIC (deposit insurer and resolver) and the Ministry of Finance, so the relationships run in many directions and require coordination among several agencies. Option A is wrong because no single agency handles all these roles. Options B and D ignore the need for coordination and leave out major players like the CBN."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 652, $official_bank_source${"itemId":"0d93afa0-bf96-52eb-b353-c2b295898b67","questionId":"08cfb439-4788-5534-9665-4103786a19f5","sourceKey":"bank:FIN216:SNP-001","payload":{"prompt":"The set of public functions made up of prudential regulation, supervision, bank resolution, lender of last resort and deposit insurance, which together protect depositors and the financial system, is called the","options":["deposit insurance fund","financial safety net","monetary policy framework","financial inclusion strategy"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The financial safety net is the collection of functions - regulation, supervision, resolution, lender of last resort and deposit insurance - that stand behind banks and their depositors. Option C is about controlling money supply and interest rates, option A is only the pool of money a deposit insurer holds, and option D is about bringing the unbanked into formal finance."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 653, $official_bank_source${"itemId":"175aaad0-17fe-530c-92e9-3e14361f012a","questionId":"80767c20-3eaa-5222-9af2-08941edd9c78","sourceKey":"bank:FIN216:SNP-002","payload":{"prompt":"Which of the following best describes the financial safety net?","options":["The reserves that each commercial bank keeps with the central bank to meet withdrawals","A private fund contributed by shareholders to bail out banks that make losses","The set of rules that decides which depositors are excluded from deposit insurance cover","The functions of prudential regulation, supervision, resolution, lender of last resort and deposit insurance, sometimes with the Ministry of Finance"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A financial safety net is the whole package of functions that protect depositors and keep the system stable: regulation, supervision, resolution, lender of last resort and deposit insurance, with the finance ministry included in many countries. Option A describes cash reserve requirements, option C describes coverage exclusions, and option B is not a public safety net at all."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 654, $official_bank_source${"itemId":"e256a2c5-a9f7-5653-8e5b-059dba873a5f","questionId":"90f31ee1-27e4-5ae3-bfd1-d8e7fb3b2d71","sourceKey":"bank:FIN216:SNP-003","payload":{"prompt":"Which of the following is NOT one of the functions that make up the financial safety net?","options":["Fiscal budgeting for capital projects","Prudential regulation and supervision","Deposit insurance","Lender of last resort"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The safety net covers prudential regulation, supervision, resolution, lender of last resort and deposit insurance. Planning government capital spending is part of fiscal policy, not a safety-net function. Options B, C and D are all genuine safety-net functions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 655, $official_bank_source${"itemId":"9ae637d8-669c-517e-bcfe-157dd5b3fe5c","questionId":"8978f353-9462-5197-bd15-ca7843d1e746","sourceKey":"bank:FIN216:SNP-004","payload":{"prompt":"In the simplest description of the financial safety net, the three core components are","options":["deposit insurance, taxation and exchange control","deposit insurance, supervision and lender of last resort","supervision, credit rating and stock exchange listing","lender of last resort, insurance regulation and pension regulation"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The basic safety net has three legs: deposit insurance to protect depositors, supervision to keep banks sound, and a lender of last resort to supply emergency liquidity. Option A mixes in tax and foreign exchange policy, while options C and D list activities or regulators outside the core three."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 656, $official_bank_source${"itemId":"3041b12f-f178-51f5-b142-f240b822415b","questionId":"96a976bb-72ee-5f22-a392-2fc4ce182fb7","sourceKey":"bank:FIN216:SNP-007","payload":{"prompt":"In Nigeria's bank failure resolution arrangements, the Federal Ministry of Finance is described as the","options":["liquidator of failed banks","guarantor of the lender of last resort","chairman of the FSRCC","buyer of non-performing loans"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The finance ministry stands behind the central bank as guarantor of the lender of last resort, since the government ultimately carries large fiscal costs in a crisis. Option A is the NDIC's role, option D is AMCON's role, and option C is wrong because the CBN Governor chairs the FSRCC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 657, $official_bank_source${"itemId":"4ec7cc8f-64da-53ef-95c1-fda9e7b35892","questionId":"d40c5b78-7430-53ad-bb89-b45c4fc548cb","sourceKey":"bank:FIN216:SNP-008","payload":{"prompt":"Which safety-net participant in Nigeria was set up to purchase non-performing loans and recapitalise distressed banks?","options":["National Insurance Commission (NAICOM)","National Pension Commission (PenCom)","Financial Reporting Council (FRC)","Asset Management Corporation of Nigeria (AMCON)"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"AMCON was created under the AMCON Act 2010 to buy bad loans from banks and inject capital into distressed ones, which made it part of the resolution side of the safety net. NAICOM, option A, regulates insurance; PenCom, option B, regulates pensions; and the FRC, option C, sets financial reporting standards."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 658, $official_bank_source${"itemId":"9eed7a07-485f-5c9e-926a-eb704a0fc89b","questionId":"af1ccb56-1677-5fab-804a-b53968a3e608","sourceKey":"bank:FIN216:SNP-009","payload":{"prompt":"Which pairing of a Nigerian safety-net participant with its role is CORRECT?","options":["NDIC - deposit insurance, failure resolution and liquidation","CBN - liquidator of failed banks","Federal Ministry of Finance - on-site examination of banks","AMCON - lender of last resort"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The NDIC guarantees deposits, resolves failing banks and liquidates failed ones. The CBN, option B, revokes licences and lends as last resort, but the NDIC is the liquidator; AMCON, option D, buys bad loans rather than lending as last resort; and the finance ministry, option C, does not examine banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 659, $official_bank_source${"itemId":"aacabedd-f683-5fea-840f-8eeb3b8dca91","questionId":"08f8a902-e379-5bab-b944-f09c1492fc9f","sourceKey":"bank:FIN216:SNP-010","payload":{"prompt":"In Nigeria's resolution framework, which of the following is NOT a power of the Central Bank of Nigeria?","options":["Open bank assistance","Paying insured depositors of a closed bank","Lender of last resort","Revoking a bank's operating licence"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Reimbursing insured depositors is the NDIC's job as deposit insurer. The CBN can give open bank assistance, lend as last resort, and revoke licences, so options A, C and D are genuine CBN powers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 660, $official_bank_source${"itemId":"d06f0482-7753-5770-b411-d53839707e40","questionId":"3ffc456a-24e6-5267-8a20-8321cd30e8e5","sourceKey":"bank:FIN216:SNP-011","payload":{"prompt":"Which of the following resolution tools is NOT listed among the NDIC's own resolution powers?","options":["Purchase and assumption","Bridge bank mechanism","Lender of last resort","Depositor reimbursement"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Lender of last resort belongs to the central bank, not the deposit insurer. The NDIC's own toolkit includes open bank assistance, depositor reimbursement, purchase and assumption, bridge banks, assisted mergers and purchase of assets, so options A, B and D are genuine NDIC tools."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 661, $official_bank_source${"itemId":"af47d672-91d7-5822-b2a7-f6eafbb789b6","questionId":"8d297701-dc28-553e-a1dc-78ff95fa26e2","sourceKey":"bank:FIN216:SNP-013","payload":{"prompt":"A solvent Nigerian bank faces a sudden run and cannot meet withdrawals for a few days, although its assets are sound. Which safety-net function is designed for this situation?","options":["Deposit payout by the deposit insurer","Liquidation by the deposit insurer","Lender of last resort by the central bank","Purchase of non-performing loans by AMCON"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A temporary liquidity shortage in a solvent bank is exactly what the lender of last resort is for: the central bank lends against good collateral until the panic passes. Options A and B apply only after a bank has failed and closed, and option D deals with bad assets rather than short-term cash needs."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 662, $official_bank_source${"itemId":"c80c66f2-4cd6-5045-9d0b-94bd851f5fcd","questionId":"ae816b1c-78d0-5847-add1-801fadf37ab3","sourceKey":"bank:FIN216:SNP-014","payload":{"prompt":"Which statement best contrasts the lender of last resort and deposit insurance?","options":["Deposit insurance replaces the need for any lender of last resort","Both functions are performed only by the Ministry of Finance","The lender of last resort deals mainly with liquidity problems, while deposit insurance protects depositors when a bank fails","The lender of last resort pays depositors of failed banks, while deposit insurance lends to solvent banks"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The lender of last resort gives temporary liquidity to banks that are short of cash, whereas deposit insurance compensates depositors when a bank actually fails. Option D reverses the two roles, option B assigns them to the wrong body, and option A ignores that the two functions complement each other."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 663, $official_bank_source${"itemId":"7014549f-061b-5d80-9914-2faf2ca33518","questionId":"391b455b-b4e1-5c86-96c5-41a97cb12b05","sourceKey":"bank:FIN216:SNP-016","payload":{"prompt":"When a Nigerian bank fails, which division of roles between the CBN and the NDIC is correct?","options":["The CBN revokes the banking licence and the NDIC acts as liquidator","The NDIC revokes the banking licence and the CBN acts as liquidator","The Ministry of Finance revokes the licence and the SEC acts as liquidator","The NDIC revokes the licence and also acts as lender of last resort"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The CBN, as licensing authority, revokes the licence, and the NDIC is then appointed liquidator and pays insured depositors; this was the pattern in the 1998 and 2006 closures. Option B reverses the roles, and options C and D give powers to bodies that do not hold them."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 664, $official_bank_source${"itemId":"a2d7fbc9-d5b6-52d1-887e-f7ac0bd45b6e","questionId":"c0f0aef8-4a9f-5a95-a56e-1493b7e70f7c","sourceKey":"bank:FIN216:SNP-017","payload":{"prompt":"If the NDIC finds serious unsafe practices in an insured bank and believes the bank's licence should be withdrawn, what does it do?","options":["It asks the SEC to delist the bank's shares","It recommends revocation of the licence to the CBN","It refers the bank to the FSRCC for a vote on the licence","It revokes the licence itself without consulting any agency"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Only the CBN can revoke a banking licence, so the NDIC's power is to recommend revocation (and suspension) to the CBN. Option D overstates the NDIC's powers, option A confuses delisting with licence withdrawal, and option C wrongly treats the FSRCC as a licensing body."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 665, $official_bank_source${"itemId":"942ea84d-59fb-5e7c-8452-a0ab2634d08a","questionId":"9cb4d725-1079-56f2-813c-56c9fa3cc73f","sourceKey":"bank:FIN216:SNP-021","payload":{"prompt":"Under the NDIC Act 2023, insured deposits may be paid on revocation of a licence or when an insured institution has actually suspended payments. In the second case, the NDIC acts","options":["only after the bank's shareholders approve","with the concurrence of the CBN","only after AMCON buys the bank's loans","only with the consent of the SEC"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The 2023 Act lets the NDIC pay depositors when a bank stops paying, not only after licence revocation, but this requires CBN concurrence. Option A would let the failing bank's owners block depositor protection, and options C and D involve bodies with no role in this decision."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 666, $official_bank_source${"itemId":"fb2d4570-ed2b-5abe-b50d-88480965ef50","questionId":"418b739f-b502-5441-9f3c-76ff8e99caa2","sourceKey":"bank:FIN216:SNP-022","payload":{"prompt":"Which of the following is an example of CBN-NDIC collaboration in bank supervision?","options":["Joint development of risk-based supervision and the eFASS returns platform","Joint issue of the naira currency notes","Joint listing of bank shares on the stock exchange","Joint regulation of insurance companies"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The CBN and NDIC jointly developed risk-based supervision and electronic returns platforms such as eFASS so that both use the same data. Option B is a CBN currency role, option D is NAICOM's area, and option C belongs to the capital market."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 667, $official_bank_source${"itemId":"adc5d4c0-6840-5004-8225-aa87b3db6042","questionId":"0c722550-827c-5e22-9eda-98e8d4616ca7","sourceKey":"bank:FIN216:SNP-023","payload":{"prompt":"Under the CBN/NDIC framework for systemically important banks (SIBs), each SIB must submit a recovery plan every year by 1 January to","options":["the Federal Ministry of Finance only","the FSRCC only","both the CBN and the NDIC","the SEC only"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Because both the CBN and NDIC supervise banks and plan for their resolution, SIB recovery plans go to both agencies. Options A, B and D name bodies that do not receive bank recovery plans under this framework."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 668, $official_bank_source${"itemId":"7eaad97b-c838-5fec-9bd3-c15a0d0ff73d","questionId":"9ae7084c-8138-5bc0-8cd5-d6495a3c348e","sourceKey":"bank:FIN216:SNP-024","payload":{"prompt":"Within Nigeria's financial safety net and wider regulatory system, the Securities and Exchange Commission is the regulator of the","options":["pension industry","deposit money banks","insurance industry","capital market"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The SEC regulates the Nigerian capital market and protects investors there. Option C is NAICOM's area, option A is PenCom's area, and option B is supervised by the CBN and NDIC."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 669, $official_bank_source${"itemId":"0422bdbf-2c60-595a-94ff-e1041f741761","questionId":"e2a29e28-3fc9-5c52-8329-ae16a687d243","sourceKey":"bank:FIN216:SNP-025","payload":{"prompt":"Which Nigerian agency is the only body with the mandate to regulate insurance firms and activities?","options":["SEC","NDIC","NAICOM","PenCom"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"NAICOM, the National Insurance Commission, regulates insurance companies. The NDIC, option B, insures bank deposits, which is different from regulating insurance firms; PenCom, option D, regulates pensions; and the SEC, option A, regulates the capital market."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 670, $official_bank_source${"itemId":"25708585-50f0-5ce4-a476-6edbc61f89c2","questionId":"b35835ac-60b5-5e27-aaff-b5ca21bcb083","sourceKey":"bank:FIN216:SNP-026","payload":{"prompt":"A Nigerian worker wants to know which regulator oversees the pension fund administrators that manage her retirement savings. The correct regulator is","options":["Corporate Affairs Commission","PenCom","NAICOM","NDIC"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The National Pension Commission (PenCom) regulates the pension industry, including pension fund administrators. NAICOM, option C, regulates insurance, the NDIC, option D, guarantees bank deposits, and the Corporate Affairs Commission, option A, registers companies."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 671, $official_bank_source${"itemId":"4ebca092-33f8-541c-9a9c-1ce700f73c25","questionId":"742572ef-81aa-53c1-925c-43767ffd0423","sourceKey":"bank:FIN216:SNP-027","payload":{"prompt":"Which statement about the NDIC and NAICOM is correct?","options":["Both bodies regulate insurance companies","Both bodies are departments of the SEC","NAICOM guarantees bank deposits, while the NDIC regulates insurance companies","The NDIC guarantees bank deposits, while NAICOM regulates insurance companies"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Despite the word insurance in both names, the NDIC insures depositors of banks while NAICOM supervises insurance companies. Option C swaps their roles, option A wrongly makes the NDIC an insurance regulator, and option B is false because neither is part of the SEC."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 672, $official_bank_source${"itemId":"274fcdf9-06d9-5aa1-a074-0a768860cffd","questionId":"16263c86-a953-5b92-a1ac-ee860f02e7fc","sourceKey":"bank:FIN216:SNP-028","payload":{"prompt":"In Nigerian financial regulation, FSRCC stands for","options":["Financial Sector Reform and Consolidation Commission","Financial Services Risk Compliance Committee","Financial Stability and Resolution Control Council","Financial Services Regulation Coordinating Committee"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"FSRCC means Financial Services Regulation Coordinating Committee, the body through which Nigeria's financial regulators coordinate. Options A, B and C sound plausible but are not real Nigerian bodies."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 673, $official_bank_source${"itemId":"68a636f5-cfa0-5de6-be7c-7eea6ed28605","questionId":"9ff6e0a7-4db3-5f0d-9f17-ac7737eb1ff7","sourceKey":"bank:FIN216:SNP-030","payload":{"prompt":"The main purpose of the FSRCC is to","options":["set the monetary policy rate","provide a forum for coordination and interaction among financial-sector regulators","pay insured depositors of failed banks","buy non-performing loans from distressed banks"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The FSRCC exists so that regulators can consult and coordinate their regulatory and supervisory work, reducing gaps and overlaps. Option C is the NDIC's role, option A is the Monetary Policy Committee's role, and option D is AMCON's role."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 674, $official_bank_source${"itemId":"9199feca-7901-5582-a0ba-d6df248ec58b","questionId":"3ec2faae-cba3-5324-a31a-ac3c6ac122a5","sourceKey":"bank:FIN216:SNP-031","payload":{"prompt":"Who chairs the Financial Services Regulation Coordinating Committee in Nigeria?","options":["The Managing Director of the NDIC","The Director-General of the SEC","The Minister of Finance","The Governor of the Central Bank of Nigeria"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The FSRCC is chaired by the CBN Governor, and its secretariat sits in the CBN. The NDIC MD, option A, and the SEC DG, option B, are members, while the finance ministry, option C, is represented as a member but does not chair it."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 675, $official_bank_source${"itemId":"caa759d4-73d0-56c3-be68-d144699fd265","questionId":"2d52eaf8-a369-566b-acd4-3d62c36b5158","sourceKey":"bank:FIN216:SNP-032","payload":{"prompt":"The FSRCC first began in April 1994 under the name","options":["Financial Services Coordinating Committee","Monetary Policy Committee","Financial Stability Forum","Bankers' Committee"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The CBN set up the Financial Services Coordinating Committee in April 1994 and renamed it the FSRCC on 27 May 1994. Option C is an international body that later became the Financial Stability Board, and options B and D are separate Nigerian committees."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 676, $official_bank_source${"itemId":"8666a0e9-7723-51fb-9e85-1b05e82fd064","questionId":"dd8c91cb-351d-53a4-8d88-3923fc475960","sourceKey":"bank:FIN216:SNP-033","payload":{"prompt":"The FSRCC was given legal status through","options":["the Investments and Securities Act","the NDIC Act 2023","a 1998 amendment to section 38 of the CBN Act 1991","the AMCON Act 2010"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A 1998 amendment to section 38 of the CBN Act 1991 gave the FSRCC its legal backing, and the CBN Governor formally inaugurated it in May 1999. Option B is the deposit insurance law, option D created AMCON, and option A governs the capital market."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 677, $official_bank_source${"itemId":"e89e4bae-12b7-548b-8a19-f6721ea98e4e","questionId":"2878e781-796e-57d7-a694-ffcf2865a3b1","sourceKey":"bank:FIN216:SNP-034","payload":{"prompt":"As at 2024, which of the following was NOT a member of the FSRCC?","options":["Corporate Affairs Commission","National Pension Commission","Asset Management Corporation of Nigeria","Federal Inland Revenue Service"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The 2024 FSRCC membership was the CBN, NAICOM, PenCom, SEC, NDIC, CAC, FIRS, the Federal Ministry of Finance and the Financial Reporting Council; AMCON was not listed. Options A, B and D were all members."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 678, $official_bank_source${"itemId":"77c5597e-3c46-508a-b705-a2b40f392f2b","questionId":"8a6dbe7a-07cd-5b0d-9ea4-58fcb1527a01","sourceKey":"bank:FIN216:SNP-035","payload":{"prompt":"As at 2024, which of these bodies was a member of the FSRCC?","options":["National Identity Management Commission","Financial Reporting Council of Nigeria","National Bureau of Statistics","Nigerian Communications Commission"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The Financial Reporting Council, which sets accounting and reporting standards, was a member of the FSRCC in 2024 alongside the CBN, NDIC, SEC, NAICOM, PenCom, CAC, FIRS and the finance ministry. Options A, C and D take part in financial inclusion work but were not FSRCC members."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 679, $official_bank_source${"itemId":"6d4351c5-623b-5f58-ad63-5046612471da","questionId":"9dc6d9dd-4d81-54c3-8d7a-62c39ff782e8","sourceKey":"bank:FIN216:SNP-036","payload":{"prompt":"A large Nigerian financial holding company owns a bank, an insurance company and a stockbroking firm. Which arrangement best helps the CBN, NAICOM and SEC avoid gaps and overlaps in supervising this group?","options":["Lender of last resort lending by the CBN","Purchase of the group's bad loans by AMCON","Coordination through the FSRCC","Deposit payout by the NDIC"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"When one group spans banking, insurance and securities, its regulators need a forum to share information and agree on a common approach, which is the FSRCC's purpose. Options A, B and D are crisis or failure tools, not coordination arrangements."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 680, $official_bank_source${"itemId":"5bcdf985-8bbf-5172-a788-6e60704574e3","questionId":"b13be282-4d23-558b-80fc-d856c70d3655","sourceKey":"bank:FIN216:SNP-037","payload":{"prompt":"Under the National Financial Inclusion Strategy, which committee receives annual reports and in turn updates the National Economic Council?","options":["Financial Services Regulation Coordinating Committee","Financial Literacy Implementation Committee","Bankers' Committee","Monetary Policy Committee"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Implementation of the inclusion strategy is reported annually to the FSRCC, which then updates the National Economic Council. Options B, C and D are other committees that do not sit at that level of the reporting chain."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 681, $official_bank_source${"itemId":"e7fefb1d-5827-5ae3-ace6-58cb15cfabcd","questionId":"204ae0ea-9763-5dca-ada2-a856d887c7f6","sourceKey":"bank:FIN216:SNP-038","payload":{"prompt":"Under the 2014 IADI Core Principles, ongoing information sharing and coordination between the deposit insurer and other safety-net participants should be formalised through","options":["informal telephone calls between agency heads","newspaper announcements","the personal discretion of individual examiners","legislation, regulation, memoranda of understanding or legal agreements"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Core Principle 4 asks that information sharing be made formal and ongoing, using laws, regulations, MOUs or legal agreements, so it does not depend on goodwill. Options A, B and C are informal or one-way and give no reliable framework."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 682, $official_bank_source${"itemId":"19006607-a8ce-5008-abef-7b4a86551c0f","questionId":"3fcd3487-af67-5554-b238-b40eced007dd","sourceKey":"bank:FIN216:SNP-039","payload":{"prompt":"A written agreement between two agencies, such as a deposit insurer and a central bank, setting out how they will share information and cooperate, is commonly called a","options":["memorandum of understanding","bridge bank agreement","purchase and assumption agreement","global standing instruction"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A memorandum of understanding (MOU) records how two agencies will cooperate and share information. A purchase and assumption agreement, option C, transfers a failed bank's deposits and assets to a buyer; a bridge bank, option B, is a temporary bank; and a global standing instruction, option D, is a loan recovery tool."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 683, $official_bank_source${"itemId":"f268581c-3640-56ef-9c1b-192edd62a8fa","questionId":"60d8cb1b-9e74-5e79-8768-6337672ff2b3","sourceKey":"bank:FIN216:SNP-040","payload":{"prompt":"Under the 2014 IADI Core Principles, how should confidentiality rules apply to information shared among safety-net participants?","options":["They require all supervisory information to be published to the public","They should stop the deposit insurer from receiving any supervisory information","They apply only to the deposit insurer and not to the central bank","They apply to all participants but should not prevent information sharing within the safety net"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Shared information must stay confidential, but secrecy rules must not block sharing among the safety-net participants themselves. Option B defeats the purpose of coordination, option C wrongly limits the rules to one participant, and option A confuses confidentiality with public disclosure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 684, $official_bank_source${"itemId":"8185db43-d09b-54c0-9801-7ffec95f9543","questionId":"483a1182-146c-5631-b65c-f022da94d24d","sourceKey":"bank:FIN216:SNP-041","payload":{"prompt":"Under the 2014 IADI Core Principles, safety-net participants should exchange information on an ongoing basis and especially when","options":["a bank pays its annual dividend","a bank opens a new branch","a bank changes its auditors","material supervisory actions are taken in respect of member banks"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Information should flow continuously, and most urgently when supervisors take significant action against a member bank, because that is when the deposit insurer must prepare. Options A, B and C are routine events that do not signal possible failure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 685, $official_bank_source${"itemId":"43ae1f94-5d71-57c8-8346-4620caf0eaab","questionId":"f39078f7-8425-5259-83a8-89e65aef8f50","sourceKey":"bank:FIN216:SNP-043","payload":{"prompt":"Under the 2014 IADI Core Principles, which principle covers the deposit insurer's role in contingency planning and crisis management?","options":["Core Principle 6","Core Principle 10","Core Principle 14","Core Principle 4"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Principle 6 of the 2014 set covers contingency planning and crisis management. Option D is about relationships with other safety-net participants, option B is Public awareness, and option C is Failure resolution."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 686, $official_bank_source${"itemId":"40909a79-7389-560f-901a-2576f85d6ab7","questionId":"a7936e6d-ddd8-593f-a160-cfbb504fcffc","sourceKey":"bank:FIN216:SNP-044","payload":{"prompt":"In the revised IADI Core Principles approved in 2025 (18 principles), cooperation, coordination and information sharing among financial safety-net participants is covered by","options":["Core Principle 11","Core Principle 4","Core Principle 17","Core Principle 18"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The 2025 revision moved safety-net cooperation to Principle 17 and cross-border cooperation to Principle 18. Option B was the number for safety-net relationships in the 2014 version, option A is Crisis preparedness and management, and option D is the cross-border principle."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 687, $official_bank_source${"itemId":"90ece8c6-c34d-5379-8fb8-1e4a047c517d","questionId":"feb72a21-dc1d-5f97-a94b-8a0bda864843","sourceKey":"bank:FIN216:SNP-045","payload":{"prompt":"In the revised IADI Core Principles approved in 2025, which principle deals with cross-border cooperation, coordination and information sharing?","options":["Core Principle 16","Core Principle 17","Core Principle 18","Core Principle 5"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Principle 18 is the cross-border principle in the 2025 set of 18. Option D was its number in the 2014 version, option B covers cooperation within the domestic safety net, and option A is Use of the deposit insurance fund in resolution."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 688, $official_bank_source${"itemId":"b3f95405-8085-561a-8830-d1f570c0c8e8","questionId":"9155133f-4c1c-54f5-a8ac-b229b35e62d1","sourceKey":"bank:FIN216:SNP-046","payload":{"prompt":"Under the 2014 IADI Core Principles, system-wide crisis preparedness and management is best described as","options":["the sole responsibility of the deposit insurer","the sole responsibility of the stock exchange","a matter left entirely to the failing bank's shareholders","a joint responsibility of all safety-net participants"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"IADI treats crisis preparedness as shared by all safety-net participants, with the deposit insurer as a member of the coordination framework. Option A puts the whole burden on one agency, while options B and C name parties that cannot manage a systemic crisis."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 689, $official_bank_source${"itemId":"5292d27d-af23-5d10-92cf-9991ae8d198f","questionId":"8b77cda8-57d5-5a42-b4a1-5a26287b5320","sourceKey":"bank:FIN216:SNP-047","payload":{"prompt":"Under the 2014 IADI Core Principles on contingency planning and crisis management, which of the following is NOT expected of the deposit insurer?","options":["Taking part in simulation exercises with all safety-net participants","Developing and regularly testing its own contingency plans","Keeping its contingency plans secret from other safety-net participants","Helping to develop pre- and post-crisis communication plans"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The deposit insurer is expected to plan, test, practise with the other safety-net participants and help prepare consistent public communication. Hiding its plans from other participants would defeat coordination, so that is the odd one out; options A, B and D are all expected practices."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 690, $official_bank_source${"itemId":"8b979aa4-2455-5e42-87f3-c3f9200ecd59","questionId":"c9865fb5-7172-53da-ac9b-22dce61daf59","sourceKey":"bank:FIN216:SNP-048","payload":{"prompt":"Why do safety-net participants prepare joint pre- and post-crisis communication plans?","options":["To give the public consistent messages and maintain confidence during a crisis","To announce changes in the monetary policy rate","To advertise bank products to new customers","To avoid informing depositors about deposit insurance cover"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"In a crisis, conflicting statements from different agencies can trigger runs, so joint communication plans keep messages consistent and calm. Option C is marketing, option B is monetary policy, and option D is the opposite of what public awareness requires."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 691, $official_bank_source${"itemId":"4b5d624c-2128-51fa-b579-5fce41c9ef20","questionId":"3fb12e49-af0e-51fd-9f2f-4c51b6bd345c","sourceKey":"bank:FIN216:SNP-049","payload":{"prompt":"During the 2009 Nigerian banking crisis, after a CBN/NDIC special examination of 24 banks, which confidence-building step did the CBN take?","options":["It assured the public that no bank would be allowed to fail and guaranteed affected banks' interbank and foreign credit obligations","It abolished deposit insurance and replaced it with a blanket government guarantee by law","It asked the SEC to suspend trading in all bank shares permanently","It closed all 24 examined banks and paid off their depositors"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The CBN injected about N620 billion, assured depositors that no bank would be allowed to fail, and guaranteed the affected banks' interbank and foreign credit lines to restore confidence. Option D is wrong because the banks were rescued, not closed; options B and C did not happen."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 692, $official_bank_source${"itemId":"aede277e-49bc-530a-af69-69937d5fc74d","questionId":"448718d0-4922-5a37-9533-8452312ad4e3","sourceKey":"bank:FIN216:SNP-050","payload":{"prompt":"Which of the following is NOT among the international partners the NDIC works with for staff training and exchange of best practice in deposit insurance?","options":["International Monetary Fund","US Federal Reserve","Organization of the Petroleum Exporting Countries","International Association of Deposit Insurers"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The NDIC collaborates with IADI, the IMF, the US Office of Technical Assistance, the US Federal Reserve and similar agencies on training and best practice. OPEC deals with oil policy and has no deposit insurance role, while options A, B and D are genuine partners."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 693, $official_bank_source${"itemId":"89fbf140-fb97-5f7e-8dc9-b5528ad2fa70","questionId":"a87f4e33-4b90-52f8-bb61-30bab1332df4","sourceKey":"bank:FIN216:SNP-051","payload":{"prompt":"In August 2019 the NDIC signed a memorandum of understanding in Seoul with which foreign deposit insurer?","options":["Deposit Insurance and Credit Guarantee Corporation","Federal Deposit Insurance Corporation","Kenya Deposit Insurance Corporation","Korea Deposit Insurance Corporation"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The NDIC and the Korea Deposit Insurance Corporation signed an MOU in Seoul on 7 August 2019 covering communication, joint work and staff exchanges. The FDIC, option B, is American, Kenya's KDIC, option C, shares the same initials but is African, and option A is India's deposit insurer."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 694, $official_bank_source${"itemId":"f5a4d51d-9360-52b8-8ed6-e07e98dd8d56","questionId":"a02b07b6-38b0-5d25-b950-fc2b7396d915","sourceKey":"bank:FIN216:SNP-052","payload":{"prompt":"A bilateral MOU between two national deposit insurers would MOST likely provide for","options":["a merger of the two countries' central banks","one insurer taking over the other's licensing powers","exchange of information, staff training and cooperation on deposit insurance matters","the transfer of one country's insured banks to the other country"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Deposit insurer MOUs are cooperation tools: they set out information exchange, technical assistance, staff exchanges and joint work. Options A, B and D describe transfers of legal power or institutions that an MOU cannot achieve."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 695, $official_bank_source${"itemId":"7d458f41-33ac-5261-ac95-3f5d62ca0138","questionId":"4edf5a8f-81b2-5ed2-9934-0af55f103f60","sourceKey":"bank:FIN216:SNP-053","payload":{"prompt":"Under the 2014 IADI Core Principles, formal information-sharing and coordination arrangements among deposit insurers in different jurisdictions are called for where","options":["there is a material presence of foreign banks","a country has no banks at all","the deposit insurer is privately owned","only domestically owned banks operate"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Cross-border arrangements matter when foreign bank branches or subsidiaries are a significant part of the banking system, because a failure may involve more than one insurer. Options B and D describe situations with no cross-border element, and option C is about ownership, which is irrelevant to the trigger."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 696, $official_bank_source${"itemId":"85e03b64-0196-5813-aaf4-56b04fd4634a","questionId":"e40ee052-bbd8-597a-91ed-3ed9f1e51169","sourceKey":"bank:FIN216:SNP-054","payload":{"prompt":"Under the 2014 IADI Core Principles, where a deposit insurer covers deposits in a foreign jurisdiction or more than one insurer covers the same jurisdiction, bilateral or multilateral agreements should determine","options":["which bank shareholders receive dividends first","which auditor the bank must appoint","which insurer handles reimbursement, premiums and public awareness","which country's currency the bank must use"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Such agreements must settle who pays depositors, who charges premiums and who informs the public, so depositors are not left uncertain. Options A, B and D are not deposit insurance responsibilities."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 697, $official_bank_source${"itemId":"9fa96228-2dd9-5ac6-9c14-420a36534b60","questionId":"55f68716-a2e6-51fe-9407-c794ac61b34d","sourceKey":"bank:FIN216:SNP-055","payload":{"prompt":"Under the 2014 IADI Core Principles, depositors affected by cross-border arrangements (for example, through foreign branches) should be given","options":["an automatic guarantee from both countries' governments","clear information on which deposit insurer is legally responsible for them","no information, to avoid panic","the right to choose any deposit insurer in the world"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"IADI's public awareness principle requires that such depositors be told clearly which deposit insurer is legally responsible for their cover. Option A invents a double guarantee, option D does not exist, and option C contradicts the aim of public awareness."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 698, $official_bank_source${"itemId":"9ed22f8a-ac66-5e9c-8f1c-0566a596b6c5","questionId":"711308c8-f591-5a6e-9928-73909734a407","sourceKey":"bank:FIN216:SNP-056","payload":{"prompt":"A Ghanaian citizen living in Lagos holds an eligible deposit in a Nigerian deposit money bank. Under the 2014 IADI Core Principles, how should the depositor's nationality affect deposit insurance coverage?","options":["The depositor is covered only by Ghana's deposit insurer","The depositor is excluded because he is a foreigner","It has no effect on coverage","The depositor receives half the normal cover"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"IADI states that the residency status or nationality of depositors has no effect on coverage; what matters is that the deposit is eligible and held in a member institution. Options A, B and D all wrongly link coverage to nationality."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 699, $official_bank_source${"itemId":"7bb00913-671b-59d6-8185-cc59ddf459fe","questionId":"fd7eed8b-c380-5d73-b3ff-4699f15077bf","sourceKey":"bank:FIN216:SNP-057","payload":{"prompt":"A foreign banking group operates in Nigeria through a subsidiary that is incorporated and licensed in Nigeria as a deposit money bank. Deposits held in this subsidiary are protected by","options":["no deposit insurer, because the bank is foreign-owned","the SEC, because the parent is listed abroad","the NDIC, because the subsidiary is a Nigerian licensed bank","only the deposit insurer of the parent bank's home country"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A subsidiary is a separate legal entity licensed in the host country, and NDIC membership is compulsory for all licensed banks, so its depositors are covered by the NDIC. Option D would apply, if at all, to a branch arrangement, option A ignores compulsory membership, and option B confuses deposit insurance with securities regulation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 700, $official_bank_source${"itemId":"360ed45f-e70d-5de4-9571-f7001ba5ba3b","questionId":"4635a18a-bb1b-5a0b-84ab-280a25042764","sourceKey":"bank:FIN216:SNP-058","payload":{"prompt":"Mrs Bello has N7.5 million in a foreign-owned deposit money bank incorporated and licensed in Nigeria. The CBN revokes the bank's licence in 2025. How much is she paid as insured deposit by the NDIC?","options":["N5,000,000","N2,000,000","N2,500,000","N7,500,000"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Since May 2024 the NDIC limit for deposit money banks is N5 million per depositor, and a foreign-owned subsidiary licensed in Nigeria is covered like any local bank, so she receives N5 million. The remaining N2.5 million in option C is her uninsured balance, which she can recover only from liquidation dividends; option B is the limit for microfinance and mortgage banks, and option D wrongly assumes full cover."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 701, $official_bank_source${"itemId":"f3f7dfed-c913-5d08-a780-e960bd060dbe","questionId":"254cb736-2c72-5b74-9c0c-9a03109c2a37","sourceKey":"bank:FIN216:SNP-059","payload":{"prompt":"In 2025 Mr Okafor holds N3 million in Bank A and N4 million in Bank B, two separate deposit money banks licensed in Nigeria (Bank B is a subsidiary of a foreign group). Both licences are revoked the same month. Assuming coverage of N5 million per depositor per bank, what is his total insured payment?","options":["N4,000,000","N10,000,000","N7,000,000","N5,000,000"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Coverage applies separately to each insured bank, and each balance is below N5 million, so he is paid N3 million plus N4 million, which is N7 million. Option D wrongly applies one limit across both banks, option B pays the full limit regardless of the balance, and option A wrongly ignores Bank A or treats one bank as uninsured."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 702, $official_bank_source${"itemId":"6bc8a6ab-0717-5568-a111-e77b1d9ccfa7","questionId":"150b6a2a-6f4f-58d1-8a19-090bbe73bbbe","sourceKey":"bank:FIN216:SNP-060","payload":{"prompt":"Under the EU Deposit Guarantee Schemes Directive 2014/49/EU, depositors at a branch that a bank from one EU member state opens in another EU member state are covered by","options":["the deposit guarantee scheme of the host member state only","the deposit guarantee scheme of the bank's home member state","the European Central Bank directly","no scheme, because branches are excluded"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Within the EU, branches are part of the parent bank, so the home country's scheme covers their depositors, with the host scheme often acting as paying agent. Option A describes how subsidiaries are treated, option D is false, and option C is wrong because the ECB is not a deposit insurer."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 703, $official_bank_source${"itemId":"0182d2c1-e4b1-56de-9928-9bc28d5f0e4c","questionId":"ede99ddd-1633-56e6-8a23-b52fc25c49f9","sourceKey":"bank:FIN216:SNP-061","payload":{"prompt":"Which statement best distinguishes a foreign bank subsidiary from a foreign bank branch for deposit insurance purposes?","options":["Both are always covered only by the home country's deposit insurer","A subsidiary is a separate legal entity licensed in the host country, while a branch is legally part of the parent bank","Neither can ever be covered by any deposit insurer","A branch is a separate legal entity, while a subsidiary is legally part of the parent bank"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A subsidiary is locally incorporated and licensed, so it normally joins the host country's deposit insurance scheme, whereas a branch is part of the foreign parent, which is why cross-border agreements are needed to say who covers branch depositors. Option D reverses the two, and options A and C are sweeping statements that are false."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 704, $official_bank_source${"itemId":"0444c6c7-a973-5377-98fe-a431cf75e827","questionId":"ec3ceacd-601d-5e16-a560-e43aa75d704e","sourceKey":"bank:FIN216:SNP-062","payload":{"prompt":"Following the adoption of universal banking in Nigeria in 2001, many banks operated through subsidiaries and affiliates. Which supervisory approach assesses the group as a whole, including risks from parents and subsidiaries?","options":["Transaction-based examination","Solo-based supervision","Off-site surveillance of a single branch","Consolidated supervision"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Consolidated supervision looks at the whole banking group, so no risk in any business segment escapes and capital is not double-counted (double gearing). Solo supervision, option B, focuses on one entity alone, and options A and C are narrower techniques."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 705, $official_bank_source${"itemId":"71822025-6569-50b8-bd77-851ac0259811","questionId":"6295fa21-c6e7-5260-a749-ff835f1df8a9","sourceKey":"bank:FIN216:SNP-063","payload":{"prompt":"Which of the following is among the FSB Key Attributes of Effective Resolution Regimes that deal directly with cross-border matters?","options":["Differential premium assessment system","Crisis Management Groups and institution-specific cross-border cooperation agreements","Pass-through deposit insurance for mobile money","CAMEL rating of individual banks"],"correctOption":1,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The FSB Key Attributes include a legal framework for cross-border cooperation, Crisis Management Groups, institution-specific cross-border cooperation agreements, and information sharing. Options A, C and D are domestic deposit insurance or supervision tools, not cross-border resolution attributes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 706, $official_bank_source${"itemId":"bc4cc918-305a-5ba6-b9c5-4abe8def4881","questionId":"e5f393d4-7a06-519f-b74b-94b122cee48c","sourceKey":"bank:FIN216:SNP-064","payload":{"prompt":"Which of the following is NOT one of the FSB Key Attributes of Effective Resolution Regimes?","options":["Recovery and resolution planning","Access to information and information sharing","Resolvability assessments","Blanket guarantee of all deposits"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The FSB Key Attributes include recovery and resolution planning, resolvability assessments, and access to information and information sharing, aiming to avoid exposing taxpayers to loss. A blanket guarantee is a crisis-time government promise, not one of the attributes; options A, B and C are genuine attributes."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 707, $official_bank_source${"itemId":"053600e7-1cc5-548e-830c-5bc5be8ec452","questionId":"50af5189-6f6e-57be-b3d6-d3209bf6cf62","sourceKey":"bank:FIN216:SNP-068","payload":{"prompt":"During the global financial crisis some countries temporarily protected all deposits beyond normal limits to prevent systemic runs. Such a declaration is called a","options":["co-insurance arrangement","purchase and assumption","differential premium","blanket guarantee"],"correctOption":3,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A blanket guarantee is a declaration by the authorities that deposits, and sometimes other liabilities, are protected beyond the normal limited coverage. Co-insurance, option A, makes depositors bear part of a loss; option C is a pricing method; and option B is a resolution method."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 708, $official_bank_source${"itemId":"38556732-4d44-5f14-b96d-628a6b1285fe","questionId":"c5f9faad-187d-5f24-809a-6f0f092515d5","sourceKey":"bank:FIN216:SNP-070","payload":{"prompt":"Which of the following key measures introduced after the global financial crisis relates most directly to safety-net coordination?","options":["Strengthening information sharing and coordination with other safety-net participants","Reducing coverage levels across countries","Removing deposit insurers from resolution","Lowering the speed of depositor payout"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"Post-crisis reforms called for stronger information sharing and closer coordination among safety-net participants, alongside higher and more harmonised coverage and SIFI resolution. Option D is the reverse of the push for faster payout, option B is the reverse of higher coverage, and option C contradicts the expanded role of deposit insurers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 709, $official_bank_source${"itemId":"3f875199-7c8d-56f6-8f90-3cf30a461138","questionId":"8bc01f8d-1c97-5073-ae94-e38d471f90c1","sourceKey":"bank:FIN216:SNP-071","payload":{"prompt":"Which of the following is NOT among the key new measures introduced because of the global financial crisis?","options":["Identification and resolution of systemically important financial institutions","Adoption of explicit deposit insurance systems","Lower and more divergent coverage levels across countries","Greater convergence in deposit insurance practices across jurisdictions"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"The crisis led to higher and more harmonised coverage, not lower and more divergent limits. Options A, B and D were all genuine post-crisis measures."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 710, $official_bank_source${"itemId":"6d7574ad-3da9-5c82-a80d-fe8b6819ff38","questionId":"04b40f73-6b93-5b6a-a164-fec30ae6edca","sourceKey":"bank:FIN216:SNP-072","payload":{"prompt":"As deposit insurers take on a growing role in financial stability and coordinate more closely with other safety-net participants, which new requirement do they face?","options":["A strong analytical capacity and an understanding of resolution tools","Less need for funding because pay-box duties disappear","Withdrawal from all contact with the central bank","Exclusive reliance on co-insurance"],"correctOption":0,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"A wider role brings wider responsibilities: deposit insurers need strong analysis and must understand resolution tools, and their funding is at risk even for a pay box. Option B ignores that funding pressure, option C contradicts closer coordination, and option D reverses the trend away from co-insurance."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 711, $official_bank_source${"itemId":"45da84e4-fad0-5dbf-8600-af888e063fb6","questionId":"56c535c6-a44b-597d-bac5-5fccdd16090f","sourceKey":"bank:FIN216:SNP-075","payload":{"prompt":"Under the 2014 IADI Core Principles, which of the following elements of the wider safety net helps to mitigate moral hazard created by deposit insurance?","options":["Flat premiums regardless of risk","Unlimited coverage for all depositors","Strong prudential regulation and supervision","Delayed intervention in failing banks"],"correctOption":2,"section":"Safety-Net Participants and Cross-Border Issues","explanation":"IADI explains that moral hazard is reduced by the wider safety net, including strong regulation and supervision, good governance and holding parties at fault responsible, as well as by limited coverage, risk-based premiums and timely intervention. Options A, B and D would all increase risk-taking."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 712, $official_bank_source${"itemId":"c7e57296-be35-51c7-926b-3f48de0b9a34","questionId":"b9f814a7-5ac8-56a7-bdf7-24b24689c1bb","sourceKey":"bank:FIN216:F216-0041","payload":{"prompt":"For a deposit insurance system to be effective, it is essential that the public be informed on an ongoing basis about the ____ of the system.","options":["staff and management","investment returns","benefits and limitations","profits and losses"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Depositors can only rely on deposit insurance if they know both what it does for them (its benefits) and where it stops (its limitations, such as the coverage limit and which deposits are excluded); this is the heart of the IADI principle on public awareness. Options B and D treat the scheme like an investment, which it is not, and option A is internal information that does not help depositors protect themselves."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 713, $official_bank_source${"itemId":"a9350a2d-e456-5dea-8805-18d5dab399a7","questionId":"f2ad1941-14f8-5ac5-90f3-99d6fe93010b","sourceKey":"bank:FIN216:F216-0043","payload":{"prompt":"Under the 2014 IADI Core Principles, Public Awareness is which of the following?","options":["Core Principle 4","Core Principle 6","Core Principle 8","Core Principle 10"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"In the 2014 Core Principles, Principle 10 is Public Awareness, requiring the public to be informed regularly about the benefits and limitations of deposit insurance. Option A is Relationships with other safety-net participants, option B is the deposit insurer's role in contingency planning and crisis management, and option C is Coverage."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 714, $official_bank_source${"itemId":"2611ae8c-f1f3-5d34-b8a5-b12b09fa4030","questionId":"18b89f6d-964d-5136-a48b-04e3674f1931","sourceKey":"bank:FIN216:F216-0043-b","payload":{"prompt":"How many principles are contained in the revised IADI Core Principles for Effective Deposit Insurance Systems issued in November 2014?","options":["18","16","10","25"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"The November 2014 revision reorganised the Core Principles into 16 principles, running from Public policy objectives (Principle 1) to Recoveries (Principle 16). Option A, 18, is tempting because the original 2009 set had 18 principles and the 2025 revision again has 18, but the 2014 version has 16. Options C and D do not match any version."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 715, $official_bank_source${"itemId":"ccc5f61f-6931-5127-967f-72f09f2c50f6","questionId":"88a39b2e-9235-591a-93d2-02d7dbacd5e6","sourceKey":"bank:FIN216:F216-0046","payload":{"prompt":"Under the 2014 IADI Core Principles, 'Relationships with other safety-net participants' is which of the following?","options":["Core Principle 8","Core Principle 10","Core Principle 6","Core Principle 4"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"In the 2014 Core Principles, Principle 4 covers Relationships with other safety-net participants, calling for formal, ongoing information sharing and coordination between the deposit insurer, the central bank, supervisors and others. Option C is the deposit insurer's role in contingency planning and crisis management, option A is Coverage, and option B is Public Awareness."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 716, $official_bank_source${"itemId":"7e9577a8-93a5-535b-bacf-8145bf8f4518","questionId":"e1af86cf-492f-550e-8ff8-b1f145467e21","sourceKey":"bank:FIN216:F216-0049","payload":{"prompt":"What is the full meaning of IADI?","options":["International Association of Deposit Insurance","International Agreement on Deposit Insurance","International Association of Deposit Insurers","International Agreement on Deposit Insurers"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI is the International Association of Deposit Insurers, a non-profit body set up in Basel in 2002 whose members are deposit insurers from around the world. Option A is the most common slip: the last word refers to the institutions (insurers), not the activity (insurance). Options B and D are wrong because IADI is an association, not an agreement."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 717, $official_bank_source${"itemId":"ba1bbd72-8dad-5fae-b691-e420284a898a","questionId":"d22cd36f-71df-5a79-b9c8-647d082ff5a9","sourceKey":"bank:FIN216:F216-0065","payload":{"prompt":"The Core Principles for Effective Deposit Insurance Systems issued in June 2009 were developed jointly by IADI and:","options":["the Basel Committee on Banking Supervision (BCBS)","the World Trade Organization","the Organization of the Petroleum Exporting Countries","the African Development Bank"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"The first internationally agreed Core Principles for Effective Deposit Insurance Systems were a joint product of IADI and the Basel Committee on Banking Supervision, released in June 2009. Bringing in the Basel Committee tied deposit insurance standards to the wider rules for bank supervision. Options D, B and C are international bodies with no role in setting deposit insurance standards."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 718, $official_bank_source${"itemId":"77080c2a-ae6d-58ad-9908-1d538a25858f","questionId":"1770251d-a37c-5b25-b159-7e1311f6a617","sourceKey":"bank:FIN216:F216-0066","payload":{"prompt":"Under IADI's Core Principles for Effective Deposit Insurance Systems, Principle 1 is:","options":["monetary policy objectives","public policy objectives","fiscal policy objectives","reimbursing depositors"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Principle 1 requires a deposit insurance system to state its public policy objectives clearly, such as protecting depositors and contributing to financial stability; it has held first place in the 2009, 2014 and 2025 sets. Options A and C relate to central bank and government budget policy, not to deposit insurance. Option D is a later principle about paying depositors after a bank fails."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 719, $official_bank_source${"itemId":"f738776f-c15a-52ef-813b-1b0cd2407538","questionId":"ca833839-8b21-58da-9dcc-dcff16630797","sourceKey":"bank:FIN216:F216-0067","payload":{"prompt":"Under the first Core Principles for Effective Deposit Insurance Systems (2009), Principle 2 was:","options":["mitigating physical hazard","recoveries","compulsory membership","mitigating moral hazard"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"In the 2009 set, Principle 2 required moral hazard to be reduced, meaning banks and depositors should not take extra risks just because deposits are insured. This is done through design features such as limited coverage and risk-based premiums, and through strong supervision. Option A is not a deposit insurance concept, while options C and B were separate, later principles in the same set."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 720, $official_bank_source${"itemId":"56e72e0d-8fae-5ee5-9fc3-8896a94a4933","questionId":"ee7bdda3-a479-5f90-8db7-e2651d5e9148","sourceKey":"bank:FIN216:F216-0068","payload":{"prompt":"Under the 2009 Core Principles for Effective Deposit Insurance Systems, the 'Powers' principle (Principle 4) states that a deposit insurer should have:","options":["all powers necessary to fulfil its mandate, and these powers should be formally specified","unlimited power to guarantee every deposit in full","only the power to collect premiums from banks","the power to set the country's monetary policy"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"The Powers principle says a deposit insurer needs every power required to carry out its mandate, such as financing reimbursements, entering contracts and getting timely information, and that these powers should be written down formally. Option C is far too narrow, and option D belongs to the central bank. Option B is wrong because deposit insurance is meant to give limited coverage, not a blanket guarantee."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 721, $official_bank_source${"itemId":"0e133455-b9ad-5b56-a863-810136dd80e8","questionId":"3b0119bb-44f5-53e5-9b3b-0c1b745add0d","sourceKey":"bank:FIN216:F216-0070","payload":{"prompt":"In 2009, a joint working group of the Basel Committee on Banking Supervision and IADI produced:","options":["the Financial Sector Assessment Program","the NDIC Act 2006","the Core Principles for Effective Deposit Insurance Systems","the Basel III capital standards"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"A joint working group of the Basel Committee and IADI drafted the Core Principles for Effective Deposit Insurance Systems, issued in June 2009. Option D came from the Basel Committee on its own and deals with bank capital. Option A is an IMF-World Bank programme, and option B is Nigerian law, not an international standard."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 722, $official_bank_source${"itemId":"45876ea5-eee0-54ec-8d1c-9cee97f0933e","questionId":"5d869a7e-494a-5a4e-8731-79a06a8c8c3d","sourceKey":"bank:FIN216:F216-0072","payload":{"prompt":"One way to make a deposit insurance system effective is:","options":["for the public to be informed about its benefits and limitations","for banks to keep details of the coverage confidential","for the public to invest in it","for the public to be able to govern it"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"A deposit insurance system only works if people know it exists, what it covers and what it does not cover, so the public must be informed on an ongoing basis about its benefits and limitations. Informed depositors are less likely to panic and run on banks. Options C and D are wrong because the public neither invests in nor governs the scheme, and option B would defeat the purpose of the scheme."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 723, $official_bank_source${"itemId":"ee5d8c78-04a8-56b9-be26-f64319db43ea","questionId":"5a77bc45-59ba-56cf-acb8-fa0ab7eb43d2","sourceKey":"bank:FIN216:F216-0074","payload":{"prompt":"One main reason why the public should be informed on a regular basis about the benefits and limitations of the deposit insurance system is:","options":["to encourage people to deposit money with the deposit insurer itself","to protect depositors","to contribute to financial stability","Both B and C"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Public awareness helps protect depositors, because they know how much of their money is covered, and it contributes to financial stability, because informed depositors are less likely to start bank runs. So both B and C are correct, making D the best answer. Option A is wrong because the deposit insurer does not take deposits from the public; banks do."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 724, $official_bank_source${"itemId":"77eb0b0b-ff48-5e3d-9fd8-3cea8e43622b","questionId":"1558f29d-15c0-5159-8d1b-d80bafe1b15b","sourceKey":"bank:FIN216:F216-0076","payload":{"prompt":"In the event of a bank failure, the deposit insurer should notify depositors about all of the following EXCEPT:","options":["whether the government will approve or reject the payment when it arises","whether advance or interim payments are being made","where, how and when insured depositors will access their funds","the information insured depositors must provide to obtain payment"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"When a bank fails, depositors need practical information: where, how and when they will get their money, what documents or details they must provide, and whether any advance or interim payments are being made. Payment of insured deposits is the deposit insurer's own legal duty, so depositors are not told to wait for a government decision to approve or reject it. That is why option A is the odd one out, while options C, D and B are all things the insurer should communicate."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 725, $official_bank_source${"itemId":"2bf45585-713f-551f-8b03-de1856e49826","questionId":"e51ba047-e1b7-5d1b-8665-bf9beabcca4e","sourceKey":"bank:FIN216:F216-0077","payload":{"prompt":"The objectives of a deposit insurer's public awareness programme should be clearly set out and consistent with:","options":["the profit targets of member banks","the advertising plans of individual banks","the public policy objectives and mandate of the deposit insurance system","the government's annual budget"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"A public awareness programme is a tool for achieving what the deposit insurance system exists to do, so its objectives must line up with the system's public policy objectives and mandate. Options A and B put the interests of individual banks first, and option D concerns government spending rather than deposit insurance goals."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 726, $official_bank_source${"itemId":"a45a6384-2772-58a8-a120-83f28353f637","questionId":"23d0246e-9d03-5b0b-8123-18c13797fcbe","sourceKey":"bank:FIN216:F216-0078","payload":{"prompt":"An effective public awareness programme for a deposit insurance system should:","options":["build credibility with depositors and other stakeholders","ensure member institutions promote information about deposit insurance","employ a wide variety of tools and channels of communication","all of the above"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"A good awareness programme builds the credibility and reputation of the deposit insurer (A), uses member banks as partners to spread information at the counter and online (B), and uses many channels such as media, printed materials, websites and seminars to reach as many people as possible (C). Since each of these is part of an effective programme, D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 727, $official_bank_source${"itemId":"01b07fa6-ddb6-5743-b8f8-a85db6eacbf0","questionId":"d6fc5327-9772-5b02-ae70-2a74f1102947","sourceKey":"bank:FIN216:F216-0079","payload":{"prompt":"Depending on the goal to be achieved and the stage of development of the deposit insurance system, the target audience of a public awareness campaign:","options":["should be reviewed and updated","should exclude ordinary depositors","should be limited to bank staff","should be fixed permanently once chosen"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"A deposit insurer should keep monitoring public attitudes and reach out to new audiences as its goals and the maturity of the scheme change, so the target audience is reviewed and updated over time. Option D ignores that needs change, for example after a bank failure. Options C and B are wrong because depositors and the general public are the principal audience."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 728, $official_bank_source${"itemId":"f8d7dee4-188f-50d3-ae6f-368cf9f9dcca","questionId":"ba7974d2-1382-531e-bd3b-2df94e722b59","sourceKey":"bank:FIN216:F216-0081","payload":{"prompt":"The principal target audience for a deposit insurer's public awareness campaign is:","options":["only foreign investors","depositors and the general public","only the shareholders of member banks","only the staff of the central bank"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Deposit insurance exists to protect depositors, so depositors and the general public are the main audience that must understand what is covered and how to claim. Other groups, such as member banks, the media and other safety-net participants, matter too, but they are secondary. Options C, A and D each name a narrow group that is not the main focus."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 729, $official_bank_source${"itemId":"aaffc133-728a-5b27-998f-cd5e867b61f6","questionId":"7b1c0bdf-ff1c-59e8-b90a-2233a782b95f","sourceKey":"bank:FIN216:F216-0082","payload":{"prompt":"Beyond depositors, the following are also important target audiences for a deposit insurer's awareness efforts:","options":["government (legislators and other authorities)","the media","students","all of the above"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Legislators and other authorities need to understand deposit insurance because they design and support it, the media both carry the message and need to report it accurately, and students are important future depositors. Each of A, B and C is a recognised audience, so D is correct."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 730, $official_bank_source${"itemId":"0cf68b1e-d253-52ce-a38c-939bcedd6e93","questionId":"6d795688-539e-5af6-a0c3-c5bfb6366364","sourceKey":"bank:FIN216:F216-0083","payload":{"prompt":"Deposit insurers use several communication tools to raise public awareness. These include:","options":["advertisements in electronic and print media","publications such as annual reports and brochures","confidential bank examination reports","Both A and B"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Advertising on television, radio, newspapers and online is usually the most effective way to reach large audiences, and printed publications such as annual reports and brochures give more detail. Both A and B are therefore awareness tools, which makes D correct. Option C is wrong because examination reports are confidential supervisory documents, not public communication."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 731, $official_bank_source${"itemId":"b1ee4d81-d209-53cd-85fe-71d76834891b","questionId":"f75a540a-1eb8-5320-b8df-8dff676793a8","sourceKey":"bank:FIN216:F216-0097","payload":{"prompt":"IADI is a non-profit organisation formed under Swiss law and based in Basel, Switzerland. It is hosted by the:","options":["International Monetary Fund (IMF)","World Bank","Swiss National Bank","Bank for International Settlements (BIS)"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI is domiciled at the Bank for International Settlements in Basel, the international organisation of central banks that also hosts bodies like the Basel Committee. Option C is Switzerland's own central bank, not IADI's host. Options A and B are Washington-based institutions that use IADI's Core Principles in their country assessments but do not host it."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 732, $official_bank_source${"itemId":"772d0986-2ebc-5eb1-92ca-9bd31a8ad51d","questionId":"fd5d07ec-3ece-5310-bd53-e7df143d5fdb","sourceKey":"bank:FIN216:F216-0098","payload":{"prompt":"IADI members conduct research and produce guidance for the benefit of those jurisdictions:","options":["That have already closed down their deposit insurance systems","Seeking to establish or improve a deposit insurance system","That are founding members of IADI only","That operate only a risk-minimiser mandate"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Sharing research and guidance is meant to help any country that wants to set up a new deposit insurance system or strengthen an existing one. Option C is too narrow because IADI's guidance is not limited to its founding members. Option D is also too narrow, since IADI serves pay-box, loss-minimiser and risk-minimiser systems alike, and option A makes no sense as a target audience."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 733, $official_bank_source${"itemId":"94cb4155-37c7-5fd5-b81e-4b8203be9c9e","questionId":"39794c2e-9be7-5602-b217-c1aca82591b0","sourceKey":"bank:FIN216:F216-0100","payload":{"prompt":"One of IADI's stated objectives is to contribute to the stability of financial systems by promoting ________ in the field of deposit insurance.","options":["competition among deposit insurers","cross-border bank mergers","international cooperation","a single global deposit insurance fund"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI brings deposit insurers from many countries together to share knowledge, set standards and work jointly, which is what international cooperation means here. Option A is wrong because IADI encourages collaboration, not rivalry. Options B and D are not IADI goals; each country still runs its own deposit insurance fund."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 734, $official_bank_source${"itemId":"48cff737-a31c-5063-9960-2af0beaf8b2b","questionId":"0c27952c-d432-52ca-9b39-b26d0ceb451b","sourceKey":"bank:FIN216:F216-0101","payload":{"prompt":"In furtherance of its objectives, the activities of IADI cover:","options":["The development of methodologies for the assessment of compliance with its principles, standards and guidelines","The encouragement of voluntary application of its principles, standards and guidelines","The development of principles, standards and guidance to enhance the effectiveness of deposit insurance systems","All of the above"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI develops principles, standards and guidance for effective deposit insurance, encourages countries to apply them voluntarily, and builds methodologies for assessing whether a system complies with them. Since A, B and C are all IADI activities, D is correct; choosing only A and B would leave out its core standard-setting work."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 735, $official_bank_source${"itemId":"032bd7d3-7625-5299-8183-fc6ac97a1682","questionId":"e08eb3d1-030a-55f1-b8dc-29e886dbf01f","sourceKey":"bank:FIN216:F216-0102","payload":{"prompt":"When the organisational structure of IADI is considered, it is governed by:","options":["A legislative council composed of individuals elected by the members","A judicial council composed of individuals elected by the members","An Executive Council composed of individuals elected by the members","A board appointed by the International Monetary Fund"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI's members elect an Executive Council (often called EXCO), which runs the association's affairs between general meetings of members. Options A and B borrow the language of national governments; IADI has no legislative or judicial council. Option D is wrong because IADI is an independent association, not run by the IMF."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 736, $official_bank_source${"itemId":"a940b866-c37d-5031-90fa-609ac45efe87","questionId":"0ff4828c-1601-5095-841c-573f38ea189b","sourceKey":"bank:FIN216:F216-0104","payload":{"prompt":"Around 2012, the standing committees of IADI included:","options":["Finance and Planning Committee","Membership and Communications Committee","Research and Guidance Committee","All of the above"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"In the early 2010s IADI worked through several standing committees, among them a Finance and Planning Committee, a Membership and Communications Committee and a Research and Guidance Committee. Since A, B and C were all IADI committees at that time, D is the answer. IADI has since reorganised its committees, so the names and number change over time."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 737, $official_bank_source${"itemId":"07dafa93-7451-5549-afee-422237c9a788","questionId":"d658f006-098f-5781-8203-ff986f2aea05","sourceKey":"bank:FIN216:F216-0105","payload":{"prompt":"The NDIC is a founding member of IADI, which was officially launched in Basel in:","options":["April 2001","May 2002","June 2003","July 2004"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI was incorporated and formally launched at the Bank for International Settlements in Basel in May 2002, with the NDIC among its founding members. Option A (2001) is when the earlier Financial Stability Forum working group on deposit insurance finished its report, before IADI existed. Options C and D come after the launch, so a founding member could not have joined then."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 738, $official_bank_source${"itemId":"30fa2309-95b2-545c-a7d2-4f8b8fc4b2a7","questionId":"1abf6e82-5a48-5215-ad60-b88013d6f3a5","sourceKey":"bank:FIN216:IAD-001","payload":{"prompt":"In May 2002 the International Association of Deposit Insurers (IADI) was formed in which city?","options":["Washington DC, United States","Basel, Switzerland","London, United Kingdom","Geneva, Switzerland"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI was formed in May 2002 in Basel, Switzerland, where it is still based. Option A is home to the FDIC and the IMF, and option D is another Swiss city but not IADI's base. Option C has no link to IADI's founding."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 739, $official_bank_source${"itemId":"8909502a-afcc-5d9b-85cb-99d96ac5de01","questionId":"d6f15493-558d-567e-a783-2490fb9eaeb0","sourceKey":"bank:FIN216:IAD-003","payload":{"prompt":"Which of the following best describes the legal form of IADI?","options":["An intergovernmental body created by a United Nations treaty","A for-profit reinsurance company owned by deposit insurers","A department of the Basel Committee on Banking Supervision","A non-profit organisation constituted under Swiss law"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI is a non-profit organisation set up under Swiss law and hosted by the BIS in Basel. Option A is wrong because it was not created by a UN treaty, and option B is wrong because it does not sell insurance or make profits. Option C confuses IADI with the BCBS, a separate standard setter that also sits at the BIS."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 740, $official_bank_source${"itemId":"168cbf26-6ff7-5018-8657-fd53ab87c429","questionId":"494832a7-19cf-5d10-8119-e1ba0f4400a5","sourceKey":"bank:FIN216:IAD-004","payload":{"prompt":"IADI grew out of work done by a Working Group on Deposit Insurance set up by which body in the late 1990s?","options":["Organisation of Petroleum Exporting Countries (OPEC)","Financial Stability Forum (FSF)","International Organization of Securities Commissions (IOSCO)","Financial Action Task Force (FATF)"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"A Financial Stability Forum study group (1999) and its Working Group on Deposit Insurance (final report 2001) led to IADI's creation in 2002. Option D deals with money laundering, and option C sets standards for securities markets. Option A is an oil producers' body with no role in deposit insurance."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 741, $official_bank_source${"itemId":"003b190d-ecf9-5561-aa70-3449f049cc0b","questionId":"1cf25039-e59b-51e9-a416-45880c831511","sourceKey":"bank:FIN216:IAD-005","payload":{"prompt":"When IADI was launched in 2002, roughly how many founding members did it have?","options":["25","300","8","103"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI started in 2002 with 25 founding members, and Nigeria's NDIC was among them. Option D is the total number of affiliated organisations (members, associates and partners) reached in March 2016, not the founding number. Option B is far too large and option C far too small."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 742, $official_bank_source${"itemId":"233aecd8-7d7f-5875-ab9c-c10d7748af9e","questionId":"5688c6fa-574a-5e13-88c9-2e710864a6c7","sourceKey":"bank:FIN216:IAD-006","payload":{"prompt":"Tunde says Nigeria joined IADI only after the 2008-09 global financial crisis. Which statement correctly corrects him?","options":["Nigeria cannot join IADI because it has no explicit deposit insurance law","The NDIC was one of IADI's founding members when IADI was formed in 2002","The CBN, not the NDIC, represents Nigeria in IADI as a Member","Nigeria joined IADI only after the NDIC Act 2023 was passed"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Nigeria, through the NDIC, is a founding member of IADI, so it has been part of the association since 2002. Option C is wrong because IADI Members are deposit insurers such as the NDIC, not central banks. Options A and D are wrong because Nigeria has had an explicit scheme since 1988 and was in IADI long before 2023."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 743, $official_bank_source${"itemId":"39d7f475-6b94-56d1-8cb4-66c7ba138644","questionId":"67d651a9-a03c-520e-b924-2de11331b640","sourceKey":"bank:FIN216:IAD-007","payload":{"prompt":"Which of the following lists these events in the correct time order (earliest first)?","options":["IADI is formed; NDIC begins operations; first Core Principles issued; Core Principles revised to 16","NDIC begins operations; IADI is formed; first Core Principles issued; Core Principles revised to 16","NDIC begins operations; first Core Principles issued; IADI is formed; Core Principles revised to 16","IADI is formed; first Core Principles issued; NDIC begins operations; Core Principles revised to 16"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"The NDIC began operations in 1989, IADI was formed in 2002, the first Core Principles were issued in 2009 and the revised set of 16 came in 2014. Option A wrongly puts IADI before the NDIC, which actually helped found it. Options C and D place the Core Principles before IADI existed, which is impossible because IADI helped write them."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 744, $official_bank_source${"itemId":"97f300aa-0d99-51fa-b71d-15c924c5fb91","questionId":"c3c84077-4b88-5706-9468-d96c13799b9c","sourceKey":"bank:FIN216:IAD-008","payload":{"prompt":"The NDIC sends its staff to IADI training events and uses them to compare notes with other deposit insurers. This reflects which function of IADI?","options":["A global fund that reimburses depositors of failed banks","A supervisor that examines banks in member countries","A lender of last resort to deposit insurers short of cash","A forum for sharing knowledge, training and best practices among deposit insurers"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI describes itself as the principal forum where deposit insurers meet to share knowledge and expertise, and it provides training and technical assistance. Option C is a central bank function, and option B belongs to national supervisors such as the CBN and NDIC. Option A is wrong because IADI does not pay any depositors; national insurers do."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 745, $official_bank_source${"itemId":"9b02e6ae-1baf-5fd9-9224-ec5f7f0dfc09","questionId":"c0cc6748-f9e9-5ec3-8120-0223c27ff6eb","sourceKey":"bank:FIN216:IAD-009","payload":{"prompt":"In the mid-2010s IADI stated its mission as which of the following?","options":["To supervise and license deposit money banks in member jurisdictions so that bank failures become less frequent","To act as lender of last resort to central banks and deposit insurers during financial crises","To provide a single global insurance fund that pays depositors directly whenever member banks fail","To contribute to the enhancement of deposit insurance effectiveness by promoting guidance and international cooperation"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI's mission was to enhance the effectiveness of deposit insurance by promoting guidance and international cooperation. Option A is a national supervisor's job, and option C is wrong because IADI holds no fund for depositors. Option B describes a central bank role, not IADI's."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 746, $official_bank_source${"itemId":"5be154c0-a073-5ae7-a029-0cbf457b0d54","questionId":"c4dad06a-d8df-5e30-96e1-86b0a1056377","sourceKey":"bank:FIN216:IAD-010","payload":{"prompt":"Which of the following is NOT one of IADI's objectives?","options":["To pay insured depositors directly when a member's bank fails","To provide guidance for establishing new deposit insurance systems and enhancing existing ones","To contribute to financial system stability by promoting international cooperation in deposit insurance","To encourage wide international contact among deposit insurers and other interested parties"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Paying insured depositors is the job of each national deposit insurer, such as the NDIC, not IADI. Options B, C and D are all genuine IADI objectives: promoting stability through international cooperation, giving guidance on setting up and improving schemes, and encouraging contact among deposit insurers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 747, $official_bank_source${"itemId":"3fc5053d-6775-5d4b-b94f-4d13565cff7a","questionId":"9e986dd3-5648-52de-9568-e340c4f92be0","sourceKey":"bank:FIN216:IAD-011","payload":{"prompt":"Today IADI describes itself as the global ______ for deposit insurance systems.","options":["lender of last resort","bank licensing authority","standard-setter","credit rating agency"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI calls itself the global standard-setter for deposit insurance systems; its main standard is the Core Principles for Effective Deposit Insurance Systems. Option A is a central bank role, and option D describes firms that grade borrowers. Option B is wrong because only national authorities such as the CBN license banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 748, $official_bank_source${"itemId":"7f8b6a02-9a81-52b5-b404-554b0406291f","questionId":"8f543a0e-458b-5f82-b29f-058738327059","sourceKey":"bank:FIN216:IAD-012","payload":{"prompt":"Which of the following is NOT an activity of IADI?","options":["Licensing and examining commercial banks in member countries","Developing principles and guidance such as the Core Principles","Carrying out research on deposit insurance issues","Providing training and technical assistance to deposit insurers"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI does not license or examine banks; that is done by national authorities like the CBN and NDIC. Options B, C and D are genuine IADI activities: it sets the Core Principles, trains and assists deposit insurers, and publishes research."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 749, $official_bank_source${"itemId":"383379e7-1d22-5060-b6a4-a7287ab885cc","questionId":"659d42ae-7fce-5420-b473-861e260b60fc","sourceKey":"bank:FIN216:IAD-013","payload":{"prompt":"A country with no formal deposit insurance wants international guidance on how to design an explicit scheme. Which body is the most appropriate source?","options":["International Association of Deposit Insurers (IADI)","International Organization of Securities Commissions (IOSCO)","International Association of Insurance Supervisors (IAIS)","Financial Action Task Force (FATF)"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI exists partly to give guidance on establishing new deposit insurance systems and improving existing ones. Option B sets standards for securities markets, and option C for insurance companies such as life and motor insurers. Option D deals with anti-money-laundering standards."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 750, $official_bank_source${"itemId":"08eea277-d4f9-5b67-824f-5b0ac6b23b12","questionId":"42ed25b1-823a-5117-aae7-12aef0f1c7a8","sourceKey":"bank:FIN216:IAD-014","payload":{"prompt":"Which pairing of international standard-setter and area is correct?","options":["IADI - deposit insurance systems","IADI - banking supervision and capital rules","IOSCO - deposit insurance premiums","BCBS - deposit insurance coverage limits"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI sets standards for deposit insurance, while the Basel Committee (BCBS) sets standards for banking supervision and capital. Option B gives IADI the BCBS's area, and option D gives the BCBS IADI's area. Option C is wrong because IOSCO covers securities markets."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 751, $official_bank_source${"itemId":"d263d618-2299-5fb4-920b-3845e941f1bc","questionId":"6d681d01-daeb-5f6e-bdb4-3bad333c8d6a","sourceKey":"bank:FIN216:IAD-015","payload":{"prompt":"Alongside the Core Principles for Effective Deposit Insurance Systems, Nigeria's DIS framework draws on the Core Principles for Effective Banking Supervision. Which body issues the banking supervision principles?","options":["Financial Services Regulation Coordinating Committee (FSRCC)","Nigeria Deposit Insurance Corporation (NDIC)","Basel Committee on Banking Supervision (BCBS)","International Association of Deposit Insurers (IADI)"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"The Core Principles for Effective Banking Supervision are issued by the Basel Committee on Banking Supervision. Option D issues the deposit insurance principles, not the supervision ones. Options A and B are Nigerian bodies that apply international standards but do not issue them."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 752, $official_bank_source${"itemId":"6206f7ae-5ad0-53b7-b279-3400f8794c8d","questionId":"df48f0a0-93e6-56af-b899-0f3d9e8d6aa5","sourceKey":"bank:FIN216:IAD-016","payload":{"prompt":"The IMF and World Bank use the IADI Core Principles when reviewing a country's deposit insurance system as part of which programme?","options":["CAMEL rating system","Financial Sector Assessment Program (FSAP)","Differential Premium Assessment System (DPAS)","Structural Adjustment Programme (SAP)"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"The Core Principles are used in Financial Sector Assessment Program reviews carried out by the IMF and World Bank. Option D was a 1980s economic reform programme, and option C is the NDIC's risk-based premium system. Option A is a bank rating tool used by supervisors, not a country assessment programme."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 753, $official_bank_source${"itemId":"efbf6b69-52f4-59c4-a357-caf1cc2c82cf","questionId":"4966ccae-178e-5162-8dec-f0a2248ce4e6","sourceKey":"bank:FIN216:IAD-017","payload":{"prompt":"The IADI Core Principles for Effective Deposit Insurance Systems are recognised as one of the key international standards for sound financial systems listed by which body?","options":["World Trade Organization (WTO)","Economic Community of West African States (ECOWAS)","Financial Stability Board (FSB)","African Development Bank (AfDB)"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"The Core Principles are part of the FSB's list of key international standards for sound financial systems. Option A deals with trade rules, option D is a development lender, and option B is a regional economic community; none of them keeps that list."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 754, $official_bank_source${"itemId":"54963b72-a9cc-57f4-a577-8f5ab968dd15","questionId":"ee97cc23-9943-594d-9355-b202bc10ea3a","sourceKey":"bank:FIN216:IAD-018","payload":{"prompt":"Which body is the supreme governing authority of IADI?","options":["The General Meeting of Members","The Africa Regional Committee","The Executive Council","The Secretariat"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"The General Meeting of Members is IADI's highest authority; it elects officers such as the President and approves the budget and annual report. Option C manages IADI's affairs but answers to the General Meeting. Option D is the permanent staff in Basel, and option B is only one of the regional groupings."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 755, $official_bank_source${"itemId":"87e259df-7e1b-5f4f-926f-4d5ff940a0fb","questionId":"1a10fd5f-6a01-5290-b1bc-248689b72b22","sourceKey":"bank:FIN216:IAD-019","payload":{"prompt":"Which IADI body, made up of individuals elected at the Annual General Meeting, manages the Association's affairs between general meetings?","options":["The Secretariat","The Executive Council","The General Meeting of Members","The Regional Committees"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"The Executive Council (EXCO) is elected by the members at the AGM and manages IADI's affairs. Option A is the salaried staff, not an elected body. Option C is the full meeting of members that elects the Council, and option D groups members by region."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 756, $official_bank_source${"itemId":"0e643da0-9e7b-556b-9e1a-e972348bec92","questionId":"a25dc79a-82a7-5ee8-9130-4bfa02af49aa","sourceKey":"bank:FIN216:IAD-020","payload":{"prompt":"Who chairs IADI's Executive Council?","options":["The chair of the Africa Regional Committee","The General Manager of the BIS","The Secretary General","The IADI President"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"The President of IADI also chairs the Executive Council and is elected by the General Meeting. Option C heads the Secretariat, the permanent staff. Option B runs the BIS, which only hosts IADI, and option A leads one regional committee."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 757, $official_bank_source${"itemId":"e1f7b8b4-ffb6-54eb-8059-59f8cf66069c","questionId":"463f8a69-c4c5-595d-a8c9-43d38b1b71ab","sourceKey":"bank:FIN216:IAD-021","payload":{"prompt":"IADI's permanent Secretariat in Basel is headed by the:","options":["Treasurer","Chair of the General Meeting","President","Secretary General"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"The Secretariat in Basel is led by the Secretary General, assisted by a Deputy Secretary General. Option C chairs the Executive Council rather than running the Secretariat. Option A is the officer responsible for finances, and option B is not a post that runs day-to-day staff."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 758, $official_bank_source${"itemId":"95115183-9843-551f-a10e-dc39e6644fce","questionId":"3d5f320e-3609-5a56-a153-2f4af6862bc2","sourceKey":"bank:FIN216:IAD-022","payload":{"prompt":"IADI wants a group of member experts to carry out its technical work on research and training. Which body sets up these committees?","options":["The Basel Committee on Banking Supervision","Each member's national parliament","The Bank for International Settlements","The Executive Council"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI's Council Committees (earlier called Standing Committees) are established by the Executive Council to carry out its work programme. Option C only hosts IADI and does not run its committees. Option A is a separate standard setter, and option B has no role in IADI's internal structure."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 759, $official_bank_source${"itemId":"80db4502-3498-5df2-9d4a-bc455c76a8b1","questionId":"83ae2acd-2dae-520d-88dc-cf38d9c7f18d","sourceKey":"bank:FIN216:IAD-024","payload":{"prompt":"Which of the following is NOT one of IADI's Regional Committees?","options":["Africa Regional Committee","Eurasia Regional Committee","Caribbean Regional Committee","West Africa Regional Committee"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI has one committee for the whole of Africa, not a separate West Africa committee. Options A, B and C are genuine IADI Regional Committees, alongside Asia-Pacific, Europe, Latin America, Middle East and North Africa, and North America."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 760, $official_bank_source${"itemId":"4b97dc7b-b2f0-50e0-bc68-25b76d3a4d04","questionId":"37b8505c-b712-57a1-8925-8d5064a667e8","sourceKey":"bank:FIN216:IAD-025","payload":{"prompt":"Within IADI's regional structure, the NDIC belongs to which committee?","options":["Eurasia Regional Committee","Africa Regional Committee","Middle East and North Africa Regional Committee","Europe Regional Committee"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"As a deposit insurer in Nigeria, the NDIC belongs to the Africa Regional Committee (ARC), which listed Nigeria among its members in 2016. Option C covers North African and Middle Eastern countries. Options A and D cover jurisdictions in Europe and Central Asia."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 761, $official_bank_source${"itemId":"3bf530a0-88f3-5021-821c-34ad57236bc1","questionId":"680f1119-2a28-51ae-9f81-f4143f430cb5","sourceKey":"bank:FIN216:IAD-026","payload":{"prompt":"In 2015-16, which of the following was a stated focus of IADI's Africa Regional Committee?","options":["Building capacity among African deposit insurers and extending deposit insurance to mobile banking products","Running a joint deposit insurance fund for all African depositors","Setting a single policy interest rate for all African central banks","Licensing banks that operate in more than one African country"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"In 2015-16 the Africa Regional Committee focused on capacity building, recruiting new members and the legal framework for covering mobile banking products to support financial inclusion. Option C is a monetary policy task, and option D is a job for national licensing authorities. Option B is wrong because each country keeps its own deposit insurance fund."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 762, $official_bank_source${"itemId":"4c87ce97-ceb9-5c91-a7b0-1f102eee8d4a","questionId":"c733f1b4-a772-51e7-8b97-f79925baaf6e","sourceKey":"bank:FIN216:IAD-027","payload":{"prompt":"What is the main purpose of IADI's Regional Committees?","options":["To collect deposit insurance premiums from the banks in each region","To bring together members in a region to address shared regional issues and hold regional events","To supervise and examine the banks in each region on behalf of IADI","To approve the deposit insurance coverage limit of each country in the region"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Regional Committees group members by region so they can share experience on common regional issues; each holds events in its region at least once a year. Options A and C are national functions carried out by bodies like the CBN and NDIC. Option D is wrong because coverage limits are set nationally, not approved by IADI."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 763, $official_bank_source${"itemId":"de094f77-d52c-5f8d-89fe-1437a90e2715","questionId":"50343701-6370-536b-b594-4292b18ab8ef","sourceKey":"bank:FIN216:IAD-028","payload":{"prompt":"Entities that, under law or agreement, have a deposit insurance system and have been approved for membership of IADI are called:","options":["Partners","Members","Observers","Associates"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Members are deposit insurers that operate a deposit insurance system under law or agreement and have been admitted to IADI; the NDIC is an example. Option D describes bodies that do not yet meet all Member criteria. Options A and C are not-for-profit organisations such as international bodies."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 764, $official_bank_source${"itemId":"21beb178-5ef3-5cb7-aea7-2e0fb405d208","questionId":"d10be4e6-c304-52ab-b5c1-013162880dd5","sourceKey":"bank:FIN216:IAD-029","payload":{"prompt":"In IADI, entities that do not meet all the criteria for full membership but are considering setting up a deposit insurance system, or are part of a financial safety net with a direct interest in deposit insurance, are called:","options":["Partners","Members","Associates","Observers"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Associates are bodies such as central banks and supervisors that are not yet deposit insurers but are considering one or are part of the safety net. Option B requires an existing deposit insurance system. Options A and D are not-for-profit organisations such as international institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 765, $official_bank_source${"itemId":"82b74a53-6c00-5a95-a1d5-ec0bce684094","questionId":"a09d6d32-bc1f-5151-9e12-0af586717189","sourceKey":"bank:FIN216:IAD-030","payload":{"prompt":"Not-for-profit entities, such as international organisations, that do not meet the criteria to be Associates but have a direct interest in effective deposit insurance systems are known in IADI as:","options":["Members","Partners","Associates","Observers"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Observers are not-for-profit bodies with an interest in deposit insurance that do not qualify as Associates. Option B also covers not-for-profit bodies, but Partners have a formal cooperative arrangement with IADI. Options A and C are safety-net bodies and deposit insurers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 766, $official_bank_source${"itemId":"f75e513e-c52f-51f3-b3ba-79bf9f8a0a16","questionId":"b888c322-ccf2-550d-9cf9-ba4d7618df5b","sourceKey":"bank:FIN216:IAD-031","payload":{"prompt":"Not-for-profit entities, such as international institutions, that enter into a cooperative arrangement with IADI to pursue its objects are called:","options":["Associates","Observers","Partners","Members"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Partners are not-for-profit bodies, often international institutions, that have a cooperative arrangement with IADI. Option B also covers not-for-profit bodies but has no cooperative arrangement, only an interest. Options A and D cover safety-net bodies and deposit insurers."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 767, $official_bank_source${"itemId":"36d95a4f-8a2d-582d-8f78-846a65868a57","questionId":"69ef8316-eb9b-58a7-b606-b0c426955550","sourceKey":"bank:FIN216:IAD-032","payload":{"prompt":"The central bank of a country with no deposit insurance law is studying whether to create a deposit insurance system and wants to join IADI. Which category fits it best?","options":["Partner","Observer","Member","Associate"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"A central bank considering a deposit insurance system does not yet meet the Member criteria but has a direct interest as part of the safety net, which is the Associate category. Option C requires an existing deposit insurance system. Options A and B are for not-for-profit organisations such as international institutions, not national central banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 768, $official_bank_source${"itemId":"ed9822b1-f874-5987-b972-d839516f240f","questionId":"3e8a2df0-6b74-53f4-8325-72cc8da2eff8","sourceKey":"bank:FIN216:IAD-033","payload":{"prompt":"The NDIC operates Nigeria's deposit insurance system under the NDIC Act. In which IADI category does it participate?","options":["Member","Observer","Partner","Associate"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"The NDIC runs a deposit insurance system established by law, which is exactly what qualifies an entity as an IADI Member. Option D is for bodies that are only considering a system or are other safety-net participants. Options B and C are for not-for-profit organisations such as international institutions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 769, $official_bank_source${"itemId":"3f442d92-17ea-5d14-ab63-ba9df744eda8","questionId":"eef47521-9180-5ce5-98b6-e745c687a6ed","sourceKey":"bank:FIN216:IAD-034","payload":{"prompt":"What mainly distinguishes an IADI Partner from an IADI Observer?","options":["A Partner has entered into a cooperative arrangement with IADI; an Observer only has an interest in deposit insurance","A Partner must run a deposit insurance system; an Observer must be a central bank","A Partner is a profit-making firm; an Observer is a government ministry","A Partner pays the highest fees; an Observer has full voting rights"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Both Partners and Observers are not-for-profit bodies, but Partners have a cooperative arrangement with IADI to pursue its objects. Option B describes Members and Associates instead. Options C and D are wrong because both categories are not-for-profit bodies and neither description matches IADI's categories."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 770, $official_bank_source${"itemId":"34b0fe24-f1f9-52fd-9610-ccaa85de105c","questionId":"76a1b7b0-c218-5a2f-b128-1577c4eebf15","sourceKey":"bank:FIN216:IAD-035","payload":{"prompt":"Which of the following is NOT a category of participation in IADI?","options":["Shareholders","Partners","Associates","Members"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI is a non-profit association, so it has no shareholders. Options B, C and D are genuine categories: Members are deposit insurers, Associates are mainly central banks and supervisors, and Partners are other interested organisations with a cooperative arrangement."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 771, $official_bank_source${"itemId":"1fe49a91-1374-57ea-b4ed-7fe1e254ed00","questionId":"d65645f9-dd8e-515f-bc74-595feb017df5","sourceKey":"bank:FIN216:IAD-036","payload":{"prompt":"As at 31 March 2016, IADI had 80 Members, 10 Associates and 13 Partners. How many organisations were affiliated with IADI in total?","options":["90","80","103","93"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Adding the three categories gives 80 + 10 + 13 = 103 affiliated organisations. Option A adds only Members and Associates, and option D adds only Members and Partners. Option B counts the Members alone."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 772, $official_bank_source${"itemId":"956376b4-5e38-581d-b1bd-93dd11941a00","questionId":"42816742-0d3a-54bb-ac26-3ba68de62630","sourceKey":"bank:FIN216:IAD-037","payload":{"prompt":"As at 31 March 2016, IADI's Associates were mainly which type of institution?","options":["Private insurance companies","Commercial banks and microfinance banks","Credit rating agencies","Central banks and bank supervisors"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"In March 2016 IADI's 10 Associates were primarily central banks and bank supervisors, which are safety-net bodies with a direct interest in deposit insurance. Option B is wrong because banks are insured by deposit insurers, not IADI participants. Options A and C are private firms that do not fit the Associate category."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 773, $official_bank_source${"itemId":"c3194b56-0f35-50bc-8f31-282eb91e50f3","questionId":"240e3698-3966-5ec1-a464-60c0c6e97e30","sourceKey":"bank:FIN216:IAD-038","payload":{"prompt":"By September 2025, roughly how many Members did IADI have?","options":["About 300","Just over 100","About 50","About 25"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"By September 2025 IADI had about 108-109 Members from nearly 100 jurisdictions, so just over 100. Option D is close to the number of founding members in 2002. Option A is far too high and option C far too low."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 774, $official_bank_source${"itemId":"3db1ccaa-1490-53ef-bbbc-27ceee3f0783","questionId":"577f01bc-876f-51af-95af-177fc989fe13","sourceKey":"bank:FIN216:IAD-040","payload":{"prompt":"In which year were the first Core Principles for Effective Deposit Insurance Systems issued?","options":["2009","2002","1999","2014"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"The BCBS and IADI completed the first Core Principles in March 2009 and issued them in June 2009. Option B is when IADI itself was formed, and option D is when the principles were revised. Option C is when the Financial Stability Forum's study group on deposit insurance began."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 775, $official_bank_source${"itemId":"0903f832-319e-52b8-990c-d6647b5b97f6","questionId":"cfcb4c9c-d993-5da5-99d4-7bd0fb21f033","sourceKey":"bank:FIN216:IAD-041","payload":{"prompt":"How many Core Principles were in the original 2009 set issued by the BCBS and IADI?","options":["25","18","12","16"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"The original 2009 set had 18 Core Principles; the 2014 revision reduced them to 16. Option D is the 2014 count, not the 2009 count. Options A and C do not match any version of the principles."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 776, $official_bank_source${"itemId":"36e0d03c-68f6-5a6e-8d99-fdc109d97da0","questionId":"b7b871ed-ed37-528a-93e3-388438a2adff","sourceKey":"bank:FIN216:IAD-042","payload":{"prompt":"The methodology for assessing compliance with the 2009 Core Principles was completed in:","options":["September 2025","December 2010","November 2014","May 2002"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"The compliance assessment methodology for the 2009 Core Principles was completed in December 2010. Option D is when IADI was formed, option C is when the revised principles (with an updated methodology) were issued, and option A is when the 2025 revision was approved."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 777, $official_bank_source${"itemId":"8ea9f503-0f6a-55ff-b6aa-1748265b937f","questionId":"6c8aea46-2b0f-507b-afe6-e5eecf844fd3","sourceKey":"bank:FIN216:IAD-044","payload":{"prompt":"Which of the following organisations was NOT part of the joint working group that helped IADI develop the 2014 revised Core Principles?","options":["Basel Committee on Banking Supervision (BCBS)","International Monetary Fund (IMF)","Organisation of Petroleum Exporting Countries (OPEC)","World Bank"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"OPEC is an oil producers' group and played no part in revising the Core Principles. Options A, B and D were genuine members of the joint working group, together with the EFDI, the European Commission and the FSB."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 778, $official_bank_source${"itemId":"3d8d40ac-0e1b-55b5-bd53-0a1adbcdf752","questionId":"e1c0ca27-e95c-5751-b342-7eb643422f20","sourceKey":"bank:FIN216:IAD-045","payload":{"prompt":"Under the 2014 IADI Core Principles, Core Principle 1 (Public policy objectives) states that the principal public policy objectives of deposit insurance are to:","options":["License new banks and set lending rates","Control inflation and stabilise the exchange rate","Maximise bank profits and fund government spending","Protect depositors and contribute to financial stability"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 1 (2014) names protecting depositors and contributing to financial stability as the principal objectives. Option B describes monetary policy goals of a central bank. Options A and C are not deposit insurance objectives at all."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 779, $official_bank_source${"itemId":"30c25892-dcd8-566d-9643-b203f064a414","questionId":"200fe65a-5e1b-5bcf-847c-06a06ffb31f7","sourceKey":"bank:FIN216:IAD-046","payload":{"prompt":"Under Core Principle 1 of the 2014 IADI Core Principles, a deposit insurance system's public policy objectives should be:","options":["Kept confidential to avoid panic","Agreed informally between the insurer and banks","Formally specified and publicly disclosed","Set afresh each year by the largest bank"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 1 (2014) says the objectives should be formally specified and publicly disclosed, and the system's design should reflect them. Option A is the opposite of disclosure. Options B and D are wrong because objectives must be formal and set by policymakers, not by banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 780, $official_bank_source${"itemId":"6b719e65-2212-50d4-a6b4-f6a201b973b3","questionId":"151dcd47-9095-5d7a-ac83-d7c358134563","sourceKey":"bank:FIN216:IAD-047","payload":{"prompt":"The NDIC Act 2006 did not state the public policy objectives of Nigeria's deposit insurance system, but section 2 of the NDIC Act 2023 now does. This change brings Nigeria in line with which 2014 IADI Core Principle?","options":["Recoveries (Core Principle 16)","Coverage (Core Principle 8)","Public policy objectives (Core Principle 1)","Membership (Core Principle 7)"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 1 (2014) requires public policy objectives to be formally specified, which the NDIC Act 2023 now does in section 2. Option B is about the level and scope of cover, and option A is about recovering claims from failed banks. Option D is about which banks must join the scheme."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 781, $official_bank_source${"itemId":"a6d6fd6b-92d1-5002-ba8f-377891916466","questionId":"0b982253-31ea-5d73-bd73-28ff0e40e8d8","sourceKey":"bank:FIN216:IAD-048","payload":{"prompt":"Under the 2014 IADI Core Principle 2 (Mandate and powers), the deposit insurer's mandate and powers should be:","options":["Decided case by case after each bank failure","Agreed verbally with the Minister of Finance","Set out only in the insurer's annual report","Clearly defined and formally specified in legislation"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 2 (2014) says the mandate and powers should support the public policy objectives and be clearly defined and formally specified in legislation. Options A and B lack the legal certainty the principle requires. Option C is wrong because an annual report is not legislation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 782, $official_bank_source${"itemId":"cee8ee43-5ccc-5cbe-a538-3c051a701311","questionId":"4a240c89-2a0a-5874-bda3-0ef4f428c495","sourceKey":"bank:FIN216:IAD-049","payload":{"prompt":"Under the 2014 IADI Core Principle 3 (Governance), which of the following is NOT a required feature of the deposit insurer?","options":["Being subject to day-to-day direction by the Minister of Finance","Being transparent and accountable","Being insulated from external interference","Being operationally independent"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 3 (2014) requires the deposit insurer to be operationally independent, well-governed, transparent, accountable and insulated from external interference, so daily ministerial direction goes against it. Options B, C and D are all features the principle requires."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 783, $official_bank_source${"itemId":"b5061d5e-6e42-50b0-b428-6d2696555e2a","questionId":"7e2b2af9-dfd5-5a79-b211-576e8dd04378","sourceKey":"bank:FIN216:IAD-050","payload":{"prompt":"The NDIC and the CBN sign an agreement to share bank examination reports and coordinate their actions on an ongoing basis. Which 2014 IADI Core Principle does this mainly satisfy?","options":["Legal protection","Public awareness","Relationships with other safety-net participants","Cross-border issues"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 4 (2014) calls for a formal, comprehensive framework for close coordination and information sharing between the deposit insurer and other safety-net participants such as the central bank. Option D is about deposit insurers in different countries. Option A protects staff from lawsuits, and option B is about informing the public."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 784, $official_bank_source${"itemId":"fd17b4e8-95fc-5ecf-84ac-d756dbe38eec","questionId":"653209e9-d6fd-54f7-b9dd-66c7e4bb1c6d","sourceKey":"bank:FIN216:IAD-051","payload":{"prompt":"Several foreign-owned banks have a large presence in Nigeria, so the NDIC signs information-sharing agreements with deposit insurers in those banks' home countries. Which 2014 IADI Core Principle does this reflect?","options":["Relationships with other safety-net participants","Cross-border issues","Membership","Recoveries"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 5 (2014) says that where foreign banks have a significant presence, formal information-sharing and coordination arrangements should exist among deposit insurers in the relevant jurisdictions. Option A deals with coordination with domestic safety-net bodies such as the CBN. Options C and D cover compulsory membership and recovering claims."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 785, $official_bank_source${"itemId":"2a05d707-ccd7-55ce-b1b6-861ec9d5123a","questionId":"eafc76b5-2b6b-573c-a097-f374bda89e8d","sourceKey":"bank:FIN216:IAD-052","payload":{"prompt":"The NDIC runs simulation exercises with other safety-net participants to test how it would respond to the failure of several banks at once. This matches which 2014 IADI Core Principle?","options":["Early detection and timely intervention","Deposit insurer's role in contingency planning and crisis management","Sources and uses of funds","Dealing with parties at fault in a bank failure"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 6 (2014) requires effective contingency planning and crisis management policies so the insurer can respond to the risk of, and actual, bank failures. Option A is about spotting and acting on troubled banks before they become non-viable, not crisis readiness. Options C and D cover legal action and funding."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 786, $official_bank_source${"itemId":"26683b6b-6534-5c46-9868-2c1b5703b9c2","questionId":"3bf0ab7c-2471-581c-b0ef-27144a190850","sourceKey":"bank:FIN216:IAD-053","payload":{"prompt":"What does Core Principle 7 (Membership) of the 2014 IADI Core Principles require?","options":["Membership should be voluntary so that only weak banks join","Membership in the deposit insurance system should be compulsory for all banks","Only foreign-owned banks should be members","Only banks above a certain size should be members"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 7 (2014) states that membership in a deposit insurance system should be compulsory for all banks. Option A would invite adverse selection, with mainly risky banks joining. Options C and D leave out many banks, which the principle does not allow."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 787, $official_bank_source${"itemId":"40d59402-9f32-585b-bd5a-12bdae726cb2","questionId":"822e7f9f-ebab-5c0a-8314-a419bda32223","sourceKey":"bank:FIN216:IAD-055","payload":{"prompt":"Under Core Principle 8 (Coverage) of the 2014 IADI Core Principles, deposit insurance coverage should be:","options":["Limited to large corporate depositors, since they hold most of the value of deposits","Set very low so that most small savers carry the risk and monitor their banks","Unlimited, covering every naira of every deposit so that no depositor ever loses money","Limited and credible, covering the large majority of depositors but leaving a substantial amount of deposits exposed to market discipline"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 8 (2014) says coverage should be limited and credible, protect the large majority of depositors, and still leave a substantial amount of deposit value exposed to market discipline. Option C would remove market discipline and increase moral hazard. Options A and B fail to protect the many small depositors the scheme is meant for."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 788, $official_bank_source${"itemId":"7987934d-7a02-51c4-b019-d66e46b9de78","questionId":"0c49f937-baea-589f-ad76-c82cb421e4cf","sourceKey":"bank:FIN216:IAD-056","payload":{"prompt":"In 2025, under Nigeria's N5m coverage limit for deposit money banks, Mrs Bello's N5m in a bank is fully insured, but a company with N800m in the same bank is covered only up to the limit. Under the 2014 IADI Core Principle on coverage, the main purpose of leaving such large deposits partly exposed is to:","options":["Keep market discipline, so large depositors watch how banks take risk","Reduce the number of depositors who are protected","Punish companies for keeping money in banks","Raise extra premium income for the deposit insurer"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 8 (2014) wants limited cover that protects most depositors while leaving a substantial amount of deposits exposed to market discipline, so big, informed depositors still monitor banks. Option D is wrong because premiums are paid by banks, not set by uninsured balances. Options B and C misread the aim, which is to protect most depositors while limiting moral hazard."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 789, $official_bank_source${"itemId":"6d9a1fc5-15c4-5bf8-a3a5-173c5f08ad12","questionId":"662a01ba-18b9-5dc0-92a4-9fe4f4448207","sourceKey":"bank:FIN216:IAD-057","payload":{"prompt":"Under Core Principle 9 (Sources and uses of funds) of the 2014 IADI Core Principles, who should bear the cost of deposit insurance?","options":["The central bank through money creation","Taxpayers through the national budget","Depositors through a withdrawal levy","Banks"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 9 (2014) says responsibility for paying the cost of deposit insurance should be borne by banks, usually through premiums. Option B would put the burden on taxpayers, which deposit insurance aims to avoid. Options A and C are not the funding arrangements the principle names."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 790, $official_bank_source${"itemId":"1de74016-3fe1-51ca-8f40-b1b247e78c82","questionId":"86b3625b-158c-5b23-a849-5aa60d0c92a4","sourceKey":"bank:FIN216:IAD-058","payload":{"prompt":"Under Core Principle 9 of the 2014 IADI Core Principles, how should the deposit insurance fund normally be built and backed up?","options":["Funded ex ante, with assured emergency liquidity arrangements in place","Funded by donations from international organisations","Funded entirely by borrowing on the capital market","Funded only after a bank fails, by levies on surviving banks"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 9 (2014) calls for readily available funds built up in advance (ex ante) plus assured liquidity funding arrangements, for example from government or the central bank. Option D describes ex post funding, which is slower and not the preferred approach. Option C is wrong because market borrowing should not be the only funding channel, and option B is not a funding mechanism the principle names."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 791, $official_bank_source${"itemId":"aeef4a2d-a0d5-599d-a8ae-593ba448515b","questionId":"bd3dfdd9-c665-568a-a857-b7637d91abdd","sourceKey":"bank:FIN216:IAD-059","payload":{"prompt":"The NDIC runs radio jingles in Pidgin and Hausa explaining which deposits are insured and up to what limit. This activity is required by which 2014 IADI Core Principle?","options":["Legal protection","Failure resolution","Public awareness","Governance"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 10 (2014) says the public should be informed on an ongoing basis about the benefits and limitations of the deposit insurance system. Option A protects the insurer's staff from lawsuits, and option D is about how the insurer is run. Option B deals with handling failed banks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 792, $official_bank_source${"itemId":"f2101f12-da7a-5114-8894-f113a60037a4","questionId":"94078754-014c-58a9-9048-e69d778b4328","sourceKey":"bank:FIN216:IAD-060","payload":{"prompt":"A former NDIC official is sued personally by shareholders of a failed bank over a decision she made in good faith while doing her job. Which 2014 IADI Core Principle says she should be protected?","options":["Governance","Dealing with parties at fault in a bank failure","Legal protection","Recoveries"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 11 (2014) says the deposit insurer and its current and former staff should be protected from liability for decisions taken in good faith in the normal course of their duties, and this protection should be in legislation. Option B is about suing those who caused a bank's failure, the reverse situation. Options A and D concern how the insurer is run and recovering claims."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 793, $official_bank_source${"itemId":"a24f7df6-54e7-5372-8c8e-7a60fe4a0d49","questionId":"7e522a13-ca2f-5a83-8d31-ceba707f4acd","sourceKey":"bank:FIN216:IAD-061","payload":{"prompt":"Directors of a failed Nigerian bank granted huge insider loans that were never repaid. Which 2014 IADI Core Principle supports the deposit insurer or another authority taking legal action against them?","options":["Dealing with parties at fault in a bank failure","Legal protection","Public awareness","Membership"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 12 (2014) says the deposit insurer, or another relevant authority, should have the power to seek legal redress against those at fault in a bank failure. Option B protects the insurer's own staff rather than pursuing wrongdoers. Options C and D deal with informing the public and compulsory membership."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 794, $official_bank_source${"itemId":"3e9eb46b-5698-5075-8503-14fdc599e168","questionId":"676ed816-e3bd-55d8-83ad-1d52047bf98f","sourceKey":"bank:FIN216:IAD-062","payload":{"prompt":"Under Core Principle 13 (Early detection and timely intervention) of the 2014 IADI Core Principles, the framework should provide for intervention:","options":["Before the bank becomes non-viable","Only after depositors have been reimbursed","Only when the bank asks for help","Only after the bank's licence has been revoked"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 13 (2014) requires a safety-net framework for early detection of, and timely intervention in, troubled banks, acting before the bank becomes non-viable. Options B and D describe actions after failure, which is too late for early intervention. Option C is wrong because the authorities should act whether or not the bank asks."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 795, $official_bank_source${"itemId":"b6154cab-6b96-5cbf-a7e1-33b5a0a110e8","questionId":"fe651a42-7d94-5a7c-ac88-d8e8eb57dfc1","sourceKey":"bank:FIN216:IAD-063","payload":{"prompt":"Under Core Principle 14 (Failure resolution) of the 2014 IADI Core Principles, the legal framework should include:","options":["Compulsory government bail-outs of failing banks","A ban on liquidating any bank","A special resolution regime","A blanket guarantee of all bank liabilities"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 14 (2014) says an effective failure resolution regime should protect depositors and contribute to financial stability, and the legal framework should include a special resolution regime. Option D goes beyond limited coverage and is meant only for extreme crises. Options A and B would expose taxpayers and remove the option of an orderly exit."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 796, $official_bank_source${"itemId":"8d889057-2612-5f9d-98d4-e2b68439c5c1","questionId":"d6668c92-5951-53b9-bd69-94ce7be2d112","sourceKey":"bank:FIN216:IAD-064","payload":{"prompt":"Under Core Principle 15 (Reimbursing depositors) of the 2014 IADI Core Principles, what should exist so that everyone knows when payouts must start?","options":["A court judgment against the failed bank's directors","A clear and unequivocal trigger for insured depositor reimbursement","Approval by a majority of the bank's shareholders","Completion of the failed bank's liquidation"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 15 (2014) requires prompt reimbursement and a clear and unequivocal trigger, such as licence revocation, for starting payouts. Option A could take years and is unrelated to the trigger. Options C and D would delay payment far beyond what prompt reimbursement allows."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 797, $official_bank_source${"itemId":"c9eeb3f4-25b9-547b-ba62-63632edc76b1","questionId":"640c9bb0-b92a-5b9b-9cd0-3650f8186cf5","sourceKey":"bank:FIN216:IAD-065","payload":{"prompt":"Under the 2014 IADI Core Principles, a deposit insurer should be able to reimburse most insured depositors within:","options":["30 days","18 months","90 days","Seven working days"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"The international standard under Core Principle 15 (2014), kept in the 2025 revision, is to reimburse most insured depositors within seven working days. Option A is several times slower than the standard, and option C reflects the kind of slow payout once seen in Nigeria under the 2006 framework. Option B is the old claim-filing period under Nigeria's 1988 decree, not a payout target."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 798, $official_bank_source${"itemId":"af216ec7-5905-576e-80e5-bb1bde5eecd9","questionId":"c8d7ad5e-37da-5dde-b927-3481b4995e1f","sourceKey":"bank:FIN216:IAD-066","payload":{"prompt":"Four deposit insurers report how quickly they paid most insured depositors after a bank failure. Under the 2014 IADI Core Principles, which one meets the reimbursement standard?","options":["Insurer Y paid most insured depositors within 90 days","Insurer X paid most insured depositors within 20 working days","Insurer Z paid only after the bank's liquidation was completed","Insurer W paid most insured depositors within 5 working days"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"The 2014 standard is to reimburse most insured depositors within seven working days, so only the insurer paying within 5 working days meets it. Option B takes nearly three times as long, and option A is far slower. Option C waits for liquidation, which can take years."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 799, $official_bank_source${"itemId":"5706fc72-bd9f-5253-9841-a2b71dba6dd1","questionId":"b10fd723-715b-54e4-88ba-d046e4b2abd4","sourceKey":"bank:FIN216:IAD-067","payload":{"prompt":"Under Core Principle 16 (Recoveries) of the 2014 IADI Core Principles, the deposit insurer should have, by law, the right to recover its claims:","options":["In accordance with the statutory creditor hierarchy","Ahead of every other creditor, including secured creditors","Only from the personal assets of bank staff","Only if the government approves each recovery"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 16 (2014) gives the deposit insurer a legal right to recover its claims in line with the statutory creditor hierarchy, the order set by law for paying creditors. Option B ignores that order. Options C and D are not part of the principle."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 800, $official_bank_source${"itemId":"fde55d08-1ead-5f7e-9b89-1a2f0d297d22","questionId":"94836a9c-a50c-5821-80e2-2445c2f62575","sourceKey":"bank:FIN216:IAD-068","payload":{"prompt":"Under the 2014 IADI Core Principles, Core Principle 8 is titled:","options":["Membership","Sources and uses of funds","Coverage","Governance"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"In the 2014 set, Core Principle 8 is Coverage, about the level and scope of deposit protection. Option A is Core Principle 7 and option B is Core Principle 9. Option D is Core Principle 3."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 801, $official_bank_source${"itemId":"d38c1633-bf17-5d3a-bee6-5c486a4973a3","questionId":"6384c21c-0b7e-5f38-99e9-854032f06b74","sourceKey":"bank:FIN216:IAD-069","payload":{"prompt":"Under the 2014 IADI Core Principles, which title belongs to Core Principle 13?","options":["Dealing with parties at fault in a bank failure","Failure resolution","Reimbursing depositors","Early detection and timely intervention"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 13 (2014) is Early detection and timely intervention. Option B is Core Principle 14, and option A is Core Principle 12. Option C is Core Principle 15."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 802, $official_bank_source${"itemId":"e9dc290d-de2a-5cba-8ada-83fced6a1cc9","questionId":"620d8eb5-b94f-5d00-ad4e-111db09e886f","sourceKey":"bank:FIN216:IAD-070","payload":{"prompt":"Under the 2014 IADI Core Principles, Recoveries is which Core Principle?","options":["Core Principle 12","Core Principle 16","Core Principle 9","Core Principle 14"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Recoveries is Core Principle 16, the last of the 16 principles in the 2014 set. Option D is Failure resolution and option A is Dealing with parties at fault in a bank failure. Option C is the principle on funding (Sources and uses of funds)."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 803, $official_bank_source${"itemId":"5fc0c41c-e26b-507f-9e56-0b01d3324f23","questionId":"3390005e-0f93-5959-b626-bcca44c20e44","sourceKey":"bank:FIN216:IAD-071","payload":{"prompt":"Under the 2014 IADI Core Principles, Cross-border issues is which Core Principle?","options":["Core Principle 11","Core Principle 5","Core Principle 4","Core Principle 6"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Cross-border issues is Core Principle 5 in the 2014 set. Option C is Relationships with other safety-net participants, and option D is the deposit insurer's role in contingency planning and crisis management. Option A is Legal protection."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 804, $official_bank_source${"itemId":"6e8ac874-77c5-5f16-ac1a-39f0666d3674","questionId":"18bb9a83-a81c-5b4e-b88a-79ddc6f7496f","sourceKey":"bank:FIN216:IAD-072","payload":{"prompt":"Which of the following is NOT the title of one of the 16 Core Principles in the 2014 IADI set?","options":["Legal protection","Mandate and powers","Lender of last resort","Reimbursing depositors"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Lender of last resort is a central bank function and is not one of IADI's 16 Core Principles (2014). Options B, A and D are genuine 2014 principles: Core Principle 2 (Mandate and powers), Core Principle 11 (Legal protection) and Core Principle 15 (Reimbursing depositors)."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 805, $official_bank_source${"itemId":"19b5ba31-4876-5ec0-b1ee-63e9a56786c5","questionId":"5b27577d-0a80-538d-ac6b-632831ac9695","sourceKey":"bank:FIN216:IAD-075","payload":{"prompt":"Under the 2014 IADI Core Principles, what most clearly separates a risk minimiser mandate from a pay box plus mandate?","options":["A risk minimiser is funded by taxpayers, while a pay box plus insurer is funded by banks","A risk minimiser only reimburses insured depositors and has no other functions at all","A risk minimiser also has risk assessment, early intervention and resolution powers, and sometimes prudential oversight","A risk minimiser has no role in resolving failed banks, unlike a pay box plus insurer"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"A risk minimiser has the widest mandate, covering risk assessment and management, early intervention and resolution powers, and sometimes prudential oversight, whereas pay box plus only adds certain resolution functions. Option B describes a pay box. Option D is the reverse of the truth, and option A has nothing to do with the mandate type."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 806, $official_bank_source${"itemId":"4de1391d-c640-5a5a-8225-ad370600e702","questionId":"5fb3d0bc-0300-5e0d-b58f-9f55516d3b74","sourceKey":"bank:FIN216:IAD-076","payload":{"prompt":"Under the 2014 IADI Core Principles, factors largely outside the deposit insurer's control, such as macroeconomic conditions, financial system structure and the legal and judicial framework, which affect how well a deposit insurance system works, are called the:","options":["Operating environment","Public policy objectives","Coverage","Mandate and powers"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI groups macroeconomic conditions, the strength of the sovereign, financial system structure, prudential regulation and supervision, the legal and judicial framework, and the accounting and disclosure regime under the operating environment. Options B, C and D are Core Principles that the deposit insurance system itself is designed around, not outside conditions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 807, $official_bank_source${"itemId":"50672d36-372c-5500-9ef5-e8ead5472a92","questionId":"438781e9-f929-5c4f-82a4-ea18449b378d","sourceKey":"bank:FIN216:IAD-077","payload":{"prompt":"Under the 2014 IADI Core Principles, which of the following is NOT part of the operating environment of a deposit insurance system?","options":["The deposit insurer's own coverage limit","Macroeconomic conditions","The legal and judicial framework","The accounting and disclosure regime"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"The coverage limit is a design feature the deposit insurance system sets itself, covered by Core Principle 8. Options B, C and D are genuine parts of the operating environment, which lies largely outside the insurer's control."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 808, $official_bank_source${"itemId":"3b807cb5-73b3-58b5-a8b6-5fc8ac6d83f1","questionId":"eb24629c-bf16-5747-901a-4cda59ba304c","sourceKey":"bank:FIN216:IAD-078","payload":{"prompt":"IADI defines moral hazard as the situation where:","options":["Depositors withdraw funds from sound banks after one bank fails","Weak banks are more likely than strong banks to join a voluntary scheme","A deposit insurer pays depositors later than promised","Parties have incentives to take more risk because the costs of that risk are borne by others"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Moral hazard arises when parties take more risk because others bear the cost, for example banks lending recklessly when depositors feel fully protected. Option B describes adverse selection, and option A describes contagion or a bank run. Option C is simply slow reimbursement."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 809, $official_bank_source${"itemId":"d1df1aac-195a-5c7a-89f0-ef094d9f0206","questionId":"b723c175-6579-5d02-a26c-178a4f6e6d61","sourceKey":"bank:FIN216:IAD-079","payload":{"prompt":"Which of the following deposit insurance design features does IADI cite as helping to reduce moral hazard?","options":["Paying uninsured creditors in full","Limited coverage","A blanket guarantee of all bank liabilities","Unlimited coverage of all deposits"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI lists limited coverage, along with differential (risk-based) premiums and timely intervention and resolution, as design features that reduce moral hazard. Options A, C and D all widen protection, which weakens market discipline and increases moral hazard."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 810, $official_bank_source${"itemId":"b63223fb-28d4-5bb5-bb8a-08f089ec7917","questionId":"2caa66b2-8820-56c2-a1c1-e3dfc7b4f0a7","sourceKey":"bank:FIN216:IAD-080","payload":{"prompt":"IADI describes the financial safety net as the functions of several bodies. Which of the following is NOT one of those functions?","options":["Prudential regulation and supervision","Lender of last resort","Collecting company income tax","Deposit insurance"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"IADI's financial safety net covers prudential regulation, supervision, resolution, lender of last resort and deposit insurance, sometimes with the Ministry of Finance. Collecting income tax is a revenue function, not a safety-net function. Options A, B and D are all genuine safety-net functions."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 811, $official_bank_source${"itemId":"b5915241-9db9-5687-9eed-c271d4c7fedf","questionId":"78ec4361-c5ca-56ea-a605-95c15c78f982","sourceKey":"bank:FIN216:IAD-081","payload":{"prompt":"Under the 2014 IADI compliance assessment methodology, which of the following is NOT a grade used to rate compliance with a Core Principle?","options":["Not Applicable","Partially Compliant","Largely Compliant","Materially Non-Compliant"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"The 2014 methodology rates each principle as Compliant, Largely Compliant, Materially Non-Compliant, Non-Compliant or Not Applicable; Partially Compliant is not one of them. Options A, C and D are genuine grades on that scale."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 812, $official_bank_source${"itemId":"b63c1478-c1e5-517c-b736-6ccc58ca5ec8","questionId":"9ffe559c-08f3-5670-a409-d6310bb252b2","sourceKey":"bank:FIN216:IAD-082","payload":{"prompt":"Under the 2014 IADI compliance assessment methodology, a jurisdiction with only minor shortcomings that can be corrected within a prescribed timeframe is rated:","options":["Compliant","Materially Non-Compliant","Non-Compliant","Largely Compliant"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"Largely Compliant means only minor shortcomings exist and they can be fixed within a set timeframe. Option A means the essential criteria are met without significant deficiencies. Option B means severe shortcomings that cannot easily be fixed, and option C means no substantive implementation."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 813, $official_bank_source${"itemId":"e81aabd5-a86d-574c-ab78-33d0b07b0bae","questionId":"083624b8-7427-5f9b-b256-12302b58eeef","sourceKey":"bank:FIN216:IAD-083","payload":{"prompt":"Under the 2014 IADI compliance assessment methodology, a jurisdiction with severe shortcomings in a Core Principle that cannot be easily rectified is rated:","options":["Compliant","Largely Compliant","Materially Non-Compliant","Not Applicable"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"Materially Non-Compliant is used where shortcomings are severe and not easily rectified. Option B applies to minor, fixable shortcomings, and option A to full compliance. Option D is for principles that do not apply because of the system's structural, legal or institutional features."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 814, $official_bank_source${"itemId":"05f3ca9e-f91e-5e46-9523-f222d53b4e5a","questionId":"e49ec41b-2b04-5bb6-bbee-169148344f2f","sourceKey":"bank:FIN216:IAD-084","payload":{"prompt":"Under the 2014 IADI compliance assessment methodology, full compliance with a Core Principle is judged on the basis of:","options":["The essential criteria only","The number of member banks only","A simple checklist where every item carries equal weight","The size of the deposit insurance fund only"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"The essential criteria are the only elements used to gauge full compliance with a Core Principle. Options B and D are single facts about a system, not the assessment basis. Option C is wrong because IADI stresses that assessments are qualitative, not a checklist, and criteria do not carry equal weight."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 815, $official_bank_source${"itemId":"9fcebdb0-de9b-5735-ada8-725eeef6afac","questionId":"21c81de0-94bf-5186-b232-5a64f12ff175","sourceKey":"bank:FIN216:IAD-085","payload":{"prompt":"A team of assessors finds that a deposit insurer meets all the essential criteria of a Core Principle without significant deficiencies. Under the 2014 IADI methodology, the rating is:","options":["Materially Non-Compliant","Compliant","Largely Compliant","Not Applicable"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Compliant is given when the essential criteria are met without significant deficiencies. Option C is for minor shortcomings that still need fixing, and option A is for severe shortcomings. Option D is used only when a principle does not apply to that system."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 816, $official_bank_source${"itemId":"07d884bf-1a12-5c28-b327-630e95743939","questionId":"bc60e847-f464-5bd2-aebd-a4f258039e2e","sourceKey":"bank:FIN216:IAD-086","payload":{"prompt":"How many Core Principles are in the revised set approved by IADI in 2025?","options":["16","20","12","18"],"correctOption":3,"section":"International Association of Deposit Insurers (IADI)","explanation":"The 2025 revision has 18 Core Principles, up from 16 in the 2014 set. Option A is the 2014 count, so it is a common mix-up. Options B and C do not match any version."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 817, $official_bank_source${"itemId":"0406db24-bad8-510d-ac55-d48aa68565e9","questionId":"7db6c1d3-9869-517e-b9ab-0440dd5fed10","sourceKey":"bank:FIN216:IAD-087","payload":{"prompt":"Which of the following became a separate Core Principle in the 2025 revision but was not a principle title in the 2014 set?","options":["Coverage","Business continuity management","Governance","Membership"],"correctOption":1,"section":"International Association of Deposit Insurers (IADI)","explanation":"Business continuity management is Core Principle 4 in the 2025 revision and had no principle of its own in 2014. Options A, C and D appear in both versions, as Core Principles 8, 7 and 3."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 818, $official_bank_source${"itemId":"ad5092ec-9a0b-54d3-a81b-e5f3f5bd09d0","questionId":"2b6bcf07-53a5-5f26-b16c-06cdef0bb420","sourceKey":"bank:FIN216:IAD-088","payload":{"prompt":"In both the 2014 and 2025 versions of the IADI Core Principles, Core Principle 15 deals with:","options":["Reimbursing depositors","Cross-border issues","Public awareness","Failure resolution"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 15 covers reimbursement in both versions (titled Reimbursing depositors in 2014 and Reimbursement in 2025), and the seven-working-day standard is kept. Option D is Core Principle 14 in both versions, and option C is Core Principle 10. Option B is Core Principle 5 in 2014 and Core Principle 18 in 2025."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_fin216', 'add', 819, $official_bank_source${"itemId":"b4d8aea4-8c9f-5908-8306-3ab375b105dc","questionId":"112fb914-9fba-5706-99f1-7c94ac1474f5","sourceKey":"bank:FIN216:IAD-089","payload":{"prompt":"Under the 2025 revision of the IADI Core Principles, Core Principle 18 deals with:","options":["Recoveries","Business continuity management","Cross-border cooperation, coordination and information-sharing","Use of the deposit insurance fund in resolution"],"correctOption":2,"section":"International Association of Deposit Insurers (IADI)","explanation":"In the 2025 set, Core Principle 18 is Cross-border cooperation, coordination and information-sharing (it was Core Principle 5 in 2014). Option A is Core Principle 6 in 2025, and option B is Core Principle 4. Option D is Core Principle 16."}}$official_bank_source$::jsonb),
  ('official_bank_fin216', 'add', 820, $official_bank_source${"itemId":"fb133155-6257-51d5-97bc-af5e16a9634f","questionId":"b5ffde81-ce0f-57ab-95fc-6a9d8e088685","sourceKey":"bank:FIN216:IAD-090","payload":{"prompt":"Under the 2025 revision of the IADI Core Principles, which principle deals with when and how deposit insurance funds may be used to support a bank's resolution?","options":["Use of the deposit insurance fund in resolution (Core Principle 16)","Crisis preparedness and management (Core Principle 11)","Recoveries (Core Principle 6)","Public awareness (Core Principle 10)"],"correctOption":0,"section":"International Association of Deposit Insurers (IADI)","explanation":"Core Principle 16 in the 2025 set is Use of the deposit insurance fund in resolution. Option C is about recovering the insurer's claims from failed banks, not using the fund. Option D covers informing the public, and option B covers readiness for crises rather than the use of the fund itself."}}$official_bank_source$::jsonb);
